DG.put("rudr-avtaar/27",{"n":27,"title":"ਅਥ ਪਾਰਸ ਨਾਥ ਰੁਦ੍ਰ ਅਵਤਾਰ ਕਥਨੰ","title_roman":"Ath paaras naath rudr avtaar kathnan","page":862,"blocks":[{"type":"invocation","gurmukhi":"ੴ ਸਤਿਗੁਰ ਪ੍ਰਸਾਦਿ","roman":"Ik Oankaar satigur prasaadi","meaning_en":"One Universal Creator; realised by the grace of the True Guru.","page":862,"meaning_status":"draft"},{"type":"invocation","gurmukhi":"ਪਾਤਸ਼ਾਹੀ ੧੦","roman":"Paatshaahee 10","meaning_en":"The Tenth King.","page":862,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":862,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":862,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਦਤ ਰੁਦ੍ਰ ਅਵਤਾਰਾ। ਪੂਰਣ ਮਤ ਕੋ ਕੀਨ ਪਸਾਰਾ।","roman":"Ih bidhi dat rudr avtaaraa | pooran mat ko keen pasaaraa |","meaning_en":"In this way Dutt, the incarnation of Rudra, spread his complete creed;","page":862,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤਿ ਜੋਤਿ ਸੋ ਜੋਤਿ ਮਿਲਾਨੀ। ਜਿਹ ਬਿਧਿ ਸੋ ਪਾਰਬ੍ਰਹਮ ਭਵਾਨੀ। ੧।","roman":"Anti joti so joti milaanee | jih bidhi so paarbraham bhavaanee | 1 |","meaning_en":"at the end his light merged into the Light, as it pleased the Supreme Lord.","page":862,"meaning_status":"draft","note":"ਭਵਾਨੀ: read as 'it pleased' (bhaavani); could also be taken as the goddess Bhavani. Uncertain."}]},{"type":"verse","number":[2],"number_text":"੨।","page":862,"lines":[{"gurmukhi":"ਏਕ ਲਛ ਦਸ ਬਰਖ ਪ੍ਰਮਾਨਾ। ਪਾਛੇ ਚਲਾ ਜੋਗ ਕੋ ਬਾਨਾ।","roman":"Ek lachh das barakh pramaanaa | paachhe chalaa jog ko baanaa |","meaning_en":"For a hundred thousand and ten years the way of yoga continued after him.","page":862,"meaning_status":"draft","note":"ਏਕ ਲਛ ਦਸ ਬਰਖ: read as 1,00,010 years; the count is not certain."},{"gurmukhi":"ਗ੍ਯਾਰਵ ਬਰਖ ਬਿਤੀਤਤ ਭਯੋ। ਪਾਰਸਨਾਥ ਪੁਰਖ ਭੂਅ ਵਯੋ। ੨।","roman":"Gyaarav barakh biteetat bhayo | paarasnaath purakh bhooa vayo | 2 |","meaning_en":"When the eleventh year had passed, the man Parasnath was born on earth.","page":862,"meaning_status":"draft","note":"ਭੂਅ ਵਯੋ: 'was sown/born on the earth'. Which 'eleventh year' is meant is unclear."}]},{"type":"verse","number":[3],"number_text":"੩।","page":862,"lines":[{"gurmukhi":"ਰੋਹ ਦੇਸ ਸੁਭ ਦਿਨ ਭਲ ਥਾਨੁ। ਪਰਸ ਨਾਥ ਭਯੋ ਸੁਰ ਗ੍ਯਾਨੁ।","roman":"Roh des subh din bhal thaanu | paras naath bhayo sur gyaanu |","meaning_en":"In the land of Roh, on an auspicious day in a fine place, Parasnath was born, with the wisdom of a god;","page":862,"meaning_status":"draft","note":"ਸੁਰ ਗ੍ਯਾਨੁ: 'wise as the gods'; uncertain."},{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਅਸਿ ਅਵਰ ਨ ਹੋਊ। ਚਕ੍ਰਤ ਰਹੇ ਮਾਤ ਪਿਤ ਦੋਊ। ੩।","roman":"Amit tej asi avar na ho'oo | chakrat rahe maat pit do'oo | 3 |","meaning_en":"his radiance was boundless, such as no other could have; his mother and father were both left astonished.","page":862,"meaning_status":"draft"}]},{"type":"verse","number":[4],"number_text":"੪।","page":863,"lines":[{"gurmukhi":"ਦਸਊ ਦਿਸਨਿ ਤੇਜ ਅਤਿ ਬਢਾ। ਦ੍ਵਾਦਸ ਭਾਨ ਏਕ ਹ੍ਵੈ ਚਢਾ।","roman":"Dasaoo disni tej ati badhaa | dvaadas bhaan ek hvai chadhaa |","meaning_en":"His radiance spread greatly in all ten directions, as if twelve suns had risen together as one;","page":863,"meaning_status":"draft"},{"gurmukhi":"ਦਹ ਦਿਹਸ ਲੋਕ ਉਠੇ ਅਕੁਲਾਈ। ਭੂਪਤਿ ਤੀਰ ਪੁਕਾਰੇ ਜਾਈ। ੪।","roman":"Dah dihas lok uthe akulaaee | bhoopti teer pukaare jaaee | 4 |","meaning_en":"the people of the ten directions rose up in distress and went to the king to cry out.","page":863,"meaning_status":"draft","note":"ਦਹ ਦਿਹਸ: printed so; read as 'ten directions'."}]},{"type":"verse","number":[5],"number_text":"੫।","page":863,"lines":[{"gurmukhi":"ਸੁਨੋ ਭੂਮ ਇਕ ਕਹੋ ਕਹਾਨੀ। ਏਕ ਪੁਰੁਖ ਉਪਜ੍ਯੋ ਅਭਿਮਾਨੀ।","roman":"Suno bhoom ik kaho kahaanee | ek purukh upjyo abhimaanee |","meaning_en":"\"Hear, O king, we tell you a story: a proud man has been born,","page":863,"meaning_status":"draft","note":"ਭੂਮ: 'lord of the earth', i.e. the king."},{"gurmukhi":"ਜਿਹ ਸਮ ਰੂਪ ਜਗਤ ਨਹੀ ਕੋਈ। ਏਕੈ ਘੜਾ ਬਿਧਾਤਾ ਸੋਈ। ੫।","roman":"Jih sam roop jagat nahee koee | ekai gharaa bidhaataa soee | 5 |","meaning_en":"\"whose beauty no one in the world equals; the Creator fashioned him alone, one of a kind.","page":863,"meaning_status":"draft"}]},{"type":"verse","number":[6],"number_text":"੬।","page":863,"lines":[{"gurmukhi":"ਕੈ ਗੰਧ੍ਰਬ ਜਛ ਕੋਈ ਅਹਾ। ਜਾਨੁਕ ਦੂਸਰ ਭਾਨੁ ਚੜ ਰਹਾ।","roman":"Kai gandhrab jachh koee ahaa | jaanuk doosar bhaanu char rahaa |","meaning_en":"\"He may be a Gandharva or a Yaksha; it is as if a second sun is rising;","page":863,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਜੋਬਨ ਝਮਕਤ ਤਿਹ ਅੰਗਾ। ਨਿਖਰਤ ਜਾ ਕੇ ਲਜਤ ਅਨੰਗਾ। ੬।","roman":"Ati joban jhamkat tih angaa | nikhrat jaa ke lajat anangaa | 6 |","meaning_en":"\"great youth gleams in his limbs; seeing his splendour, Kama, the bodiless god of love, is put to shame.\"","page":863,"meaning_status":"draft","note":"ਅਨੰਗਾ: Anang, 'the bodiless', a name of Kama."}]},{"type":"verse","number":[7],"number_text":"੭।","page":863,"lines":[{"gurmukhi":"ਭੂਪਤਿ ਦੇਖਨ ਕਾਜ ਬੁਲਾਵਾ। ਪਹਿਲੇ ਦ੍ਯੋਸ ਸਾਥ ਚਲ ਆਵਾ।","roman":"Bhoopti dekhan kaaj bulaavaa | pahile dyos saath chal aavaa |","meaning_en":"The king sent for him in order to see him; on the first day he came along (with the messengers).","page":863,"meaning_status":"draft"},{"gurmukhi":"ਹਰਖ ਹ੍ਰਿਦੈ ਧਰ ਕੇ ਜਟਧਾਰੀ। ਜਾਨੁਕ ਦੁਤੀ ਦਤ ਅਵਤਾਰੀ। ੭।","roman":"Harakh hridai dhar ke jatdhaaree | jaanuk dutee dat avtaaree | 7 |","meaning_en":"Holding joy in his heart came the one with matted hair, as if a second incarnation of Dutt.","page":863,"meaning_status":"draft","note":"ਜਟਧਾਰੀ here read as Parasnath himself; it may instead refer to the matted-haired ascetics present. Uncertain."}]},{"type":"verse","number":[8],"number_text":"੮।","page":863,"lines":[{"gurmukhi":"ਨਿਰਖ ਰੂਪ ਕਾਪੇ ਜਟਧਾਰੀ। ਯਹ ਕੋਊ ਭਯੋ ਪੁਰਖੁ ਅਵਤਾਰੀ।","roman":"Nirakh roop kaape jatdhaaree | yah ko'oo bhayo purkhu avtaaree |","meaning_en":"Seeing his form, the matted-haired ascetics trembled: \"This is some man born as an incarnation;","page":863,"meaning_status":"draft"},{"gurmukhi":"ਯਹ ਮਤ ਦੂਰ ਹਮਾਰਾ ਕੈ ਹੈ। ਜਟਾਧਾਰ ਕੋਈ ਰਹੈ ਨ ਪੈ ਹੈ। ੮।","roman":"Yah mat door hamaaraa kai hai | jataadhaar koee rahai na pai hai | 8 |","meaning_en":"\"he will drive our creed far away; no matted-haired ascetic will be able to remain.\"","page":863,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":863,"lines":[{"gurmukhi":"ਤੇਜ ਪ੍ਰਭਾਵ ਨਿਰਖਿ ਤਬ ਰਾਜਾ। ਅਤਿ ਪ੍ਰਸੰਨਿ ਪੁਲਕਤ ਚਿਤ ਗਾਜਾ।","roman":"Tej prabhaav nirkhi tab raajaa | ati prasanni pulkat chit gaajaa |","meaning_en":"Then the king, seeing his radiance and power, was greatly pleased; his heart thrilled and rejoiced;","page":863,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਜਿਹਾ ਲਖਾ ਰਹੇ ਬਿਸਮਾਈ। ਜਾਨੁਕ ਰੰਕ ਨਵੋ ਨਿਧ ਪਾਈ। ੯।","roman":"Jih jihaa lakhaa rahe bismaaee | jaanuk rank navo nidh paaee | 9 |","meaning_en":"whoever saw him was left in wonder, as if a pauper had found the nine treasures.","page":863,"meaning_status":"draft"}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":863,"lines":[{"gurmukhi":"ਮੋਹਨ ਜਾਲ ਸਭਨ ਸਿਰ ਡਾਰਾ। ਚੇਟਕ ਬਾਨ ਚਕ੍ਰਿਤ ਹ੍ਵੈ ਮਾਰਾ।","roman":"Mohan jaal sabhan sir daaraa | chetak baan chakrit hvai maaraa |","meaning_en":"He cast a net of enchantment over everyone's head, and struck them, astonished, with the arrow of magic;","page":863,"meaning_status":"draft","note":"ਚੇਟਕ: magic, enchantment."},{"gurmukhi":"ਜਹ ਤਹ ਮੋਹਿ ਸਕਲ ਨਰ ਗਿਰੇ। ਜਾਨ ਸੁਭਟ ਸਾਮੁਹਿ ਰਣ ਭਿਰੇ। ੧੦।","roman":"Jah tah mohi sakal nar gire | jaan subhat saamuhi ran bhire | 10 |","meaning_en":"here and there all the men fell, enchanted, like brave warriors who have clashed face to face in battle.","page":863,"meaning_status":"draft"}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":863,"lines":[{"gurmukhi":"ਨਰ ਨਾਰੀ ਜਿਹ ਜਿਹ ਤਿਹ ਪੇਖਾ। ਤਿਹ ਤਿਹ ਮਦਨ ਰੂਪ ਅਵਿਰੇਖਾ।","roman":"Nar naaree jih jih tih pekhaa | tih tih madan roop avirekhaa |","meaning_en":"Every man and woman who looked on him saw him as the very form of Kama, the god of love;","page":863,"meaning_status":"draft","note":"ਅਵਿਰੇਖਾ: read as 'beheld / considered'; uncertain."},{"gurmukhi":"ਸਾਧਨ ਸਰਬ ਸਿਧਿ ਕਰ ਜਾਨਾ। ਜੋਗਨ ਜੋਗ ਰੂਪ ਅਨੁਮਾਨਾ। ੧੧।","roman":"Saadhan sarab sidhi kar jaanaa | jogan jog roop anumaanaa | 11 |","meaning_en":"the sadhus took him for one perfect in every power; the yogis judged him to be the very form of yoga.","page":863,"meaning_status":"draft"}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":863,"lines":[{"gurmukhi":"ਨਿਰਖਿ ਰੂਪ ਰਨਵਾਸ ਲੁਭਾਨਾ। ਦੇ ਤਿਹ ਸੁਤਾ ਨ੍ਰਿਪਤਿ ਮਨਿ ਮਾਨਾ।","roman":"Nirkhi roop ranvaas lubhaanaa | de tih sutaa nripti mani maanaa |","meaning_en":"Seeing his beauty, the women's quarters were captivated; the king resolved in his mind to give him his daughter.","page":863,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਕੋ ਭਯੋ ਜਬੈ ਜਾਮਾਤਾ। ਮਹਾ ਧਨੁਖਧਰ ਬੀਰ ਬਿਖ੍ਯਾਤਾ। ੧੨।","roman":"Nrip ko bhayo jabai jaamaataa | mahaa dhanukhdhar beer bikhyaataa | 12 |","meaning_en":"When he became the king's son-in-law, he was renowned as a great archer and hero.","page":863,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":863,"lines":[{"gurmukhi":"ਮਹਾ ਰੂਪ ਅਰੁ ਅਮਿਤ ਪ੍ਰਤਾਪੂ। ਜਾਨੁ ਜਪੈ ਹੈ ਆਪਨ ਜਾਪੂ।","roman":"Mahaa roop aru amit prataapoo | jaanu japai hai aapan jaapoo |","meaning_en":"Of great beauty and boundless glory, it was as if he were reciting his own chant;","page":863,"meaning_status":"draft","note":"ਜਾਨੁ ਜਪੈ ਹੈ ਆਪਨ ਜਾਪੂ: literally 'as if he chants his own chant'; the sense may be that he was absorbed in himself, or that all chanted his name. Uncertain."},{"gurmukhi":"ਸਸਤ੍ਰ ਸਾਸਤ੍ਰ ਬੇਤਾ ਸੁਰਿ ਗ੍ਯਾਨਾ। ਜਾ ਸਮ ਪੰਡਿਤ ਜਗਤਿ ਨ ਆਨਾ। ੧੩।","roman":"Sasatr saasatr betaa suri gyaanaa | jaa sam pandit jagti na aanaa | 13 |","meaning_en":"he knew weapons and scriptures and had godlike wisdom; there was no other pandit in the world like him.","page":863,"meaning_status":"draft"}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":864,"lines":[{"gurmukhi":"ਥੋਰਿ ਬਹਿਕ੍ਰਮ ਬੁਧਿ ਬਿਸੇਖਾ। ਜਾਨੁਕ ਧਰਾ ਬਿਤਨ ਯਹਿ ਭੇਖਾ।","roman":"Thori bahikram budhi bisekhaa | jaanuk dharaa bitan yahi bhekhaa |","meaning_en":"Though young in age, he was exceptional in intellect, as if the bodiless one (Kama) had taken this guise on earth;","page":864,"meaning_status":"draft","note":"ਥੋਰਿ ਬਹਿਕ੍ਰਮ: read as 'small age' (vayakram). ਬਿਤਨ: 'bodiless', read as Kama. Uncertain."},{"gurmukhi":"ਜਿਹ ਜਿਹ ਰੂਪ ਤਵਨ ਕਾ ਲਹਾ। ਸੋ ਸੋ ਚਮਕ ਚਕ੍ਰਿ ਹੁਐ ਰਹਾ। ੧੪।","roman":"Jih jih roop tavan kaa lahaa | so so chamak chakri huai rahaa | 14 |","meaning_en":"whoever beheld his form remained dazzled and astonished.","page":864,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":864,"meaning_status":"draft"},{"type":"verse","number":[15],"number_text":"੧੫।","page":864,"lines":[{"gurmukhi":"ਮਾਨ ਭਰੇ ਸਰ ਸਾਨ ਧਰੇ ਮਠ ਸਾਨ ਚੜੇ ਅਸਿ ਸ੍ਰੋਣਤਿ ਸਾਏ।","roman":"Maan bhare sar saan dhare math saan chare asi sronti saae |","meaning_en":"(His eyes are like) arrows full of pride, set to the whetstone, like swords sharpened on the stone and steeped in blood;","page":864,"meaning_status":"draft","note":"The verse describes his eyes. ਮਠ: unclear; perhaps 'sharp'. Uncertain."},{"gurmukhi":"ਲੇਤ ਹਰੇ ਜਿਹ ਡੀਠ ਪਰੇ ਨਹੀ ਫੇਰਿ ਫਿਰੇ ਗ੍ਰਿਹ ਜਾਨ ਨ ਪਾਏ।","roman":"Let hare jih deeth pare nahee pheri phire grih jaan na paae |","meaning_en":"whoever they fall upon is carried away; he never turns back and cannot go home again.","page":864,"meaning_status":"draft"},{"gurmukhi":"ਝੀਮ ਝਰੇ ਜਨ ਸੇਲ ਹਰੇ ਇਹ ਭਾਤਿ ਗਿਰੇ ਜਨੁ ਦੇਖਨ ਆਏ।","roman":"Jheem jhare jan sel hare ih bhaati gire janu dekhan aae |","meaning_en":"They fall in a swoon as if struck by a lance; they fall like this though they came only to look;","page":864,"meaning_status":"draft","note":"ਝੀਮ ਝਰੇ: read as 'swooning, collapsing'; uncertain."},{"gurmukhi":"ਜਾਸੁ ਹਿਰੇ ਸੋਊ ਮੈਨ ਘਿਰੇ ਗਿਰ ਭੂਮਿ ਪਰੇ ਨ ਉਠੰਤ ਉਠਾਏ। ੧੫।","roman":"Jaasu hire so'oo main ghire gir bhoomi pare na uthant uthaae | 15 |","meaning_en":"whoever they steal is hemmed in by love; he falls to the ground and does not rise, though lifted up.","page":864,"meaning_status":"draft","note":"ਮੈਨ: Kama, love."}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":864,"lines":[{"gurmukhi":"ਸੋਭਤ ਜਾਨੁ ਸੁਧਾਸਰ ਸੁੰਦਰ ਕਾਮ ਕੇ ਮਾਨਹੁ ਕੂਪ ਸੁ ਧਾਰੇ।","roman":"Sobhat jaanu sudhaasar sundar kaam ke maanhu koop su dhaare |","meaning_en":"They shine like beautiful pools of nectar, as if wells of love had been set there;","page":864,"meaning_status":"draft"},{"gurmukhi":"ਲਾਜਿ ਕੇ ਜਾਨ ਜਹਾਜ ਬਿਰਾਜਤ ਹੇਰਤ ਹੀ ਹਰ ਲੇਤ ਹਕਾਰੇ।","roman":"Laaji ke jaan jahaaj biraajat herat hee har let hakaare |","meaning_en":"they look splendid like ships of modesty; with a glance they steal (the heart) and challenge.","page":864,"meaning_status":"draft","note":"ਹਕਾਰੇ: 'call out / challenge'; uncertain."},{"gurmukhi":"ਹਉ ਚਹੁ ਕੁੰਟ ਭ੍ਰਮ੍ਯੋ ਖਗ ਜ੍ਯੋਂ ਇਨ ਕੇ ਸਮ ਰੂਪ ਨ ਨੈਕੁ ਨਿਹਾਰੇ।","roman":"Hau chahu kunt bhramyo khag jyon in ke sam roop na naiku nihaare |","meaning_en":"I have wandered the four quarters like a bird, and have not seen the least beauty to equal these.","page":864,"meaning_status":"draft"},{"gurmukhi":"ਪਾਰਥ ਬਾਨ ਕਿ ਜੁਬਨ ਖਾਨ ਕਿ ਕਾਲ ਕ੍ਰਿਪਾਨ ਕਿ ਕਾਮ ਕਟਾਰੇ। ੧੬।","roman":"Paarath baan ki juban khaan ki kaal kripaan ki kaam kataare | 16 |","meaning_en":"Are they Arjun's arrows, or a mine of youth, or the sword of Death, or the daggers of Kama?","page":864,"meaning_status":"draft"}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":864,"lines":[{"gurmukhi":"ਤੰਤ੍ਰ ਭਰੇ ਕਿਧੌ ਜੰਤ੍ਰ ਜਰੇ ਅਰ ਮੰਤ੍ਰ ਹਰੇ ਚਖ ਚੀਨਤ ਯਾ ਤੇ।","roman":"Tantr bhare kidhau jantr jare ar mantr hare chakh cheenat yaa te |","meaning_en":"Are they filled with spells, or set with charms, with incantations that captivate? Such do the eyes appear;","page":864,"meaning_status":"draft","note":"ਚਖ ਚੀਨਤ ਯਾ ਤੇ: read as 'thus are the eyes seen'; uncertain."},{"gurmukhi":"ਜੋਬਨ ਜੋਤਿ ਜਗੇ ਅਤਿ ਸੁੰਦਰ ਰੰਗ ਰੰਗੇ ਮਦ ਸੇ ਮਦੂਆ ਤੇ।","roman":"Joban joti jage ati sundar rang range mad se madooaa te |","meaning_en":"the light of youth is awake in them; very beautiful, dyed in colour, like the intoxicated from wine;","page":864,"meaning_status":"draft"},{"gurmukhi":"ਰੰਗ ਸਹਾਬ ਫੂਲ ਗੁਲਾਬ ਸੇ ਸੀਖੇ ਹੈ ਜੋਰਿ ਕਰੋਰਕ ਘਾਤੇ।","roman":"Rang sahaab phool gulaab se seekhe hai jori karorak ghaate |","meaning_en":"coloured like wine, like rose flowers, they have learnt millions of strokes;","page":864,"meaning_status":"draft","note":"ਸਹਾਬ: read as 'sharab', wine (or 'red'); ਘਾਤੇ: blows, wiles. Uncertain."},{"gurmukhi":"ਮਾਧੁਰੀ ਮੂਰਤਿ ਸੁੰਦਰ ਸੂਰਤਿ ਹੇਰਤਿ ਹੀ ਹਰ ਲੇਤ ਹੀਯਾ ਤੇ। ੧੭।","roman":"Maadhuree moorti sundar soorti herti hee har let heeyaa te | 17 |","meaning_en":"a sweet form, a beautiful face, which steals the heart at a glance.","page":864,"meaning_status":"draft"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":864,"lines":[{"gurmukhi":"ਪਾਨ ਚਬਾਇ ਸੀਗਾਰ ਬਨਾਇ। ਸੁਗੰਧ ਲਗਾਇ ਸਭਾ ਜਬ ਆਵੈ।","roman":"Paan chabaai seegaar banaai | sugandh lagaai sabhaa jab aavai |","meaning_en":"When he comes to the assembly, chewing betel, adorned and perfumed,","page":864,"meaning_status":"draft"},{"gurmukhi":"ਕਿਨਰ ਜਛ ਭੁਜੰਗ ਚਰਾਚਰ ਦੇਵ ਅਦੇਵ ਦੋਊ ਬਿਸਮਾਵੈ।","roman":"Kinar jachh bhujang charaachar dev adev do'oo bismaavai |","meaning_en":"Kinnars, Yakshas, serpents, all that moves and does not move, gods and demons alike are amazed;","page":864,"meaning_status":"draft"},{"gurmukhi":"ਮੋਹਿਤ ਜੇ ਮਹਿ ਲੋਗਨ ਮਾਨਨਿ ਮੋਹਤ ਤਉਨ ਮਹਾ ਸੁਖ ਪਾਵੈ।","roman":"Mohit je mahi logan maanni mohat taun mahaa sukh paavai |","meaning_en":"the proud women who enchant the people of the earth, he enchants them, and they find great joy;","page":864,"meaning_status":"draft","note":"Construction unclear; read as above. Uncertain."},{"gurmukhi":"ਵਾਰਹਿ ਹੀਰ ਅਮੋਲਕ ਚੀਰ ਤ੍ਰੀਯਾ ਬਿਨ ਧੀਰ ਸਬੈ ਬਲ ਜਾਵੈ। ੧੮।","roman":"Vaarhi heer amolak cheer treeyaa bin dheer sabai bal jaavai | 18 |","meaning_en":"women offer up diamonds and priceless garments over him; losing their composure, they all give themselves up to him.","page":864,"meaning_status":"draft","note":"ਬਲ ਜਾਵੈ: 'are sacrificed to, devote themselves to'."}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":864,"lines":[{"gurmukhi":"ਰੂਪ ਅਪਾਰ ਪੜੇ ਦਸ ਚਾਰ ਮਨੋ ਅਸੁਰਾਰਿ ਚਤੁਰ ਚਕ ਜਾਨ੍ਯੋ।","roman":"Roop apaar pare das chaar mano asuraari chatur chak jaanyo |","meaning_en":"Of boundless beauty, he studied the fourteen sciences; as if he were Vishnu, enemy of demons, he was known as wise in the four quarters.","page":864,"meaning_status":"draft","note":"ਦਸ ਚਾਰ: the fourteen sciences. ਅਸੁਰਾਰਿ: 'enemy of demons', Vishnu. ਚਤੁਰ ਚਕ: read as 'four quarters'; uncertain."},{"gurmukhi":"ਆਹਵ ਜੁਕਤਿ ਜਿਤੀਕ ਹੁਤੀ ਜਗ ਸਰਬਨ ਮੈ ਸਬ ਹੀ ਅਨੁਮਾਨ੍ਯੋ।","roman":"Aahav jukti jiteek hutee jag sarban mai sab hee anumaanyo |","meaning_en":"Every skill of war there was in the world, he grasped them all;","page":864,"meaning_status":"draft"},{"gurmukhi":"ਦੇਸਿ ਬਿਦੇਸਨ ਜੀਤ ਜੁਧਾਂਬਰ ਕ੍ਰਿਤ ਚੰਦੋਵ ਦਸੋ ਦਿਸ ਤਾਨ੍ਯੋ।","roman":"Desi bidesan jeet judhaanbar krit chandov daso dis taanyo |","meaning_en":"conquering lands near and far in battle, he stretched the canopy of his fame over the ten directions;","page":864,"meaning_status":"draft","note":"ਜੁਧਾਂਬਰ ਕ੍ਰਿਤ ਚੰਦੋਵ: read as 'canopy of glory won in war'; uncertain."},{"gurmukhi":"ਦੇਵਨ ਇੰਦ੍ਰ ਗੋਪੀਨ ਗੋਬਿੰਦ ਨਿਸਾ ਕਰਿ ਚੰਦ ਸਮਾਨ ਪਛਾਨ੍ਯੋ। ੧੯।","roman":"Devan indr gopeen gobind nisaa kari chand samaan pachhaanyo | 19 |","meaning_en":"the gods knew him as Indra, the gopis as Gobind (Krishna), the night as the moon.","page":864,"meaning_status":"draft","note":"ਨਿਸਾ ਕਰਿ: may also be 'nishakar', the moon. Uncertain."}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":865,"lines":[{"gurmukhi":"ਚਉਧਿਤ ਚਾਰ ਦਿਸਾ ਭਈ ਚਕ੍ਰਤ ਭੂਮਿ ਅਕਾਸ ਦੁਹੂੰ ਪਹਿਚਾਨਾ।","roman":"Chaudhit chaar disaa bhaee chakrat bhoomi akaas duhoon pahichaanaa |","meaning_en":"The four directions were dazzled and astonished; earth and sky both recognised him;","page":865,"meaning_status":"draft"},{"gurmukhi":"ਜੁਧ ਸਮਾਨ ਲਖ੍ਯੋ ਜਗ ਜੋਧਨ ਬੋਧਨ ਬੋਧ ਮਹਾ ਅਨੁਮਾਨਾ।","roman":"Judh samaan lakhyo jag jodhan bodhan bodh mahaa anumaanaa |","meaning_en":"the warriors of the world saw him as war itself; the learned took him to be great wisdom;","page":865,"meaning_status":"draft"},{"gurmukhi":"ਸੂਰ ਸਮਾਨ ਲਖਾ ਦਿਨ ਕੈ ਤਿਹ ਚੰਦ ਸਰੂਪ ਨਿਸਾ ਪਹਿਚਾਨਾ।","roman":"Soor samaan lakhaa din kai tih chand saroop nisaa pahichaanaa |","meaning_en":"by day they saw him as the sun; by night they knew him as the moon in form;","page":865,"meaning_status":"draft"},{"gurmukhi":"ਰਾਨਨਿ ਰਾਵਿ ਸਵਾਨਿਨ ਸਾਵ ਭਵਾਨਿਨ ਭਾਵ ਭਲੋ ਮਨਿ ਮਾਨਾ। ੨੦।","roman":"Raanni raavi savaanin saav bhavaanin bhaav bhalo mani maanaa | 20 |","meaning_en":"the queens took him as their king, the wives as their husband, the Bhavanis as Bhav (Shiva); all deemed him good at heart.","page":865,"meaning_status":"draft","note":"ਸਵਾਨਿਨ ਸਾਵ, ਭਵਾਨਿਨ ਭਾਵ: read as 'wives / husband' and 'Bhavanis / Bhav (Shiva)'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":865,"meaning_status":"draft"},{"type":"verse","number":[21],"number_text":"੨੧।","page":865,"lines":[{"gurmukhi":"ਬਿਤੈ ਬਰਖ ਦ੍ਵੈ ਅਸਟ ਮਾਸੰ ਪ੍ਰਮਾਨੰ। ਭਯੋ ਸੁਪ੍ਰਭੰ ਸਰਬ ਬਿਦ੍ਯਾ ਨਿਧਾਨੰ।","roman":"Bitai barakh dvai asat maasan pramaanan | bhayo suprabhan sarab bidyaa nidhaanan |","meaning_en":"When two years and eight months had passed, the radiant one became a treasury of all learning;","page":865,"meaning_status":"draft"},{"gurmukhi":"ਜਪੈ ਹਿੰਗੁਲਾ ਠਿੰਗੁਲਾ ਪਾਣ ਦੇਵੀ। ਅਨਾਸਾ ਛੁਧਾ ਅਤ੍ਰਧਾਰੀ ਅਭੇਵੀ। ੨੧।","roman":"Japai hingulaa thingulaa paan devee | anaasaa chhudhaa atradhaaree abhevee | 21 |","meaning_en":"he meditated on Hingula, Thingula, the goddess with (weapons) in hand, beyond hunger, armed with weapons, the mysterious one;","page":865,"meaning_status":"draft","note":"Hingula: the goddess of Hinglaj. Thingula: a goddess-name; unclear. ਅਨਾਸਾ ਛੁਧਾ: read as 'free of hunger' (or 'without hope or hunger'); uncertain."}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":865,"lines":[{"gurmukhi":"ਜਪੈ ਤੋਤਲਾ ਸੀਤਲਾ ਖਗ ਤਾਨੀ। ਭ੍ਰਮਾ ਭੈਹਰੀ ਭੀਮ ਰੂਪਾ ਭਵਾਣੀ।","roman":"Japai totlaa seetlaa khag taanee | bhramaa bhaihree bheem roopaa bhavaanee |","meaning_en":"he meditated on Totla, Sitala, she who wields the sword, Bhrama, the remover of fear, Bhavani of terrible form;","page":865,"meaning_status":"draft","note":"ਖਗ ਤਾਨੀ: read as 'who draws the sword (or bow)'; uncertain."},{"gurmukhi":"ਚਲਾਚਲ ਸਿੰਘ ਝਮਾਝੰਮ ਅਤ੍ਰੰ। ਹਹਾ ਹੂਹਿ ਹਾਸੰ ਝਲਾ ਝਲ ਛਤ੍ਰੰ। ੨੨।","roman":"Chalaachal singh jhamaajhanm atran | hahaa hoohi haasan jhalaa jhal chhatran | 22 |","meaning_en":"her lion moving, her weapons gleaming, laughing aloud \"ha ha hu hu\", her canopy swaying;","page":865,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":865,"lines":[{"gurmukhi":"ਅਟਾ ਅਟ ਹਾਸੰ ਛਟਾ ਛੁਟ ਕੇਸੰ। ਅਸੰ ਓਧ ਪਾਣੰ ਨਮੋ ਕ੍ਰੂਰ ਭੇਸੰ।","roman":"Ataa at haasan chhataa chhut kesan | asan odh paanan namo kroor bhesan |","meaning_en":"roaring with laughter, her hair loose and flowing, sword in hand; salutation to her of fierce guise;","page":865,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਅਸੰ ਓਧ ਪਾਣੰ: read as 'sword in hand'; ਓਧ unclear."},{"gurmukhi":"ਸਿਰੰਮਾਲ ਸ੍ਵਛੰ ਲਸੈ ਦੰਤ ਪੰਤੰ। ਭਜੈ ਸਤ੍ਰੂ ਗੂੜੰ ਪ੍ਰਫੁਲੰਤ ਸੰਤੰ। ੨੩।","roman":"Siranmaal svachhan lasai dant pantan | bhajai satroo gooran praphulant santan | 23 |","meaning_en":"a bright garland of heads, her row of teeth shining; the enemies flee into hiding, the saints rejoice.","page":865,"meaning_status":"draft","note":"ਗੂੜੰ: read as 'into hiding'; uncertain."}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":865,"lines":[{"gurmukhi":"ਅਲਿੰਪਾਤਿ ਅਰਧੀ ਮਹਾ ਰੂਪ ਰਾਜੈ। ਮਹਾ ਜੋਤ ਜ੍ਵਾਲੰ ਕਰਾਲੰ ਬਿਰਾਜੈ।","roman":"Alinpaati ardhee mahaa roop raajai | mahaa jot jvaalan karaalan biraajai |","meaning_en":"her great form shines ..., her great blazing light shines terrible;","page":865,"meaning_status":"draft","note":"ਅਲਿੰਪਾਤਿ ਅਰਧੀ: unclear; perhaps 'untouched' (alipt) and 'worshipped'. Left untranslated."},{"gurmukhi":"ਤ੍ਰਸੈ ਦੁਸਟ ਪੁਸਟੰ ਹਸੈ ਸੁਧ ਸਾਧੰ। ਭਜੈ ਪਾਨ ਦੁਰਗਾ ਅਰੂਪੀ ਅਗਾਧੰ। ੨੪।","roman":"Trasai dusat pustan hasai sudh saadhan | bhajai paan durgaa aroopee agaadhan | 24 |","meaning_en":"the wicked and mighty tremble, the pure saints laugh; (Parasnath) worships Durga, formless and unfathomable, with folded hands.","page":865,"meaning_status":"draft","note":"ਭਜੈ ਪਾਨ: 'worships with hands (joined)'; uncertain."}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":865,"lines":[{"gurmukhi":"ਸੁਨੇ ਉਸਤਤੀ ਭੀ ਭਵਾਨੀ ਕ੍ਰਿਪਾਲੰ। ਅਧੰ ਉਰਧਵੀ ਆਪ ਰੂਪੀ ਰਸਾਲੰ।","roman":"Sune usattee bhee bhavaanee kripaalan | adhan uradhvee aap roopee rasaalan |","meaning_en":"Hearing the praise, the compassionate Bhavani was pleased, she who is below and above, beautiful in her own form;","page":865,"meaning_status":"draft","note":"ਭੀ: read as 'became (pleased)'. ਅਧੰ ਉਰਧਵੀ: 'below and above', i.e. all-pervading; uncertain."},{"gurmukhi":"ਦਏ ਇਖ੍ਵਧੀ ਦ੍ਵੈ ਅਭੰਗੰ ਖਤੰਗੰ। ਪਰਸ੍ਯੰ ਧਰੰ ਜਾਨ ਲੋਹੰ ਸੁਰੰਗੰ। ੨੫।","roman":"Dae ikhvadhee dvai abhangan khatangan | parsyan dharan jaan lohan surangan | 25 |","meaning_en":"she gave two quivers and unbreakable arrows, and an axe, as if of fine-coloured steel.","page":865,"meaning_status":"draft","note":"ਪਰਸ੍ਯੰ: axe (parsa). ਜਾਨ ਲੋਹੰ ਸੁਰੰਗੰ: read as 'like steel of fine colour'; uncertain."}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":865,"lines":[{"gurmukhi":"ਜਬੈ ਸਸਤ੍ਰ ਸਾਧੀ ਸਬੈ ਸਸਤ੍ਰ ਪਾਏ। ਉਘਾਰੇ ਚੂਮੇ ਕੰਠ ਸੀਸੰ ਛੁਹਾਏ।","roman":"Jabai sasatr saadhee sabai sasatr paae | ughaare choome kanth seesan chhuhaae |","meaning_en":"When he received all the weapons, the master of arms unsheathed them, kissed them, and touched them to his throat and head.","page":865,"meaning_status":"draft"},{"gurmukhi":"ਲਖ੍ਯੋ ਸਰਬ ਰਾਵੰ ਪ੍ਰਭਾਵੰ ਅਪਾਰੰ। ਅਜੋਨੀ ਅਜੈ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੰ। ੨੬।","roman":"Lakhyo sarab raavan prabhaavan apaaran | ajonee ajai bed bidiaa bichaaran | 26 |","meaning_en":"All the kings saw his boundless power, (as of one) unborn, unconquerable, a thinker on Vedic learning.","page":865,"meaning_status":"draft"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":866,"lines":[{"gurmukhi":"ਗ੍ਰਿਹੀਤੁਆ ਜਬੈ ਸਸਤ੍ਰ ਅਸਤ੍ਰੰ ਅਪਾਰੰ। ਪੜੇ ਅਨੁਭਵੰ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੰ।","roman":"Griheetuaa jabai sasatr astran apaaran | pare anubhvan bed bidiaa bichaaran |","meaning_en":"When he had taken up countless weapons, he read with insight and pondered Vedic learning;","page":866,"meaning_status":"draft"},{"gurmukhi":"ਪੜੇ ਸਰਬ ਬਿਦਿਆ ਹੁਤੀ ਸਰਬ ਦੇਸੰ। ਜਿਤੇ ਸਰਬ ਦੇਸੀ ਸੁ ਅਸਤ੍ਰੁੰ ਨਰੇਸੰ। ੨੭।","roman":"Pare sarab bidiaa hutee sarab desan | jite sarab desee su astrun naresan | 27 |","meaning_en":"he studied all the learning there was in every land, and with weapons he conquered the kings of every land.","page":866,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":866,"lines":[{"gurmukhi":"ਪਠੇ ਕਾਗਦੰ ਦੇਸ ਦੇਸੰ ਆਪਰੀ। ਕਰੋ ਆਨਿ ਕੈ ਬੇਦ ਬਿਦ੍ਯਾ ਬਿਚਾਰੀ।","roman":"Pathe kaagdan des desan aapree | karo aani kai bed bidyaa bichaaree |","meaning_en":"He sent letters to land after land: \"Come and hold discourse on Vedic learning\";","page":866,"meaning_status":"draft","note":"ਆਪਰੀ: printed so; read as 'apaari', boundless (countless lands), or 'his own'. Uncertain."},{"gurmukhi":"ਜਟੇ ਦੰਡ ਮੁੰਡੀ ਤਪੀ ਬ੍ਰਹਮਚਾਰੀ। ਸਧੀ ਸ੍ਰਾਵਗੀ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੀ। ੨੮।","roman":"Jate dand mundee tapee brahamchaaree | sadhee sraavgee bed bidiaa bichaaree | 28 |","meaning_en":"the matted-haired, the staff-bearers, the shaven-headed, ascetics, celibates, siddhas and Jain Shravaks, thinkers on Vedic learning.","page":866,"meaning_status":"draft","note":"ਸਧੀ: read as 'siddhas/adepts'; ਸ੍ਰਾਵਗੀ: Jain lay followers. Uncertain."}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":866,"lines":[{"gurmukhi":"ਹਕਾਰੇ ਸਬੈ ਦੇਸ ਦੇਸਾ ਨਰੇਸੰ। ਬੁਲਾਏ ਸਬੈ ਮੋਨ ਮਾਨੀ ਸੁ ਬੇਸੰ।","roman":"Hakaare sabai des desaa naresan | bulaae sabai mon maanee su besan |","meaning_en":"He summoned all the kings of every land; he called all the silent sages in their garbs;","page":866,"meaning_status":"draft","note":"ਮੋਨ ਮਾਨੀ: those who keep silence."},{"gurmukhi":"ਜਟਾ ਧਾਰ ਜੇਤੇ ਕਹੂੰ ਦੇਖ ਪਈਯੈ। ਬੁਲਾਵੈ ਤਿਸੈ ਨਾਥ ਭਾਖੈ ਬੁਲਈਯੈ। ੨੯।","roman":"Jataa dhaar jete kahoon dekh paeeyai | bulaavai tisai naath bhaakhai bulaeeyai | 29 |","meaning_en":"\"Every matted-haired one who is seen anywhere, call him,\" so the lord said, \"let him be called.\"","page":866,"meaning_status":"draft"}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":866,"lines":[{"gurmukhi":"ਫਿਰੇ ਸਰਬ ਦੇਸੰ ਨਰੇਸੰ ਬੁਲਾਵੈ। ਮਿਲੇ ਨ ਤਿਸੈ ਛਤ੍ਰ ਛੈਣੀ ਛਿਨਾਵੈ।","roman":"Phire sarab desan naresan bulaavai | mile na tisai chhatr chhainee chhinaavai |","meaning_en":"(His men) went round all lands, calling the kings; whoever did not come had his canopy (of rule) snatched away;","page":866,"meaning_status":"draft","note":"ਛੈਣੀ ਛਿਨਾਵੈ: 'snatched by force'; ਛੈਣੀ unclear (chisel?). Uncertain."},{"gurmukhi":"ਪਠੇ ਪਤ੍ਰ ਏਕੈ ਦਿਸਾ ਏਕ ਧਾਵੈ। ਜਟੀ ਦੰਡ ਮੁੰਡੀ ਕਹੂੰ ਹਾਥ ਆਵੈ। ੩੦।","roman":"Pathe patr ekai disaa ek dhaavai | jatee dand mundee kahoon haath aavai | 30 |","meaning_en":"he sent letters, one messenger rushing in each direction, so that the matted-haired, staff-bearing and shaven ascetics, wherever they were, might be brought in.","page":866,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":866,"lines":[{"gurmukhi":"ਰਚ੍ਯੋ ਜਗ ਰਾਜਾ ਚਲੇ ਸਰਬ ਜੋਗੀ। ਜਹਾ ਲਉ ਕੋਈ ਬੂਢ ਬਾਰੋ ਸਭੋਗੀ।","roman":"Rachyo jag raajaa chale sarab jogee | jahaa lau koee boodh baaro sabhogee |","meaning_en":"The king arranged a sacrificial feast and all the yogis set out, as many as there were, old and young, and householders;","page":866,"meaning_status":"draft","note":"ਜਗ: yagya. ਸਭੋਗੀ: read as 'householders / those who enjoy the world'; uncertain."},{"gurmukhi":"ਕਹਾ ਰੰਕ ਰਾਜਾ ਕਹਾ ਨਾਰ ਹੋਈ। ਰਚ੍ਯੋ ਜਗ ਰਾਜਾ ਚਲਿਓ ਸਰਬ ਕੋਈ। ੩੧।","roman":"Kahaa rank raajaa kahaa naar hoee | rachyo jag raajaa chalio sarab koee | 31 |","meaning_en":"whether pauper or king, or woman, the king had arranged a feast and everyone came.","page":866,"meaning_status":"draft"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":866,"lines":[{"gurmukhi":"ਫਿਰੇ ਪਤ੍ਰ ਸਰਬਤ੍ਰ ਦੇਸੰ ਅਪਾਰੰ। ਜੁਰੇ ਸਰਬ ਰਾਜਾ ਨ੍ਰਿਪੰ ਆਨਿ ਦੁਆਰੰ।","roman":"Phire patr sarbatr desan apaaran | jure sarab raajaa nripan aani duaaran |","meaning_en":"Letters went everywhere through countless lands; all the kings gathered at the king's door;","page":866,"meaning_status":"draft"},{"gurmukhi":"ਜਹਾ ਲੌ ਹੁਤੇ ਜਗਤ ਮੈ ਜਟਾਧਾਰੀ। ਮਿਲੈ ਰੋਹ ਦੇਸੰ ਭਏ ਭੇਖ ਭਾਰੀ। ੩੨।","roman":"Jahaa lau hute jagat mai jataadhaaree | milai roh desan bhae bhekh bhaaree | 32 |","meaning_en":"as many matted-haired ascetics as there were in the world met in the land of Roh; it became a vast gathering of garbs.","page":866,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":866,"lines":[{"gurmukhi":"ਜਹਾ ਲਉ ਹੁਤੇ ਜੋਗ ਜੋਗਿਸਟ ਸਾਧੇ। ਮਲੇ ਮੁਖ ਬਿਭੂਤੰ ਸੁ ਲੰਗੋਟ ਬਾਧੇ।","roman":"Jahaa lau hute jog jogisat saadhe | male mukh bibhootan su langot baadhe |","meaning_en":"All who practised yoga and the yogic disciplines, their faces smeared with ash and loincloths tied,","page":866,"meaning_status":"draft"},{"gurmukhi":"ਜਟਾ ਸੀਸ ਧਾਰੇ ਨਿਹਾਰੇ ਅਪਾਰੰ। ਮਹਾ ਜੋਗ ਧਾਰੰ ਸੁਬਿਦਿਆ ਬਿਚਾਰੰ। ੩੩।","roman":"Jataa sees dhaare nihaare apaaran | mahaa jog dhaaran subidiaa bichaaran | 33 |","meaning_en":"with matted hair on their heads, were seen without number, great yogis and thinkers on learning.","page":866,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":866,"lines":[{"gurmukhi":"ਜਿਤੇ ਸਰਬ ਭੂਪੰ ਬੁਲੇ ਸਰਬ ਰਾਜਾ। ਚਹੂੰ ਚਕ ਮੋ ਦਾਨ ਨੀਸਾਨ ਬਾਜਾ।","roman":"Jite sarab bhoopan bule sarab raajaa | chahoon chak mo daan neesaan baajaa |","meaning_en":"All the kings and rulers who had been summoned came; in the four quarters the drum of charity sounded;","page":866,"meaning_status":"draft"},{"gurmukhi":"ਮਿਲੇ ਦੇਸ ਦੇਸਾਨ ਅਨੇਕ ਮੰਤ੍ਰੀ। ਕਰੈ ਸਾਧਨਾ ਜੋਗ ਬਾਜੰਤ੍ਰ ਤੰਤ੍ਰੀ। ੩੪।","roman":"Mile des desaan anek mantree | karai saadhnaa jog baajantr tantree | 34 |","meaning_en":"many ministers from land after land met; they practised yoga, with music of instruments and strings.","page":866,"meaning_status":"draft","note":"ਬਾਜੰਤ੍ਰ ਤੰਤ੍ਰੀ: read as 'instruments and stringed instruments'; may also be 'spells and charms'. Uncertain."}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":866,"lines":[{"gurmukhi":"ਜਿਤੇ ਸਰਬ ਭੂਮਿ ਸਥਲੀ ਸੰਤ ਆਹੇ। ਤਿਤੇ ਸਰਬ ਪਾਰਸ ਨਾਥੰ ਬੁਲਾਏ।","roman":"Jite sarab bhoomi sathlee sant aahe | tite sarab paaras naathan bulaae |","meaning_en":"All the saints there were in every land and place, Parasnath summoned them all;","page":866,"meaning_status":"draft"},{"gurmukhi":"ਦਏ ਭਾਤਿ ਅਨੇਕ ਭੋਜ ਅਰਘ ਦਾਨੰ। ਲਜੀ ਪੇਖ ਦੇਵਿ ਸਥਲੀ ਮੋਨ ਮਾਨੰ। ੩੫।","roman":"Dae bhaati anek bhoj aragh daanan | lajee pekh devi sathlee mon maanan | 35 |","meaning_en":"he gave many kinds of food, offerings and gifts; seeing it, the abode of the gods was abashed and fell silent.","page":866,"meaning_status":"draft","note":"ਲਜੀ ਪੇਖ ਦੇਵਿ ਸਥਲੀ ਮੋਨ ਮਾਨੰ: read as above; may also mean 'the gods and the silent sages felt shame'. Uncertain."}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":866,"lines":[{"gurmukhi":"ਕਰੈ ਬੈਠ ਕੇ ਬੇਦ ਬਿਦਿਆ ਬਿਚਾਰੰ। ਪ੍ਰਕਾਸੋ ਸਬੈ ਆਪੁ ਆਪੰ ਪ੍ਰਕਾਰੰ।","roman":"Karai baith ke bed bidiaa bichaaran | prakaaso sabai aapu aapan prakaaran |","meaning_en":"Sitting down, they pondered Vedic learning; each expounded it in his own way;","page":866,"meaning_status":"draft"},{"gurmukhi":"ਟਕੰ ਟਕ ਲਾਗੀ ਮੁਖੰ ਮੁਖਿ ਪੇਖਿਓ। ਸੁਨ੍ਯੋ ਕਾਨ ਹੋ ਤੋ ਸੁ ਤੋ ਆਖਿ ਦੇਖਿਓ। ੩੬।","roman":"Takan tak laagee mukhan mukhi pekhio | sunyo kaan ho to su to aakhi dekhio | 36 |","meaning_en":"they stared fixedly at one another, face to face; what had been heard with the ears was now seen with the eyes.","page":866,"meaning_status":"draft"}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":867,"lines":[{"gurmukhi":"ਪ੍ਰਕਾਸੋ ਸਬੈ ਆਪ ਆਪੰ ਪੁਰਾਣੰ। ਰੜੋ ਦੇਸਿ ਦੇਸਾਣ ਬਿਦਿਆ ਮੁਹਾਣੰ।","roman":"Prakaaso sabai aap aapan puraanan | raro desi desaan bidiaa muhaanan |","meaning_en":"Each expounded his own Purana; the masters of learning from land after land recited;","page":867,"meaning_status":"draft","note":"ਮੁਹਾਣੰ: read as 'leaders / masters'; uncertain."},{"gurmukhi":"ਕਰੋ ਭਾਤਿ ਭਾਤੰ ਸੁ ਬਿਦਿਆ ਬਿਚਾਰੰ। ਨ੍ਰਿਭੈ ਚਿਤ ਦੈ ਕੈ ਮਹਾ ਤ੍ਰਾਸ ਟਾਰੰ। ੩੭।","roman":"Karo bhaati bhaatan su bidiaa bichaaran | nribhai chit dai kai mahaa traas taaran | 37 |","meaning_en":"\"Hold discourse on learning in every way; make your minds fearless and cast off great dread.\"","page":867,"meaning_status":"draft","note":"Read as the king's call to the gathering; could also be narrative ('they discoursed, fearless'). Uncertain."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":867,"lines":[{"gurmukhi":"ਜੁਰੇ ਬੰਗਸੀ ਰਾਫਿਜੀ ਰੋਹਿ ਰੂਮੀ। ਚਲੇ ਬਾਲਖੀ ਛਾਡ ਕੈ ਰਾਜ ਭੂਮੀ।","roman":"Jure bangsee raaphijee rohi roomee | chale baalkhee chhaad kai raaj bhoomee |","meaning_en":"There gathered men of Bangash, Rafizis, men of Roh and of Rum; men of Balkh came, leaving their kingdoms;","page":867,"meaning_status":"draft","note":"ਰਾਫਿਜੀ: Rafizi, a Persian term for Shia Muslims. ਰੂਮੀ: of Rum (Anatolia)."},{"gurmukhi":"ਨ੍ਰਿਭੈ ਭਿੰਭਰੀ ਕਾਸਮੀਰੀ ਕੰਧਾਰੀ। ਕਿ ਕੈ ਕਾਲਮਾਖੀ ਕਸੇ ਕਾਸਕਾਰੀ। ੩੮।","roman":"Nribhai bhinbhree kaasmeeree kandhaaree | ki kai kaalmaakhee kase kaaskaaree | 38 |","meaning_en":"fearless men of Bhimbar, Kashmiris, Kandharis, and Kalmaks, and those of Kashghar.","page":867,"meaning_status":"draft","note":"ਕਾਲਮਾਖੀ: read as Kalmaks (Kalmyks); ਕਸੇ ਕਾਸਕਾਰੀ: read as 'those of Kashghar'; uncertain."}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":867,"lines":[{"gurmukhi":"ਜੁਰੇ ਦਛਣੀ ਸਸਤ੍ਰ ਬੇਤਾ ਅਰਯਾਰੇ। ਦ੍ਰੁਜੈ ਦ੍ਰਾਵੜੀ ਤਪਤ ਤਈਲੰਗ ਵਾਰੇ।","roman":"Jure dachhnee sasatr betaa aryaare | drujai draavree tapat taeelang vaare |","meaning_en":"There gathered southerners, skilled in weapons and fierce in fight; Dravidians and men of hot Tailang;","page":867,"meaning_status":"draft","note":"ਅਰਯਾਰੇ: read as 'quarrelsome, fierce'; ਦ੍ਰੁਜੈ: unclear. ਤਈਲੰਗ: Telangana/Telugu country. Uncertain."},{"gurmukhi":"ਪਰੰ ਪੂਰਬੀ ਉਤ੍ਰ ਦੇਸੀ ਅਪਾਰੰ। ਮਿਲੇ ਦੇਸ ਦੇਸੇਣ ਜੋਧਾ ਜੁਝਾਰੰ। ੩੯।","roman":"Paran poorbee utr desee apaaran | mile des desen jodhaa jujhaaran | 39 |","meaning_en":"and beyond them countless easterners and northerners; warriors and fighters met from every land.","page":867,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਪਾਧਰੀ ਛੰਦ","gurmukhi":"ਪਾਧਰੀ ਛੰਦ","roman":"Paadhree chhand","meaning_en":"Padhari metre.","page":867,"meaning_status":"draft"},{"type":"verse","number":[40],"number_text":"੪੦।","page":867,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਬੀਰ ਬਹੁ ਬੀਰ ਜੋਰਿ। ਮਤ ਦੇਸ ਦੇਸ ਰਾਜਾ ਕਰੋਰ।","roman":"Ih bhaati beer bahu beer jori | mat des des raajaa karor |","meaning_en":"In this way he gathered many heroes, and countless kings of different creeds from land after land;","page":867,"meaning_status":"draft","note":"ਮਤ: read as 'creeds'; may be 'intoxicated (proud)'. ਕਰੋਰ: literally 'crores', countless."},{"gurmukhi":"ਦੇ ਹੀਰ ਚੀਰ ਬਹੁ ਦਿਰਬ ਸਾਜ। ਸਨਮਾਨ ਦਾਨ ਬਹੁ ਭਾਤਿ ਰਾਜ। ੪੦।","roman":"De heer cheer bahu dirab saaj | sanmaan daan bahu bhaati raaj | 40 |","meaning_en":"giving diamonds, garments, much wealth and equipment, the king showed honour and gave gifts in many ways.","page":867,"meaning_status":"draft"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":867,"lines":[{"gurmukhi":"ਅਨਭੈ ਅਭੰਗ ਅਵਧੂਤ ਛਤ੍ਰ। ਅਨਜੀਤ ਜੁਧ ਬੇਤਾ ਅਤਿ ਅਤ੍ਰ।","roman":"Anbhai abhang avdhoot chhatr | anjeet judh betaa ati atr |","meaning_en":"Fearless, unbreakable avadhuts and Kshatriyas, unconquered, skilled in war and great with weapons;","page":867,"meaning_status":"draft"},{"gurmukhi":"ਅਨਗੰਜ ਸੂਰ ਅਬਿਚਲ ਜੁਝਾਰ। ਰਣ ਰੰਗ ਅਭੰਗ ਜਿਤੇ ਹਜਾਰ। ੪੧।","roman":"Anganj soor abichal jujhaar | ran rang abhang jite hajaar | 41 |","meaning_en":"unvanquished heroes, steadfast fighters; unbroken in the fray of battle, he conquered thousands of them.","page":867,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":867,"lines":[{"gurmukhi":"ਸਬ ਦੇਸ ਦੇਸ ਕੇ ਜੀਤ ਰਾਵ। ਕਰ ਕ੍ਰੁਧ ਜੁਧ ਨਾਨਾ ਉਪਾਵ।","roman":"Sab des des ke jeet raav | kar krudh judh naanaa upaav |","meaning_en":"Conquering the kings of every land, waging war in wrath by many means,","page":867,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਸਾਮ ਦਾਮ ਅਰੁ ਦੰਡ ਭੇਦ। ਅਵਨੀਪ ਸਰਬ ਜੋਰੇ ਅਛੇਦ। ੪੨।","roman":"Kai saam daam aru dand bhed | avneep sarab jore achhed | 42 |","meaning_en":"by conciliation, gifts, punishment and division (sam, dam, dand, bhed), he gathered together all the rulers of the earth, firmly.","page":867,"meaning_status":"draft","note":"ਅਛੇਦ: 'unbreakable', read as 'firmly bound'."}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":867,"lines":[{"gurmukhi":"ਜਬ ਸਰਬ ਭੂਪ ਜੋਰੇ ਮਹਾਨ। ਜੈ ਜੀਤ ਪਤ੍ਰ ਦਿਨੋ ਨਿਸਾਨ।","roman":"Jab sarab bhoop jore mahaan | jai jeet patr dino nisaan |","meaning_en":"When he had gathered all the great kings, he gave them letters of victory and banners;","page":867,"meaning_status":"draft","note":"ਨਿਸਾਨ: banner or drum."},{"gurmukhi":"ਦੈ ਹੀਰ ਚੀਰ ਅਨਭੰਗ ਦਿਰਬ। ਮਹਿਪਾਲ ਮੋਹਿ ਡਾਰੇ ਸੁ ਸਰਬ। ੪੩।","roman":"Dai heer cheer anbhang dirab | mahipaal mohi daare su sarab | 43 |","meaning_en":"giving diamonds, garments and endless wealth, he enchanted all the rulers.","page":867,"meaning_status":"draft"}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":867,"lines":[{"gurmukhi":"ਇਕ ਦਯੋ੍ਸ ਬੀਤ ਪਾਰਸ੍ਵ ਰਾਇ। ਉਤਿਸਟ ਦੇਵਿ ਪੂਜੰਤ ਜਾਇ।","roman":"Ik dayso beet paarasv raai | utisat devi poojant jaai |","meaning_en":"One day passed; then King Paras rose and went to worship the goddess;","page":867,"meaning_status":"draft","note":"ਦਯੋ੍ਸ: printed so; read as 'day'. ਉਤਿਸਟ: read as 'rose up' (uttishth); uncertain."},{"gurmukhi":"ਉਸਤਤਿ ਕਿਨ ਬਹੁ ਬਿਧਿ ਪ੍ਰਕਾਰ। ਸੋ ਕਹੋ ਛੰਦ ਮੋਹਣਿ ਮਝਾਰ। ੪੪।","roman":"Usatti kin bahu bidhi prakaar | so kaho chhand mohni majhaar | 44 |","meaning_en":"he praised her in many ways; I tell it in the Mohani metre.","page":867,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਮੋਹਣੀ ਛੰਦ","gurmukhi":"ਮੋਹਣੀ ਛੰਦ","roman":"Mohnee chhand","meaning_en":"Mohani metre.","page":867,"meaning_status":"draft"},{"type":"verse","number":[45],"number_text":"੪੫।","page":867,"lines":[{"gurmukhi":"ਜੈ ਦੇਵੀ ਭੇਵੀ ਭਾਵਾਣੀ। ਭਉ ਖੰਡੀ ਦੁਰਗਾ ਸਰਬਾਣੀ।","roman":"Jai devee bhevee bhaavaanee | bhau khandee durgaa sarbaanee |","meaning_en":"Hail, goddess, mysterious Bhavani, destroyer of fear, Durga, Sarbani;","page":867,"meaning_status":"draft","note":"ਸਰਬਾਣੀ: Sharvani, consort of Shiva."},{"gurmukhi":"ਕੇਸਰੀਆ ਬਾਹੀ ਕਊਮਾਰੀ। ਭੈਖੰਡੀ ਭੈਰਵਿ ਉਧਾਰੀ। ੪੫।","roman":"Kesreeaa baahee kaoomaaree | bhaikhandee bhairvi udhaaree | 45 |","meaning_en":"rider of the lion, the maiden, destroyer of fear, Bhairavi, deliverer.","page":867,"meaning_status":"draft"}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":867,"lines":[{"gurmukhi":"ਅਕਲੰਕਾ ਅਤ੍ਰੀ ਛਤ੍ਰਾਣੀ। ਮੋਹਣੀਅੰ ਸਰਬੰ ਲੋਕਾਣੀ।","roman":"Aklankaa atree chhatraanee | mohneean sarban lokaanee |","meaning_en":"Stainless, bearer of weapons, Kshatrani; enchantress of all the worlds;","page":867,"meaning_status":"draft"},{"gurmukhi":"ਰਕਤਾਂਗੀ ਸਾਂਗੀ ਸਾਵਿਤ੍ਰੀ। ਪਰਮੇਸ੍ਰੀ ਪਰਮਾ ਪਾਵਿਤ੍ਰੀ। ੪੬।","roman":"Raktaangee saangee saavitree | parmesree parmaa paavitree | 46 |","meaning_en":"red-limbed, bearer of the lance, Savitri; supreme lady, supreme and pure.","page":867,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":868,"lines":[{"gurmukhi":"ਤੋਤਲੀਆ ਜਿਹਬਾ ਕਊਮਾਰੀ। ਭਵ ਭਰਣੀ ਹਰਣੀ ਉਧਾਰੀ।","roman":"Totleeaa jihbaa kaoomaaree | bhav bharnee harnee udhaaree |","meaning_en":"Of lisping tongue, the maiden; sustainer and destroyer of the world, the deliverer;","page":868,"meaning_status":"draft"},{"gurmukhi":"ਮ੍ਰਿਦੁ ਰੂਪਾ ਭੂਪਾ ਬੁਧਾਣੀ। ਜੈ ਜੰਪੈ ਸੁਧੰ ਸਿਧਾਣੀ। ੪੭।","roman":"Mridu roopaa bhoopaa budhaanee | jai janpai sudhan sidhaanee | 47 |","meaning_en":"gentle of form, queen, wise one; the pure siddhas chant your victory.","page":868,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":868,"lines":[{"gurmukhi":"ਜਗ ਧਾਰੀ ਭਾਰੀ ਭਗਤਾਯੰ। ਕਰਿ ਧਾਰੀ ਭਾਰੀ ਮੁਕਤਾਯੰ।","roman":"Jag dhaaree bhaaree bhagtaayan | kari dhaaree bhaaree muktaayan |","meaning_en":"Upholder of the world, great to her devotees; who holds great liberation in her hand;","page":868,"meaning_status":"draft","note":"ਕਰਿ ਧਾਰੀ ਭਾਰੀ ਮੁਕਤਾਯੰ: read as 'who confers great liberation'; may be 'who wears great pearls'. Uncertain."},{"gurmukhi":"ਸੁੰਦਰ ਗੋਫਣੀਆ ਗੁਰਜਾਣੀ। ਤੇ ਬਰਣੀ ਹਰਣੀ ਭਾਮਾਣੀ। ੪੮।","roman":"Sundar gophneeaa gurjaanee | te barnee harnee bhaamaanee | 48 |","meaning_en":"beautiful, with sling and mace; fair of hue, the destroyer, the lady.","page":868,"meaning_status":"draft","note":"ਤੇ ਬਰਣੀ: read as 'of bright hue'; uncertain."}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":868,"lines":[{"gurmukhi":"ਭਿੰਭਰੀਆ ਜਛੰ ਸਰਬਾਣੀ। ਗੰਧਰਬੀ ਸਿਧੰ ਚਾਰਾਣੀ।","roman":"Bhinbhreeaa jachhan sarbaanee | gandharbee sidhan chaaraanee |","meaning_en":"Bhimbharia, mistress of all the Yakshas; Gandharvi, of the siddhas and charans;","page":868,"meaning_status":"draft","note":"ਭਿੰਭਰੀਆ: a goddess-name, unclear (perhaps 'terrible'). Uncertain."},{"gurmukhi":"ਅਕਲੰਕ ਸਰੂਪੰ ਨਿਰਮਲੀਅੰ। ਘਣ ਮਧੇ ਮਾਨੋ ਚੰਚਲੀਅੰ। ੪੯।","roman":"Aklank saroopan niramleean | ghan madhe maano chanchleean | 49 |","meaning_en":"of stainless form, pure, like lightning amidst the clouds.","page":868,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":868,"lines":[{"gurmukhi":"ਅਸਿਪਾਣੰ ਮਾਣੰ ਲੋਕਾਯੰ। ਸੁਖ ਕਰਣੀ ਹਰਣੀ ਸੋਕਾਯੰ।","roman":"Asipaanan maanan lokaayan | sukh karnee harnee sokaayan |","meaning_en":"Sword in hand, the honour of the worlds; giver of joy, remover of sorrow;","page":868,"meaning_status":"draft"},{"gurmukhi":"ਦੁਸਟ ਹੰਤੀ ਸੰਤੰ ਉਧਾਰੀ। ਅਨਛੇਦਾਭੇਦਾ ਕਉਮਾਰੀ। ੫੦।","roman":"Dusat hantee santan udhaaree | anchhedaabhedaa kaumaaree | 50 |","meaning_en":"slayer of the wicked, deliverer of the saints, unbreakable, impenetrable maiden.","page":868,"meaning_status":"draft"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":868,"lines":[{"gurmukhi":"ਆਨੰਦੀ ਗਿਰਜਾ ਕਉਮਾਰੀ। ਅਨਛੇਦਾਭੇਦਾ ਉਧਾਰੀ।","roman":"Aanandee girjaa kaumaaree | anchhedaabhedaa udhaaree |","meaning_en":"Blissful one, Girija, the maiden; unbreakable, impenetrable deliverer;","page":868,"meaning_status":"draft"},{"gurmukhi":"ਅਨਗੰਜ ਅਭੰਜਾ ਖੰਕਾਲੀ। ਮ੍ਰਿਗਨੈਣੀ ਰੂਪੰ ਉਜਾਲੀ। ੫੧।","roman":"Anganj abhanjaa khankaalee | mrignainee roopan ujaalee | 51 |","meaning_en":"unconquerable, indestructible, Khankali; doe-eyed, radiant of form.","page":868,"meaning_status":"draft","note":"ਖੰਕਾਲੀ: a name of Kali."}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":868,"lines":[{"gurmukhi":"ਰਕਤਾਂਗੀ ਰੁਦ੍ਰਾ ਪਿੰਗਾਛੀ। ਕਟਿ ਕਛੀ ਸ੍ਵਛੀ ਹੁਲਾਸੀ।","roman":"Raktaangee rudraa pingaachhee | kati kachhee svachhee hulaasee |","meaning_en":"Red-limbed, Rudra's own, tawny-eyed; with a loincloth at her waist, bright and joyous;","page":868,"meaning_status":"draft"},{"gurmukhi":"ਰਕਤਾਲੀ ਰਾਮਾ ਧਉਲਾਲੀ। ਮੋਹਣੀਆ ਮਾਈ ਖੰਕਾਲੀ। ੫੨।","roman":"Raktaalee raamaa dhaulaalee | mohneeaa maaee khankaalee | 52 |","meaning_en":"red-hued, the beautiful one, white-hued, enchanting Mother Khankali.","page":868,"meaning_status":"draft","note":"ਰਕਤਾਲੀ, ਧਉਲਾਲੀ: read as 'red' and 'white'; uncertain."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":868,"lines":[{"gurmukhi":"ਜਗਦਾਨੀ ਮਾਨੀ ਭਾਵਾਣੀ। ਭਵਖੰਡੀ ਦੁਰਗਾ ਦੇਵਾਣੀ।","roman":"Jagdaanee maanee bhaavaanee | bhavkhandee durgaa devaanee |","meaning_en":"Giver to the world, honoured one, Bhavani; destroyer of the world, Durga, the goddess;","page":868,"meaning_status":"draft"},{"gurmukhi":"ਰੁਦ੍ਰਾਗੀ ਰੁਦ੍ਰਾ ਰਕਤਾਂਗੀ। ਪਰਮੇਸਰੀ ਮਾਈ ਧਰਮਾਂਗੀ। ੫੩।","roman":"Rudraagee rudraa raktaangee | parmesree maaee dharmaangee | 53 |","meaning_en":"consort of Rudra, Rudra herself, red-limbed; supreme lady, Mother whose body is dharma.","page":868,"meaning_status":"draft"}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":868,"lines":[{"gurmukhi":"ਮਹਿਖਾਸੁਰ ਦਰਣੀ ਮਹਿਪਾਲੀ। ਚਿਛੁਰਾਸਰ ਹੰਤੀ ਖੰਕਾਲੀ।","roman":"Mahikhaasur darnee mahipaalee | chichhuraasar hantee khankaalee |","meaning_en":"Slayer of Mahishasur, protectress of the earth; slayer of Chichhurasur, Khankali;","page":868,"meaning_status":"draft","note":"ਚਿਛੁਰਾਸਰ: the demon Chikshur."},{"gurmukhi":"ਅਸਿ ਪਾਣੀ ਮਾਣੀ ਦੇਵਾਣੀ। ਜੈ ਦਾਤੀ ਦੁਰਗਾ ਭਾਵਾਣੀ। ੫੪।","roman":"Asi paanee maanee devaanee | jai daatee durgaa bhaavaanee | 54 |","meaning_en":"sword in hand, honoured goddess; giver of victory, Durga Bhavani.","page":868,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":868,"lines":[{"gurmukhi":"ਪਿੰਗਾਛੀ ਪਰਮਾ ਪਾਵਿਤ੍ਰੀ। ਸਾਵਿਤ੍ਰੀ ਸੰਧਿਆ ਗਾਇਤ੍ਰੀ।","roman":"Pingaachhee parmaa paavitree | saavitree sandhiaa gaaitree |","meaning_en":"Tawny-eyed, supreme, pure; Savitri, Sandhya, Gayatri;","page":868,"meaning_status":"draft"},{"gurmukhi":"ਭੈ ਹਰਣੀ ਭੀਮਾ ਭਾਮਾਣੀ। ਜੈ ਦੇਵੀ ਦੁਰਗਾ ਦੇਵਾਣੀ। ੫੫।","roman":"Bhai harnee bheemaa bhaamaanee | jai devee durgaa devaanee | 55 |","meaning_en":"remover of fear, terrible, the lady; hail, goddess Durga, divine one.","page":868,"meaning_status":"draft"}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":869,"lines":[{"gurmukhi":"ਦੁਰਗਾ ਦਲ ਗਾਹੀ ਦੇਵਾਣੀ। ਭੈ ਖੰਡੀ ਸਰਬੰ ਭੂਤਾਣੀ।","roman":"Durgaa dal gaahee devaanee | bhai khandee sarban bhootaanee |","meaning_en":"Durga who tramples (demon) armies, the goddess; destroyer of the fear of all beings;","page":869,"meaning_status":"draft"},{"gurmukhi":"ਜੈ ਚੰਡੀ ਮੁੰਡੀ ਸਤ੍ਰੁ ਹੰਤੀ। ਜੈ ਦਾਤੀ ਮਾਤਾ ਜੈਅੰਤੀ। ੫੬।","roman":"Jai chandee mundee satru hantee | jai daatee maataa jaiantee | 56 |","meaning_en":"hail Chandi, slayer of Mund, slayer of enemies; hail giver, Mother Jayanti.","page":869,"meaning_status":"draft","note":"ਮੁੰਡੀ: read as 'slayer of Mund'; could be 'wearer of skulls'. Uncertain."}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":869,"lines":[{"gurmukhi":"ਸੰਸਰਣੀ ਤਰਾਣੀ ਲੋਕਾਣੀ। ਭਿੰਭਰਾਣੀ ਦਰਣੀ ਦਈਤਾਣੀ।","roman":"Sansarnee taraanee lokaanee | bhinbhraanee darnee daeetaanee |","meaning_en":"Mover of the world, who ferries the worlds across; Bhimbharani, destroyer of the demons;","page":869,"meaning_status":"draft","note":"ਸੰਸਰਣੀ, ਭਿੰਭਰਾਣੀ: goddess-names; uncertain."},{"gurmukhi":"ਕੇਕਰਣੀ ਕਾਰਣ ਲੋਕਾਣੀ। ਦੁਖ ਹਰਣੀ ਦੇਵੰ ਇੰਦ੍ਰਾਣੀ। ੫੭।","roman":"Kekarnee kaaran lokaanee | dukh harnee devan indraanee | 57 |","meaning_en":"Kekarani, the cause of the worlds; remover of the gods' sorrow, Indrani.","page":869,"meaning_status":"draft","note":"ਕੇਕਰਣੀ: unclear goddess-name. Uncertain."}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":869,"lines":[{"gurmukhi":"ਸੁੰਭ ਹੰਤੀ ਜਯੰਤੀ ਖੰਕਾਲੀ। ਕੰਕੜੀਆ ਰੂਪਾ ਰਕਤਾਲੀ।","roman":"Sunbh hantee jayantee khankaalee | kankreeaa roopaa raktaalee |","meaning_en":"Slayer of Sumbh, Jayanti, Khankali; of terrible form, the red one;","page":869,"meaning_status":"draft","note":"ਕੰਕੜੀਆ: unclear; perhaps 'of the kankar (fierce)'. Uncertain."},{"gurmukhi":"ਤੋਤਲੀਆ ਜਿਹਵਾ ਸਿੰਧੁਲੀਆ। ਹਿੰਗਲੀਆ ਮਾਤਾ ਪਿੰਗਲੀਆ। ੫੮।","roman":"Totleeaa jihvaa sindhuleeaa | hingleeaa maataa pingleeaa | 58 |","meaning_en":"of lisping tongue, Sindhulia, Hinglia the Mother, Pinglia.","page":869,"meaning_status":"draft","note":"Goddess-names (Hinglaj; tawny one); ਸਿੰਧੁਲੀਆ unclear."}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":869,"lines":[{"gurmukhi":"ਚੰਚਾਲੀ ਚਿਤ੍ਰਾ ਚਿਤ੍ਰਾਂਗੀ। ਭਿੰਭਰੀਆ ਭੀਮਾ ਸਰਬਾਂਗੀ।","roman":"Chanchaalee chitraa chitraangee | bhinbhreeaa bheemaa sarbaangee |","meaning_en":"Restless, wondrous, of wondrous limbs; Bhimbharia, terrible, perfect in every limb;","page":869,"meaning_status":"draft"},{"gurmukhi":"ਬੁਧਿ ਭੂਪਾ ਕੂਪਾ ਜੁਜ੍ਵਾਲੀ। ਅਕਲੰਕਾ ਮਾਈ ਨ੍ਰਿਮਾਲੀ। ੫੯।","roman":"Budhi bhoopaa koopaa jujvaalee | aklankaa maaee nrimaalee | 59 |","meaning_en":"queen of wisdom, a well (of it), blazing one; stainless, pure Mother.","page":869,"meaning_status":"draft","note":"ਜੁਜ੍ਵਾਲੀ: read as 'flaming'; uncertain."}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":869,"lines":[{"gurmukhi":"ਉਛਲੈ ਲੰਕੜੁੀਆ ਛਤ੍ਰਾਲਾ। ਭਿੰਭਰੀਆ ਭੈਰੋ ਭਉਹਾਲਾ।","roman":"Uchhlai lankreeaa chhatraalaa | bhinbhreeaa bhairo bhauhaalaa |","meaning_en":"Leaping, Lankaria, bearer of the canopy; Bhimbharia, Bhairo, of fearsome brows;","page":869,"meaning_status":"draft","note":"ਲੰਕੜੁੀਆ: printed so; perhaps the 'langur' (Hanuman) attendant. ਭਉਹਾਲਾ: read as 'fearsome'. Uncertain."},{"gurmukhi":"ਜੈ ਦਾਤਾ ਮਾਤਾ ਜੈਦਾਣੀ। ਲੋਕੇਸੀ ਦੁਰਗਾ ਭਾਵਾਣੀ। ੬੦।","roman":"Jai daataa maataa jaidaanee | lokesee durgaa bhaavaanee | 60 |","meaning_en":"hail giver, Mother, bestower of victory; ruler of the worlds, Durga Bhavani.","page":869,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":869,"lines":[{"gurmukhi":"ਸੰਮੋਹੀ ਸਰਬੰ ਜਗਤਾਯੰ। ਨਿੰਦ੍ਰਾ ਛੁਧ੍ਯਾ ਪਿਪਾਸਾਯੰ।","roman":"Sanmohee sarban jagtaayan | nindraa chhudhyaa pipaasaayan |","meaning_en":"Enchantress of the whole world; you are sleep, hunger and thirst;","page":869,"meaning_status":"draft"},{"gurmukhi":"ਜੈ ਕਾਲੰ ਰਾਤੀ ਸਕ੍ਰਾਣੀ। ਉਧਾਰੀ ਭਾਰੀ ਭਗਤਾਣੀ। ੬੧।","roman":"Jai kaalan raatee sakraanee | udhaaree bhaaree bhagtaanee | 61 |","meaning_en":"hail Kalratri (the dark night), Shakrani; great deliverer of devotees.","page":869,"meaning_status":"draft","note":"ਸਕ੍ਰਾਣੀ: Indra's consort or power."}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":869,"lines":[{"gurmukhi":"ਜੈ ਮਾਈ ਗਾਈ ਬੇਦਾਣੀ। ਅਨਛਿਜ ਅਭਿਦਾ ਅਖਿਦਾਣੀ।","roman":"Jai maaee gaaee bedaanee | anchhij abhidaa akhidaanee |","meaning_en":"Hail Mother, sung by the Vedas; indestructible, impenetrable, untiring;","page":869,"meaning_status":"draft","note":"ਅਖਿਦਾਣੀ: read as 'unwearied'; uncertain."},{"gurmukhi":"ਭੈ ਹਰਣੀ ਸਰਬੰ ਸੰਤਾਣੀ। ਜੈ ਦਾਤਾ ਮਾਤਾ ਕ੍ਰਿਪਾਣੀ। ੬੨।","roman":"Bhai harnee sarban santaanee | jai daataa maataa kripaanee | 62 |","meaning_en":"remover of fear of all saints; hail giver, Mother, bearer of the sword.","page":869,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅਚਕੜਾ ਛੰਦ","gurmukhi":"ਅਚਕੜਾ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Achakraa chhand | tvaprasaadi","meaning_en":"Achkara metre. By Your grace.","page":869,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[63],"number_text":"੬੩।","page":869,"lines":[{"gurmukhi":"ਅੰਬਿਕਾ ਤੋਤਲਾ ਸੀਤਲਾ ਸਾਕਣੀ।","roman":"Anbikaa totlaa seetlaa saaknee |","meaning_en":"Ambika, Totla (of lisping speech), Sitala, Sakini;","page":869,"meaning_status":"draft","note":"This metre is a string of names and epithets of the goddess; many are rendered by transliteration. Sakini, Dakini: female spirits in the goddess's train."},{"gurmukhi":"ਸਿੰਧੁਰੀ ਸੁਪ੍ਰਭਾ ਸੁਭ੍ਰਮਾ ਡਾਕਣੀ।","roman":"Sindhuree suprabhaa subhramaa daaknee |","meaning_en":"Sindhuri (the vermilion one), Suprabha (of fair radiance), Subhrama, Dakini;","page":869,"meaning_status":"draft","note":"Several names uncertain."},{"gurmukhi":"ਸਾਵਜਾ ਸੰਭਿਰੀ ਸਿੰਧੁਲਾ ਦੁਖਹਰੀ।","roman":"Saavjaa sanbhiree sindhulaa dukhahree |","meaning_en":"Savaja (rider of the lion?), Sambhiri, Sindhula, remover of sorrow;","page":869,"meaning_status":"draft","note":"ਸਾਵਜਾ: perhaps 'with the wild beast (lion)'; ਸੰਭਿਰੀ, ਸਿੰਧੁਲਾ: names; uncertain."},{"gurmukhi":"ਸੁੰਮਿਲਾ ਸੰਭਿਲਾ ਸੁਪ੍ਰਭਾ ਦੁਧਰੀ। ੬੩।","roman":"Sunmilaa sanbhilaa suprabhaa dudhree | 63 |","meaning_en":"Summila, Sambhila, Suprabha, the double-edged one.","page":869,"meaning_status":"draft","note":"ਦੁਧਰੀ: read as 'two-edged (sword)' or 'hard to hold'; names uncertain."}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":869,"lines":[{"gurmukhi":"ਭਾਵਨਾ ਭੈ ਹਰੀ ਭੂਤਿਲੀ ਭੈਹਰਾ।","roman":"Bhaavnaa bhai haree bhootilee bhaihraa |","meaning_en":"Bhavana (the beloved), remover of fear, Bhutili (mistress of spirits), remover of dread;","page":869,"meaning_status":"draft"},{"gurmukhi":"ਟਾਕਣੀ ਝਾਕਣੀ ਸਾਕਣੀ ਸਿੰਧੁਲਾ।","roman":"Taaknee jhaaknee saaknee sindhulaa |","meaning_en":"Takini, Jhakini, Sakini, Sindhula;","page":869,"meaning_status":"draft","note":"Names of female spirits; uncertain."},{"gurmukhi":"ਦੁਧਰਾ ਦ੍ਰੁਮੁਖਾ ਦ੍ਰੁਕਟਾ ਦੁਧਰੀ।","roman":"Dudhraa drumukhaa druktaa dudhree |","meaning_en":"the double-edged, the hard-faced, the hard to cut, the hard to hold;","page":869,"meaning_status":"draft","note":"ਦੁਧਰਾ, ਦ੍ਰੁਮੁਖਾ, ਦ੍ਰੁਕਟਾ, ਦੁਧਰੀ: read as epithets with 'dur-' (hard, fierce); uncertain."},{"gurmukhi":"ਕੰਪਿਲਾ ਜੰਪਿਲਾ ਹਿੰਗੁਲਾ ਭੈਹਰੀ। ੬੪।","roman":"Kanpilaa janpilaa hingulaa bhaihree | 64 |","meaning_en":"Kampila (who makes tremble), Jampila (much invoked), Hingula, remover of fear.","page":869,"meaning_status":"draft","note":"ਕੰਪਿਲਾ, ਜੰਪਿਲਾ: uncertain."}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":870,"lines":[{"gurmukhi":"ਚਿਤ੍ਰਣੀ ਚਾਪਣੀ ਚਾਰਣੀ ਚਛਣੀ।","roman":"Chitranee chaapnee chaarnee chachhnee |","meaning_en":"Chitrani (the wondrous), bearer of the bow, the wanderer, the watchful-eyed;","page":870,"meaning_status":"draft","note":"ਚਾਰਣੀ: wanderer or bard; ਚਛਣੀ: 'of eyes'; uncertain."},{"gurmukhi":"ਹਿੰਗੁਲਾ ਪਿੰਗੁਲਾ ਗੰਧ੍ਰਬਾ ਜਛਣੀ।","roman":"Hingulaa pingulaa gandhrabaa jachhnee |","meaning_en":"Hingula, Pingula, the Gandharva lady, the Yaksha lady;","page":870,"meaning_status":"draft"},{"gurmukhi":"ਬਰਮਣੀ ਚਰਮਣੀ ਪਰਘਣੀ ਪਾਸਣੀ।","roman":"Baramnee charamnee paraghnee paasnee |","meaning_en":"bearer of armour, bearer of shield, bearer of the club, bearer of the noose;","page":870,"meaning_status":"draft"},{"gurmukhi":"ਖੜਗਣੀ ਗੜਗਣੀ ਸੈਥਣੀ ਸਾਪਣੀ। ੬੫।","roman":"Kharagnee garagnee saithnee saapnee | 65 |","meaning_en":"bearer of the sword, bearer of the gadga (?), bearer of the lance, bearer of the serpent.","page":870,"meaning_status":"draft","note":"ਗੜਗਣੀ: unclear, perhaps the mace or a sound-word; ਸੈਥਣੀ: lance (saihthi). Uncertain."}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":870,"lines":[{"gurmukhi":"ਭੀਮੜਾ ਸਮਦੜਾ ਹਿੰਗੁਲਾ ਕਾਰਤਕੀ।","roman":"Bheemraa samadraa hingulaa kaaratkee |","meaning_en":"the terrible, the ocean-wide (?), Hingula, Kartaki;","page":870,"meaning_status":"draft","note":"ਸਮਦੜਾ: unclear; ਕਾਰਤਕੀ: perhaps of Kartikeya (the power of Kartikeya). Uncertain."},{"gurmukhi":"ਸੁਪ੍ਰਭਾ ਅਛਿਦਾ ਅਧਿਰਾ ਮਾਰੁਤਕੀ।","roman":"Suprabhaa achhidaa adhiraa maarutkee |","meaning_en":"the radiant, the unpierceable, the unsteady (?), Marutaki (power of the wind);","page":870,"meaning_status":"draft","note":"ਅਧਿਰਾ: read as 'restless' or 'supreme'; uncertain."},{"gurmukhi":"ਗਿੰਗਲੀ ਹਿੰਗੁਲੀ ਠਿੰਗੁਲੀ ਪਿੰਗੁਲਾ।","roman":"Ginglee hingulee thingulee pingulaa |","meaning_en":"Gingali, Hinguli, Thinguli, Pingula;","page":870,"meaning_status":"draft","note":"Names; uncertain."},{"gurmukhi":"ਚਿਕਣੀ ਚਰਕਟਾ ਚਰਪਟਾ ਚਾਂਵਡਾ। ੬੬।","roman":"Chiknee charaktaa charaptaa chaanvdaa | 66 |","meaning_en":"the smooth one, Charkata, Charpata, Chamunda.","page":870,"meaning_status":"draft","note":"ਚਾਂਵਡਾ: read as Chamunda. ਚਰਕਟਾ, ਚਰਪਟਾ: names; uncertain."}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":870,"lines":[{"gurmukhi":"ਅਛਿਦਾ ਅਭਿਦਾ ਅਸਿਤਾ ਅਧਰੀ।","roman":"Achhidaa abhidaa asitaa adhree |","meaning_en":"unbreakable, unpierceable, the dark one, the support (?)","page":870,"meaning_status":"draft","note":"ਅਸਿਤਾ: dark, or 'with the sword'; ਅਧਰੀ: uncertain."},{"gurmukhi":"ਅਕਟਾ ਅਖੰਡਾ ਅਛਟਾ ਦੁਧਰੀ।","roman":"Aktaa akhandaa achhtaa dudhree |","meaning_en":"uncuttable, unbroken, unblemished, the double-edged;","page":870,"meaning_status":"draft"},{"gurmukhi":"ਅੰਜਨੀ ਅੰਬਿਕਾ ਅਸਤ੍ਰਣੀ ਧਾਰਣੀ।","roman":"Anjnee anbikaa astranee dhaarnee |","meaning_en":"Anjani, Ambika, bearer of weapons, the sustainer;","page":870,"meaning_status":"draft"},{"gurmukhi":"ਅਭਰੰ ਅਧਰਾ ਜਗਤਿ ਉਧਾਰਣੀ। ੬੭।","roman":"Abhran adhraa jagti udhaarnee | 67 |","meaning_en":"filler of all, support of all, deliverer of the world.","page":870,"meaning_status":"draft","note":"ਅਭਰੰ ਅਧਰਾ: read as 'who fills (all)' and 'support'; uncertain."}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":870,"lines":[{"gurmukhi":"ਅੰਜਨੀ ਗੰਜਨੀ ਸਾਕੜੀ ਸੀਤਲਾ।","roman":"Anjnee ganjnee saakree seetlaa |","meaning_en":"Anjani, destroyer, Sakri (?), Sitala;","page":870,"meaning_status":"draft","note":"ਗੰਜਨੀ: destroyer; ਸਾਕੜੀ: unclear."},{"gurmukhi":"ਸਿਧਰੀ ਸੁਪ੍ਰਭਾ ਸਾਮਲਾ ਤੋਤਲਾ।","roman":"Sidhree suprabhaa saamlaa totlaa |","meaning_en":"Sidhri (the accomplished), Suprabha, the dark one, Totla;","page":870,"meaning_status":"draft"},{"gurmukhi":"ਸੰਭਰੀ ਗੰਭਰੀ ਅੰਭਰੀ ਅਕਟਾ।","roman":"Sanbhree ganbhree anbhree aktaa |","meaning_en":"Sambhari, the deep one, the sky-like, the uncuttable;","page":870,"meaning_status":"draft","note":"ਸੰਭਰੀ: Shakambhari (?); ਅੰਭਰੀ: of the sky or of water; uncertain."},{"gurmukhi":"ਦੁਸਲਾ ਦ੍ਰੁਭਿਖਾ ਦ੍ਰੁਕਟਾ ਅਮਿਟਾ। ੬੮।","roman":"Duslaa drubhikhaa druktaa amitaa | 68 |","meaning_en":"the hard to bear, the dread of famine, hard to cut, the ineffaceable.","page":870,"meaning_status":"draft","note":"ਦੁਸਲਾ, ਦ੍ਰੁਭਿਖਾ: read as 'hard to bear' and 'famine'; uncertain."}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":870,"lines":[{"gurmukhi":"ਭੈਰਵੀ ਭੈਹਰੀ ਭੂਚਰਾ ਭਾਨਵੀ।","roman":"Bhairvee bhaihree bhoochraa bhaanvee |","meaning_en":"Bhairavi, remover of fear, earth-dweller, the radiant (like the sun);","page":870,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਿਕੁਟਾ ਚਰਪਟਾ ਚਾਂਵਡਾ ਮਾਨਵੀ।","roman":"Trikutaa charaptaa chaanvdaa maanvee |","meaning_en":"Trikuta, Charpata, Chamunda, the human-formed;","page":870,"meaning_status":"draft","note":"ਤ੍ਰਿਕੁਟਾ: of the three peaks (Trikuta mountain); uncertain."},{"gurmukhi":"ਜੋਬਨਾ ਜੈਕਰੀ ਜੰਭਹਰੀ ਜਾਲਪਾ।","roman":"Jobnaa jaikree janbhahree jaalpaa |","meaning_en":"youthful, bringer of victory, slayer of Jambh, Jalpa;","page":870,"meaning_status":"draft","note":"ਜੰਭਹਰੀ: slayer of the demon Jambh. ਜਾਲਪਾ: Jalpa, a goddess-name."},{"gurmukhi":"ਤੋਤਲਾ ਤੁੰਦਲਾ ਦੰਤਲੀ ਕਾਲਿਕਾ। ੬੯।","roman":"Totlaa tundlaa dantlee kaalikaa | 69 |","meaning_en":"Totla, the pot-bellied, the long-toothed, Kalika.","page":870,"meaning_status":"draft"}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":870,"lines":[{"gurmukhi":"ਭਰਮਣਾ ਨਿਭ੍ਰਮਾ ਭਾਵਨਾ ਭੈਹਰੀ।","roman":"Bharamnaa nibhramaa bhaavnaa bhaihree |","meaning_en":"she who causes wandering, free of delusion, the beloved, remover of fear;","page":870,"meaning_status":"draft"},{"gurmukhi":"ਬਰ ਬੁਧਾ ਦਾਤ੍ਰਣੀ ਸਤ੍ਰਣੀ ਛੈਕਰੀ।","roman":"Bar budhaa daatranee satranee chhaikree |","meaning_en":"best in wisdom, the giver, the slayer of foes, the destroyer;","page":870,"meaning_status":"draft","note":"ਸਤ੍ਰਣੀ: read as 'slayer of enemies' (or 'bearer of weapons'); ਛੈਕਰੀ: 'who brings destruction'."},{"gurmukhi":"ਦ੍ਰੁਕਟਾ ਦ੍ਰੁਭਿਦਾ ਦੁਧਰਾ ਦ੍ਰੁਮਦੀ।","roman":"Druktaa drubhidaa dudhraa drumdee |","meaning_en":"hard to cut, hard to pierce, hard to hold, hard to subdue;","page":870,"meaning_status":"draft","note":"ਦ੍ਰੁਮਦੀ: uncertain."},{"gurmukhi":"ਅਤ੍ਰੁਟਾ ਅਛੁਟਾ ਅਜਟਾ ਅਭਿਦੀ। ੭੦।","roman":"Atrutaa achhutaa ajtaa abhidee | 70 |","meaning_en":"unbreakable, inescapable, without matted hair (?), impenetrable.","page":870,"meaning_status":"draft","note":"ਅਜਟਾ: uncertain (perhaps 'unborn')."}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":870,"lines":[{"gurmukhi":"ਤੰਤਲਾ ਅੰਤਲਾ ਸੰਤਲਾ ਸਾਵਜਾ।","roman":"Tantlaa antlaa santlaa saavjaa |","meaning_en":"Tantala (mistress of spells), Antala (the end), Santala (of the saints), Savaja;","page":870,"meaning_status":"draft","note":"Names; uncertain."},{"gurmukhi":"ਭੀਮੜਾ ਭੈਹਰੀ ਭੂਤਲਾ ਬਾਵਜਾ।","roman":"Bheemraa bhaihree bhootlaa baavjaa |","meaning_en":"the terrible one, remover of fear, mistress of the earth, Bavja;","page":870,"meaning_status":"draft","note":"ਬਾਵਜਾ: uncertain."},{"gurmukhi":"ਡਾਕਣੀ ਸਾਕਣੀ ਝਾਕਣੀ ਕਾਕਿੜਾ।","roman":"Daaknee saaknee jhaaknee kaakiraa |","meaning_en":"Dakini, Sakini, Jhakini, Kakira;","page":870,"meaning_status":"draft","note":"Names of female spirits; uncertain."},{"gurmukhi":"ਕਿੰਕੜੀ ਕਾਲਿਕਾ ਜਾਲਪਾ ਜੈ ਮ੍ਰਿੜਾ। ੭੧।","roman":"Kinkree kaalikaa jaalpaa jai mriraa | 71 |","meaning_en":"Kinkari, Kalika, Jalpa; hail, Mrira (gracious one).","page":870,"meaning_status":"draft","note":"ਮ੍ਰਿੜਾ: Mrida, the gracious one, a name of Parvati."}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":871,"lines":[{"gurmukhi":"ਠਿੰਗੁਲਾ ਹਿੰਗੁਲਾ ਪਿੰਗੁਲਾ ਪ੍ਰਾਸਣੀ।","roman":"Thingulaa hingulaa pingulaa praasnee |","meaning_en":"Thingula, Hingula, Pingula, bearer of the dart;","page":871,"meaning_status":"draft","note":"ਪ੍ਰਾਸਣੀ: bearer of the prās (dart/spear)."},{"gurmukhi":"ਸਸਤ੍ਰਣੀ ਅਸਤ੍ਰਣੀ ਸੂਲਣੀ ਸਾਸਣੀ।","roman":"Sastranee astranee soolnee saasnee |","meaning_en":"bearer of weapons wielded and weapons thrown, bearer of the trident, the ruler;","page":871,"meaning_status":"draft","note":"ਸਸਤ੍ਰ / ਅਸਤ੍ਰ: weapons held / weapons thrown."},{"gurmukhi":"ਕੰਨਿਕਾ ਅੰਨਿਕਾ ਧੰਨਿਕਾ ਧਉਲਰੀ।","roman":"Kannikaa annikaa dhannikaa dhaulree |","meaning_en":"Kanika (the maiden), Annika (giver of food?), Dhannika (the blessed), the white one;","page":871,"meaning_status":"draft","note":"Names; uncertain."},{"gurmukhi":"ਰਕਤਿਕਾ ਸਕਤਿਕਾ ਭਕਤਕਾ ਜੈਕਰੀ। ੭੨।","roman":"Raktikaa saktikaa bhakatkaa jaikree | 72 |","meaning_en":"the red one, the power (shakti), the devoted, bringer of victory.","page":871,"meaning_status":"draft"}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":871,"lines":[{"gurmukhi":"ਝਿੰਗੜਾ ਪਿੰਗੜਾ ਜਿੰਗੜਾ ਜਾਲਪਾ।","roman":"Jhingraa pingraa jingraa jaalpaa |","meaning_en":"Jhingra, Pingra, Jingra, Jalpa;","page":871,"meaning_status":"draft","note":"Names; uncertain."},{"gurmukhi":"ਜੋਗਣੀ ਭੋਗਣੀ ਰੋਗ ਹਰੀ ਕਾਲਿਕਾ।","roman":"Jognee bhognee rog haree kaalikaa |","meaning_en":"the yogini, the enjoyer, remover of disease, Kalika;","page":871,"meaning_status":"draft"},{"gurmukhi":"ਚੰਚਲਾ ਚਾਂਵਡਾ ਚਾਚਰਾ ਚਿਤ੍ਰਤਾ।","roman":"Chanchlaa chaanvdaa chaachraa chitrataa |","meaning_en":"the restless, Chamunda, Chachra, the wondrous;","page":871,"meaning_status":"draft","note":"ਚਾਚਰਾ: uncertain."},{"gurmukhi":"ਤੰਤਰੀ ਭਿੰਭਰੀ ਛਤ੍ਰਣੀ ਛਿੰਛਲਾ। ੭੩।","roman":"Tantree bhinbhree chhatranee chhinchhlaa | 73 |","meaning_en":"mistress of spells, Bhimbhari, bearer of the canopy, Chhinchhala.","page":871,"meaning_status":"draft","note":"ਤੰਤਰੀ: of tantra (or of strings); ਛਿੰਛਲਾ: uncertain."}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":871,"lines":[{"gurmukhi":"ਦੰਤੁਲਾ ਦਾਮਣੀ ਦ੍ਰੁਕਟਾ ਦ੍ਰੁਭ੍ਰਮਾ।","roman":"Dantulaa daamnee druktaa drubhramaa |","meaning_en":"the long-toothed, the lightning-like, hard to cut, hard to bewilder;","page":871,"meaning_status":"draft"},{"gurmukhi":"ਛੁਧਿਤਾ ਨਿੰਦ੍ਰਕਾ ਨ੍ਰਿਭਿਖਾ ਨ੍ਰਿਗਮਾ।","roman":"Chhudhitaa nindrakaa nribhikhaa nrigmaa |","meaning_en":"hunger, sleep, the one beyond begging (?), beyond the scriptures;","page":871,"meaning_status":"draft","note":"ਨ੍ਰਿਭਿਖਾ: read as 'free of want'; ਨ੍ਰਿਗਮਾ: 'beyond the Nigam (Vedas)'; uncertain."},{"gurmukhi":"ਕਦ੍ਰਕਾ ਚੂੜਿਕਾ ਚਾਚਕਾ ਚਾਪਣੀ।","roman":"Kadrakaa choorikaa chaachkaa chaapnee |","meaning_en":"Kadraka, Churika (the bangled), Chachka, bearer of the bow;","page":871,"meaning_status":"draft","note":"Names; uncertain."},{"gurmukhi":"ਚਿਚ੍ਰੜੀ ਚਾਵੜਾ ਚਿੰਪਿਲਾ ਜਾਪਣੀ। ੭੪।","roman":"Chichraree chaavraa chinpilaa jaapnee | 74 |","meaning_en":"Chichrari, Chavra, Chimpila, the one to be chanted.","page":871,"meaning_status":"draft","note":"Names; uncertain. ਜਾਪਣੀ: 'worthy of being chanted'."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਪਰਜ","gurmukhi":"ਬਿਸਨਪਦ। ਪਰਜ","roman":"Bisanpad | paraj","meaning_en":"Bishanpad. In Raag Paraj.","page":871,"meaning_status":"draft","note":"Bishanpad (Vishnupad): a devotional song form."},{"type":"invocation","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Tvaprasaadi kathtaa","meaning_en":"Spoken by Your grace.","page":871,"meaning_status":"draft"},{"type":"verse","number":[75],"number_text":"੭੫।","page":871,"lines":[{"gurmukhi":"ਕੈਸੇ ਕੌ ਪਾਇਨ ਪ੍ਰਭਾ ਉਚਾਰੋ।","roman":"Kaise kau paain prabhaa uchaaro |","meaning_en":"How shall I describe the splendour of your feet?","page":871,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਨਿਪਟ ਅਘਟ ਅੰਮ੍ਰਿਤ ਸਮ ਸੰਪਟ ਸੁਭਟ ਬਿਚਾਰੋ।","roman":"Jaanuk nipat aghat anmrit sam sanpat subhat bichaaro |","meaning_en":"consider them like a perfect, inexhaustible casket of nectar for a warrior;","page":871,"meaning_status":"draft","note":"ਸੰਪਟ ਸੁਭਟ: read as 'casket ... for the brave'; uncertain."},{"gurmukhi":"ਮਨ ਮਧੁਕਰਹਿ ਚਰਨ ਕਮਲਨ ਪਰ ਹ੍ਵੈ ਮਨਮਤ ਗੁੰਜਾਰੋ।","roman":"Man madhukarhi charan kamlan par hvai manmat gunjaaro |","meaning_en":"let the mind become a bee upon the lotus feet, and hum there, intoxicated;","page":871,"meaning_status":"draft"},{"gurmukhi":"ਮਾਤ੍ਰਿਕ ਸਪਤ ਸਪਿਤ ਪਿਤਰਨ ਕੁਲ ਚੌਦਹੂੰ ਕੁਲੀ ਉਧਾਰੋ। ੭੫।","roman":"Maatrik sapat sapit pitran kul chaudhoon kulee udhaaro | 75 |","meaning_en":"deliver the seven generations of my mother and of my father, all fourteen lines.","page":871,"meaning_status":"draft","note":"Seven generations on each side make the fourteen."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ","roman":"Bisanpad | kaaphee","meaning_en":"Bishanpad. In Raag Kafi.","page":871,"meaning_status":"draft"},{"type":"verse","number":[76],"number_text":"੭੬।","page":871,"lines":[{"gurmukhi":"ਤਾ ਦਿਨ ਦੇਹ ਸਫਲ ਕਰ ਜਾਨੋ।","roman":"Taa din deh saphal kar jaano |","meaning_en":"I shall consider my body fruitful on that day,","page":871,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਦਿਨ ਜਗਤ ਮਾਤ ਪ੍ਰਫੁਲਿਤ ਹ੍ਵੈ ਦੇਹਿ ਬਿਜੈ ਬਰਦਾਨੋ।","roman":"Jaa din jagat maat praphulit hvai dehi bijai bardaano |","meaning_en":"the day on which the Mother of the world, delighted, gives me the boon of victory;","page":871,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਦਿਨ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਕਟਿ ਬਾਧੋ ਚੰਦਨ ਚਿਤ੍ਰ ਲਗਾਊਂ।","roman":"Taa din sasatr asatr kati baadho chandan chitr lagaaoon |","meaning_en":"on that day I shall tie weapons and arms to my waist and anoint myself with sandal marks,","page":871,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕਹੁ ਨੇਤ ਨਿਗਮ ਕਹਿ ਬੋਲਤ ਤਾਸੁ ਸੁ ਬਰੁ ਜਬ ਪਾਊਂ। ੭੬।","roman":"Jaa kahu net nigam kahi bolat taasu su baru jab paaoon | 76 |","meaning_en":"when I obtain the One whom the Vedas call \"not this, not this\" as my bridegroom.","page":871,"meaning_status":"draft","note":"ਨੇਤ: neti, 'not this'. ਬਰੁ: read as 'bridegroom' (the Lord); it could also be 'boon'. Uncertain."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"Bishanpad. In Raag Sorath.","page":871,"meaning_status":"draft"},{"type":"invocation","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Tvaprasaadi kathtaa","meaning_en":"Spoken by Your grace.","page":871,"meaning_status":"draft"},{"type":"verse","number":[77],"number_text":"੭੭।","page":871,"lines":[{"gurmukhi":"ਅੰਤਰਜਾਮੀ ਅਭਯ ਭਵਾਨੀ।","roman":"Antarjaamee abhay bhavaanee |","meaning_en":"Bhavani, knower of hearts, the fearless,","page":871,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਹੀ ਨਿਰਖਿ ਪ੍ਰੇਮ ਪਾਰਸ ਕੋ ਚਿਤ ਕੀ ਬ੍ਰਿਥਾ ਪਛਾਨੀ।","roman":"Ati hee nirkhi prem paaras ko chit kee brithaa pachhaanee |","meaning_en":"seeing Paras's great love, recognised the pain of his heart;","page":871,"meaning_status":"draft"},{"gurmukhi":"ਆਪਨ ਭਗਤ ਜਾਨ ਭਵਖੰਡਨ ਅਭਯ ਰੂਪ ਦਿਖਾਯੋ।","roman":"Aapan bhagat jaan bhavkhandan abhay roop dikhaayo |","meaning_en":"knowing him as her own devotee, the destroyer of the world showed him her fearless form;","page":871,"meaning_status":"draft","note":"ਭਵਖੰਡਨ: 'destroyer of the world' or 'breaker of the cycle of birth'."},{"gurmukhi":"ਚਕ੍ਰਤ ਰਹੇ ਪੇਖਿ ਮੁਨਿ ਜਨ ਸੁਰ ਅਜਰ ਅਮਰ ਪਦ ਪਾਯੋ। ੭੭।","roman":"Chakrat rahe pekhi muni jan sur ajar amar pad paayo | 77 |","meaning_en":"seeing it, sages, people and gods were amazed; he obtained the state beyond age and death.","page":871,"meaning_status":"draft"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":871,"lines":[{"gurmukhi":"ਸੋਭਿਤ ਬਾਮਹਿੰ ਪਾਨਿ ਕ੍ਰਿਪਾਣੀ।","roman":"Sobhit baamhin paani kripaanee |","meaning_en":"In her left hand the sword shines,","page":871,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਤਰ ਜਛ ਕਿੰਨਰ ਅਸੁਰਨ ਕੀ ਸਬ ਕੀ ਕ੍ਰਿਯਾ ਹਿਰਾਨੀ।","roman":"Jaa tar jachh kinnar asuran kee sab kee kriyaa hiraanee |","meaning_en":"under which the actions of the Yakshas, Kinnars and demons were all taken away;","page":871,"meaning_status":"draft","note":"ਜਾ ਤਰ: read as 'by which / under which'; uncertain."},{"gurmukhi":"ਜਾ ਤਨ ਮਧੁ ਕੀਟਭ ਕਹੁ ਖੰਡ੍ਯੋ ਸੁੰਭ ਨਿਸੁੰਭ ਸੰਘਾਰੇ।","roman":"Jaa tan madhu keetabh kahu khandyo sunbh nisunbh sanghaare |","meaning_en":"with which she cut down Madhu and Kaitabh, and destroyed Sumbh and Nisumbh;","page":871,"meaning_status":"draft"},{"gurmukhi":"ਸੋਈ ਕ੍ਰਿਪਾਨ ਨਿਦਾਨ ਲਗੇ ਜਗ ਦਾਇਨ ਰਹੋ ਹਮਾਰੇ। ੭੮।","roman":"Soee kripaan nidaan lage jag daain raho hamaare | 78 |","meaning_en":"may that very sword in the end be on our right side, protecting us.","page":871,"meaning_status":"draft","note":"ਦਾਇਨ: 'on the right (side)', or 'giving (help)'. Uncertain."}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":872,"lines":[{"gurmukhi":"ਜਾ ਤਨ ਬਿੜਾਲਾਛ ਚਿਛ੍ਰਾਦਿਕ ਖੰਡਨ ਖੰਡ ਉਡਾਏ।","roman":"Jaa tan biraalaachh chichhraadik khandan khand udaae |","meaning_en":"With which she cut Biralachh, Chichhur and the rest into pieces and sent them flying;","page":872,"meaning_status":"draft","note":"ਬਿੜਾਲਾਛ: the demon Bidalaksha. ਚਿਛ੍ਰ: Chikshur."},{"gurmukhi":"ਧੂਲੀਕਰਨ ਧੂਮ੍ਰਲੋਚਨ ਕੇ ਮਾਸਨ ਗਿਧ ਰਜਾਏ।","roman":"Dhooleekran dhoomralochan ke maasan gidh rajaae |","meaning_en":"turned Dhumar Lochan to dust, and filled the vultures with his flesh;","page":872,"meaning_status":"draft","note":"ਰਜਾਏ: 'satisfied, sated'."},{"gurmukhi":"ਰਾਮ ਰਸੂਲ ਕਿਸਨ ਬਿਸਨਾਦਿਕ ਕਾਲ ਕ੍ਰਵਾਲਹਿ ਕੂਟੇ।","roman":"Raam rasool kisan bisnaadik kaal kravaalhi koote |","meaning_en":"Ram, the Prophet, Krishna, Vishnu and the rest were pounded by the sword of Death;","page":872,"meaning_status":"draft","note":"ਰਸੂਲ: Rasul, the Prophet (Arabic)."},{"gurmukhi":"ਕੋਟਿ ਉਪਾਇ ਧਾਇ ਸਭ ਥਾਕੇ ਬਿਨ ਤਿਹ ਭਜਨ ਨ ਛੂਟੇ। ੭੯।","roman":"Koti upaai dhaai sabh thaake bin tih bhajan na chhoote | 79 |","meaning_en":"they all tried millions of ways and ran about until exhausted; without worship of Him none is freed.","page":872,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੂਹੀ","gurmukhi":"ਬਿਸਨਪਦ। ਸੂਹੀ","roman":"Bisanpad | soohee","meaning_en":"Bishanpad. In Raag Suhi.","page":872,"meaning_status":"draft"},{"type":"invocation","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Tvaprasaadi kathtaa","meaning_en":"Spoken by Your grace.","page":872,"meaning_status":"draft"},{"type":"verse","number":[80],"number_text":"੮੦।","page":872,"lines":[{"gurmukhi":"ਸੋਭਿਤ ਪਾਨਿ ਕ੍ਰਿਪਾਨ ਉਜਾਰੀ।","roman":"Sobhit paani kripaan ujaaree |","meaning_en":"The bright sword shines in her hand,","page":872,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਤਨ ਇੰਦ੍ਰ ਕੋਟਿ ਕਈ ਖੰਡੇ ਬਿਸਨ ਕ੍ਰੋਰਿ ਤ੍ਰਿਪੁਰਾਰੀ।","roman":"Jaa tan indr koti kaee khande bisan krori tripuraaree |","meaning_en":"with which many millions of Indras were cut down, and millions of Vishnus and Shivas;","page":872,"meaning_status":"draft","note":"ਤ੍ਰਿਪੁਰਾਰੀ: 'enemy of Tripura', Shiva."},{"gurmukhi":"ਜਾ ਕਹੁ ਰਾਮ ਉਚਰ ਮੁਨਿ ਜਨ ਸਬ ਸੇਵਤ ਧਿਆਨ ਲਗਾਏ।","roman":"Jaa kahu raam uchar muni jan sab sevat dhiaan lagaae |","meaning_en":"the One whom all the sages call Ram and serve with their attention fixed,","page":872,"meaning_status":"draft"},{"gurmukhi":"ਤਸ ਤੁਮ ਰਾਮ ਕ੍ਰਿਸਨ ਕਈ ਕੋਟਿਕ ਬਾਰ ਉਪਾਇ ਮਿਟਾਏ। ੮੦।","roman":"Tas tum raam krisan kaee kotik baar upaai mitaae | 80 |","meaning_en":"so You have created and wiped out Ram and Krishna many millions of times.","page":872,"meaning_status":"draft"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":872,"lines":[{"gurmukhi":"ਅਨਭਵ ਰੂਪ ਸਰੂਪ ਅਗੰਜਨ ਕਹੋ ਕਵਨ ਬਿਧਿ ਗਈਯੈ।","roman":"Anbhav roop saroop aganjan kaho kavan bidhi gaeeyai |","meaning_en":"Tell me, how can the One of experienced form, the indestructible being, be sung?","page":872,"meaning_status":"draft","note":"ਅਨਭਵ ਰੂਪ: 'whose form is known by inner experience'."},{"gurmukhi":"ਜਿਹਬਾ ਸਹੰਸ੍ਰ ਰਟਤ ਗੁਨ ਥਾਕੀ ਕਬਿ ਜਿਹਵੇਕ ਬਤਈਯੈ।","roman":"Jihbaa sahansr ratat gun thaakee kabi jihvek bataeeyai |","meaning_en":"A thousand tongues grew tired reciting His virtues; how can a poet with one tongue tell them?","page":872,"meaning_status":"draft","note":"A thousand tongues: the serpent Sheshnag."},{"gurmukhi":"ਭੂਮਿ ਅਕਾਸ ਪਤਾਰ ਜਵਨ ਕਰ ਚਉਦਹਿ ਖੰਡ ਬਿਹੰਡੇ।","roman":"Bhoomi akaas pataar javan kar chaudhi khand bihande |","meaning_en":"He who made earth, sky and underworld, and shattered the fourteen regions,","page":872,"meaning_status":"draft","note":"ਬਿਹੰਡੇ: read as 'divided' or 'destroyed'; uncertain."},{"gurmukhi":"ਜਗਮਗ ਜੋਤਿ ਹੋਤਿ ਭੂਤਲਿ ਮੈ ਖੰਡਨ ਅਉ ਬ੍ਰਹਮੰਡੇ। ੮੧।","roman":"Jagmag joti hoti bhootli mai khandan au brahmande | 81 |","meaning_en":"His light shines brilliantly on the earth, in its regions and in the universe.","page":872,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"Bishanpad. In Raag Sorath.","page":872,"meaning_status":"draft"},{"type":"verse","number":[82],"number_text":"੮੨।","page":872,"lines":[{"gurmukhi":"ਜੈ ਜੈ ਰੂਪ ਅਰੇਖ ਅਪਾਰ।","roman":"Jai jai roop arekh apaar |","meaning_en":"Hail, hail to the formless, boundless One,","page":872,"meaning_status":"draft"},{"gurmukhi":"ਜਾਸਿ ਪਾਇ ਭ੍ਰਮਾਇ ਜਹ ਤਹ ਭੀਖ ਕੋ ਸਿਵ ਦੁਆਰ।","roman":"Jaasi paai bhramaai jah tah bheekh ko siv duaar |","meaning_en":"by whose doing Shiva was made to wander here and there, begging at doors;","page":872,"meaning_status":"draft","note":"ਸਿਵ ਦੁਆਰ: read as 'Shiva (begging) at doors'; uncertain."},{"gurmukhi":"ਜਾਸਿ ਪਾਇ ਲਗ੍ਯੋ ਨਿਸੇਸਿਹ ਕਾਰਮਾ ਤਨ ਏਕ।","roman":"Jaasi paai lagyo nisesih kaarmaa tan ek |","meaning_en":"by whose doing the moon received a dark mark on its body,","page":872,"meaning_status":"draft","note":"ਨਿਸੇਸਿ: 'lord of the night', the moon. ਕਾਰਮਾ: blackness, the stain."},{"gurmukhi":"ਦੇਵਤੇਸ ਸਹੰਸ੍ਰ ਭੇ ਭਗ ਜਾਸਿ ਪਾਇ ਅਨੇਕ। ੮੨।","roman":"Devtes sahansr bhe bhag jaasi paai anek | 82 |","meaning_en":"and by whose doing the lord of the gods (Indra) came to bear a thousand marks of shame.","page":872,"meaning_status":"draft","note":"ਭਗ: refers to the story of Indra cursed with a thousand marks for his offence with Ahalya."}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":872,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨ ਰਾਮ ਭਏ ਕਿਤੇ ਪੁਨਿ ਕਾਲ ਪਾਇ ਬਿਹਾਨ।","roman":"Krisan raam bhae kite puni kaal paai bihaan |","meaning_en":"How many Krishnas and Rams have there been, who then passed away in time.","page":872,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲ ਕੋ ਅਨਕਾਲ ਕੈ ਅਕਲੰਕ ਮੂਰਤਿ ਮਾਨ।","roman":"Kaal ko ankaal kai aklank moorti maan |","meaning_en":"Know Him to be the Death of death, the stainless form.","page":872,"meaning_status":"draft"},{"gurmukhi":"ਜਾਸਿ ਪਾਇ ਭਯੋ ਸਭੈ ਜਗ ਜਾਸ ਪਾਇ ਬਿਲਾਨ।","roman":"Jaasi paai bhayo sabhai jag jaas paai bilaan |","meaning_en":"By whose doing the whole world came to be, and by whose doing it dissolves,","page":872,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹਿ ਤੈ ਅਬਿਚਾਰ ਜੜ ਕਰਤਾਰ ਕਾਹਿ ਨ ਜਾਨ। ੮੩।","roman":"Taahi tai abichaar jar kartaar kaahi na jaan | 83 |","meaning_en":"why, O thoughtless fool, do you not know Him as the Creator?","page":872,"meaning_status":"draft"}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":872,"lines":[{"gurmukhi":"ਨਰਹਰਿ ਜਾਨ ਕਾਹਿ ਨ ਲੇਤ।","roman":"Narahri jaan kaahi na let |","meaning_en":"Why do you not take Him as the Lord?","page":872,"meaning_status":"draft","note":"ਨਰਹਰਿ: literally the man-lion; here read as 'the Lord'."},{"gurmukhi":"ਤੈ ਭਰੋਸ ਪਰ੍ਯੋ ਪਸੂ ਜਿਹ ਮੋਹਿ ਬਧਿ ਅਚੇਤ।","roman":"Tai bharos paryo pasoo jih mohi badhi achet |","meaning_en":"You have put your trust in a beast-like (idol?), bound in attachment and senseless.","page":872,"meaning_status":"draft","note":"Construction uncertain; ਪਸੂ may refer to the worshipper ('like a beast you lie bound in attachment'). Uncertain."},{"gurmukhi":"ਰਾਮ ਕ੍ਰਿਸਨ ਰਸੂਲ ਕੋ ਉਠਿ ਲੇਤ ਨਿਤਪ੍ਰਤਿ ਨਾਉ।","roman":"Raam krisan rasool ko uthi let nitprati naau |","meaning_en":"You rise and daily take the names of Ram, Krishna and the Prophet,","page":872,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਵੈ ਅਬ ਜੀਅਤ ਜਗ ਮੈ ਕਹਾ ਤਿਨ ਕੋ ਗਾਉ। ੮੪।","roman":"Kahaa vai ab jeeat jag mai kahaa tin ko gaau | 84 |","meaning_en":"but where are they now, living in the world? Where is their village now?","page":872,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਿ","gurmukhi":"ਸੋਰਠਿ","roman":"Sorthi","meaning_en":"Sorath.","page":873,"meaning_status":"draft"},{"type":"verse","number":[85],"number_text":"੮੫।","page":873,"lines":[{"gurmukhi":"ਤਾਸ ਕਿਉ ਨ ਪਛਾਨਹੀ ਜੇ ਹੋਹਿ ਹੈ ਅਬ ਹੈ।","roman":"Taas kiu na pachhaanhee je hohi hai ab hai |","meaning_en":"Why do you not recognise Him who will be, who was, and who is now?","page":873,"meaning_status":"draft","note":"ਹੋਹਿ ਹੈ ਅਬ ਹੈ: read as past, future and present; uncertain wording."},{"gurmukhi":"ਨਿਹਫਲ ਕਾਹੇ ਭਜਤ ਪਾਹਨ ਤੋਹਿ ਕਛੁ ਫਲਿ ਦੈ।","roman":"Nihphal kaahe bhajat paahan tohi kachhu phali dai |","meaning_en":"Why worship stones fruitlessly? What fruit will they give you?","page":873,"meaning_status":"draft"},{"gurmukhi":"ਤਾਸੁ ਸੇਵਹੁ ਜਾਸ ਸੇਵਤਿ ਹੋਹਿ ਪੂਰਣ ਕਾਮ।","roman":"Taasu sevhu jaas sevti hohi pooran kaam |","meaning_en":"Serve Him, by serving whom all desires are fulfilled;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਹੋਹਿ ਮਨਸਾ ਸਕਲ ਪੂਰਣ ਲੈਤ ਜਾ ਕੇ ਨਾਮ। ੮੫।","roman":"Hohi mansaa sakal pooran lait jaa ke naam | 85 |","meaning_en":"all the wishes of the mind are fulfilled by taking His Name.","page":873,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਰਾਮਕਲੀ","gurmukhi":"ਬਿਸਨਪਦ। ਰਾਮਕਲੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | raamaklee | tvaprasaadi","meaning_en":"Bishanpad. In Raag Ramkali. By Your grace.","page":873,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[86],"number_text":"੮੬।","page":873,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਕੀਨੀ ਜਬੈ ਬਡਾਈ।","roman":"Ih bidhi keenee jabai badaaee |","meaning_en":"When he had praised her in this way,","page":873,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝੇ ਦੇਵ ਦਿਆਲ ਤਿਹ ਉਪਰ ਪੂਰਣ ਪੁਰਖ ਸੁਖਦਾਈ।","roman":"Reejhe dev diaal tih upar pooran purakh sukhdaaee |","meaning_en":"the merciful goddess was pleased with him, the perfect being, giver of joy.","page":873,"meaning_status":"draft","note":"Read as the goddess pleased with Parasnath; ਪੂਰਣ ਪੁਰਖ may also describe the deity. Uncertain."},{"gurmukhi":"ਆਪਨਿ ਮਿਲੇ ਦੇਵਿ ਦਰਸਨਿ ਭਯੋ ਸਿੰਘ ਕਰੀ ਅਸਵਾਰੀ।","roman":"Aapni mile devi darasni bhayo singh karee asvaaree |","meaning_en":"The goddess herself met him and appeared to him, riding on her lion;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਲੀਨੇ ਛਤ੍ਰ ਲੰਕੁਰਾ ਕੂਦਤ ਨਾਚਤ ਗਣ ਦੈ ਤਾਰੀ। ੮੬।","roman":"Leene chhatr lankuraa koodat naachat gan dai taaree | 86 |","meaning_en":"the Langur (attendant) held her canopy, jumping, and her attendants danced, clapping their hands.","page":873,"meaning_status":"draft","note":"ਲੰਕੁਰਾ: the Langur (monkey-like attendant of the goddess)."}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":873,"lines":[{"gurmukhi":"ਝਮਕਤ ਅਸਤ੍ਰ ਛਟਾ ਸਸਤ੍ਰਨਿ ਕੀ ਬਾਜਤ ਡਉਰ ਅਪਾਰ।","roman":"Jhamkat asatr chhataa sastrani kee baajat daur apaar |","meaning_en":"The weapons flashed and the arms glittered; countless dhaurs (drums) sounded;","page":873,"meaning_status":"draft","note":"ਡਉਰ: damru, a small drum."},{"gurmukhi":"ਨਿਰਤਤ ਭੂਤ ਪ੍ਰੇਤ ਨਾਨਾ ਬਿਧਿ ਡਹਕਤ ਫਿਰਤ ਬੈਤਾਰ।","roman":"Nirtat bhoot pret naanaa bidhi dahkat phirat baitaar |","meaning_en":"ghosts and spirits danced in many ways; the vampires (baitals) went about shrieking;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਕੁਹਕਤਿ ਫਿਰਤਿ ਕਾਕਣੀ ਕੁਹਰਤ ਡਹਕਤ ਕਠਨ ਮਸਾਨ।","roman":"Kuhakti phirti kaaknee kuhrat dahkat kathan masaan |","meaning_en":"the crows (or witches) went about cawing; the dreadful cremation grounds howled and shrieked;","page":873,"meaning_status":"draft","note":"ਕਾਕਣੀ: female crows or witches; uncertain."},{"gurmukhi":"ਘਹਰਤਿ ਗਗਨਿ ਸਘਨ ਰਿਖ ਦਹਲਤ ਬਿਚਰਤ ਬ੍ਯੋਮ ਬਿਵਾਨ। ੮੭।","roman":"Ghaharti gagni saghan rikh dahlat bichrat byom bivaan | 87 |","meaning_en":"the sky thundered thickly, the stars (sages?) trembled, and chariots of the gods moved through the sky.","page":873,"meaning_status":"draft","note":"ਰਿਖ: read as 'stars' or 'rishis'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਦੇਵੀ ਬਾਚ","gurmukhi":"ਦੇਵੀ ਬਾਚ","roman":"Devee baach","meaning_en":"The goddess said:","page":873,"meaning_status":"draft"},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | saarang | tvaprasaadi","meaning_en":"Bishanpad. In Raag Sarang. By Your grace.","page":873,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[88],"number_text":"੮੮।","page":873,"lines":[{"gurmukhi":"ਕਛੂ ਬਰ ਮਾਂਗਹੁ ਪੂਤ ਸਯਾਨੇ।","roman":"Kachhoo bar maanghu poot sayaane |","meaning_en":"\"Ask for some boon, my wise son;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਭੂਤ ਭਵਿਖ ਨਹੀ ਤੁਮਰੀ ਸਰ ਸਾਧ ਚਰਿਤ ਹਮ ਜਾਨੇ।","roman":"Bhoot bhavikh nahee tumree sar saadh charit ham jaane |","meaning_en":"\"in past or future none is your equal; I know your saintly conduct;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਬਰਦਾਨ ਚਹੋ ਸੋ ਮਾਂਗੋ ਸਬ ਹਮ ਤੁਮੈ ਦਿਵਾਰ।","roman":"Jo bardaan chaho so maango sab ham tumai divaar |","meaning_en":"\"ask for whatever boon you wish; I shall have it all given to you;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਕੰਚਨ ਰਤਨ ਬਜ੍ਰ ਮੁਕਤਾਫਲ ਲੀਜਹਿ ਸਕਲ ਸੁ ਧਾਰ। ੮੮।","roman":"Kanchan ratan bajr muktaaphal leejhi sakal su dhaar | 88 |","meaning_en":"\"gold, jewels, diamonds and pearls, take them all and keep them.\"","page":873,"meaning_status":"draft","note":"ਸੁ ਧਾਰ: 'keep, take'. ਬਜ੍ਰ: diamonds."}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸ ਨਾਥ ਬਾਚ","gurmukhi":"ਪਾਰਸ ਨਾਥ ਬਾਚ","roman":"Paaras naath baach","meaning_en":"Parasnath said:","page":873,"meaning_status":"draft"},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","roman":"Bisanpad | saarang","meaning_en":"Bishanpad. In Raag Sarang.","page":873,"meaning_status":"draft"},{"type":"verse","number":[89],"number_text":"੮੯।","page":873,"lines":[{"gurmukhi":"ਸਬ ਹੀ ਪੜੋ ਬੇਦ ਬਿਦਿਆ ਬਿਧਿ ਸਬ ਹੀ ਸਸਤ੍ਰ ਚਲਾਊ।","roman":"Sab hee paro bed bidiaa bidhi sab hee sasatr chalaaoo |","meaning_en":"\"May I master every Vedic learning and every method, and wield all weapons;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਸਬ ਹੀ ਦੇਸ ਜੇਰ ਕਰਿ ਆਪਨ ਆਪੇ ਮਤਾ ਮਤਾਊ।","roman":"Sab hee des jer kari aapan aape mataa mataaoo |","meaning_en":"\"may I subdue all lands and set up my own creed.\"","page":873,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿ ਤਥਾਸਤੁ ਭਈ ਲੋਪ ਚੰਡਿਕਾ ਤਾਸ ਮਹਾ ਬਰ ਦੈ ਕੈ।","roman":"Kahi tathaastu bhaee lop chandikaa taas mahaa bar dai kai |","meaning_en":"Saying \"So be it,\" Chandika vanished, having given him a great boon;","page":873,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤ੍ਰ ਧ੍ਯਾਨ ਹੁਐ ਗਈ ਆਪਨ ਪਰ ਸਿੰਘ ਅਰੂੜਤ ਹੂਐ ਕੈ। ੮੯।","roman":"Antr dhyaan huai gaee aapan par singh aroorat hooai kai | 89 |","meaning_en":"she disappeared, mounted on her lion.","page":873,"flags":[{"code":"ੁ+ੂ","reason":"overlapping ੁ and ੂ drawn as one ੂ"}],"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਗਉਰੀ","gurmukhi":"ਬਿਸਨਪਦ। ਗਉਰੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | gauree | tvaprasaadi","meaning_en":"Bishanpad. In Raag Gauri. By Your grace.","page":873,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[90],"number_text":"੯੦।","page":873,"lines":[{"gurmukhi":"ਪਾਰਸ ਕਰਿ ਡੰਡੌਤ ਫਿਰਿ ਆਏ।","roman":"Paaras kari dandaut phiri aae |","meaning_en":"Paras bowed down prostrate, and came back.","page":873,"meaning_status":"draft"},{"gurmukhi":"ਆਵਤ ਬੀਰ ਦੇਸ ਦੇਸਨ ਤੇ ਮਾਨੁਖ ਭੇਜ ਬੁਲਾਏ।","roman":"Aavat beer des desan te maanukh bhej bulaae |","meaning_en":"He sent men to call the heroes, who came from land after land.","page":873,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਕੋ ਰੂਪ ਬਿਲੋਕਿ ਸੁਭਟ ਸਭ ਚਕ੍ਰਿਤ ਚਿਤ ਬਿਸਮਾਏ।","roman":"Nrip ko roop biloki subhat sabh chakrit chit bismaae |","meaning_en":"Seeing the king's form, all the warriors were astonished and amazed at heart:","page":873,"meaning_status":"draft"},{"gurmukhi":"ਐਸੇ ਕਬਹੀ ਲਖੇ ਨਹੀ ਰਾਜਾ ਜੈਸੇ ਆਜ ਲਖਾਏ।","roman":"Aise kabhee lakhe nahee raajaa jaise aaj lakhaae |","meaning_en":"\"never have we seen such a king as we see today.\"","page":873,"meaning_status":"draft"},{"gurmukhi":"ਚਕ੍ਰਿਤ ਭਈ ਗਗਨਿ ਕੀ ਬਾਲਾ ਗਨ ਉਡਗਨ ਬਿਰਮਾਏ।","roman":"Chakrit bhaee gagni kee baalaa gan udgan birmaae |","meaning_en":"The maidens of the sky were astonished; the hosts of stars were charmed;","page":873,"meaning_status":"draft","note":"ਬਿਰਮਾਏ: 'were captivated' or 'halted'; uncertain."},{"gurmukhi":"ਝਿਮਝਿਮ ਮੇਘ ਬੂੰਦ ਜ੍ਯੋਂ ਦੇਵਨ ਅਮਰ ਪੁਹਪ ਬਰਖਾਏ।","roman":"Jhimjhim megh boond jyon devan amar puhap barkhaae |","meaning_en":"the gods rained down heavenly flowers like a pattering shower of rain;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਜੁਬਨ ਖਾਨ ਹੁਐ ਨਿਕਸੇ ਰੂਪ ਸਿੰਧੁ ਅਨੁਵਾਏ।","roman":"Jaanuk juban khaan huai nikse roop sindhu anuvaae |","meaning_en":"as if a mine of youth had come forth, or an ocean of beauty had come;","page":874,"meaning_status":"draft","note":"ਅਨੁਵਾਏ: uncertain; read as 'come forth'."},{"gurmukhi":"ਜਾਨੁਕ ਧਾਰਿ ਨਿਡਰ ਬਸੁਧਾ ਪਰ ਕਾਮ ਕਲੇਵਰ ਆਏ। ੯੦।","roman":"Jaanuk dhaari nidar basudhaa par kaam kalevar aae | 90 |","meaning_en":"as if Kama, fearless, had taken a body and come upon the earth.","page":874,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦਿ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦਿ। ਸਾਰੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisnapdi | saarang | tvaprasaadi","meaning_en":"Bishanpad. In Raag Sarang. By Your grace.","page":874,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft","note":"ਬਿਸਨਪਦਿ: printed so."},{"type":"verse","number":[91],"number_text":"੯੧।","page":874,"lines":[{"gurmukhi":"ਭੂਪਤਿ ਪਰਮ ਗ੍ਯਾਨ ਜਬ ਪਾਯੋ।","roman":"Bhoopti param gyaan jab paayo |","meaning_en":"When the king obtained the supreme knowledge,","page":874,"meaning_status":"draft"},{"gurmukhi":"ਮਨ ਬਚ ਕਰਮ ਕਠਨ ਕਰ ਤਾ ਕੋ ਜੌ ਕਰਿ ਧ੍ਯਾਨ ਲਗਾਯੋ।","roman":"Man bach karam kathan kar taa ko jau kari dhyaan lagaayo |","meaning_en":"which he had won by hard effort in mind, word and deed, fixing his meditation,","page":874,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਬਹੁ ਨ੍ਯਾਸ ਕਠਨ ਜਪੁ ਸਾਧ੍ਯੋ ਦਰਸਨਿ ਦੀਯੋ ਭਵਾਨੀ।","roman":"Kari bahu nyaas kathan japu saadhyo darasni deeyo bhavaanee |","meaning_en":"having done many nyasas and hard chanting, Bhavani gave him sight of herself;","page":874,"meaning_status":"draft","note":"ਨ੍ਯਾਸ: ritual placings (nyasa) of mantras on the body."},{"gurmukhi":"ਤਤਛਿਨ ਪਰਮ ਗ੍ਯਾਨ ਉਪਦੇਸ੍ਯੋ ਲੋਕ ਚਤੁਰ ਦਸ ਰਾਨੀ।","roman":"Tatchhin param gyaan updesyo lok chatur das raanee |","meaning_en":"at once the queen of the fourteen worlds taught him the supreme knowledge.","page":874,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਛਿਨ ਸਰਬ ਸਾਸਤ੍ਰ ਮੁਖ ਉਚਰੇ ਤਤ ਅਤਤ ਪਛਾਨਾ।","roman":"Tih chhin sarab saasatr mukh uchre tat atat pachhaanaa |","meaning_en":"In that instant he recited all the scriptures from his mouth, and recognised the real and the unreal;","page":874,"meaning_status":"draft","note":"ਤਤ ਅਤਤ: essence and non-essence."},{"gurmukhi":"ਅਵਰ ਅਤਤ ਸਬੈ ਕਰ ਜਾਨੇ ਏਕ ਤਤ ਠਹਰਾਨਾ।","roman":"Avar atat sabai kar jaane ek tat thahraanaa |","meaning_en":"he knew all else as unreal and settled upon the one Reality.","page":874,"meaning_status":"draft"},{"gurmukhi":"ਅਨਭਵ ਜੋਤਿ ਅਨੂਪ ਪ੍ਰਕਾਸੀ ਅਨਹਦ ਨਾਦ ਬਜਾਯੋ।","roman":"Anbhav joti anoop prakaasee anhad naad bajaayo |","meaning_en":"The peerless light of inner experience shone forth and the unstruck sound rang out;","page":874,"meaning_status":"draft","note":"ਅਨਹਦ ਨਾਦ: the unstruck melody."},{"gurmukhi":"ਦੇਸ ਬਿਦੇਸ ਜੀਤਿ ਰਾਜਨ ਕਹੁ ਸੁਭਟ ਅਭੈ ਪਦ ਪਾਯੋ। ੯੧।","roman":"Des bides jeeti raajan kahu subhat abhai pad paayo | 91 |","meaning_en":"conquering the kings of lands near and far, the warrior attained the state of fearlessness.","page":874,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਪਰਜ","gurmukhi":"ਬਿਸਨਪਦ। ਪਰਜ","roman":"Bisanpad | paraj","meaning_en":"Bishanpad. In Raag Paraj.","page":874,"meaning_status":"draft"},{"type":"verse","number":[92],"number_text":"੯੨।","page":874,"lines":[{"gurmukhi":"ਐਸੇ ਅਮਰਪਦ ਕਹੁ ਪਾਇ।","roman":"Aise amarpad kahu paai |","meaning_en":"Having attained such an immortal state,","page":874,"meaning_status":"draft"},{"gurmukhi":"ਦੇਸ ਅਉਰ ਬਿਦੇਸ ਭੂਪਤਿ ਜੀਤਿ ਲੀਨ ਬੁਲਾਇ।","roman":"Des aur bides bhoopti jeeti leen bulaai |","meaning_en":"he conquered the kings of his own and foreign lands and called them to him;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਭਰੇ ਗੁਮਾਨ ਨਿਸਾਨ ਸਰਬ ਬਜਾਇ।","roman":"Bhaati bhaati bhare gumaan nisaan sarab bajaai |","meaning_en":"filled with pride of every kind, they all sounded their drums;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਚਉਪ ਚਉਪ ਚਲੇ ਚਮੂੰਪਤਿ ਚਿਤ ਚਉਪ ਬਢਾਇ।","roman":"Chaup chaup chale chamoonpti chit chaup badhaai |","meaning_en":"the commanders came on eagerly, their hearts swelling with eagerness;","page":874,"meaning_status":"draft","note":"ਚਉਪ: eagerness, zeal."},{"gurmukhi":"ਆਨਿ ਆਨਿ ਸਬੈ ਲਗੇ ਪਗ ਭੂਪ ਕੇ ਜੁਹਰਾਇ।","roman":"Aani aani sabai lage pag bhoop ke juhraai |","meaning_en":"all came and touched the king's feet, greeting him with respect;","page":874,"meaning_status":"draft","note":"ਜੁਹਰਾਇ: from 'johar', a salutation."},{"gurmukhi":"ਆਵ ਆਵ ਸੁਭਾਵ ਸੋ ਕਹਿ ਲੀਨ ਕੰਠ ਲਗਾਇ।","roman":"Aav aav subhaav so kahi leen kanth lagaai |","meaning_en":"saying lovingly \"Come, come,\" he embraced them;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਹੀਰ ਚੀਰ ਸੁ ਬਾਜ ਦੈ ਗਜ ਰਾਜ ਦੈ ਪਹਿਰਾਇ।","roman":"Heer cheer su baaj dai gaj raaj dai pahiraai |","meaning_en":"giving diamonds, garments, fine horses and great elephants, he dressed them in robes of honour;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਸਾਧ ਦੈ ਸਨਮਾਨ ਕੈ ਕਰ ਲੀਨ ਚਿਤ ਚੁਰਾਇ। ੯੨।","roman":"Saadh dai sanmaan kai kar leen chit churaai | 92 |","meaning_en":"giving the saints honour, he stole their hearts away.","page":874,"meaning_status":"draft","note":"ਸਾਧ: read as 'the good / the saints'; it may instead mean 'skilfully (sadh)'. Uncertain."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | kaaphee | tvaprasaadi","meaning_en":"Bishanpad. In Raag Kafi. By Your grace.","page":874,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[93],"number_text":"੯੩।","page":874,"lines":[{"gurmukhi":"ਇਮ ਕਰ ਦਾਨ ਦੈ ਸਨਮਾਨ।","roman":"Im kar daan dai sanmaan |","meaning_en":"In this way, giving gifts and honour,","page":874,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਿਮੋਹਿ ਭੂਪਤਿ ਭੂਪ ਬੁਧ ਨਿਧਾਨ।","roman":"Bhaati bhaati bimohi bhoopti bhoop budh nidhaan |","meaning_en":"the king, a treasury of wisdom, enchanted the kings in many ways;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿਨ ਸਾਜ ਦੈ ਬਰ ਬਾਜ ਅਉ ਗਜਰਾਜ।","roman":"Bhaati bhaatin saaj dai bar baaj au gajraaj |","meaning_en":"giving many kinds of trappings, fine horses and great elephants,","page":874,"meaning_status":"draft"},{"gurmukhi":"ਆਪਨੇ ਕੀਨੋ ਨ੍ਰਿਪੰ ਸਬ ਪਾਰਸੈ ਮਹਾਰਾਜ।","roman":"Aapne keeno nripan sab paarsai mahaaraaj |","meaning_en":"the great king Paras made all the kings his own.","page":874,"meaning_status":"draft"},{"gurmukhi":"ਲਾਲ ਜਾਲ ਪ੍ਰਵਾਲ ਬਿਦ੍ਰਮ ਹੀਰ ਚੀਰ ਅਨੰਤ।","roman":"Laal jaal pravaal bidram heer cheer anant |","meaning_en":"Rubies in heaps, coral and red coral, diamonds and garments without end,","page":874,"meaning_status":"draft","note":"ਪ੍ਰਵਾਲ ਬਿਦ੍ਰਮ: both words mean coral."},{"gurmukhi":"ਲਛ ਲਛ ਸ੍ਵਰਣ ਸਿੰਙੀ ਦਿਜ ਏਕ ਏਕ ਮਿਲੰਤ।","roman":"Lachh lachh svaran sinngee dij ek ek milant |","meaning_en":"and gold-horned cows by the hundred thousand, each Brahmin received;","page":874,"meaning_status":"draft","note":"ਸ੍ਵਰਣ ਸਿੰਙੀ: cows with gilded horns, given in charity. ਦਿਜ: Brahmin."},{"gurmukhi":"ਮੋਹਿ ਭੂਪਿਤ ਭੂਮਿ ਕੈ ਇਕ ਕੀਨ ਜਗ ਬਨਾਇ।","roman":"Mohi bhoopit bhoomi kai ik keen jag banaai |","meaning_en":"having enchanted the kings of the earth, he arranged a great sacrifice;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸਭਾ ਬਨਾਇ ਸੁ ਬੈਠਿ ਭੂਪਤਿ ਆਇ। ੯੩।","roman":"Bhaati bhaati sabhaa banaai su baithi bhoopti aai | 93 |","meaning_en":"arranging the assembly in many ways, the king came and sat down.","page":874,"meaning_status":"draft"}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":874,"lines":[{"gurmukhi":"ਇਕ ਦਿਨ ਬੈਠੇ ਸਭਾ ਬਨਾਈ।","roman":"Ik din baithe sabhaa banaaee |","meaning_en":"One day he sat, having convened an assembly;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਬਡੇ ਬਡੇ ਛਤ੍ਰੀ ਬਸੁਧਾ ਕੇ ਲੀਨੇ ਨਿਕਟਿ ਬੁਲਾਈ।","roman":"Bade bade chhatree basudhaa ke leene nikti bulaaee |","meaning_en":"he called near him the great Kshatriyas of the earth,","page":874,"meaning_status":"draft"},{"gurmukhi":"ਅਰੁ ਜੇ ਹੁਤੇ ਦੇਸ ਦੇਸਨ ਮਤਿ ਤੇ ਭੀ ਸਰਬ ਬੁਲਾਏ।","roman":"Aru je hute des desan mati te bhee sarab bulaae |","meaning_en":"and all those who held the creeds of the various lands, he called them all too.","page":874,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਿ ਇਹ ਭਾਤਿ ਸਰਬ ਜਟਧਾਰੀ ਦੇਸ ਦੇਸ ਤੇ ਆਏ।","roman":"Suni ih bhaati sarab jatdhaaree des des te aae |","meaning_en":"Hearing this, all the matted-haired ascetics came from land after land;","page":874,"meaning_status":"draft"},{"gurmukhi":"ਨਾਨਾ ਭਾਤਿ ਜਟਨ ਕਹ ਧਾਰੇ ਅਰੁ ਮੁਖ ਬਿਭੂਤ ਲਗਾਏ।","roman":"Naanaa bhaati jatan kah dhaare aru mukh bibhoot lagaae |","meaning_en":"they had their matted hair dressed in many ways and ash smeared on their faces;","page":875,"meaning_status":"draft"},{"gurmukhi":"ਬਲਕੁਲ ਅੰਗਿ ਦੀਰਘ ਨਖ ਸੋਭਤ ਮ੍ਰਿਗਪਤਿ ਦੇਖ ਲਜਾਏ।","roman":"Balkul angi deeragh nakh sobhat mrigapti dekh lajaae |","meaning_en":"bark garments on their bodies and long nails shone, at which the lion would be ashamed;","page":875,"meaning_status":"draft","note":"ਬਲਕੁਲ: bark-cloth (valkal). The long nails put the lion's claws to shame."},{"gurmukhi":"ਮੁੰਦ੍ਰਤ ਨੇਤ੍ਰ ਊਰਧ ਕਰ ਓਪਤ ਪਰਮ ਕਾਛਨੀ ਕਾਛੇ।","roman":"Mundrat netr ooradh kar opat param kaachhnee kaachhe |","meaning_en":"eyes closed, arms raised up, splendid, with fine loincloths tied;","page":875,"meaning_status":"draft"},{"gurmukhi":"ਨਿਸ ਦਿਨ ਜਪ੍ਯੋ ਕਰਤ ਦਤਾਤ੍ਰੈ ਮਹਾ ਮੁਨੀਸਰ ਆਛੇ। ੯੪।","roman":"Nis din japyo karat dataatrai mahaa muneesar aachhe | 94 |","meaning_en":"night and day they chanted (the name of) Dattatreya, these fine great sages.","page":875,"meaning_status":"draft","note":"ਆਛੇ: 'fine, excellent'."}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ","roman":"Paarasnaath baach","meaning_en":"Parasnath said:","page":875,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਧਨਾਸਰੀ","gurmukhi":"ਧਨਾਸਰੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Dhanaasree | tvaprasaadi","meaning_en":"Dhanasari. By Your grace.","page":875,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[95],"number_text":"੯੫।","page":875,"lines":[{"gurmukhi":"ਕੈ ਤੁਮ ਹਮ ਕੋ ਪਰਚੌ ਦਿਖਾਓ।","roman":"Kai tum ham ko parchau dikhaao |","meaning_en":"\"Either show me some proof (of your powers),","page":875,"meaning_status":"draft","note":"ਪਰਚੌ: a demonstration, a miracle as proof."},{"gurmukhi":"ਨਾਤਰ ਜਿਤੇ ਤੁਮ ਹੋ ਜਟਧਾਰੀ ਸਬਹੀ ਜਟਾ ਮੁੰਡਾਓ।","roman":"Naatar jite tum ho jatdhaaree sabhee jataa mundaao |","meaning_en":"\"or else, all of you who wear matted hair, have your matted hair shaved off.","page":875,"meaning_status":"draft"},{"gurmukhi":"ਜੋਗੀ ਜੋਗੁ ਜਟਨ ਕੇ ਭੀਤਰ ਜੇ ਕਰ ਕਛੂਅਕ ਹੋਈ।","roman":"Jogee jogu jatan ke bheetar je kar kachhooak hoee |","meaning_en":"\"If there were any yoga in the matted hair of the yogis,","page":875,"meaning_status":"draft"},{"gurmukhi":"ਤਉ ਹਰਿ ਧ੍ਯਾਨ ਛੋਰਿ ਦਰ ਦਰ ਤੇ ਭੀਖ ਨ ਮਾਂਗੈ ਕੋਈ।","roman":"Tau hari dhyaan chhori dar dar te bheekh na maangai koee |","meaning_en":"\"then none would abandon meditation on the Lord to beg alms from door to door.","page":875,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਕਰ ਮਹਾ ਤਤ ਕਹੁ ਚੀਨੈ ਪਰਮ ਤਤ ਕਹੁ ਪਾਵੈ।","roman":"Je kar mahaa tat kahu cheenai param tat kahu paavai |","meaning_en":"\"If one recognised the great Essence, he would attain the supreme Essence;","page":875,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਯਹ ਮੋਨ ਸਾਧਿ ਮਨਿ ਬੈਠੇ ਅਨਤ ਨ ਖੋਜਨ ਧਾਵੈ।","roman":"Tab yah mon saadhi mani baithe anat na khojan dhaavai |","meaning_en":"\"then he would sit with his mind in silent discipline, and would not run elsewhere searching.","page":875,"meaning_status":"draft"},{"gurmukhi":"ਜਾਕੀ ਰੂਪ ਰੇਖ ਨਹੀ ਜਾਨੀਐ ਸਦਾ ਅਦ੍ਵੈਖ ਕਹਾਯੋ।","roman":"Jaakee roop rekh nahee jaaneeai sadaa advaikh kahaayo |","meaning_en":"\"He whose form and outline are not known has always been called without a second (or, without hatred);","page":875,"meaning_status":"draft","note":"ਅਦ੍ਵੈਖ: read as 'non-dual' (advait) or 'without enmity' (advesh). Uncertain."},{"gurmukhi":"ਜਉਨ ਅਭੇਖ ਰੇਖ ਨਹੀ ਸੋ ਕਹੁ ਭੇਖ ਬਿਖੈ ਕਿਉ ਆਯੋ। ੯੫।","roman":"Jaun abhekh rekh nahee so kahu bhekh bikhai kiu aayo | 95 |","meaning_en":"\"tell me, how could He who has no garb and no outline come within a garb?\"","page":875,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | saarang | tvaprasaadi","meaning_en":"Bishanpad. In Raag Sarang. By Your grace.","page":875,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[96],"number_text":"੯੬।","page":875,"lines":[{"gurmukhi":"ਜੇ ਜੇ ਤਿਨ ਮੈ ਹੁਤੇ ਸਯਾਨੇ।","roman":"Je je tin mai hute sayaane |","meaning_en":"All those among them who were wise,","page":875,"meaning_status":"draft"},{"gurmukhi":"ਪਾਰਸ ਪਰਮ ਤਤ ਕੇ ਬੇਤਾ ਮਹਾ ਪਰਮ ਕਰ ਮਾਨੇ।","roman":"Paaras param tat ke betaa mahaa param kar maane |","meaning_en":"accepted Paras as the knower of the supreme Essence, and as most exalted;","page":875,"meaning_status":"draft"},{"gurmukhi":"ਸਬਹਨਿ ਸੀਸ ਨ੍ਯਾਇ ਕਰਿ ਜੋਰੇ ਇਹ ਬਿਧਿ ਸੰਗਿ ਬਖਾਨੇ।","roman":"Sabahni sees nyaai kari jore ih bidhi sangi bakhaane |","meaning_en":"they all bowed their heads, joined their palms, and spoke to him thus:","page":875,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਜੋ ਗੁਰੂ ਕਹਾ ਸੋ ਕੀਨਾ ਅਉਰ ਹਮ ਕਛੂ ਨ ਜਾਨੇ।","roman":"Jo jo guroo kahaa so keenaa aur ham kachhoo na jaane |","meaning_en":"\"Whatever the Guru told us, that we have done; we know nothing else.","page":875,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਹੋ ਮਹਾਰਾਜ ਰਾਜਨ ਕੇ ਜੋ ਤੁਮ ਬਚਨ ਬਖਾਨੇ।","roman":"Sunho mahaaraaj raajan ke jo tum bachan bakhaane |","meaning_en":"\"Listen, great king of kings: the words that you have spoken,","page":875,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਹਮ ਦਤ ਬਕਤ੍ਰ ਤੇ ਸੁਨ ਕਰਿ ਸਾਚ ਹੀਐ ਅਨੁਮਾਨੇ।","roman":"So ham dat bakatr te sun kari saach heeai anumaane |","meaning_en":"\"we heard them from the mouth of Dutt and have judged them in our hearts to be true;","page":875,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਪਰਮ ਅੰਮ੍ਰਿਤ ਤੇ ਨਿਕਸੇ ਮਹਾ ਰਸਨ ਰਸ ਸਾਨੇ।","roman":"Jaanuk param anmrit te nikse mahaa rasan ras saane |","meaning_en":"\"as if they came out of supreme nectar, steeped in the finest flavour;","page":875,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਜੋ ਬਚਨ ਭਏ ਇਹ ਮੁਖਿ ਤੇ ਸੋ ਸੋ ਸਬ ਹਮ ਮਾਨੇ। ੯੬।","roman":"Jo jo bachan bhae ih mukhi te so so sab ham maane | 96 |","meaning_en":"\"every word that came from this mouth, we have accepted them all.\"","page":875,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"Bishanpad. In Raag Sorath.","page":875,"meaning_status":"draft"},{"type":"verse","number":[97],"number_text":"੯੭।","page":875,"lines":[{"gurmukhi":"ਜੋਗੀ ਜੋਗੁ ਜਟਨ ਮੋ ਨਾਹੀ।","roman":"Jogee jogu jatan mo naahee |","meaning_en":"\"O yogi, yoga is not in matted hair.","page":875,"meaning_status":"draft","note":"Read as Parasnath speaking again."},{"gurmukhi":"ਭ੍ਰਮ ਭ੍ਰਮ ਮਰਤ ਕਹਾ ਪਚਿ ਪਚਿ ਕਹਿ ਦੇਖਿ ਸਮਝ ਮਨ ਮਾਹੀ।","roman":"Bhram bhram marat kahaa pachi pachi kahi dekhi samajh man maahee |","meaning_en":"\"Why do you die wandering and wandering, wearing yourself out? Look, and understand it in your mind.","page":875,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਜਨ ਮਹਾ ਤਤ ਕਹੁ ਜਾਨੈ ਪਰਮ ਗ੍ਯਾਨ ਕਹੁ ਪਾਵੈ।","roman":"Jo jan mahaa tat kahu jaanai param gyaan kahu paavai |","meaning_en":"\"The person who knows the great Essence attains the supreme knowledge;","page":875,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਯਹ ਏਕ ਠਉਰ ਮਨੁ ਰਾਖੈ ਦਰਿ ਦਰਿ ਭ੍ਰਮਤ ਨ ਧਾਵੈ।","roman":"Tab yah ek thaur manu raakhai dari dari bhramat na dhaavai |","meaning_en":"\"then he keeps this mind in one place, and does not run wandering from door to door.","page":875,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਭਯੋ ਗ੍ਰਿਹ ਤਜਿ ਉਠਿ ਭਾਗੇ ਬਨ ਮੈ ਕੀਨ ਨਿਵਾਸਾ।","roman":"Kahaa bhayo grih taji uthi bhaage ban mai keen nivaasaa |","meaning_en":"\"What is gained by abandoning home and running off to live in the forest?","page":875,"meaning_status":"draft"},{"gurmukhi":"ਮਨ ਤੋ ਰਹਾ ਸਦਾ ਘਰ ਹੀ ਮੋ ਸੋ ਨਹੀ ਭਯੋ ਉਦਾਸਾ।","roman":"Man to rahaa sadaa ghar hee mo so nahee bhayo udaasaa |","meaning_en":"\"The mind always stayed at home; it never became detached.","page":875,"meaning_status":"draft"},{"gurmukhi":"ਅਧਿਕ ਪ੍ਰਪੰਚ ਦਿਖਾਇਆ ਠਗਾ ਜਗ ਜਾਨਿ ਜੋਗ ਕੋ ਜੋਰਾ।","roman":"Adhik prapanch dikhaaiaa thagaa jag jaani jog ko joraa |","meaning_en":"\"You put on a great show and cheated the world, knowing it as the power of yoga;","page":875,"meaning_status":"draft","note":"ਜੋਰਾ: read as 'power / force'; uncertain."},{"gurmukhi":"ਤੁਮ ਜੀਅ ਲਖਾ ਤਜੀ ਹਮ ਮਾਯਾ ਮਾਯਾ ਤੁਮੈ ਨ ਛੋਰਾ। ੯੭।","roman":"Tum jeea lakhaa tajee ham maayaa maayaa tumai na chhoraa | 97 |","meaning_en":"\"you thought in your heart, 'We have given up Maya,' but Maya has not let go of you.\"","page":875,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"Bishanpad. In Raag Sorath.","page":876,"meaning_status":"draft"},{"type":"verse","number":[98],"number_text":"੯੮।","page":876,"lines":[{"gurmukhi":"ਭੇਖੀ ਜੋਗ ਨ ਭੇਖ ਦਿਖਾਏ।","roman":"Bhekhee jog na bhekh dikhaae |","meaning_en":"\"Yoga is not shown by wearing a garb.","page":876,"meaning_status":"draft","note":"ਭੇਖੀ: 'one who wears a garb'."},{"gurmukhi":"ਨਾਹਨ ਜਟਾ ਬਿਭੂਤ ਨਖਨ ਮੈ ਨਾਹਿਨ ਬਸਤ੍ਰ ਰੰਗਾਏ।","roman":"Naahan jataa bibhoot nakhan mai naahin basatr rangaae |","meaning_en":"\"It is not in matted hair, ashes or nails, nor in dyed clothes.","page":876,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਬਨਿ ਬਸੈ ਜੋਗ ਕਹੁ ਪਈਐ ਪੰਛੀ ਸਦਾ ਬਸਤ ਬਨਿ।","roman":"Jo bani basai jog kahu paeeai panchhee sadaa basat bani |","meaning_en":"\"If yoga were gained by living in the forest, the birds always live in the forest;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਕੁੰਚਰ ਸਦਾ ਧੂਰਿ ਸਿਰਿ ਮੇਲਤ ਦੇਖਹੁ ਸਮਝ ਤੁਮ ਹੀ ਮਨਿ।","roman":"Kunchar sadaa dhoori siri melat dekhhu samajh tum hee mani |","meaning_en":"\"the elephant always puts dust on its head; look and understand this in your own mind.","page":876,"meaning_status":"draft"},{"gurmukhi":"ਦਾਦੁਰ ਮੀਨ ਸਦਾ ਤੀਰਥ ਮੋ ਕਰ੍ਯੋ ਕਰਤ ਇਸਨਾਨਾ।","roman":"Daadur meen sadaa teerath mo karyo karat isnaanaa |","meaning_en":"\"Frogs and fish are always bathing at places of pilgrimage;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਧ੍ਯਾਨ ਬਿੜਾਲ ਬਕੀ ਬਕ ਲਾਵਤ ਤਿਨ ਕਿਆ ਜੋਗੁ ਪਛਾਨਾ।","roman":"Dhyaan biraal bakee bak laavat tin kiaa jogu pachhaanaa |","meaning_en":"\"the cat, the female crane and the heron practise meditation; what yoga have they known?","page":876,"meaning_status":"draft"},{"gurmukhi":"ਜੈਸੇ ਕਸਟ ਠਗਨ ਕਰ ਠਾਟਤ ਐਸੇ ਹਰਿ ਹਿਤ ਕੀਜੈ।","roman":"Jaise kasat thagan kar thaatat aise hari hit keejai |","meaning_en":"\"The hardships you take on to cheat (the world), take on such for the love of the Lord;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਹੀ ਮਹਾ ਗ੍ਯਾਨ ਕੋ ਜਾਨੈ ਪਰਮ ਪਯੂਖਹਿ ਪੀਜੈ। ੯੮।","roman":"Tab hee mahaa gyaan ko jaanai param payookhhi peejai | 98 |","meaning_en":"\"only then will one know the great knowledge and drink the supreme nectar.\"","page":876,"meaning_status":"draft","note":"ਪਯੂਖ: nectar (piyush)."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","roman":"Bisanpad | saarang","meaning_en":"Bishanpad. In Raag Sarang.","page":876,"meaning_status":"draft"},{"type":"verse","number":[99],"number_text":"੯੯।","page":876,"lines":[{"gurmukhi":"ਸੁਨਿ ਸੁਨਿ ਐਸੇ ਬਚਨ ਸਿਯਾਨੇ।","roman":"Suni suni aise bachan siyaane |","meaning_en":"Hearing such words, the wise ones,","page":876,"meaning_status":"draft"},{"gurmukhi":"ਉਠਿ ਉਠਿ ਮਹਾ ਬੀਰ ਪਾਰਸ ਕੇ ਪਾਇਨ ਸੋ ਲਪਟਾਨੇ।","roman":"Uthi uthi mahaa beer paaras ke paain so laptaane |","meaning_en":"rising one by one, clung to the feet of the great hero Paras.","page":876,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਜੇ ਹੁਤੇ ਮੂੜ ਅਗਿਆਨੀ ਤਿਨ ਤਿਨ ਬੈਨ ਨ ਮਾਨੇ।","roman":"Je je hute moor agiaanee tin tin bain na maane |","meaning_en":"All those who were foolish and ignorant did not accept his words;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਉਠਿ ਉਠਿ ਲਗੇ ਕਰਨ ਬਕਬਾਦਹ ਮੂਰਖ ਮੁਗਧ ਇਆਨੇ।","roman":"Uthi uthi lage karan bakbaadah moorakh mugadh iaane |","meaning_en":"they rose up and began to argue, foolish, stupid and ignorant.","page":876,"meaning_status":"draft"},{"gurmukhi":"ਉਠਿ ਉਠਿ ਭਜੇ ਕਿਤੇ ਕਾਨਨ ਕੋ ਕੇਤਕਿ ਜਲਹਿ ਸਮਾਨੇ।","roman":"Uthi uthi bhaje kite kaanan ko ketki jalhi samaane |","meaning_en":"Rising, some fled to the forests, and some sank themselves in water;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਕ ਭਏ ਜੁਧ ਕਹਿ ਪ੍ਰਾਪਤਿ ਸੁਨਤ ਸਬਦੁ ਘਹਰਾਨੇ।","roman":"Ketak bhae judh kahi praapti sunat sabdu ghahraane |","meaning_en":"some went to battle, hearing the roar of the sound (of war drums);","page":876,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਕ ਆਨਿ ਆਨਿ ਸਨਮੁਖਿ ਭਏ ਕੇਤਕ ਛੋਰਿ ਪਰਾਨੇ।","roman":"Ketak aani aani sanmukhi bhae ketak chhori paraane |","meaning_en":"some came on, face to face, and some left and fled;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਕ ਜੂਝਿ ਸੋਭੇ ਰਣ ਮੰਡਲ ਬਾਸਵ ਲੋਕਿ ਸਿਧਾਨੇ। ੯੯।","roman":"Ketak joojhi sobhe ran mandal baasav loki sidhaane | 99 |","meaning_en":"some fought and shone on the field of battle, and went to the world of Indra.","page":876,"meaning_status":"draft","note":"ਬਾਸਵ: Vasav, Indra."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਤਿਲੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਤਿਲੰਗ। ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Bisanpad | tilang | tvaprasaadi kathtaa","meaning_en":"Bishanpad. In Raag Tilang. Spoken by Your grace.","page":876,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","meaning_status":"draft"},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":876,"lines":[{"gurmukhi":"ਜਬ ਹੀ ਸੰਖ ਸਬਦ ਘਹਰਾਏ।","roman":"Jab hee sankh sabad ghahraae |","meaning_en":"As soon as the conches sounded,","page":876,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਜੇ ਹੁਤੇ ਸੂਰ ਜਟਧਾਰੀ ਤਿਨ ਤਿਨ ਤੁਰੰਗ ਨਚਾਏ।","roman":"Je je hute soor jatdhaaree tin tin turang nachaae |","meaning_en":"all the heroes among the matted-haired ones made their horses dance;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਚਕ੍ਰਤ ਭਈ ਗਗਨ ਕੀ ਤਰੁਨੀ ਦੇਵ ਅਦੇਵ ਤ੍ਰਸਾਏ।","roman":"Chakrat bhaee gagan kee tarunee dev adev trasaae |","meaning_en":"the maidens of the sky were astonished; gods and demons were frightened;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖਤ ਭਯੋ ਸੂਰ ਰਥ ਥੰਭਤ ਨੈਨ ਨਿਮੇਖ ਨ ਲਾਏ।","roman":"Nirkhat bhayo soor rath thanbhat nain nimekh na laae |","meaning_en":"the sun halted his chariot to watch, and did not blink his eyes.","page":876,"meaning_status":"draft"},{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਨਾਨਾ ਬਿਧਿ ਛਡੇ ਬਾਣ ਪ੍ਰਯੋਘ ਚਲਾਏ।","roman":"Sasatr asatr naanaa bidhi chhade baan prayogh chalaae |","meaning_en":"They let fly weapons of many kinds and loosed showers of arrows,","page":876,"meaning_status":"draft","note":"ਪ੍ਰਯੋਘ: read as 'volleys'; uncertain."},{"gurmukhi":"ਮਾਨਹੁ ਮਾਹ ਮੇਘ ਬੂੰਦਨ ਜ੍ਯੋਂ ਬਾਣ ਬ੍ਯੂਹ ਬਰਸਾਏ।","roman":"Maanhu maah megh boondan jyon baan byooh barsaae |","meaning_en":"as if, like the drops of the clouds in the month of Magh, they rained down masses of arrows;","page":876,"meaning_status":"draft","note":"ਮਾਹ: read as the winter month Magh; uncertain."},{"gurmukhi":"ਚਟਪਟ ਚਰਮ ਬਰਮ ਪਰ ਚਟਕੇ ਦਾਝਤ ਤ੍ਰਿਣਾ ਲਜਾਏ।","roman":"Chatpat charam baram par chatke daajhat trinaa lajaae |","meaning_en":"they struck with a crackle on shields and armour, like dry grass catching fire;","page":876,"meaning_status":"draft","note":"ਚਟਪਟ: sound of the arrows striking. ਦਾਝਤ ਤ੍ਰਿਣਾ ਲਜਾਏ: 'putting burning straw to shame'."},{"gurmukhi":"ਸ੍ਰੋਣਤ ਭਰੇ ਬਸਤ੍ਰ ਸੋਭਿਤ ਜਨੁ ਚਾਚਰ ਖੇਲਿ ਸਿਧਾਏ। ੧੦੦।","roman":"Sronat bhare basatr sobhit janu chaachar kheli sidhaae | 100 |","meaning_en":"their clothes, soaked in blood, looked as if they had come from playing Holi.","page":876,"meaning_status":"draft","note":"ਚਾਚਰ: the spring festival (Holi) revels with coloured water."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਿਦਾਰਾ","gurmukhi":"ਬਿਸਨਪਦ। ਕਿਦਾਰਾ","roman":"Bisanpad | kidaaraa","meaning_en":"Bishanpad. In Raag Kidara.","page":876,"meaning_status":"draft"},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":876,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਯੋ ਆਹਵ ਘੋਰ।","roman":"Ih bidhi bhayo aahav ghor |","meaning_en":"In this way a dreadful battle took place.","page":876,"meaning_status":"draft"},{"gurmukhi":"ਭਾਪਿ ਭਾਤਿ ਗਿਰੇ ਧਰਾ ਪਰ ਸੂਰ ਸੁੰਦਰ ਕਿਸੋਰ।","roman":"Bhaapi bhaati gire dharaa par soor sundar kisor |","meaning_en":"Handsome young warriors fell on the earth in many ways;","page":876,"meaning_status":"draft","note":"ਭਾਪਿ ਭਾਤਿ: printed so; read as 'bhaat bhaat', in many ways."},{"gurmukhi":"ਕੋਪ ਕੋਪ ਹਠੀ ਘਟੀ ਰਣਿ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਚਲਾਇ।","roman":"Kop kop hathee ghatee rani sasatr asatr chalaai |","meaning_en":"in fury after fury the stubborn ones, unyielding in battle, plied their weapons;","page":876,"meaning_status":"draft","note":"ਘਟੀ: read as 'unbending'; uncertain."},{"gurmukhi":"ਜੂਝਿ ਜੂਝਿ ਗਏ ਦਿਵਾਲਯ ਢੋਲ ਬੋਲ ਬਜਾਇ।","roman":"Joojhi joojhi gae divaalay dhol bol bajaai |","meaning_en":"fighting on and on they went to the abode of the gods, to the sound of drums;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਹਾਇ ਹਾਇ ਭਈ ਜਹਾ ਤਹ ਭਾਜਿ ਭਾਜਿ ਸੁ ਬੀਰ।","roman":"Haai haai bhaee jahaa tah bhaaji bhaaji su beer |","meaning_en":"there were cries of woe here and there, as warriors fled and fled;","page":876,"meaning_status":"draft"},{"gurmukhi":"ਪੈਠਿ ਪੈਠਿ ਗਏ ਤ੍ਰੀਆਲੈ ਹਾਰਿ ਹਾਰਿ ਅਧੀਰ।","roman":"Paithi paithi gae treeaalai haari haari adheer |","meaning_en":"the faint-hearted, defeated again and again, went and hid in the women's quarters.","page":877,"meaning_status":"draft"},{"gurmukhi":"ਅਪ੍ਰਮਾਨ ਛੁਟੇ ਸਰਾਨ ਦਿਸਾਨ ਭਯੋ ਅੰਧਿਆਰ।","roman":"Apramaan chhute saraan disaan bhayo andhiaar |","meaning_en":"Countless arrows flew, and darkness fell over the directions;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਪਰੇ ਜਹਾ ਤਹ ਮਾਰਿ ਮਾਰਿ ਜੁਝਾਰ। ੧੦੧।","roman":"Took took pare jahaa tah maari maari jujhaar | 101 |","meaning_en":"hacking and slashing, the warriors lay in pieces here and there.","page":877,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਦੇਵਗੰਧਾਰੀ","gurmukhi":"ਬਿਸਨਪਦ। ਦੇਵਗੰਧਾਰੀ","roman":"Bisanpad | devgandhaaree","meaning_en":"Bishanpad. In Raag Devgandhari.","page":877,"meaning_status":"draft"},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":877,"lines":[{"gurmukhi":"ਮਾਰੂ ਸਬਦੁ ਸੁਹਾਵਨ ਬਾਜੈ।","roman":"Maaroo sabdu suhaavan baajai |","meaning_en":"The war music sounds splendidly.","page":877,"meaning_status":"draft","note":"ਮਾਰੂ: the martial measure."},{"gurmukhi":"ਜੇ ਜੇ ਹੁਤੇ ਸੁਭਟ ਰਣਿ ਸੁੰਦਰ ਗਹਿ ਗਹਿ ਆਯੁਦ ਗਾਜੇ।","roman":"Je je hute subhat rani sundar gahi gahi aayud gaaje |","meaning_en":"All the fine warriors on the field seized their weapons and roared;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਕਵਚ ਪਹਰਿ ਪਾਖਰ ਸੋ ਡਾਰੀ ਅਉਰੈ ਆਯੁਧ ਸਾਜੇ।","roman":"Kavach pahri paakhar so daaree aurai aayudh saaje |","meaning_en":"they put on armour, put the armour on the horses, and readied other weapons;","page":877,"meaning_status":"draft","note":"ਪਾਖਰ: horse-armour."},{"gurmukhi":"ਭਰੇ ਗੁਮਾਨ ਸੁਭਟ ਸਿੰਘਨ ਜ੍ਯੋਂ ਆਹਵ ਭੂਮਿ ਬਿਰਾਜੇ।","roman":"Bhare gumaan subhat singhan jyon aahav bhoomi biraaje |","meaning_en":"full of pride, the warriors stood like lions on the field of battle;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਗਹਿ ਗਹਿ ਚਲੇ ਗਦਾ ਗਾਜੀ ਸਬ ਸੁਭਟ ਅਯੋਧਨ ਕਾਜੇ।","roman":"Gahi gahi chale gadaa gaajee sab subhat ayodhan kaaje |","meaning_en":"grasping maces, all the champions went forward for the fight;","page":877,"meaning_status":"draft","note":"ਗਾਜੀ: champions (ghazi)."},{"gurmukhi":"ਆਹਵ ਭੂਮਿ ਸੂਰ ਅਸ ਸੋਭੇ ਨਿਰਖਿ ਇੰਦ੍ਰ ਦੁਤਿ ਲਾਜੇ।","roman":"Aahav bhoomi soor as sobhe nirkhi indr duti laaje |","meaning_en":"the heroes shone on the battlefield so that Indra was ashamed of his splendour, seeing them;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਹੂਐ ਗਿਰੇ ਧਰਣਿ ਪਰ ਆਹਵ ਛੋਰਿ ਨ ਭਾਜੇ।","roman":"Took took hooai gire dharni par aahav chhori na bhaaje |","meaning_en":"they fell to the earth in pieces, but did not leave the fight and flee;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਪਤਿ ਭਏ ਦੇਵ ਮੰਦਰ ਕਹੁ ਸਸਤ੍ਰਨ ਸੁਭਟ ਨਿਵਾਜੇ। ੧੦੨।","roman":"Praapti bhae dev mandar kahu sastran subhat nivaaje | 102 |","meaning_en":"they reached the temple of the gods; the warriors were honoured by the weapons.","page":877,"meaning_status":"draft","note":"ਸਸਤ੍ਰਨ ... ਨਿਵਾਜੇ: read as 'honoured through (dying by) weapons'; uncertain."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਲਿਆਨ","gurmukhi":"ਬਿਸਨਪਦ। ਕਲਿਆਨ","roman":"Bisanpad | kaliaan","meaning_en":"Bishanpad. In Raag Kalyan.","page":877,"meaning_status":"draft"},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":877,"lines":[{"gurmukhi":"ਦਹਦਿਸ ਧਾਵ ਭਏ ਜੁਝਾਰੇ।","roman":"Dahdis dhaav bhae jujhaare |","meaning_en":"The fighters ran in all ten directions.","page":877,"meaning_status":"draft"},{"gurmukhi":"ਮੁਦਗਰ ਗੁਫਨ ਗੁਰਜ ਗੋਲਾਲੇ ਪਟਸਿ ਪਰਘ ਪ੍ਰਹਾਰੇ।","roman":"Mudgar guphan guraj golaale patsi paragh prahaare |","meaning_en":"They struck with hammers, slings, maces, cannon-balls, battle-axes and clubs;","page":877,"meaning_status":"draft","note":"ਗੋਲਾਲੇ: read as 'balls (shot)'; ਪਟਸਿ: a kind of blade. Uncertain."},{"gurmukhi":"ਗਿਰਿ ਗਿਰਿ ਪਰੇ ਸੁਭਟ ਰਨ ਮੰਡਲਿ ਜਾਨੁ ਬਸੰਤ ਖਿਲਾਰੇ।","roman":"Giri giri pare subhat ran mandli jaanu basant khilaare |","meaning_en":"warriors fell and fell on the field, as if spring (flowers) were scattered;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਉਠਿ ਉਠਿ ਭਏ ਜੁਧ ਕਉ ਪ੍ਰਾਪਤਿ ਰੋਹ ਭਰੇ ਰਜਵਾਰੇ।","roman":"Uthi uthi bhae judh kau praapti roh bhare rajvaare |","meaning_en":"the princes, full of rage, rose and rose and came to the fight;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਭਖਿ ਭਖਿ ਬੀਰ ਪੀਸ ਦਾਤਨ ਕਹ ਰਣ ਮੰਡਲੀ ਹਕਾਰੇ।","roman":"Bhakhi bhakhi beer pees daatan kah ran mandlee hakaare |","meaning_en":"the heroes, blazing, gnashing their teeth, challenged one another on the field;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਬਰਛੀ ਬਾਨ ਕ੍ਰਿਪਾਨ ਗਜਾਇਧੁ ਅਸਤ੍ਰ ਸਸਤ੍ਰ ਸੰਭਾਰੇ।","roman":"Barchhee baan kripaan gajaaidhu asatr sasatr sanbhaare |","meaning_en":"they took up spears, arrows, swords, elephant-goads, and weapons of all kinds;","page":877,"meaning_status":"draft","note":"ਗਜਾਇਧੁ: read as 'elephant weapons / goads'; uncertain."},{"gurmukhi":"ਭਸਮੀ ਭੂਤ ਭਏ ਗੰਧ੍ਰਬ ਗਣ ਦਾਝਤ ਦੇਵ ਪੁਕਾਰੇ।","roman":"Bhasmee bhoot bhae gandhrab gan daajhat dev pukaare |","meaning_en":"hosts of Gandharvas were burnt to ashes, and the gods, scorched, cried out:","page":877,"meaning_status":"draft"},{"gurmukhi":"ਹਮ ਮਤ ਮੰਦ ਚਰਣ ਸਰਣਾਗਤਿ ਕਾਹਿ ਨ ਲੇਤ ਉਬਾਰੇ। ੧੦੩।","roman":"Ham mat mand charan sarnaagti kaahi na let ubaare | 103 |","meaning_en":"\"We are of dull mind and have come to the shelter of your feet; why do you not save us?\"","page":877,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਮਾਰੂ","gurmukhi":"ਮਾਰੂ","roman":"Maaroo","meaning_en":"Maru.","page":877,"meaning_status":"draft"},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":877,"lines":[{"gurmukhi":"ਦੋਊ ਦਿਸ ਸੁਭਟ ਜਬੈ ਜੁਰਿ ਆਏ।","roman":"Do'oo dis subhat jabai juri aae |","meaning_en":"When the warriors on both sides came together,","page":877,"meaning_status":"draft"},{"gurmukhi":"ਦੁੰਦਭਿ ਢੋਲ ਮ੍ਰਿਦੰਗ ਬਜਤ ਸੁਨਿ ਸਾਵਨ ਮੇਘ ਲਜਾਏ।","roman":"Dundbhi dhol mridang bajat suni saavan megh lajaae |","meaning_en":"kettledrums, drums and mridangs sounded; hearing them, the clouds of Sawan were put to shame;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖਨ ਦੇਵ ਅਦੇਵ ਮਹਾ ਹਵ ਚੜੇ ਬਿਮਾਨ ਸੁਹਾਏ।","roman":"Dekhan dev adev mahaa hav chare bimaan suhaae |","meaning_en":"to watch the great battle, gods and demons mounted their fine chariots of the air,","page":877,"meaning_status":"draft"},{"gurmukhi":"ਕੰਚਨ ਜਟਤ ਖਚੇ ਰਤਨਨ ਲਖਿ ਗੰਧ੍ਰਬ ਨਗਰ ਰਿਸਾਏ।","roman":"Kanchan jatat khache ratnan lakhi gandhrab nagar risaae |","meaning_en":"set with gold and studded with jewels; seeing them, the cities of the Gandharvas grew jealous.","page":877,"meaning_status":"draft","note":"ਰਿਸਾਏ: 'were angered / envious'."},{"gurmukhi":"ਕਾਛਿ ਕਛਿ ਕਾਛ ਕਛੇ ਕਛਨੀ ਚੜਿ ਕੋਪ ਭਰੇ ਨਿਜਕਾਏ।","roman":"Kaachhi kachhi kaachh kachhe kachhnee chari kop bhare nijkaae |","meaning_en":"Girding on their loincloths tightly, full of anger, they rode out themselves;","page":877,"meaning_status":"draft","note":"ਨਿਜਕਾਏ: read as 'themselves' or 'came near'; uncertain."},{"gurmukhi":"ਕੋਊ ਕੋਊ ਰਹੇ ਸੁਭਟ ਰਣ ਮੰਡਲਿ ਕੇਈ ਕੇਈ ਛਾਡਿ ਪਰਾਏ।","roman":"Ko'oo ko'oo rahe subhat ran mandli ke'ee ke'ee chhaadi paraae |","meaning_en":"some warriors stayed on the field, and some left and fled;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਝਿਮਝਿਮ ਮਹਾ ਮੇਘ ਪਰਲੈ ਜ੍ਯੋਂ ਬ੍ਰਿੰਦ ਬਿਸਿਖ ਬਰਸਾਏ।","roman":"Jhimjhim mahaa megh parlai jyon brind bisikh barsaae |","meaning_en":"like the great clouds pouring at the dissolution of the world, they rained down masses of arrows.","page":877,"meaning_status":"draft"},{"gurmukhi":"ਐਸੋ ਨਿਰਖਿ ਬਡੇ ਕਵਤਕ ਕਹ ਪਾਰਸ ਆਪ ਸਿਧਾਏ। ੧੦੪।","roman":"Aiso nirkhi bade kavtak kah paaras aap sidhaae | 104 |","meaning_en":"Seeing such a great spectacle, Paras himself set out.","page":877,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਭੈਰੋ","gurmukhi":"ਬਿਸਨਪਦ। ਭੈਰੋ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bisanpad | bhairo | tvaprasaadi","meaning_en":"Bishanpad. In Raag Bhairo. By Your grace.","page":877,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":877,"lines":[{"gurmukhi":"ਦੈ ਰੇ ਦੈ ਰੇ ਦੀਹ ਦਮਾਮਾ।","roman":"Dai re dai re deeh damaamaa |","meaning_en":"\"Beat, oh beat the great kettledrum!","page":877,"meaning_status":"draft","note":"Parasnath speaks."},{"gurmukhi":"ਕਰਹੌ ਰੁੰਡ ਮੁੰਡ ਬਸੁਧਾ ਪਰ ਲਖਤ ਸ੍ਵਰਗ ਕੀ ਬਾਮਾ।","roman":"Karhau rund mund basudhaa par lakhat svarag kee baamaa |","meaning_en":"\"I shall strew headless trunks and heads over the earth, while the women of heaven look on;","page":877,"meaning_status":"draft"},{"gurmukhi":"ਧੁਕਿ ਧੁਕਿ ਪਰਹਿ ਧਰਣਿ ਭਾਰੀ ਭਟ ਬੀਰ ਬੈਤਾਲ ਰਜਾਊ।","roman":"Dhuki dhuki parhi dharni bhaaree bhat beer baitaal rajaaoo |","meaning_en":"\"great warriors shall fall heavily, thudding on the earth; I shall sate the heroes and the vampires;","page":877,"meaning_status":"draft","note":"ਬੀਰ ਬੈਤਾਲ: Bir and Baital, spirits of the battlefield."},{"gurmukhi":"ਭੂਤ ਪਿਸਾਚ ਡਾਕਣੀ ਜੋਗਣ ਕਾਕਣ ਰੁਹਰ ਪਿਵਾਊ।","roman":"Bhoot pisaach daaknee jogan kaakan ruhar pivaaoo |","meaning_en":"\"I shall make ghosts, goblins, Dakinis, yoginis and crows (witches) drink blood;","page":877,"meaning_status":"draft","note":"ਰੁਹਰ: printed so; read as 'blood' (rudhir)."},{"gurmukhi":"ਭਕਿ ਭਕਿ ਉਠੇ ਭੀਮ ਭੈਰੋ ਰਣਿ ਅਰਧ ਉਰਧ ਸੰਘਾਰੋ।","roman":"Bhaki bhaki uthe bheem bhairo rani aradh uradh sanghaaro |","meaning_en":"\"terrible Bhairo shall rise roaring on the field; I shall destroy all below and above;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਇੰਦ੍ਰ ਚੰਦ ਸੂਰਜ ਬਰਣਾਦਿਕ ਆਜ ਸਭੈ ਚੁਨਿ ਮਾਰੋ।","roman":"Indr chand sooraj barnaadik aaj sabhai chuni maaro |","meaning_en":"\"Indra, the moon, the sun, Varun and the rest, I shall pick out and kill them all today.","page":878,"meaning_status":"draft"},{"gurmukhi":"ਮੋਹਿ ਬਰ ਦਾਨ ਦੇਵਤਾ ਦੀਨਾ ਜਿਹ ਸਰਿ ਅਉਰ ਨ ਕੋਈ।","roman":"Mohi bar daan devtaa deenaa jih sari aur na koee |","meaning_en":"\"The goddess has given me a boon; there is no other equal to me;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਮੈ ਹੀ ਭਯੋ ਜਗਤ ਕੋ ਕਰਤਾ ਜੋ ਮੈ ਕਰੌ ਸੁ ਹੋਈ। ੧੦੫।","roman":"Mai hee bhayo jagat ko kartaa jo mai karau su hoee | 105 |","meaning_en":"\"I alone have become the creator of the world; whatever I do, that will be.\"","page":878,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਗਉਰੀ","gurmukhi":"ਬਿਸਨਪਦ। ਗਉਰੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","roman":"Bisanpad | gauree | tvaprasaadi kathtaa","meaning_en":"Bishanpad. In Raag Gauri. Spoken by Your grace.","page":878,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ ਕਥਤਾ","meaning_status":"draft"},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":878,"lines":[{"gurmukhi":"ਮੋ ਤੇ ਆਉਰ ਬਲੀ ਕੋ ਹੈ।","roman":"Mo te aaur balee ko hai |","meaning_en":"\"Who else is mightier than I,","page":878,"meaning_status":"draft"},{"gurmukhi":"ਜਉਨ ਮੋ ਤੇ ਜੰਗ ਜੀਤੇ ਜੁਧ ਮੈ ਕਰ ਜੈ।","roman":"Jaun mo te jang jeete judh mai kar jai |","meaning_en":"\"who could win the war against me and gain victory in battle?","page":878,"meaning_status":"draft"},{"gurmukhi":"ਇੰਦ੍ਰ ਚੰਦ ਉਪਿੰਦ੍ਰ ਕੌ ਪਲ ਮਧਿ ਜੀਤੌ ਜਾਇ।","roman":"Indr chand upindr kau pal madhi jeetau jaai |","meaning_en":"\"Indra, the moon, Upendra (Vishnu), I could go and conquer in a moment;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਐਸੋ ਕੋ ਭਯੋ ਰਣ ਮਧਿ ਜੀਤੇ ਆਇ।","roman":"Aur aiso ko bhayo ran madhi jeete aai |","meaning_en":"\"who else has there been, who could come and win against me in battle?","page":878,"meaning_status":"draft"},{"gurmukhi":"ਸਾਤ ਸਿੰਧ ਸੁਕਾਇ ਡਾਰੋ ਨੈਕੁ ਰੋਸੁ ਕਰੋ।","roman":"Saat sindh sukaai daaro naiku rosu karo |","meaning_en":"\"I could dry up the seven seas if I grew a little angry;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਜਛ ਗੰਧ੍ਰਬ ਕਿੰਨ੍ਰ ਕੋਰ ਕਰੋਰ ਮੋਰਿ ਧਰੋ।","roman":"Jachh gandhrab kinnr kor karor mori dharo |","meaning_en":"\"Yakshas, Gandharvas and Kinnars by the million I could twist and put down;","page":878,"meaning_status":"draft","note":"ਕੋਰ ਕਰੋਰ: 'crores', millions. ਮੋਰਿ ਧਰੋ: read as 'twist and put down'; uncertain."},{"gurmukhi":"ਦੇਵ ਔਰ ਅਦੇਵ ਜੀਤੇ ਕਰੇ ਸਬੈ ਗੁਲਾਮ।","roman":"Dev aur adev jeete kare sabai gulaam |","meaning_en":"\"I have conquered gods and demons and made them all my slaves;","page":878,"meaning_status":"draft","note":"ਗੁਲਾਮ: slaves (Persian/Arabic)."},{"gurmukhi":"ਦਿਬ ਦਾਨ ਦਯੋ ਮੁਝੈ ਛੁਐ ਸਕੈ ਕੋ ਮੁਹਿ ਛਾਮ।੧੦੬।","roman":"Dib daan dayo mujhai chhuai sakai ko muhi chhaam | 106 |","meaning_en":"\"a divine gift was given to me; who can touch even my shadow?\"","page":878,"meaning_status":"draft","note":"ਛਾਮ: read as 'shadow' (chhaya); uncertain."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਮਾਰੂ","gurmukhi":"ਬਿਸਨਪਦ। ਮਾਰੂ","roman":"Bisanpad | maaroo","meaning_en":"Bishanpad. In Raag Maru.","page":878,"meaning_status":"draft"},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":878,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਪਾਰਸ ਰੋਸ ਬਢਾਯੋ।","roman":"Yau kahi paaras ros badhaayo |","meaning_en":"Saying this, Paras increased in wrath.","page":878,"meaning_status":"draft"},{"gurmukhi":"ਦੁੰਦਭਿ ਢੋਲ ਬਜਾਇ ਮਹਾ ਧੁਨਿ ਸਾਮੁਹਿ ਸੰਨ੍ਯਾਸਨਿ ਧਾਯੋ।","roman":"Dundbhi dhol bajaai mahaa dhuni saamuhi sannyaasni dhaayo |","meaning_en":"Sounding kettledrums and drums with a great din, he charged at the sannyasis;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਅਸਤ੍ਰ ਸਸਤ੍ਰ ਨਾਨਾ ਬਿਧਿ ਛਡੈ ਬਾਣ ਪ੍ਰਯੋਘ ਚਲਾਏ।","roman":"Asatr sasatr naanaa bidhi chhadai baan prayogh chalaae |","meaning_en":"letting fly weapons of many kinds, he loosed showers of arrows;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਸੁਭਟ ਸਨਾਹਿ ਪਤ੍ਰ ਚਲਦਲ ਜ੍ਯੋਂ ਬਾਨਨ ਬੇਧਿ ਉਡਾਏ।","roman":"Subhat sanaahi patr chaldal jyon baanan bedhi udaae |","meaning_en":"he pierced the warriors and their armour with arrows and sent them flying like the leaves of the peepal;","page":878,"meaning_status":"draft","note":"ਚਲਦਲ: the peepal tree, whose leaves always tremble."},{"gurmukhi":"ਦੁਹਦਿਸ ਬਾਨ ਪਾਨ ਤੇ ਛੂਟੇ ਦਿਨਪਤਿ ਦੇਹ ਦੁਰਾਨਾ।","roman":"Duhdis baan paan te chhoote dinapti deh duraanaa |","meaning_en":"the arrows flew from hands on both sides, and the body of the sun was hidden;","page":878,"meaning_status":"draft","note":"ਦਿਨਪਤਿ: 'lord of the day', the sun."},{"gurmukhi":"ਭੂਮਿ ਅਕਾਸ ਏਕ ਜਨੁ ਹੁਐ ਗਏ ਚਾਲ ਚਹੂੰ ਚਕ ਮਾਨਾ।","roman":"Bhoomi akaas ek janu huai gae chaal chahoon chak maanaa |","meaning_en":"earth and sky seemed to become one; the four quarters felt them moving (shaking);","page":878,"meaning_status":"draft","note":"ਚਾਲ ... ਮਾਨਾ: read as 'felt an earthquake'; uncertain."},{"gurmukhi":"ਇੰਦਰ ਚੰਦ੍ਰ ਮੁਨਿਵਰ ਸਬ ਕਾਪੇ ਬਸੁ ਦਿਗਿਪਾਲ ਡਰਾਨੀਯ।","roman":"Indar chandr munivar sab kaape basu digipaal daraaneey |","meaning_en":"Indra, the moon and the great sages all trembled; the Vasus and the guardians of the directions were frightened;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਬਰਨ ਕੁਬੇਰ ਛਾਡਿ ਪੁਰ ਭਾਜੇ ਦੁਤੀਯ ਪ੍ਰਲੈ ਕਰਿ ਮਾਨੀਯ। ੧੦੭।","roman":"Baran kuber chhaadi pur bhaaje duteey pralai kari maaneey | 107 |","meaning_en":"Varun and Kuber left their cities and fled, thinking it a second dissolution of the world.","page":878,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਮਾਰੂ","gurmukhi":"ਬਿਸਨਪਦ। ਮਾਰੂ","roman":"Bisanpad | maaroo","meaning_en":"Bishanpad. In Raag Maru.","page":878,"meaning_status":"draft"},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":878,"lines":[{"gurmukhi":"ਸੁਰਪੁਰ ਨਾਰਿ ਬਧਾਵਾ ਮਾਨਾ।","roman":"Surpur naari badhaavaa maanaa |","meaning_en":"The women of the city of the gods rejoiced:","page":878,"meaning_status":"draft","note":"ਬਧਾਵਾ: rejoicing, congratulation."},{"gurmukhi":"ਬਰਿ ਹੈ ਆਜ ਮਹਾ ਸੁਭਟਨ ਕੌ ਸਮਰ ਸੁਯੰਬਰ ਜਾਨਾ।","roman":"Bari hai aaj mahaa subhtan kau samar suyanbar jaanaa |","meaning_en":"\"Today we shall wed the great warriors,\" taking the battle to be a choosing of grooms (swayamvar);","page":878,"meaning_status":"draft","note":"ਸੁਯੰਬਰ: swayamvar, a bride's choice of husband. The apsaras are said to wed warriors who die in battle."},{"gurmukhi":"ਲਖਿ ਹੈ ਏਕ ਪਾਇ ਠਢੀ ਹਮ ਜਿਮ ਜਿਮ ਸੁਭਟ ਜੁਝੈ ਹੈ।","roman":"Lakhi hai ek paai thadhee ham jim jim subhat jujhai hai |","meaning_en":"\"we shall stand on one foot and watch, and as each warrior falls fighting,","page":878,"meaning_status":"draft"},{"gurmukhi":"ਤਿਮ ਤਿਮ ਘਾਲਿ ਪਾਲਕੀ ਆਪਨ ਅਮਰਪੁਰੀ ਲੈ ਜੈ ਹੈ।","roman":"Tim tim ghaali paalkee aapan amarpuree lai jai hai |","meaning_en":"\"so shall we put him in our palanquin and take him to the city of the immortals;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਚੰਦਨ ਚਾਰੁ ਚਿਤ੍ਰ ਚੰਦਨ ਕੇ ਚੰਚਲ ਅੰਗ ਚੜਾਊ।","roman":"Chandan chaaru chitr chandan ke chanchal ang charaaoo |","meaning_en":"\"we shall put lovely marks of sandal on our lively limbs,","page":878,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਦਿਨ ਸਮਰ ਸੁਅੰਬਰ ਕਰਿ ਕੈ ਪਰਮ ਪਿਅਰ ਵਹਿ ਪਾਊ।","roman":"Jaa din samar suanbar kari kai param piar vahi paaoo |","meaning_en":"\"on the day when, having made the battle a swayamvar, we win that dearest beloved;","page":878,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਦਿਨ ਦੇਹ ਸਫਲ ਕਰਿ ਮਾਨੋ ਅੰਗ ਸੀਗਾਰ ਧਰੋ।","roman":"Taa din deh saphal kari maano ang seegaar dharo |","meaning_en":"\"on that day I shall count my body fruitful and adorn my limbs,","page":878,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਦਿਨ ਸਮਰ ਸੁਯੰਬਰ ਸਖੀ ਰੀ ਪਾਰਸ ਨਾਥ ਬਰੋ। ੧੦੮।","roman":"Jaa din samar suyanbar sakhee ree paaras naath baro | 108 |","meaning_en":"\"the day when, O friend, in the swayamvar of battle I shall wed Parasnath.\"","page":878,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ","roman":"Bisanpad | kaaphee","meaning_en":"Bishanpad. In Raag Kafi.","page":878,"meaning_status":"draft"},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":878,"lines":[{"gurmukhi":"ਚਹੁ ਦਿਸ ਮਾਰੂ ਸਬਦ ਬਜੇ।","roman":"Chahu dis maaroo sabad baje |","meaning_en":"In all four directions the war music sounded.","page":878,"meaning_status":"draft"},{"gurmukhi":"ਗਹਿ ਗਹਿ ਗਦਾ ਗੁਰਜ ਗਾਜੀ ਸਬ ਹਠਿ ਰਣਿ ਆਨਿ ਗਜੇ।","roman":"Gahi gahi gadaa guraj gaajee sab hathi rani aani gaje |","meaning_en":"Grasping maces and clubs, all the champions came stubbornly to the field and roared;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਸੈਹਥੀ ਬਾਣ ਪ੍ਰਯੋਘ ਚਲਾਏ।","roman":"Baan kamaan kripaan saihthee baan prayogh chalaae |","meaning_en":"they plied arrows, bows, swords and lances, and loosed showers of arrows,","page":879,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਮਹਾ ਮੇਘ ਬੂੰਦਨ ਜ੍ਯੋਂ ਬਿਸਿਖ ਬ੍ਯੂਹਿ ਬਰਸਾਏ।","roman":"Jaanuk mahaa megh boondan jyon bisikh byoohi barsaae |","meaning_en":"as if the great clouds were raining masses of arrows like drops of rain;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਚਟਪਟ ਚਰਮ ਬਰਮ ਸਬ ਬੇਧੇ ਸਟਪਟ ਪਾਰ ਪਰਾਨੇ।","roman":"Chatpat charam baram sab bedhe satpat paar paraane |","meaning_en":"with a crackle they pierced all the shields and armour and passed swiftly right through;","page":879,"meaning_status":"draft","note":"ਚਟਪਟ, ਸਟਪਟ, ਖਟਪਟ: sound-words for the arrows' speed and impact."},{"gurmukhi":"ਖਟਪਟ ਸਰਬ ਭੂਮਿ ਕੇ ਬੇਧੇ ਨਾਗਨ ਲੋਕ ਸਿਧਾਨੇ।","roman":"Khatpat sarab bhoomi ke bedhe naagan lok sidhaane |","meaning_en":"piercing through the whole earth with a clatter, they went on to the world of the serpents;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਝਮਕਤ ਖੜਗ ਕਾਢਿ ਨਾਨਾ ਬਿਧਿ ਸੈਹਥੀ ਸੁਭਟ ਚਲਾਵਤ।","roman":"Jhamkat kharag kaadhi naanaa bidhi saihthee subhat chalaavat |","meaning_en":"the warriors drew flashing swords and plied lances in many ways,","page":879,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਪ੍ਰਗਟ ਬਾਟ ਸੁਰ ਪੁਰ ਕੀ ਨੀਕੇ ਹਿਰਦੇ ਦਿਖਾਵਤ। ੧੦੯।","roman":"Jaanuk pragat baat sur pur kee neeke hirde dikhaavat | 109 |","meaning_en":"as if openly showing the good hearts (of the warriors) the way to the city of the gods.","page":879,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"Bishanpad. In Raag Sorath.","page":879,"meaning_status":"draft"},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":879,"lines":[{"gurmukhi":"ਬਾਨਨ ਬੇਧੇ ਅਮਿਤ ਸੰਨਿਆਸੀ।","roman":"Baanan bedhe amit sanniaasee |","meaning_en":"Countless sannyasis were pierced with arrows;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਤੇ ਤਜ ਦੇਹ ਨੇਹ ਸੰਪਤਿ ਕੋ ਭਏ ਸੁਰਗ ਕੇ ਬਾਸੀ।","roman":"Te taj deh neh sanpti ko bhae surag ke baasee |","meaning_en":"they left their bodies, and their love of wealth, and became dwellers of heaven;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਚਰਮ ਬਰਮ ਰਥ ਧੁਜਾ ਪਤਾਕਾ ਬਹੁ ਬਿਧਿ ਕਾਟਿ ਗਿਰਾਏ।","roman":"Charam baram rath dhujaa pataakaa bahu bidhi kaati giraae |","meaning_en":"shields, armour, chariots, flags and banners were cut down in many ways;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਸੋਭਤ ਭਏ ਇੰਦ੍ਰ ਪੁਰ ਜਮ ਪੁਰ ਸੁਰ ਪੁਰ ਨਿਰਖ ਲਜਾਏ।","roman":"Sobhat bhae indr pur jam pur sur pur nirakh lajaae |","meaning_en":"(the field) looked so splendid that Indra's city, Yama's city and the city of the gods were ashamed to see it;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਭੂਖਨ ਬਸਤ੍ਰ ਰੰਗ ਰੰਗਨ ਕੇ ਛੁਟਿ ਛੁਟਿ ਭੂਮਿ ਗਿਰੇ।","roman":"Bhookhan basatr rang rangan ke chhuti chhuti bhoomi gire |","meaning_en":"ornaments and clothes of every colour came loose and fell to the ground,","page":879,"meaning_status":"draft"},{"gurmukhi":"ਜਨੁਕ ਅਸੋਕ ਬਾਗ ਦਿਵਪਤਿ ਕੇ ਪੁਹਪ ਬਸੰਤਿ ਝਰੇ।","roman":"Januk asok baag divapti ke puhap basanti jhare |","meaning_en":"as if the flowers of the Ashok garden of the lord of heaven had fallen in spring;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਕਟਿ ਕਟਿ ਗਿਰੇ ਗਜਨ ਕੁੰਭ ਸਥਲ ਮੁਕਤਾ ਬਿਥੁਰਿ ਪਰੇ।","roman":"Kati kati gire gajan kunbh sathal muktaa bithuri pare |","meaning_en":"the elephants' temples were cut open and fell, and the pearls were scattered,","page":879,"meaning_status":"draft","note":"Pearls were believed to form in elephants' temples."},{"gurmukhi":"ਜਾਨੁਕ ਅੰਮ੍ਰਿਤ ਕੁੰਡ ਮੁਖ ਛੁਟੈ ਜਲ ਕਨ ਸੁਭਗ ਝਰੇ। ੧੧੦।","roman":"Jaanuk anmrit kund mukh chhutai jal kan subhag jhare | 110 |","meaning_en":"as if fine drops of water had sprinkled out from the mouth of a pool of nectar.","page":879,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੇਵ ਗੰਧਾਰੀ। ਦੂਜੀ ਤਰਹ","gurmukhi":"ਦੇਵ ਗੰਧਾਰੀ। ਦੂਜੀ ਤਰਹ","roman":"Dev gandhaaree | doojee tarah","meaning_en":"Devgandhari. In the second style.","page":879,"meaning_status":"draft","note":"ਦੂਜੀ ਤਰਹ: 'in another manner (of singing)'."},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":879,"lines":[{"gurmukhi":"ਦੁਹ ਦਿਸ ਪਰੇ ਬੀਰ ਹਕਾਰਿ।","roman":"Duh dis pare beer hakaari |","meaning_en":"On both sides the heroes fell upon each other, challenging;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਕਾਢਿ ਕਾਢਿ ਕ੍ਰਿਪਾਣ ਧਾਵਤ ਮਾਰੁ ਮਾਰੁ ਉਚਾਰਿ।","roman":"Kaadhi kaadhi kripaan dhaavat maaru maaru uchaari |","meaning_en":"drawing their swords they rushed, shouting \"Kill, kill!\"","page":879,"meaning_status":"draft"},{"gurmukhi":"ਪਾਨ ਰੋਕਿ ਸਰੋਖ ਰਾਵਤ ਕ੍ਰੁਧ ਜੁਧ ਫਿਰੇ।","roman":"Paan roki sarokh raavat krudh judh phire |","meaning_en":"holding back their hands (?), the angry chiefs turned in wrath to the battle;","page":879,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਪਾਨ ਰੋਕਿ: read as 'stopping blows with their hands' or 'checking (their) hands'; uncertain."},{"gurmukhi":"ਗਾਹਿ ਗਾਹਿ ਗਜੀ ਰਥੀ ਰਣਿ ਅੰਤਿ ਭੂਮਿ ਗਿਰੇ।","roman":"Gaahi gaahi gajee rathee rani anti bhoomi gire |","meaning_en":"churning (the field), elephant-riders and charioteers fell at last to the ground in battle;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਤਾਨਿ ਤਾਨਿ ਸੰਧਾਨ ਬਾਨ ਪ੍ਰਮਾਨ ਕਾਨ ਸੁਬਾਹਿ।","roman":"Taani taani sandhaan baan pramaan kaan subaahi |","meaning_en":"drawing and fitting arrows to the bow, pulling them to the ear, the strong-armed ones","page":879,"meaning_status":"draft","note":"ਪ੍ਰਮਾਨ ਕਾਨ: 'as far as the ear'."},{"gurmukhi":"ਬਾਹਿ ਬਾਹਿ ਫਿਰੇ ਸੁਬਾਹਨ ਛਤ੍ਰ ਧਰਮ ਨਿਬਾਹਿ।","roman":"Baahi baahi phire subaahan chhatr dharam nibaahi |","meaning_en":"loosed them again and again, and went about on their fine mounts, keeping the dharma of the Kshatriya.","page":879,"meaning_status":"draft","note":"ਸੁਬਾਹਨ: read as 'fine mounts', or 'strong arms'; uncertain."},{"gurmukhi":"ਬੇਧਿ ਬੇਧਿ ਸੁ ਬਾਨ ਅੰਗ ਜੁਆਨ ਜੁਝੇ ਐਸ।","roman":"Bedhi bedhi su baan ang juaan jujhe ais |","meaning_en":"With fine arrows piercing their limbs, the young men fell fighting in such a way,","page":879,"meaning_status":"draft"},{"gurmukhi":"ਭੂਰਿ ਭਾਰਥ ਕੇ ਸਮੇ ਸਰ ਸੇਜ ਭੀਖਮ ਜੈਸ। ੧੧੧।","roman":"Bhoori bhaarath ke same sar sej bheekham jais | 111 |","meaning_en":"as Bhishma lay on his bed of arrows in the time of the great Bharat war.","page":879,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","gurmukhi":"ਬਿਸਨਪਦ। ਸਾਰੰਗ","roman":"Bisanpad | saarang","meaning_en":"Bishanpad. In Raag Sarang.","page":879,"meaning_status":"draft"},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":879,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਬਹੁਤੁ ਸੰਨਿਆਸੀ ਮਾਰੇ।","roman":"Ih bidhi bahutu sanniaasee maare |","meaning_en":"In this way many sannyasis were killed.","page":879,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਿਕ ਬਾਧਿ ਬਾਰਿ ਮੋ ਬੋਰੇ ਕਿਤੇ ਅਗਨਿ ਮੋ ਸਾਰੇ।","roman":"Ketik baadhi baari mo bore kite agni mo saare |","meaning_en":"Some were bound and drowned in water, some were burnt in fire;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਨ ਏਕ ਹਾਥ ਕਟਿ ਡਾਰੇ ਕੇਤਿਨ ਕੇ ਦ੍ਵੈ ਹਾਥ।","roman":"Ketan ek haath kati daare ketin ke dvai haath |","meaning_en":"some had one hand cut off, and some both hands;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਤਿਲ ਤਿਲ ਪਾਇ ਰਥੀ ਕਟਿ ਡਾਰੇ ਕਟੇ ਕਿਤਨ ਕੇ ਮਾਥ।","roman":"Til til paai rathee kati daare kate kitan ke maath |","meaning_en":"charioteers were cut into pieces small as sesame seeds, and some had their heads cut off;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਛਤ੍ਰ ਚਮ੍ਰ ਰਥ ਬਾਜ ਕਿਤਨੇ ਕੇ ਕਾਟਿ ਕਾਟਿ ਰਣਿ ਡਾਰੇ।","roman":"Chhatr chamr rath baaj kitne ke kaati kaati rani daare |","meaning_en":"the canopies, whisks, chariots and horses of many were cut and cut and thrown down on the field;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਕੇਤਨ ਮੁਕਟ ਲਕੁਟ ਲੈ ਤੋਰੇ ਕੇਤਨ ਜੂਟ ਉਪਾਰੇ।","roman":"Ketan mukat lakut lai tore ketan joot upaare |","meaning_en":"some had their crowns smashed with clubs, and some had their topknots torn out;","page":879,"meaning_status":"draft"},{"gurmukhi":"ਭਕਿ ਭਕਿ ਗਿਰੇ ਭਿੰਭਰ ਬਸੁਧਾ ਪਰ ਘਾਇ ਅੰਗ ਭਿਭਰਾਰੇ।","roman":"Bhaki bhaki gire bhinbhar basudhaa par ghaai ang bhibhraare |","meaning_en":"gasping, they fell trembling on the earth, their limbs shaken by wounds,","page":879,"meaning_status":"draft","note":"ਭਿੰਭਰ, ਭਿਭਰਾਰੇ: read as 'trembling, in panic'; uncertain."},{"gurmukhi":"ਜਾਨੁਕ ਅੰਤ ਬਸੰਤ ਸਮੈ ਮਿਲਿ ਚਾਚਰ ਖੇਲ ਸਿਧਾਰੇ। ੧੧੨।","roman":"Jaanuk ant basant samai mili chaachar khel sidhaare | 112 |","meaning_en":"as if at the end of spring they had gone off together after playing Holi.","page":879,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਅਡਾਨ","gurmukhi":"ਬਿਸਨਪਦ। ਅਡਾਨ","roman":"Bisanpad | adaan","meaning_en":"Bishanpad. In Raag Adan.","page":880,"meaning_status":"draft"},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":880,"lines":[{"gurmukhi":"ਚੁਪਰੇ ਚਾਰੁ ਚਿਕਨੇ ਕੇਸ।","roman":"Chupre chaaru chikne kes |","meaning_en":"With hair oiled, lovely and glossy,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਆਨਿ ਆਨਿ ਫਿਰੀ ਚਹੂੰ ਦਿਸਿ ਨਾਰਿ ਨਾਗਰਿ ਭੇਸ।","roman":"Aani aani phiree chahoon disi naari naagri bhes |","meaning_en":"women in fine attire came and went about in all four directions;","page":880,"meaning_status":"draft","note":"ਨਾਗਰਿ: refined, of the city."},{"gurmukhi":"ਚਿਬਕ ਚਾਰੁ ਸੁ ਧਾਰ ਬੇਸਰ ਡਾਰਿ ਕਾਜਰ ਨੈਨ।","roman":"Chibak chaaru su dhaar besar daari kaajar nain |","meaning_en":"with lovely chins, wearing nose-rings, with collyrium in their eyes,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜੀਵ ਜੰਤਨ ਕਾ ਚਲੀ ਚਿਤ ਲੇਤ ਚੋਰ ਸੁ ਮੈਨ।","roman":"Jeev jantan kaa chalee chit let chor su main |","meaning_en":"they went along stealing the hearts of all living beings, like Kama himself, the thief of hearts.","page":880,"meaning_status":"draft","note":"Read as the heavenly women (apsaras) come to the battlefield."},{"gurmukhi":"ਦੇਖ ਰੀ ਸੁਕੁਮਾਰ ਸੁੰਦਰ ਆਜੁ ਬਰ ਹੈ ਬੀਰ।","roman":"Dekh ree sukumaar sundar aaju bar hai beer |","meaning_en":"\"Look, friend, today we shall wed the tender, handsome heroes;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਬੀਨ ਬੀਨ ਧਰੋ ਸਬੰਗਨ ਸੁਧ ਕੇਸਰਿ ਚੀਰ।","roman":"Been been dharo sabangan sudh kesri cheer |","meaning_en":"\"pick them out and dress all our limbs in pure saffron robes;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਚੀਨ ਚੀਨ ਬਰਿ ਹੈ ਸੁਬਾਹ ਸੁ ਮਧ ਜੁਧ ਉਛਾਹ।","roman":"Cheen cheen bari hai subaah su madh judh uchhaah |","meaning_en":"\"we shall choose and wed the strong-armed ones, eager for battle;","page":880,"meaning_status":"draft","note":"ਸੁ ਮਧ ਜੁਧ ਉਛਾਹ: read as 'eager in the midst of battle'; uncertain."},{"gurmukhi":"ਤੇਗ ਤੀਰਨ ਬਾਨ ਬਰਛਨ ਜੀਤ ਕਰਿ ਹੈ ਬਯਾਹ। ੧੧੩।","roman":"Teg teeran baan barchhan jeet kari hai bayaah | 113 |","meaning_en":"\"winning them by swords, arrows, darts and spears, we shall marry them.\"","page":880,"meaning_status":"draft","note":"ਤੇਗ: sword (Persian)."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"Bishanpad. In Raag Sorath.","page":880,"meaning_status":"draft"},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":880,"lines":[{"gurmukhi":"ਕਹਾ ਲੌ ਉਪਮਾ ਇਤੀ ਕਰੌ।","roman":"Kahaa lau upmaa itee karau |","meaning_en":"How far shall I go on making such comparisons?","page":880,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਰੰਥ ਬਢਨ ਕੇ ਕਾਜ ਸੁਨਹੁ ਜੂ ਚਿਤ ਮੈ ਅਧਿਕ ਡਰੌ।","roman":"Granth badhan ke kaaj sunhu joo chit mai adhik darau |","meaning_en":"Listen, sir: I greatly fear in my heart that the book will grow too long;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਤਉ ਸੁਧਾਰਿ ਬਿਚਾਰ ਕਥਾ ਕਹਿ ਕਹਿ ਸੰਛੇਪ ਬਖਾਨੋ।","roman":"Tau sudhaari bichaar kathaa kahi kahi sanchhep bakhaano |","meaning_en":"so, having reflected and put it in order, I tell the story briefly,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜੈਸੇ ਤਵ ਪ੍ਰਤਾਪ ਕੇ ਬਲ ਤੇ ਜਥਾ ਸਕਤਿ ਅਨੁਮਾਨੋ।","roman":"Jaise tav prataap ke bal te jathaa sakti anumaano |","meaning_en":"as far as I can judge, by the strength of Your glory.","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਪਾਰਸ ਇਹ ਬਿਧਿ ਰਨ ਮੰਡ੍ਯੋ ਨਾਨਾ ਸਸਤ੍ਰ ਚਲਾਏ।","roman":"Jab paaras ih bidhi ran mandyo naanaa sasatr chalaae |","meaning_en":"When Paras had arrayed the battle in this way and plied many weapons,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਹਤੇ ਸੁ ਹਤੇ ਜੀਅ ਲੈ ਭਾਜੇ ਚਹੁੰ ਦਿਸ ਗਏ ਪਰਾਏ।","roman":"Hate su hate jeea lai bhaaje chahun dis gae paraae |","meaning_en":"those who were killed were killed; others fled with their lives and ran off in all four directions;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਹਠ ਤਿਆਗਿ ਆਨਿ ਪਗ ਲਾਗੇ ਤੇ ਸਬ ਲਏ ਬਚਾਈ।","roman":"Je hath tiaagi aani pag laage te sab lae bachaaee |","meaning_en":"those who gave up their stubbornness and came and fell at his feet, he saved them all,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਭੂਖਨ ਬਸਨ ਬਹੁਤੁ ਬਿਧਿ ਦੀਨੇ ਦੈ ਦੈ ਬਹੁਤ ਬਡਾਈ। ੧੧੪।","roman":"Bhookhan basan bahutu bidhi deene dai dai bahut badaaee | 114 |","meaning_en":"and gave them ornaments and clothes in many ways, giving them great honour.","page":880,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਕਾਫੀ","gurmukhi":"ਬਿਸਨਪਦ। ਕਾਫੀ","roman":"Bisanpad | kaaphee","meaning_en":"Bishanpad. In Raag Kafi.","page":880,"meaning_status":"draft"},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":880,"lines":[{"gurmukhi":"ਪਾਰਸ ਨਾਥ ਬਡੋ ਰਣ ਪਾਰ੍ਯੋ।","roman":"Paaras naath bado ran paaryo |","meaning_en":"Parasnath fought a great battle.","page":880,"meaning_status":"draft","note":"ਪਾਰ੍ਯੋ: read as 'waged / accomplished'."},{"gurmukhi":"ਆਪਨ ਪ੍ਰਚੁਰ ਜਗਤ ਮਤੁ ਕੀਨਾ ਦੇਵਦਤ ਕੋ ਟਾਰ੍ਯੋ।","roman":"Aapan prachur jagat matu keenaa devdat ko taaryo |","meaning_en":"He made his own creed widespread in the world and put aside that of Dev Dutt;","page":880,"meaning_status":"draft","note":"ਦੇਵਦਤ: read as 'the god Dutt' (Dattatreya)."},{"gurmukhi":"ਲੈ ਲੈ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਨਾਨਾ ਬਿਧਿ ਭਾਤਿ ਅਨਿਕ ਅਰਿ ਮਾਰੇ।","roman":"Lai lai sasatr asatr naanaa bidhi bhaati anik ari maare |","meaning_en":"taking up weapons of many kinds, he killed enemies in many ways;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜੀਤੇ ਪਰਮ ਪੁਰਖ ਪਾਰਸ ਕੇ ਸਗਲ ਜਟਾ ਧਰ ਹਾਰੇ।","roman":"Jeete param purakh paaras ke sagal jataa dhar haare |","meaning_en":"the supreme man Paras won, and all the matted-haired ones lost.","page":880,"meaning_status":"draft"},{"gurmukhi":"ਬੇਖ ਬੇਖ ਭਟ ਪਰੇ ਧਰਨ ਗਿਰਿ ਬਾਣ ਪ੍ਰਯੋਘਨ ਘਾਏ।","roman":"Bekh bekh bhat pare dharan giri baan prayoghan ghaae |","meaning_en":"Pierced through and through, the warriors fell to the earth, struck by showers of arrows,","page":880,"meaning_status":"draft","note":"ਬੇਖ ਬੇਖ: read as 'bedh bedh', pierced; uncertain."},{"gurmukhi":"ਜਾਨੁਕ ਪਰਮ ਲੋਕ ਪਾਵਨ ਕਹੁ ਪ੍ਰਾਨਨ ਪੰਖ ਲਗਾਏ।","roman":"Jaanuk param lok paavan kahu praanan pankh lagaae |","meaning_en":"as if their lives had put on wings to reach the supreme world;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਹ੍ਵੈ ਗਿਰੇ ਕਵਚ ਕਟਿ ਪਰਮ ਪ੍ਰਭਾ ਕਹੁ ਪਾਈ।","roman":"Took took hvai gire kavach kati param prabhaa kahu paaee |","meaning_en":"their armour cut, they fell in pieces and attained supreme splendour,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜਣੁ ਦੈ ਚਲੇ ਨਿਸਾਣ ਸੁਰਗ ਕਹ ਕੁਲਹਿ ਕਲੰਕ ਮਿਟਾਈ। ੧੧੫।","roman":"Janu dai chale nisaan surag kah kulhi kalank mitaaee | 115 |","meaning_en":"as if they went to heaven sounding their drums, having wiped the stain from their lineage.","page":880,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੂਹੀ","gurmukhi":"ਬਿਸਨਪਦ। ਸੂਹੀ","roman":"Bisanpad | soohee","meaning_en":"Bishanpad. In Raag Suhi.","page":880,"meaning_status":"draft"},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":880,"lines":[{"gurmukhi":"ਪਾਰਸ ਨਾਥ ਬਡੋ ਰਣ ਜੀਤੋ।","roman":"Paaras naath bado ran jeeto |","meaning_en":"Parasnath won a great battle,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਭਈ ਦੂਸਰ ਕਰਣਾਰਜੁਨ ਭਾਰਥ ਸੋ ਹੁਇ ਬੀਤੋ।","roman":"Jaanuk bhaee doosar karnaarjun bhaarath so hui beeto |","meaning_en":"as if a second Karan-Arjun war of the Bharat had come about;","page":880,"meaning_status":"draft","note":"Karan and Arjun: the great duel of the Mahabharat."},{"gurmukhi":"ਬਹੁ ਬਿਧਿ ਚਲੈ ਪ੍ਰਵਾਹਿ ਸ੍ਰੋਣ ਕੇ ਰਥ ਗਜ ਅਸਵ ਬਹਾਏ।","roman":"Bahu bidhi chalai pravaahi sron ke rath gaj asav bahaae |","meaning_en":"streams of blood flowed in many ways, sweeping away chariots, elephants and horses;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਭੈ ਕਰ ਜਾਨ ਭਯੋ ਬਡ ਆਹਵ ਸਾਤ ਸਮੁੰਦਰ ਲਜਾਏ।","roman":"Bhai kar jaan bhayo bad aahav saat samundar lajaae |","meaning_en":"so terrible was the great battle that the seven oceans were put to shame;","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜਹ ਤਹ ਚਲੇ ਭਾਜ ਸੰਨਿਆਸੀ ਬਾਣਨ ਅੰਗ ਪ੍ਰਹਾਰੇ।","roman":"Jah tah chale bhaaj sanniaasee baanan ang prahaare |","meaning_en":"here and there the sannyasis fled, their limbs struck with arrows,","page":880,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਬਜ੍ਰ ਇੰਦ੍ਰ ਕੇ ਭੈ ਤੇ ਪਬ ਸਪਛ ਸਿਧਾਰੇ।","roman":"Jaanuk bajr indr ke bhai te pab sapachh sidhaare |","meaning_en":"as if the winged mountains had fled for fear of Indra's thunderbolt;","page":880,"meaning_status":"draft","note":"In legend, mountains once had wings, which Indra cut off with his thunderbolt."},{"gurmukhi":"ਜਿਹ ਤਿਹ ਗਿਰਤ ਸ੍ਰੋਣ ਕੀ ਧਾਰਾ ਅਰਿ ਘੂਮਤ ਭਿਭਰਾਤ।","roman":"Jih tih girat sron kee dhaaraa ari ghoomat bhibhraat |","meaning_en":"wherever they went, streams of blood fell; the enemies reeled and panicked;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਨਿੰਦਾ ਕਰਤ ਛਤ੍ਰੀਯ ਧਰਮ ਕੀ ਭਜਤ ਦਸੋ ਦਿਸ ਜਾਤ। ੧੧੬।","roman":"Nindaa karat chhatreey dharam kee bhajat daso dis jaat | 116 |","meaning_en":"reviling the duty of the Kshatriya, they fled away in all ten directions.","page":881,"meaning_status":"draft"}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","gurmukhi":"ਬਿਸਨਪਦ। ਸੋਰਠਿ","roman":"Bisanpad | sorthi","meaning_en":"Bishanpad. In Raag Sorath.","page":881,"meaning_status":"draft"},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":881,"lines":[{"gurmukhi":"ਜੇਤਕ ਜੀਅਤ ਬਚੇ ਸੰਨ੍ਯਾਸੀ।","roman":"Jetak jeeat bache sannyaasee |","meaning_en":"All the sannyasis who were left alive,","page":881,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਾਸ ਮਰਤ ਫਿਰਿ ਬਹੁਰਿ ਨ ਆਏ ਹੋਤ ਭਏ ਬਨਬਾਸੀ।","roman":"Traas marat phiri bahuri na aae hot bhae banbaasee |","meaning_en":"dying of fright, never came back again, and became forest-dwellers;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਦੇਸ ਬਿਦੇਸ ਢੂੰਢ ਬਨ ਬੇਹੜ ਤਹ ਤਹ ਪਕਰਿ ਸੰਘਾਰੇ।","roman":"Des bides dhoondh ban behar tah tah pakri sanghaare |","meaning_en":"he searched lands near and far, forests and wastelands, and caught and killed them there;","page":881,"meaning_status":"draft","note":"ਬੇਹੜ: rough wild land."},{"gurmukhi":"ਖੋਜਿ ਪਤਾਲ ਅਕਾਸ ਸੁਰਗ ਕਹੁ ਜਹਾ ਤਹਾ ਚੁਨਿ ਮਾਰੇ।","roman":"Khoji pataal akaas surag kahu jahaa tahaa chuni maare |","meaning_en":"searching the underworld, the sky and heaven, he picked them out and killed them wherever they were.","page":881,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਨਾਸ ਕਰੇ ਸੰਨਿਆਸੀ ਆਪਨ ਮਤਹ ਮਤਾਯੋ।","roman":"Ih bidhi naas kare sanniaasee aapan matah mataayo |","meaning_en":"In this way he destroyed the sannyasis and established his own creed;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਆਪਨ ਨ੍ਯਾਸ ਸਿਖਾਇ ਸਬਨ ਕਹੁ ਆਪਨ ਮੰਤ੍ਰ ਚਲਾਯੋ।","roman":"Aapan nyaas sikhaai saban kahu aapan mantr chalaayo |","meaning_en":"he taught everyone his own nyasas and set his own mantra going;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਜੇ ਗਹੇ ਤਿਨ ਤੇ ਘਾਇਲ ਤਿਨ ਕੀ ਜਟਾ ਮੁੰਡਾਈ।","roman":"Je je gahe tin te ghaail tin kee jataa mundaaee |","meaning_en":"all those he caught alive, wounded, he had their matted hair shaved off;","page":881,"meaning_status":"draft","note":"ਤਿਨ ਤੇ ਘਾਇਲ: read as 'those captured wounded'; uncertain."},{"gurmukhi":"ਦੋਹੀ ਦੂਰ ਦਤ ਕੀ ਕੀਨੀ ਆਪਨ ਫੇਰਿ ਦੁਹਾਈ। ੧੧੭।","roman":"Dohee door dat kee keenee aapan pheri duhaaee | 117 |","meaning_en":"he did away with Dutt's proclamation and proclaimed his own instead.","page":881,"meaning_status":"draft","note":"ਦੋਹੀ, ਦੁਹਾਈ: a royal proclamation, authority."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਬਸੰਤ","gurmukhi":"ਬਿਸਨਪਦ। ਬਸੰਤ","roman":"Bisanpad | basant","meaning_en":"Bishanpad. In Raag Basant.","page":881,"meaning_status":"draft"},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":881,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਫਾਗ ਕ੍ਰਿਪਾਨਨ ਖੇਲੇ।","roman":"Ih bidhi phaag kripaanan khele |","meaning_en":"In this way they played Phag (Holi) with swords.","page":881,"meaning_status":"draft","note":"ਫਾਗ: the spring festival of colours."},{"gurmukhi":"ਸੋਭਤ ਢਾਲ ਮਾਲ ਡਫ ਮਾਲੈ ਮੂਠ ਗੁਲਾਲਨ ਸੇਲੇ।","roman":"Sobhat dhaal maal daph maalai mooth gulaalan sele |","meaning_en":"The shields shone like rows of tambourines, and the lances like handfuls of red powder;","page":881,"meaning_status":"draft","note":"ਗੁਲਾਲ: red powder thrown at Holi."},{"gurmukhi":"ਜਾਨੁ ਤੁਫੰਗ ਭਰਤ ਪਿਚਕਾਰੀ ਸੂਰਨ ਅੰਗ ਲਗਾਵਤ।","roman":"Jaanu tuphang bharat pichkaaree sooran ang lagaavat |","meaning_en":"the muskets were like squirts being filled, which they put to the heroes' limbs;","page":881,"meaning_status":"draft","note":"ਤੁਫੰਗ: musket. ਪਿਚਕਾਰੀ: syringe for coloured water."},{"gurmukhi":"ਨਿਕਸਤ ਸ੍ਰੋਣ ਅਧਿਕ ਛਬਿ ਉਪਜਤ ਕੇਸਰ ਜਾਨੁ ਸੁਹਾਵਤ।","roman":"Niksat sron adhik chhabi upjat kesar jaanu suhaavat |","meaning_en":"the blood flowing out created great beauty, as if it were lovely saffron;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਣਤ ਭਰੀ ਜਟਾ ਅਤਿ ਸੋਭਤ ਛਬਹਿ ਨ ਜਾਤ ਕਹ੍ਯੋ।","roman":"Sronat bharee jataa ati sobhat chhabhi na jaat kahyo |","meaning_en":"the matted hair filled with blood looked very fine; its beauty cannot be told;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਪਰਮ ਪ੍ਰੇਮ ਸੌ ਡਾਰ੍ਯੋ ਈਂਗਰ ਲਾਗਿ ਰਹ੍ਯੋ।","roman":"Maanhu param prem sau daaryo eengar laagi rahyo |","meaning_en":"it was as if vermilion had been thrown with great love and stuck there;","page":881,"meaning_status":"draft","note":"ਈਂਗਰ: vermilion."},{"gurmukhi":"ਜਹ ਤਹ ਗਿਰਤ ਭਏ ਨਾਨਾ ਬਿਧਿ ਸਾਂਗਨ ਸਤ੍ਰੁ ਪਰੋਏ।","roman":"Jah tah girat bhae naanaa bidhi saangan satru paroe |","meaning_en":"here and there they fell in many ways, the enemies strung on lances,","page":881,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨੁਕ ਖੇਲ ਧਮਾਰ ਪਸਾਰਿ ਕੈ ਅਧਿਕ ਸ੍ਰਮਿਤ ਹ੍ਵੈ ਸੋਏ। ੧੧੮।","roman":"Jaanuk khel dhamaar pasaari kai adhik sramit hvai soe | 118 |","meaning_en":"as if, having spread out the game of Dhamar (the Holi revels), they lay down to sleep, very tired.","page":881,"meaning_status":"draft","note":"ਧਮਾਰ: the boisterous Holi play and song."}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ। ਪਰਜ","gurmukhi":"ਬਿਸਨਪਦ। ਪਰਜ","roman":"Bisanpad | paraj","meaning_en":"Bishanpad. In Raag Paraj.","page":881,"meaning_status":"draft"},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":881,"lines":[{"gurmukhi":"ਦਸ ਸੈ ਬਰਖ ਰਾਜ ਤਿਨ ਕੀਨਾ।","roman":"Das sai barakh raaj tin keenaa |","meaning_en":"He ruled for ten hundred years.","page":881,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਕੈ ਦੂਰ ਦਤ ਕੇ ਮਤ ਕਹੁ ਰਾਜ ਜੋਗ ਦੋਊ ਲੀਨਾ।","roman":"Kai kai door dat ke mat kahu raaj jog do'oo leenaa |","meaning_en":"Having driven away Dutt's creed, he took both kingship and yoga to himself.","page":881,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਜੇ ਛਪੇ ਲੁਕੇ ਕਹੂੰ ਬਾਚੇ ਰਹਿ ਰਹਿ ਵਹੈ ਗਏ।","roman":"Je je chhape luke kahoon baache rahi rahi vahai gae |","meaning_en":"Those few who had hidden somewhere and survived, they alone remained,","page":881,"meaning_status":"draft","note":"ਰਹਿ ਰਹਿ ਵਹੈ ਗਏ: read as 'only they were left'; uncertain."},{"gurmukhi":"ਐਸੇ ਏਕ ਨਾਮ ਲੈਬੇ ਕੋ ਜਗ ਮੋ ਰਹਤ ਭਏ।","roman":"Aise ek naam laibe ko jag mo rahat bhae |","meaning_en":"so that there remained in the world only (enough of them) to keep the name alive.","page":881,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸੌ ਰਾਜ ਕਰਤ ਯੌ ਭਾਤਿ ਭਾਤਿ ਧਨ ਜੋਰ੍ਯੋ।","roman":"Bhaati bhaati sau raaj karat yau bhaati bhaati dhan joryo |","meaning_en":"Ruling in many ways, he gathered wealth in many ways;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਜਹਾ ਜਹਾ ਮਾਨਸ ਸ੍ਰਉਨਨ ਸੁਨ ਤਹਾ ਤਹਾ ਤੇ ਤੋਰ੍ਯੋ।","roman":"Jahaa jahaa maanas sraunan sun tahaa tahaa te toryo |","meaning_en":"wherever he heard with his ears of a man (of that creed), from there he broke him off (destroyed him).","page":881,"meaning_status":"draft","note":"ਤੋਰ੍ਯੋ: 'broke off, rooted out'; uncertain."},{"gurmukhi":"ਇਹ ਬਿਧਿ ਜੀਤ ਦੇਸ ਪੁਰ ਦੇਸਨ ਜੀਤ ਨਿਸਾਨ ਬਜਾਯੋ।","roman":"Ih bidhi jeet des pur desan jeet nisaan bajaayo |","meaning_en":"In this way he conquered lands and cities, and sounded the drum of victory;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਆਪਨ ਕਰਣ ਕਾਰਣ ਕਰਿ ਮਾਨ੍ਯੋ ਕਾਲ ਪੁਰਖ ਬਿਸਰਾਯੋ। ੧੧੯।","roman":"Aapan karan kaaran kari maanyo kaal purakh bisraayo | 119 |","meaning_en":"he took himself to be the Cause of causes, and forgot the Timeless Being (Kal Purakh).","page":881,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਮਲ ਛੰਦ","gurmukhi":"ਰੂਆਮਲ ਛੰਦ","roman":"Rooaamal chhand","meaning_en":"Ruamal metre.","page":881,"meaning_status":"draft","note":"ਰੂਆਮਲ: printed so; the same metre is elsewhere spelt ਰੂਆਲ (Rual)."},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":881,"lines":[{"gurmukhi":"ਦਸ ਸਹੰਸ੍ਰ ਪ੍ਰਮਾਣ ਬਰਖਨ ਕੀਨ ਰਾਜ ਸੁਧਾਰਿ।","roman":"Das sahansr pramaan barkhan keen raaj sudhaari |","meaning_en":"For ten thousand years he ruled well,","page":881,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਧਰਾਨ ਲੈ ਅਰੁ ਸਤ੍ਰੁ ਸਰਬ ਸੰਘਾਰਿ।","roman":"Bhaati bhaati dharaan lai aru satru sarab sanghaari |","meaning_en":"taking the lands of many kinds and destroying all his enemies;","page":881,"meaning_status":"draft"},{"gurmukhi":"ਜੀਤਿ ਜੀਤਿ ਅਨੂਪ ਭੂਪ ਅਨੂਪ ਰੂਪ ਅਪਾਰ।","roman":"Jeeti jeeti anoop bhoop anoop roop apaar |","meaning_en":"conquering incomparable kings, he, of incomparable and boundless beauty,","page":881,"meaning_status":"draft"},{"gurmukhi":"ਭੂਪ ਮੇਧ ਠਟ੍ਯੋ ਨ੍ਰਿਪੋਤਮ ਏਕ ਜਗ ਸੁਧਾਰਿ। ੧੨੦।","roman":"Bhoop medh thatyo nripotam ek jag sudhaari | 120 |","meaning_en":"the best of kings, set about a Nripmedh (sacrifice of kings), properly arranging a great sacrifice.","page":881,"meaning_status":"draft","note":"ਭੂਪ ਮੇਧ: 'sacrifice of kings', a sacrifice in which conquered kings are offered."}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":882,"lines":[{"gurmukhi":"ਦੇਸ ਦੇਸਨ ਕੇ ਨਰੇਸਨ ਬਾਧਿ ਕੈ ਇਕ ਬਾਰਿ।","roman":"Des desan ke naresan baadhi kai ik baari |","meaning_en":"Having bound the kings of land after land all at once,","page":882,"meaning_status":"draft"},{"gurmukhi":"ਰੋਹ ਦੇਸ ਬਿਖੈ ਗਯੋ ਲੈ ਪੁਤ੍ਰ ਮਿਤ੍ਰ ਕੁਮਾਰ।","roman":"Roh des bikhai gayo lai putr mitr kumaar |","meaning_en":"he went into the land of Roh, taking his sons, friends and princes;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਨਾਰਿ ਸੰਜੁਤ ਬੈਠਿ ਬਿਧਵਤ ਕੀਨ ਜਗ ਅਰੰਭ।","roman":"Naari sanjut baithi bidhvat keen jag aranbh |","meaning_en":"sitting with his wife, he began the sacrifice according to the rites,","page":882,"meaning_status":"draft"},{"gurmukhi":"ਬੋਲਿ ਬੋਲਿ ਕਰੋਰ ਰਿਤਜ ਔਰ ਬਿਪ ਅਸੰਭ। ੧੨੧।","roman":"Boli boli karor ritaj aur bip asanbh | 121 |","meaning_en":"calling countless priests and innumerable Brahmins.","page":882,"meaning_status":"draft","note":"ਰਿਤਜ: ritvij, officiating priests. ਬਿਪ: Brahmins."}]},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":882,"lines":[{"gurmukhi":"ਰਾਜਮੇਧ ਕਰ੍ਯੋ ਲਗੈ ਆਰੰਭ ਭੂਪ ਅਪਾਰ।","roman":"Raajmedh karyo lagai aaranbh bhoop apaar |","meaning_en":"The king began to perform a Rajmedh, a vast one;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸਮ੍ਰਿਧ ਜੋਰਿ ਸੁਮਿਤ੍ਰ ਪੁਤ੍ਰ ਕੁਮਾਰ।","roman":"Bhaati bhaati samridh jori sumitr putr kumaar |","meaning_en":"gathering many kinds of wealth, (with) good friends, sons and princes;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਅਨੇਕਨ ਕੇ ਜੁਰੇ ਜਨ ਆਨਿ ਕੈ ਤਿਹ ਦੇਸ।","roman":"Bhaati anekan ke jure jan aani kai tih des |","meaning_en":"people of many kinds came and gathered in that land;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਛੀਨਿ ਛੀਨਿ ਲਏ ਨ੍ਰਿਪਾਬਰ ਦੇਸ ਦਿਰਬ ਅਵਿਨੇਸ। ੧੨੨।","roman":"Chheeni chheeni lae nripaabar des dirab avines | 122 |","meaning_en":"the great king had seized the lands and wealth of the rulers of the earth.","page":882,"meaning_status":"draft","note":"ਅਵਿਨੇਸ: rulers of the earth."}]},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":882,"lines":[{"gurmukhi":"ਦੇਖ ਕੇ ਇਹ ਭਾਤਿ ਸਰਬ ਸੁ ਭੂਪ ਸੰਪਤਿ ਨੈਣ।","roman":"Dekh ke ih bhaati sarab su bhoop sanpti nain |","meaning_en":"Seeing in this way all the kings and the wealth with his own eyes,","page":882,"meaning_status":"draft"},{"gurmukhi":"ਗਰਬ ਸੋ ਭੁਜ ਦੰਡ ਕੈ ਇਹ ਭਾਤਿ ਬੋਲਾ ਬੈਣ।","roman":"Garab so bhuj dand kai ih bhaati bolaa bain |","meaning_en":"with pride, raising his strong arms, he spoke these words:","page":882,"meaning_status":"draft","note":"ਭੁਜ ਦੰਡ ਕੈ: read as 'raising (or striking) his arms'; uncertain."},{"gurmukhi":"ਭੂਪ ਮੇਧ ਕਰੋ ਸਬੈ ਤੁਮ ਆਜ ਜਗ ਅਰੰਭ।","roman":"Bhoop medh karo sabai tum aaj jag aranbh |","meaning_en":"\"All of you, perform the Nripmedh; begin the sacrifice today,","page":882,"meaning_status":"draft"},{"gurmukhi":"ਸਤਜੁਗ ਮਾਹਿ ਭਯੋ ਜਿਹੀ ਬਿਧਿ ਕੀਨ ਰਾਜੈ ਜੰਭ। ੧੨੩।","roman":"Satjug maahi bhayo jihee bidhi keen raajai janbh | 123 |","meaning_en":"\"in the way that King Jambh performed it in the Satyug.\"","page":882,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਮੰਤ੍ਰੀਯ ਬਾਚ","gurmukhi":"ਮੰਤ੍ਰੀਯ ਬਾਚ","roman":"Mantreey baach","meaning_en":"The minister said:","page":882,"meaning_status":"draft"},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":882,"lines":[{"gurmukhi":"ਲਛ ਜਉ ਨ੍ਰਿਪ ਮਾਰੀਯੈ ਤਬ ਹੋਤ ਹੈ ਨ੍ਰਿਪ ਮੇਧ।","roman":"Lachh jau nrip maareeyai tab hot hai nrip medh |","meaning_en":"\"When a hundred thousand kings are killed, then the Nripmedh takes place;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਏਕ ਅਨੇਕ ਸੰਪਤਿ ਦੀਜੀਯੈ ਭਵਿਖੇਧ।","roman":"Ek ek anek sanpti deejeeyai bhavikhedh |","meaning_en":"\"to each one (Brahmin) great wealth must be given, (so) it is laid down;","page":882,"meaning_status":"draft","note":"ਭਵਿਖੇਧ: unclear; perhaps 'it is prescribed'. Uncertain."},{"gurmukhi":"ਲਛ ਲਛ ਤੁਰੰਗ ਏਕਹਿ ਦੀਜੀਐ ਅਬਿਚਾਰ।","roman":"Lachh lachh turang ekhi deejeeai abichaar |","meaning_en":"\"a hundred thousand horses must be given to each without a thought;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਜਗ ਪੂਰਣ ਹੋਤੁ ਹੈ ਸੁਨ ਰਾਜ ਰਾਜ ਵਤਾਰ। ੧੨੪।","roman":"Jag pooran hotu hai sun raaj raaj vataar | 124 |","meaning_en":"\"then the sacrifice is complete; listen, O incarnation of the king of kings.","page":882,"meaning_status":"draft"}]},{"type":"verse","number":[125],"number_text":"੧੨੫।","page":882,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸੁਮ੍ਰਿਧ ਸੰਪਤਿ ਦੀਜੀਯੈ ਇਕ ਬਾਰ।","roman":"Bhaati bhaati sumridh sanpti deejeeyai ik baar |","meaning_en":"\"Plentiful wealth of many kinds must be given at one time;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਲਛ ਹਸਤ ਤੁਰੰਗ ਦ੍ਵੈ ਲਛ ਸੁਵਰਨ ਭਾਰ ਅਪਾਰ।","roman":"Lachh hasat turang dvai lachh suvran bhaar apaar |","meaning_en":"\"a hundred thousand elephants, two hundred thousand horses, and boundless loads of gold;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਕੋਟਿ ਕੋਟਿ ਦਿਜੇਕ ਏਕਹਿ ਦੀਜੀਯੈ ਅਬਿਲੰਬ।","roman":"Koti koti dijek ekhi deejeeyai abilanb |","meaning_en":"\"to each Brahmin millions upon millions must be given without delay;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਜਗ ਪੂਰਣ ਹੋਇ ਤਉ ਸੁਨ ਰਾਜ ਰਾਜ ਅਸੰਭ। ੧੨੫।","roman":"Jag pooran hoi tau sun raaj raaj asanbh | 125 |","meaning_en":"\"then the sacrifice will be complete; listen, O king of kings beyond compare.\"","page":882,"meaning_status":"draft","note":"ਅਸੰਭ: read as 'incomparable / unborn'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ","roman":"Paarasnaath baach","meaning_en":"Parasnath said:","page":882,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Rual metre.","page":882,"meaning_status":"draft"},{"type":"verse","number":[126],"number_text":"੧੨੬।","page":882,"lines":[{"gurmukhi":"ਸੁਵਰਨ ਕੀ ਨ ਇਤੀ ਕਮੀ ਜਉ ਟੁਟ ਹੈ ਬਹੁ ਬਰਖ।","roman":"Suvran kee na itee kamee jau tut hai bahu barakh |","meaning_en":"\"There is no such lack of gold that it would run out in many years;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਹਸਤ ਕੀ ਨ ਕਮੀ ਮੁਝੈ ਹਯ ਸਾਰ ਲੀਜੈ ਪਰਖ।","roman":"Hasat kee na kamee mujhai hay saar leejai parakh |","meaning_en":"\"I have no lack of elephants; take the finest horses after testing them;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਜਉ ਧਨ ਚਾਹੀਯੈ ਸੋ ਲੀਜੀਯੈ ਅਬਿਚਾਰ।","roman":"Aur jau dhan chaaheeyai so leejeeyai abichaar |","meaning_en":"\"and whatever other wealth is needed, take it without hesitation;","page":882,"meaning_status":"draft"},{"gurmukhi":"ਚਿਤ ਮੈ ਨ ਕਛੂ ਕਰੋ ਸੁਨ ਮੰਤ੍ਰ ਮਿਤ੍ਰ ਅਵਤਾਰ। ੧੨੬।","roman":"Chit mai na kachhoo karo sun mantr mitr avtaar | 126 |","meaning_en":"\"have no worry in your mind; listen, O minister, incarnation of a friend.\"","page":882,"meaning_status":"draft"}]},{"type":"verse","number":[127],"number_text":"੧੨੭।","page":882,"lines":[{"gurmukhi":"ਯਉ ਜਬੈ ਨ੍ਰਿਪ ਉਚਰ੍ਯੋ ਤਬ ਮੰਤ੍ਰਿ ਬਰ ਸੁਨਿ ਬੈਨ।","roman":"Yau jabai nrip uchryo tab mantri bar suni bain |","meaning_en":"When the king had spoken thus, the chief minister, hearing his words,","page":882,"meaning_status":"draft"},{"gurmukhi":"ਹਾਥ ਜੋਰਿ ਸਲਾਮ ਕੈ ਨ੍ਰਿਪ ਨੀਚ ਕੈ ਜੁਗ ਨੈਨ।","roman":"Haath jori salaam kai nrip neech kai jug nain |","meaning_en":"joining his hands and saluting the king, with both eyes lowered, (said):","page":882,"meaning_status":"draft","note":"ਸਲਾਮ: salute (Arabic/Persian)."},{"gurmukhi":"ਅਉਰ ਏਕ ਸੁਨੋ ਨ੍ਰਿਪੋਤਮ ਉਚਰੋ ਇਕ ਗਾਥ।","roman":"Aur ek suno nripotam uchro ik gaath |","meaning_en":"\"Listen to one more thing, O best of kings; I shall tell a story,","page":882,"meaning_status":"draft"},{"gurmukhi":"ਜੋਨ ਮਧਿ ਸੁਨੀ ਪੁਰਾਰਨਨ ਅਉਰ ਸਿੰਮ੍ਰਿਤ ਸਾਥ। ੧੨੭।","roman":"Jon madhi sunee puraarnan aur sinmrit saath | 127 |","meaning_en":"\"which I have heard in the Puranas and in the Smritis too.\"","page":882,"meaning_status":"draft","note":"ਪੁਰਾਰਨਨ: printed so; read as 'Puranas'."}]},{"type":"heading","kind":"speaker","name":"ਮੰਤ੍ਰੀ ਬਾਚ","gurmukhi":"ਮੰਤ੍ਰੀ ਬਾਚ","roman":"Mantree baach","meaning_en":"The minister said:","page":883,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Rual metre.","page":883,"meaning_status":"draft"},{"type":"verse","number":[128],"number_text":"੧੨੮।","page":883,"lines":[{"gurmukhi":"ਅਉਰ ਜੋ ਸਭ ਦੇਸ ਕੇ ਨ੍ਰਿਪ ਜੀਤੀਯੈ ਸੁਨਿ ਭੂਪ।","roman":"Aur jo sabh des ke nrip jeeteeyai suni bhoop |","meaning_en":"\"Moreover, all the kings of every land must be conquered, listen, O king,","page":883,"meaning_status":"draft"},{"gurmukhi":"ਪਰਮ ਰੂਪ ਪਵਿਤ੍ਰ ਗਾਤ ਅਪਵਿਤ੍ਰ ਹਰਣ ਸਰੂਪ।","roman":"Param roop pavitr gaat apvitr haran saroop |","meaning_en":"\"(you who are) of supreme beauty, pure of body, the very form that takes away impurity.","page":883,"meaning_status":"draft"},{"gurmukhi":"ਐਸ ਜਉ ਸੁਨਿ ਭੂਪ ਭੂਪਤਿ ਸਭ ਪੂਛੀਆ ਤਿਹ ਗਾਥ।","roman":"Ais jau suni bhoop bhoopti sabh poochheeaa tih gaath |","meaning_en":"\"When you have heard this, O king of kings, ask all of them about this matter;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਪੂਛ ਆਉ ਸਬੈ ਨ੍ਰਿਪਾਲਨ ਹਉ ਕਹੋ ਤੁਹ ਸਾਥ। ੧੨੮।","roman":"Poochh aau sabai nripaalan hau kaho tuh saath | 128 |","meaning_en":"\"go and ask all the rulers; I tell you this.\"","page":883,"meaning_status":"draft"}]},{"type":"verse","number":[129],"number_text":"੧੨੯।","page":883,"lines":[{"gurmukhi":"ਯੌ ਕਹੇ ਜਬ ਬੈਨ ਭੂਪਤਿ ਮੰਤ੍ਰਿ ਬਰ ਸੁਨਿ ਧਾਇ।","roman":"Yau kahe jab bain bhoopti mantri bar suni dhaai |","meaning_en":"When he had spoken these words, the king, hearing the chief minister, went at once;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਪੰਚ ਲਛ ਬੁਲਾਇ ਭੂਪਤਿ ਪੂਛ ਸਰਬ ਬੁਲਾਇ।","roman":"Panch lachh bulaai bhoopti poochh sarab bulaai |","meaning_en":"he called five hundred thousand kings and called them all and asked them:","page":883,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਸਾਤ ਹੂੰ ਲੋਕ ਭੀਤਰ ਦੇਹੁ ਅਉਰ ਬਤਾਇ।","roman":"Aur saat hoon lok bheetar dehu aur bataai |","meaning_en":"\"Tell me further, within all seven worlds,","page":883,"meaning_status":"draft"},{"gurmukhi":"ਜਉਨ ਜਉਨ ਨ ਜੀਤਿਆ ਨ੍ਰਿਪ ਰੋਸ ਕੈ ਨ੍ਰਿਪ ਰਾਇ। ੧੨੯।","roman":"Jaun jaun na jeetiaa nrip ros kai nrip raai | 129 |","meaning_en":"\"which king there is that the king of kings, in his anger, has not conquered.\"","page":883,"meaning_status":"draft"}]},{"type":"verse","number":[130],"number_text":"੧੩੦।","page":883,"lines":[{"gurmukhi":"ਦੇਖਿ ਦੇਖਿ ਰਹੇ ਸਬੈ ਤਰ ਕੋ ਨ ਦੇਤ ਬਿਚਾਰ।","roman":"Dekhi dekhi rahe sabai tar ko na det bichaar |","meaning_en":"They all kept looking (at one another) below; no one gave an answer:","page":883,"meaning_status":"draft","note":"ਤਰ: read as 'downward' (looking down); uncertain."},{"gurmukhi":"ਐਸ ਕਉਨ ਰਹਾ ਧਰਾ ਪਰ ਦੇਹੁ ਤਾਹਿ ਉਚਾਰ।","roman":"Ais kaun rahaa dharaa par dehu taahi uchaar |","meaning_en":"\"Who is there left on the earth like that? Tell me, speak of him.\"","page":883,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਏਕ ਬੁਲਾਇ ਭੂਪਤਿ ਪੂਛ ਸਰਬ ਬੁਲਾਇ।","roman":"Ek ek bulaai bhoopti poochh sarab bulaai |","meaning_en":"The king called each one, and asked them all:","page":883,"meaning_status":"draft"},{"gurmukhi":"ਕੋ ਅਜੀਤ ਰਹਾ ਨਹੀ ਜਿਹ ਠਉਰ ਦੇਹੁ ਬਤਾਇ। ੧੩੦।","roman":"Ko ajeet rahaa nahee jih thaur dehu bataai | 130 |","meaning_en":"\"Who has remained unconquered? Tell me where he is.\"","page":883,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਏਕ ਨ੍ਰਿਪ ਬਾਚ","gurmukhi":"ਏਕ ਨ੍ਰਿਪ ਬਾਚ","roman":"Ek nrip baach","meaning_en":"A king said:","page":883,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Rual metre.","page":883,"meaning_status":"draft"},{"type":"verse","number":[131],"number_text":"੧੩੧।","page":883,"lines":[{"gurmukhi":"ਏਕ ਭੂਪਤਿ ਉਚਰੋ ਸੁਨਿ ਲੇਹੁ ਰਾਜਾ ਬੈਨ।","roman":"Ek bhoopti uchro suni lehu raajaa bain |","meaning_en":"One king said, \"Listen to my words, O king;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਜਾਨ ਮਾਫ ਕਰੋ ਕਹੋ ਤਬ ਰਾਜ ਰਾਜ ਸੁ ਨੈਨ।","roman":"Jaan maaph karo kaho tab raaj raaj su nain |","meaning_en":"\"if you pardon my life, then I shall tell you, O king of kings with fine eyes.","page":883,"meaning_status":"draft","note":"ਜਾਨ ਮਾਫ: 'pardon (my) life' (Persian jaan, maaf)."},{"gurmukhi":"ਏਕ ਹੈ ਮੁਨਿ ਸਿੰਧੁ ਮੈ ਅਰੁ ਮਛ ਕੇ ਉਰ ਮਾਹਿ।","roman":"Ek hai muni sindhu mai aru machh ke ur maahi |","meaning_en":"\"There is one sage in the ocean, in the belly of a fish;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਮੋਹਿ ਰਾਵ ਬਿਬੇਕ ਭਾਖੌ ਤਾਹਿ ਭੂਪਤਿ ਨਾਹਿ। ੧੩੧।","roman":"Mohi raav bibek bhaakhau taahi bhoopti naahi | 131 |","meaning_en":"\"by my judgement, O king, I say that you, O lord of the earth, have not (conquered) him.\"","page":883,"meaning_status":"draft","note":"ਮੋਹਿ ਰਾਵ ਬਿਬੇਕ ਭਾਖੌ ਤਾਹਿ ਭੂਪਤਿ ਨਾਹਿ: read as above; uncertain."}]},{"type":"verse","number":[132],"number_text":"੧੩੨।","page":883,"lines":[{"gurmukhi":"ਏਕ ਦ੍ਯੋਸ ਜਟਧਰੀ ਨ੍ਰਿਪ ਕੀਨੁ ਛੀਰ ਪ੍ਰਵੇਸ।","roman":"Ek dyos jatadhree nrip keenu chheer praves |","meaning_en":"\"One day the matted-haired king (Shiva) entered the Ocean of Milk;","page":883,"meaning_status":"draft","note":"ਜਟਧਰੀ ਨ੍ਰਿਪ: read as Shiva, given ਸਿਵੇਸ in the next line."},{"gurmukhi":"ਚਿਤ੍ਰ ਰੂਪ ਹੁਤੀ ਤਹਾ ਇਕ ਨਾਰਿ ਨਾਗਰ ਭੇਸ।","roman":"Chitr roop hutee tahaa ik naari naagar bhes |","meaning_en":"\"there was a woman there, beautiful as a picture, in refined attire;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਤਾਸੁ ਦੇਖਿ ਸਿਵੇਸ ਕੋ ਗਿਰ ਬਿੰਦ ਸਿੰਧ ਮਝਾਰ।","roman":"Taasu dekhi sives ko gir bind sindh majhaar |","meaning_en":"\"seeing her, the seed of Lord Shiva fell into the ocean;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਮਛ ਪੇਟ ਮਛੰਦ੍ਰ ਜੋਗੀ ਬੈਠਿ ਹੈ ਨ੍ਰਿਪ ਬਾਰ। ੧੩੨।","roman":"Machh pet machhandr jogee baithi hai nrip baar | 132 |","meaning_en":"\"(from it) the yogi Machhindra sits in the belly of a fish, O king.\"","page":883,"meaning_status":"draft","note":"ਨ੍ਰਿਪ ਬਾਰ: read as 'O king'; could be 'for a long time'. Uncertain."}]},{"type":"verse","number":[133],"number_text":"੧੩੩।","page":883,"lines":[{"gurmukhi":"ਤਾਸੁ ਤੇ ਚਲ ਪੁਛੀਐ ਨ੍ਰਿਪ ਸਰਬ ਬਾਤ ਬਿਬੇਕ।","roman":"Taasu te chal puchheeai nrip sarab baat bibek |","meaning_en":"\"Go and ask him, O king, about every matter of wisdom;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਏਨ ਤੋਹਿ ਬਤਾਇ ਹੈ ਨ੍ਰਿਪ ਭਾਖਿ ਹੋ ਜੁ ਅਨੇਕ।","roman":"En tohi bataai hai nrip bhaakhi ho ju anek |","meaning_en":"\"he will tell you, O king, the many things you ask.\"","page":883,"meaning_status":"draft"},{"gurmukhi":"ਐਸ ਬਾਤ ਸੁਨੀ ਜਬੈ ਤਬ ਰਾਜ ਰਾਜ ਅਵਤਾਰ।","roman":"Ais baat sunee jabai tab raaj raaj avtaar |","meaning_en":"When the incarnation of the king of kings heard such a thing,","page":883,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਧੁ ਖੋਜਨ ਕੋ ਚਲਾ ਲੈ ਜਗਤ ਕੇ ਸਬ ਜਾਰ। ੧੩੩।","roman":"Sindhu khojan ko chalaa lai jagat ke sab jaar | 133 |","meaning_en":"he set out to search the ocean, taking all the nets in the world.","page":883,"meaning_status":"draft"}]},{"type":"verse","number":[134],"number_text":"੧੩੪।","page":883,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਮੰਗਾਇ ਜਾਲਨ ਸੰਗ ਲੈ ਦਲ ਸਰਬ।","roman":"Bhaati bhaati mangaai jaalan sang lai dal sarab |","meaning_en":"Having nets of many kinds brought, and taking his whole army along,","page":883,"meaning_status":"draft"},{"gurmukhi":"ਜੀਤ ਦੁੰਦਭ ਦੈ ਚਲਾ ਨ੍ਰਿਪ ਜਾਨਿ ਕੈ ਜੀਅ ਗਰਬ।","roman":"Jeet dundabh dai chalaa nrip jaani kai jeea garab |","meaning_en":"the king set out with drums of victory, holding pride in his heart;","page":883,"meaning_status":"draft"},{"gurmukhi":"ਮੰਤ੍ਰੀ ਮਿਤ੍ਰ ਕੁਮਾਰਿ ਸੰਪਤ ਸਰਬ ਮਧਿ ਬੁਲਾਇ।","roman":"Mantree mitr kumaari sanpat sarab madhi bulaai |","meaning_en":"calling all his ministers, friends, princes and wealth to come along,","page":883,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਧ ਜਾਰ ਡਰੇ ਜਹਾ ਤਹਾ ਮਛ ਸਤ੍ਰੁ ਡਰਾਇ। ੧੩੪।","roman":"Sindh jaar dare jahaa tahaa machh satru daraai | 134 |","meaning_en":"he cast the nets in the ocean here and there, frightening the fish, (as if) they were his enemies.","page":883,"meaning_status":"draft","note":"ਮਛ ਸਤ੍ਰੁ ਡਰਾਇ: uncertain."}]},{"type":"verse","number":[135],"number_text":"੧੩੫।","page":884,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਨ ਮਛ ਕਛਪ ਅਉਰ ਜੀਵ ਅਪਾਰ।","roman":"Bhaati bhaatan machh kachhap aur jeev apaar |","meaning_en":"Fish and tortoises of many kinds and countless other creatures","page":884,"meaning_status":"draft"},{"gurmukhi":"ਬਧਿ ਜਾਰਨ ਹ੍ਵੈ ਕਢੇ ਤਬ ਤਿਆਗਿ ਪ੍ਰਾਨ ਸੁ ਧਾਰ।","roman":"Badhi jaaran hvai kadhe tab tiaagi praan su dhaar |","meaning_en":"were bound in the nets and drawn out, and then gave up their lives;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਧੁ ਤੀਰ ਗਏ ਜਬੈ ਜਲ ਜੀਵ ਏਕੈ ਬਾਰ।","roman":"Sindhu teer gae jabai jal jeev ekai baar |","meaning_en":"when all the water creatures went together to the shore of the ocean,","page":884,"meaning_status":"draft"},{"gurmukhi":"ਐਸ ਭਾਤਿ ਭਏ ਬਖਾਨਤ ਸਿੰਧੁ ਪੈ ਮਤ ਸਾਰ। ੧੩੫।","roman":"Ais bhaati bhae bakhaanat sindhu pai mat saar | 135 |","meaning_en":"in this way they told the ocean the whole matter.","page":884,"meaning_status":"draft"}]},{"type":"verse","number":[136],"number_text":"੧੩੬।","page":884,"lines":[{"gurmukhi":"ਬਿਪ ਕੋ ਧਰਿ ਸਿੰਧੁ ਮੂਰਤਿ ਆਇਯੋ ਤਿਹ ਪਾਸਿ।","roman":"Bip ko dhari sindhu moorti aaiyo tih paasi |","meaning_en":"Taking the form of a Brahmin, the Ocean came to him (the king);","page":884,"meaning_status":"draft","note":"Sindhu: the Ocean, personified."},{"gurmukhi":"ਰਤਨ ਹੀਰ ਪ੍ਰਵਾਲ ਮਾਨਕ ਦੀਨ ਹੈ ਅਨਿਆਸ।","roman":"Ratan heer pravaal maanak deen hai aniaas |","meaning_en":"he gave jewels, diamonds, coral and rubies in abundance:","page":884,"meaning_status":"draft","note":"ਅਨਿਆਸ: read as 'freely, in abundance'; uncertain."},{"gurmukhi":"ਜੀਵ ਕਾਹਿ ਸੰਘਾਰੀਐ ਸੁਨਿ ਲੀਜੀਐ ਨ੍ਰਿਪ ਬੈਨ।","roman":"Jeev kaahi sanghaareeai suni leejeeai nrip bain |","meaning_en":"\"Why kill these creatures? Listen to my words, O king;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਜਉਨ ਕਾਰਜ ਕੋ ਚਲੇ ਤੁਮ ਸੋ ਨਹੀ ਇਹ ਠੈਨ। ੧੩੬।","roman":"Jaun kaaraj ko chale tum so nahee ih thain | 136 |","meaning_en":"\"what you have come for is not in this place.\"","page":884,"meaning_status":"draft","note":"ਠੈਨ: 'place'."}]},{"type":"heading","kind":"speaker","name":"ਸਿੰਧੁ ਬਾਚ","gurmukhi":"ਸਿੰਧੁ ਬਾਚ","roman":"Sindhu baach","meaning_en":"The Ocean said:","page":884,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Rual metre.","page":884,"meaning_status":"draft"},{"type":"verse","number":[137],"number_text":"੧੩੭।","page":884,"lines":[{"gurmukhi":"ਛੀਰ ਸਾਗਰ ਹੈ ਜਹਾ ਸੁਨ ਰਾਜ ਰਾਜ ਵਤਾਰ।","roman":"Chheer saagar hai jahaa sun raaj raaj vataar |","meaning_en":"\"Where the Ocean of Milk is, listen, O incarnation of the king of kings,","page":884,"meaning_status":"draft"},{"gurmukhi":"ਮਛ ਉਦਰ ਮਛੰਦ੍ਰ ਜੋਗੀ ਬੈਠ ਹੈ ਬ੍ਰਤ ਧਾਰਿ।","roman":"Machh udar machhandr jogee baith hai brat dhaari |","meaning_en":"\"the yogi Machhindra sits in the belly of a fish, keeping his vow;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਡਾਰਿ ਜਾਰ ਨਿਕਾਰ ਤਾਕਹਿ ਪੂਛ ਲੇਹੁ ਬਨਾਇ।","roman":"Daari jaar nikaar taakhi poochh lehu banaai |","meaning_en":"\"cast a net, draw him out, and question him properly;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਕਹਾ ਸੋ ਕੀਜੀਐ ਨ੍ਰਿਪ ਇਹੀ ਸਤਿ ਉਪਾਇ। ੧੩੭।","roman":"Jo kahaa so keejeeai nrip ihee sati upaai | 137 |","meaning_en":"\"whatever he tells you, do it, O king; this is the true way.\"","page":884,"meaning_status":"draft"}]},{"type":"verse","number":[138],"number_text":"੧੩੮।","page":884,"lines":[{"gurmukhi":"ਜੋਰਿ ਬੀਰਨ ਨਾਖ ਸਿੰਧਹ ਆਗ ਚਾਲ ਸੁਬਾਹ।","roman":"Jori beeran naakh sindhah aag chaal subaah |","meaning_en":"Gathering his warriors, the strong-armed one crossed the ocean and went on ahead;","page":884,"meaning_status":"draft","note":"ਨਾਖ: 'crossing'; uncertain."},{"gurmukhi":"ਹੂਰ ਪੂਰ ਰਹੀ ਜਹਾ ਤਹਾ ਜਤ੍ਰ ਤਤ੍ਰ ਉਛਾਹ।","roman":"Hoor poor rahee jahaa tahaa jatr tatr uchhaah |","meaning_en":"joy filled every place, here and there;","page":884,"meaning_status":"draft","note":"ਹੂਰ ਪੂਰ: unclear; perhaps 'houris (heavenly maidens) filled' or 'clamour filled'. Uncertain."},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਜੰਤ੍ਰ ਬਾਜਤ ਅਉਰ ਘੁਰਤ ਨਿਸਾਨ।","roman":"Bhaati bhaati bajantr baajat aur ghurat nisaan |","meaning_en":"instruments of many kinds were playing and kettledrums were thundering;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਛੀਰ ਸਿੰਧੁ ਹੁਤੋ ਜਹਾ ਤਿਹ ਠਾਮ ਪਹੁਚੇ ਆਨਿ। ੧੩੮।","roman":"Chheer sindhu huto jahaa tih thaam pahuche aani | 138 |","meaning_en":"they came and reached the place where the Ocean of Milk was.","page":884,"meaning_status":"draft"}]},{"type":"verse","number":[139],"number_text":"੧੩੯।","page":884,"lines":[{"gurmukhi":"ਸੂਤ੍ਰ ਜਾਰ ਬਨਾਇ ਕੈ ਤਿਹ ਮਧਿ ਡਾਰਿ ਅਪਾਰ।","roman":"Sootr jaar banaai kai tih madhi daari apaar |","meaning_en":"Making nets of thread, they cast countless of them into it;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਜੀਵ ਘਨੇ ਗਹੇ ਨ ਵਿਲੋਕਯੋ ਸਿਵ ਬਾਰ।","roman":"Aur jeev ghane gahe na vilokyo siv baar |","meaning_en":"they caught many other creatures, but did not see Shiva's child;","page":884,"meaning_status":"draft","note":"ਸਿਵ ਬਾਰ: read as 'Shiva's child' (Machhindra); uncertain."},{"gurmukhi":"ਹਾਰਿ ਹਾਰਿ ਫਿਰੇ ਸਬੈ ਭਟ ਆਨਿ ਭੂਪਤਿ ਤੀਰ।","roman":"Haari haari phire sabai bhat aani bhoopti teer |","meaning_en":"all the warriors, having failed and failed, came back to the king:","page":884,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਜੀਵ ਘਨੇ ਗਹੇ ਪਰ ਸੋ ਨ ਪਾਵ ਫਕੀਰ। ੧੩੯।","roman":"Aur jeev ghane gahe par so na paav phakeer | 139 |","meaning_en":"\"We caught many other creatures, but did not find that fakir.\"","page":884,"meaning_status":"draft","note":"ਫਕੀਰ: an ascetic (Arabic)."}]},{"type":"verse","number":[140],"number_text":"੧੪੦।","page":884,"lines":[{"gurmukhi":"ਮਛ ਪੇਟਿ ਮਛੰਦ੍ਰ ਜੋਗੀ ਬੈਠ ਹੈ ਬਿਨੁ ਆਸ।","roman":"Machh peti machhandr jogee baith hai binu aas |","meaning_en":"(The Ocean said:) \"The yogi Machhindra sits in the belly of the fish, free of desire;","page":884,"meaning_status":"draft","note":"Speaker uncertain; read as the Ocean or an adviser."},{"gurmukhi":"ਜਾਰ ਭੇਟ ਸਕੈ ਨ ਵਾ ਕੋ ਮੋਨਿ ਅੰਗ ਸੁ ਬਾਸ।","roman":"Jaar bhet sakai na vaa ko moni ang su baas |","meaning_en":"\"the net cannot reach him; the silent sage dwells in his own body;","page":884,"meaning_status":"draft","note":"ਮੋਨਿ ਅੰਗ ਸੁ ਬਾਸ: uncertain."},{"gurmukhi":"ਏਕ ਜਾਰ ਸੁਨਾ ਨਯੋ ਤਿਹ ਡਾਰੀਐ ਅਬਿਚਾਰ।","roman":"Ek jaar sunaa nayo tih daareeai abichaar |","meaning_en":"\"I have heard of one new net; cast it without hesitation;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿ ਬਾਤ ਕਹੋ ਤੁਮੈ ਸੁਨਿ ਰਾਜ ਰਾਜ ਵਤਾਰ। ੧੪੦।","roman":"Sati baat kaho tumai suni raaj raaj vataar | 140 |","meaning_en":"\"I tell you the truth; listen, O incarnation of the king of kings.","page":884,"meaning_status":"draft"}]},{"type":"verse","number":[141],"number_text":"੧੪੧।","page":884,"lines":[{"gurmukhi":"ਗਿਆਨ ਨਾਮੁ ਸੁਨਾ ਹਮੋ ਤਿਹ ਜਾਰ ਕੋ ਨ੍ਰਿਪ ਰਾਇ।","roman":"Giaan naamu sunaa hamo tih jaar ko nrip raai |","meaning_en":"\"I have heard the name of that net is Knowledge, O king;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਤਉਨ ਤਾ ਮੈ ਡਾਰਿ ਕੈ ਮੁਨਿ ਰਾਜ ਲੇਹੁ ਗਹਾਇ।","roman":"Taun taa mai daari kai muni raaj lehu gahaai |","meaning_en":"\"cast that into it and have the king of sages caught;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਨ ਹਾਥਿ ਪਰੇ ਮੁਨੀਸੁਰ ਬੀਤ ਹੈ ਬਹੁ ਬਰਖ।","roman":"Yau na haathi pare muneesur beet hai bahu barakh |","meaning_en":"\"otherwise the lord of sages will not come into your hands though many years pass;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿ ਬਾਤ ਕਹੌ ਤੁਮੈ ਸੁਨ ਲੀਜੀਐ ਭਰਤਰਖ। ੧੪੧।","roman":"Sati baat kahau tumai sun leejeeai bharatrakh | 141 |","meaning_en":"\"I tell you the truth; listen, O lord of Bharat.\"","page":884,"meaning_status":"draft","note":"ਭਰਤਰਖ: read as 'protector of Bharat' or 'best of the Bharatas'; uncertain."}]},{"type":"verse","number":[142],"number_text":"੧੪੨।","page":884,"lines":[{"gurmukhi":"ਯੌ ਨ ਪਾਨਿ ਪਰੇ ਮੁਨਾਬਰ ਹੋਹਿੰ ਕੋਟਿ ਉਪਾਇ।","roman":"Yau na paani pare munaabar hohin koti upaai |","meaning_en":"\"Otherwise the great sage will not come into your hands, though millions of means are tried;","page":884,"meaning_status":"draft"},{"gurmukhi":"ਡਾਰ ਕੇ ਤੁਮ ਗ੍ਯਾਨ ਜਾਰ ਸੁ ਤਾਸੁ ਲੇਹੁ ਗਹਾਇ।","roman":"Daar ke tum gyaan jaar su taasu lehu gahaai |","meaning_en":"\"cast the net of Knowledge and have him caught.\"","page":884,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਯਾਨ ਜਾਰ ਜਬੈ ਨ੍ਰਿਪੰਬਰ ਡਾਰ੍ਯੋ ਤਿਹ ਬੀਚ।","roman":"Gyaan jaar jabai nripanbar daaryo tih beech |","meaning_en":"When the best of kings cast the net of Knowledge into it,","page":884,"meaning_status":"draft"},{"gurmukhi":"ਤਉਨ ਜਾਰ ਗਹੋ ਮੁਨਾਬਰ ਜਾਨੁ ਦੂਜ ਦਧੀਚ। ੧੪੨।","roman":"Taun jaar gaho munaabar jaanu dooj dadheech | 142 |","meaning_en":"that net caught the great sage, like a second Dadhichi.","page":884,"meaning_status":"draft","note":"Dadhichi: a famous sage."}]},{"type":"verse","number":[143],"number_text":"੧੪੩।","page":885,"lines":[{"gurmukhi":"ਮਛ ਸਹਿਤ ਮਛਿੰਦ੍ਰ ਜੋਗੀ ਬਧਿ ਜਾਰ ਮਝਾਰ।","roman":"Machh sahit machhindr jogee badhi jaar majhaar |","meaning_en":"The yogi Machhindra, together with the fish, was bound in the net;","page":885,"meaning_status":"draft"},{"gurmukhi":"ਮਛ ਲੋਕ ਬਿਲੋਕਿ ਕੈ ਸਬ ਹ੍ਵੈ ਗਏ ਬਿਸੰਭਾਰ।","roman":"Machh lok biloki kai sab hvai gae bisanbhaar |","meaning_en":"seeing the fish, the people all lost their senses;","page":885,"meaning_status":"draft"},{"gurmukhi":"ਦ੍ਵੈ ਮਹੂਰਤ ਬਿਤੀ ਜਬੈ ਸੁਧਿ ਪਾਇ ਕੈ ਕਛੁ ਅੰਗਿ।","roman":"Dvai mahoorat bitee jabai sudhi paai kai kachhu angi |","meaning_en":"when two muhurtas had passed, regaining some awareness in their bodies,","page":885,"meaning_status":"draft","note":"ਮਹੂਰਤ: a period of about 48 minutes."},{"gurmukhi":"ਭੂਪ ਦ੍ਵਾਰ ਗਏ ਸਭੈ ਭਟ ਬਾਧਿ ਅਸਤ੍ਰ ਉਤੰਗ। ੧੪੩।","roman":"Bhoop dvaar gae sabhai bhat baadhi asatr utang | 143 |","meaning_en":"all the warriors went to the king's door, girding on lofty weapons.","page":885,"meaning_status":"draft"}]},{"type":"verse","number":[144],"number_text":"੧੪੪।","page":885,"lines":[{"gurmukhi":"ਮਛ ਉਦਰ ਲਗੇ ਸੁ ਚੀਰਨ ਕਿਉਹੂੰ ਨ ਚੀਰਾ ਜਾਇ।","roman":"Machh udar lage su cheeran kiuhoon na cheeraa jaai |","meaning_en":"They began to cut open the fish's belly, but it could not be cut in any way;","page":885,"meaning_status":"draft"},{"gurmukhi":"ਹਾਰਿ ਹਾਰਿ ਪਰੈ ਜਬੈ ਤਬ ਪੂਛ ਮਿਤ੍ਰ ਬੁਲਾਇ।","roman":"Haari haari parai jabai tab poochh mitr bulaai |","meaning_en":"when they had tried and given up, he called his friends and asked:","page":885,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਕਉਨ ਬਿਚਾਰੀਐ ਉਪਚਾਰ ਤਾਕਰ ਆਜ।","roman":"Aur kaun bichaareeai upchaar taakar aaj |","meaning_en":"\"What other remedy should be considered for it today,","page":885,"meaning_status":"draft"},{"gurmukhi":"ਦ੍ਰਿਸਟਿ ਜਾ ਤੇ ਪਰੈ ਮੁਨੀਸ੍ਵਰ ਸਰੇ ਹਮਰੋ ਕਾਜੁ। ੧੪੪।","roman":"Dristi jaa te parai muneesvar sare hamro kaaju | 144 |","meaning_en":"\"so that the lord of sages may be seen and our task accomplished?\"","page":885,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":885,"meaning_status":"draft"},{"type":"verse","number":[145],"number_text":"੧੪੫।","page":885,"lines":[{"gurmukhi":"ਮਛ ਪੇਟ ਕਿਹੂੰ ਨ ਫੁਟੇ ਸਬ ਕਰ ਹਟੇ ਉਪਾਇ।","roman":"Machh pet kihoon na phute sab kar hate upaai |","meaning_en":"The fish's belly would not burst by any means; all had tried every means and given up;","page":885,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਯਾਨ ਗੁਰੂ ਤਿਨ ਕੋ ਹੁਤੋ ਪੂਛਾ ਤਹਿ ਬਨਾਇ। ੧੪੫।","roman":"Gyaan guroo tin ko huto poochhaa tahi banaai | 145 |","meaning_en":"their guru was Knowledge; they asked him properly.","page":885,"meaning_status":"draft","note":"ਗ੍ਯਾਨ ਗੁਰੂ: read as 'Knowledge, their guru'; may be a person named Gyan. Uncertain."}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"Totak metre.","page":885,"meaning_status":"draft"},{"type":"verse","number":[146],"number_text":"੧੪੬।","page":885,"lines":[{"gurmukhi":"ਭਟ ਤ੍ਯਾਗ ਕੈ ਸਬ ਗਰਬ। ਨ੍ਰਿਪ ਤੀਰ ਬੋਲੋ ਸਰਬ।","roman":"Bhat tyaag kai sab garab | nrip teer bolo sarab |","meaning_en":"The warriors, giving up all their pride, all spoke to the king:","page":885,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਪੂਛੀਐ ਗੁਰ ਗ੍ਯਾਨ। ਕਹਿ ਦੇਇ ਤੋਹਿ ਬਿਧਾਨ। ੧੪੬।","roman":"Nrip poochheeai gur gyaan | kahi dei tohi bidhaan | 146 |","meaning_en":"\"O king, ask the guru Knowledge; he will tell you the way.\"","page":885,"meaning_status":"draft"}]},{"type":"verse","number":[147],"number_text":"੧੪੭।","page":885,"lines":[{"gurmukhi":"ਬਿਧਿ ਪੂਰਿ ਕੈ ਸੁਭ ਚਾਰ। ਅਰੁ ਗ੍ਯਾਨ ਰੀਤਿ ਬਿਚਾਰਿ।","roman":"Bidhi poori kai subh chaar | aru gyaan reeti bichaari |","meaning_en":"Completing the rites in good order, and reflecting on the way of knowledge, (the king said:)","page":885,"meaning_status":"draft"},{"gurmukhi":"ਗੁਰ ਭਾਖੀਐ ਮੁਹਿ ਭੇਵ। ਕਿਮ ਦੇਖੀਐ ਮੁਨਿ ਦੇਵ। ੧੪੭।","roman":"Gur bhaakheeai muhi bhev | kim dekheeai muni dev | 147 |","meaning_en":"\"O Guru, tell me the secret: how may the godlike sage be seen?\"","page":885,"meaning_status":"draft"}]},{"type":"verse","number":[148],"number_text":"੧੪੮।","page":885,"lines":[{"gurmukhi":"ਗੁਰ ਗ੍ਯਾਨ ਬੋਲ੍ਯੋ ਬੈਨ। ਸੁਭ ਬਾਚ ਸੋ ਸੁਖ ਦੈਨ।","roman":"Gur gyaan bolyo bain | subh baach so sukh dain |","meaning_en":"The guru Knowledge spoke words, good words that give peace:","page":885,"meaning_status":"draft"},{"gurmukhi":"ਛੁਰਕਾ ਬਿਬੇਕ ਲੈ ਹਾਥ। ਇਹ ਫਾਰੀਐ ਤਿਹ ਸਾਥ। ੧੪੮।","roman":"Chhurkaa bibek lai haath | ih phaareeai tih saath | 148 |","meaning_en":"\"Take the knife of Discernment (Bibek) in your hand, and with it cut this open.\"","page":885,"meaning_status":"draft","note":"ਬਿਬੇਕ: discernment, discrimination between true and false. Kept as the name Bibek below."}]},{"type":"verse","number":[149],"number_text":"੧੪੯।","page":885,"lines":[{"gurmukhi":"ਤਬ ਕਾਮ ਤੈਸੋ ਈ ਕੀਨ। ਗੁਰ ਗ੍ਯਾਨ ਜ੍ਯੋਂ ਸਿਖ ਦੀਨ।","roman":"Tab kaam taiso ee keen | gur gyaan jyon sikh deen |","meaning_en":"Then he did the task just so, as the guru Knowledge had instructed;","page":885,"meaning_status":"draft"},{"gurmukhi":"ਗਹਿ ਕੈ ਬਿਬੇਕਹਿ ਹਾਥ। ਤਿਹ ਚੀਰਿਆ ਤਿਹ ਸਾਥ। ੧੪੯।","roman":"Gahi kai bibekhi haath | tih cheeriaa tih saath | 149 |","meaning_en":"taking Discernment in hand, he cut it open with it.","page":885,"meaning_status":"draft"}]},{"type":"verse","number":[150],"number_text":"੧੫੦।","page":885,"lines":[{"gurmukhi":"ਜਬ ਚੀਰਿ ਪੇਟ ਬਨਾਇ। ਤਬ ਦੇਖਏ ਜਗ ਰਾਇ।","roman":"Jab cheeri pet banaai | tab dekhae jag raai |","meaning_en":"When he had cut the belly open properly, then the king of the world saw (the sage),","page":885,"meaning_status":"draft"},{"gurmukhi":"ਜੁਤ ਧ੍ਯਾਨ ਮੁੰਦ੍ਰਤ ਨੈਨ। ਬਿਨੁ ਆਸ ਚਿਤ ਨ ਡੁਲੈਨ। ੧੫੦।","roman":"Jut dhyaan mundrat nain | binu aas chit na dulain | 150 |","meaning_en":"absorbed in meditation, eyes closed, free of desire, his mind not wavering.","page":885,"meaning_status":"draft"}]},{"type":"verse","number":[151],"number_text":"੧੫੧।","page":885,"lines":[{"gurmukhi":"ਸਤ ਧਾਤ ਪੁਤ੍ਰਾ ਕੀਨ। ਮੁਨਿ ਦ੍ਰਿਸਟਿ ਤਰ ਧਰ ਦੀਨ।","roman":"Sat dhaat putraa keen | muni dristi tar dhar deen |","meaning_en":"He had an image made of the seven metals and set it beneath the sage's gaze;","page":885,"meaning_status":"draft","note":"ਪੁਤ੍ਰਾ: an effigy, figure."},{"gurmukhi":"ਜਬ ਛੂਟਿ ਰਿਖਿ ਕੇ ਧ੍ਯਾਨ। ਤਬ ਭਏ ਭਸਮ ਪ੍ਰਮਾਨ। ੧੫੧।","roman":"Jab chhooti rikhi ke dhyaan | tab bhae bhasam pramaan | 151 |","meaning_en":"when the seer's meditation broke, it was at once burnt to ashes.","page":885,"meaning_status":"draft"}]},{"type":"verse","number":[152],"number_text":"੧੫੨।","page":885,"lines":[{"gurmukhi":"ਜੋ ਅਉਰ ਦ੍ਰਿਗ ਤਰਿ ਆਉ। ਸੋਊ ਜੀਅਤ ਜਾਨ ਨ ਪਾਉ।","roman":"Jo aur drig tari aau | so'oo jeeat jaan na paau |","meaning_en":"Whatever else came beneath his gaze would not escape alive;","page":885,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਭਸਮ ਹੋਵਤ ਜਾਨੁ। ਬਿਨੁ ਪ੍ਰੀਤਿ ਭਗਤ ਨ ਮਾਨੁ। ੧੫੨।","roman":"So bhasam hovat jaanu | binu preeti bhagat na maanu | 152 |","meaning_en":"know that it would be burnt to ashes; (and) without love, do not take it as devotion.","page":885,"meaning_status":"draft","note":"ਬਿਨੁ ਪ੍ਰੀਤਿ ਭਗਤ ਨ ਮਾਨੁ: the link with the preceding is unclear. Uncertain."}]},{"type":"verse","number":[153],"number_text":"੧੫੩।","page":885,"lines":[{"gurmukhi":"ਜਬ ਭਏ ਪੁਤ੍ਰਾ ਭਸਮ। ਜਨ ਅੰਧਤਾ ਰਵਿ ਰਸਮ।","roman":"Jab bhae putraa bhasam | jan andhtaa ravi rasam |","meaning_en":"When the image had been burnt to ashes, as darkness (is destroyed) by the sun's rays,","page":885,"meaning_status":"draft","note":"ਜਨ ਅੰਧਤਾ ਰਵਿ ਰਸਮ: read as above; uncertain."},{"gurmukhi":"ਪੁਨਿ ਪੂਛੀਆ ਤਿਹਾ ਜਾਇ। ਮੁਨਿ ਰਾਜ ਭੇਦ ਬਤਾਇ। ੧੫੩।","roman":"Puni poochheeaa tihaa jaai | muni raaj bhed bataai | 153 |","meaning_en":"he then went there and asked, \"O king of sages, tell me the secret.\"","page":885,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਨਰਾਜ ਛੰਦ","gurmukhi":"ਨਰਾਜ ਛੰਦ","roman":"Naraaj chhand","meaning_en":"Naraj metre.","page":886,"meaning_status":"draft"},{"type":"verse","number":[154],"number_text":"੧੫੪।","page":886,"lines":[{"gurmukhi":"ਕਉਨ ਭੂਪ ਭੂਮਿ ਮੈ ਬਤਾਇ ਮੋਹਿ ਦੀਜੀਯੈ।","roman":"Kaun bhoop bhoomi mai bataai mohi deejeeyai |","meaning_en":"\"Tell me, which king is there on earth","page":886,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਮੋਹਿ ਤ੍ਰਾਸਿ ਨ ਤ੍ਰਸ੍ਯੋ ਕ੍ਰਿਪਾ ਰਿਖੀਸ ਕੀਜੀਯੈ।","roman":"Jo mohi traasi na trasyo kripaa rikhees keejeeyai |","meaning_en":"\"who has not trembled in fear of me? Be gracious, O lord of seers.","page":886,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਅਉਰ ਕਉਨ ਹੈ ਹਠੀ ਸੁ ਜਉਨ ਮੋ ਨ ਜੀਤਿਯੋ।","roman":"Su aur kaun hai hathee su jaun mo na jeetiyo |","meaning_en":"\"Who else is there, a stubborn one, whom I have not conquered?","page":886,"meaning_status":"draft"},{"gurmukhi":"ਅਤ੍ਰਾਸ ਕਉਨ ਠਉਰ ਹੈ ਜਹਾ ਨ ਮੋਹ ਬੀਤਿਯੋ। ੧੫੪।","roman":"Atraas kaun thaur hai jahaa na moh beetiyo | 154 |","meaning_en":"\"What place is free of fear, where I have not passed?","page":886,"meaning_status":"draft","note":"ਮੋਹ: read as 'me' (moh = mo); could be 'attachment'. Uncertain."}]},{"type":"verse","number":[155],"number_text":"੧੫੫।","page":886,"lines":[{"gurmukhi":"ਨ ਸੰਕ ਚਿਤ ਆਨੀਯੈ ਨਿਸੰਕ ਭਾਖ ਦੀਜੀਯੈ।","roman":"Na sank chit aaneeyai nisank bhaakh deejeeyai |","meaning_en":"\"Do not bring doubt into your mind; speak without hesitation;","page":886,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਕੋ ਅਜੀਤ ਹੈ ਰਹਾ ਉਚਾਰ ਤਾਸੁ ਕੀਜੀਯੈ।","roman":"Su ko ajeet hai rahaa uchaar taasu keejeeyai |","meaning_en":"\"who has remained unconquered? Tell me of him.","page":886,"meaning_status":"draft"},{"gurmukhi":"ਨਰੇਸ ਦੇਸ ਦੇਸ ਕੇ ਅਸੇਸ ਜੀਤ ਮੈ ਲੀਏ।","roman":"Nares des des ke ases jeet mai lee'e |","meaning_en":"\"I have conquered the kings of every land, all of them;","page":886,"meaning_status":"draft"},{"gurmukhi":"ਛਿਤੇਸ ਭੇਸ ਭੇਸ ਕੇ ਗੁਲਾਮ ਆਨਿ ਹੂਐ ਰਹੇ। ੧੫੫।","roman":"Chhites bhes bhes ke gulaam aani hooai rahe | 155 |","meaning_en":"\"lords of the earth of every garb have come and become my slaves.","page":886,"meaning_status":"draft"}]},{"type":"verse","number":[156],"number_text":"੧੫੬।","page":886,"lines":[{"gurmukhi":"ਅਸੇਖ ਰਾਜ ਕਾਜ ਮੋ ਲਗਾਇ ਕੈ ਦੀਏ।","roman":"Asekh raaj kaaj mo lagaai kai dee'e |","meaning_en":"\"I have set countless (people) to the work of kingship;","page":886,"meaning_status":"draft"},{"gurmukhi":"ਅਨੰਤ ਤੀਰਥ ਨਾਤਿ ਕੈ ਅਛਿਨ ਪੁਨ ਮੈ ਕੀਏ।","roman":"Anant teerath naati kai achhin pun mai kee'e |","meaning_en":"\"bathing at endless places of pilgrimage, I have done imperishable good deeds;","page":886,"meaning_status":"draft"},{"gurmukhi":"ਅਨੰਤ ਛਤ੍ਰੀਆਨ ਛੈ ਦੁਰੰਤ ਰਾਜ ਮੈ ਕਰੋ।","roman":"Anant chhatreeaan chhai durant raaj mai karo |","meaning_en":"\"destroying countless Kshatriyas, I rule an invincible kingdom;","page":886,"meaning_status":"draft","note":"ਦੁਰੰਤ: read as 'unbounded, invincible'; uncertain."},{"gurmukhi":"ਸੋ ਕੋ ਤਿਹੁੰ ਜਹਾਨ ਮੈ ਸਮਾਜ ਜਉਨ ਤੇ ਟਰੋ। ੧੫੬।","roman":"So ko tihun jahaan mai samaaj jaun te taro | 156 |","meaning_en":"\"who is there in the three worlds who can turn from my assembly (my rule)?","page":886,"meaning_status":"draft"}]},{"type":"verse","number":[157],"number_text":"੧੫੭।","page":886,"lines":[{"gurmukhi":"ਅਨੰਗ ਰੰਗ ਰੰਗ ਕੇ ਸੁਰੰਗ ਬਾਜ ਮੈ ਹਰੇ।","roman":"Anang rang rang ke surang baaj mai hare |","meaning_en":"\"I have carried off horses of many colours, fine as Kama;","page":886,"meaning_status":"draft","note":"ਅਨੰਗ ਰੰਗ: 'coloured like Kama', i.e. beautiful; uncertain."},{"gurmukhi":"ਬਸੇਖ ਰਾਜਸੂਇ ਜਗ ਬਾਜਮੇਧ ਮੈ ਕਰੇ।","roman":"Basekh raajsooi jag baajmedh mai kare |","meaning_en":"\"I have performed special Rajsui sacrifices and horse sacrifices;","page":886,"meaning_status":"draft","note":"ਰਾਜਸੂਇ: the Rajasuya. ਬਾਜਮੇਧ: the horse sacrifice (ashvamedh)."},{"gurmukhi":"ਨ ਭੂਮਿ ਐਸ ਕੋ ਰਹੀ ਨ ਜਗ ਖੰਭ ਜਾਨੀਯੈ।","roman":"Na bhoomi ais ko rahee na jag khanbh jaaneeyai |","meaning_en":"\"there is no land left where a pillar of my sacrifice is not known;","page":886,"meaning_status":"draft"},{"gurmukhi":"ਜਗਤ੍ਰ ਕਰਣ ਕਾਰਣ ਕਰਿ ਦੁਤੀਯ ਮੋਹਿ ਮਾਨੀਯੈ। ੧੫੭।","roman":"Jagatr karan kaaran kari duteey mohi maaneeyai | 157 |","meaning_en":"\"consider me a second Cause of the causes of the world.","page":886,"meaning_status":"draft"}]},{"type":"verse","number":[158],"number_text":"੧੫੮।","page":886,"lines":[{"gurmukhi":"ਸੁ ਅਤ੍ਰ ਛਤ੍ਰ ਜੇ ਧਰੇ ਸੁ ਛਤ੍ਰ ਸੂਰ ਸੇਵਹੀ।","roman":"Su atr chhatr je dhare su chhatr soor sevhee |","meaning_en":"\"The heroes who held weapons and canopies serve (me) as their canopy (king);","page":886,"meaning_status":"draft"},{"gurmukhi":"ਅਦੰਡ ਖੰਡ ਖੰਡ ਕੇ ਸੁਦੰਡ ਮੋਹਿ ਦੇਵ ਹੀ।","roman":"Adand khand khand ke sudand mohi dev hee |","meaning_en":"\"those never punished before, from every region, pay me fine tribute;","page":886,"meaning_status":"draft","note":"ਸੁਦੰਡ: tribute, levy."},{"gurmukhi":"ਸੁ ਐਸ ਅਉਰ ਕੌਨ ਹੈ ਪ੍ਰਤਾਪਵਾਨ ਜਾਨੀਐ।","roman":"Su ais aur kaun hai prataapvaan jaaneeai |","meaning_en":"\"who else is there, known to be as glorious as this?","page":886,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਿਲੋਕ ਆਜ ਕੇ ਬਿਖੈ ਜੋਗਿੰਦਰ ਮੋਹਿ ਮਾਨੀਐ। ੧੫੮।","roman":"Trilok aaj ke bikhai jogindar mohi maaneeai | 158 |","meaning_en":"\"Today in the three worlds, consider me the lord of yogis.\"","page":886,"meaning_status":"draft","note":"ਜੋਗਿੰਦਰ: lord of yogis."}]},{"type":"heading","kind":"speaker","name":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","gurmukhi":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","roman":"Machhindr baach paarasnaath so","meaning_en":"Machhindra said to Parasnath:","page":886,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":886,"meaning_status":"draft"},{"type":"verse","number":[159],"number_text":"੧੫੯।","page":886,"lines":[{"gurmukhi":"ਕਹਾ ਭਯੋ ਜੋ ਸਭ ਹੀ ਜਗ ਜੀਤਿ ਸੁ ਲੋਗਨ ਕੋ ਬਹੁ ਤ੍ਰਾਸ ਦਿਖਾਯੋ।","roman":"Kahaa bhayo jo sabh hee jag jeeti su logan ko bahu traas dikhaayo |","meaning_en":"\"What of it if you have conquered the whole world and shown people great terror?","page":886,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਕਹਾ ਜੁ ਪੈ ਦੇਸ ਬਿਦੇਸਨ ਮਾਹਿ ਭਲੇ ਗਜ ਗਾਹਿ ਬਧਾਯੋ।","roman":"Aur kahaa ju pai des bidesan maahi bhale gaj gaahi badhaayo |","meaning_en":"\"And what of it if, in lands near and far, you have had fine elephants caught and tied up?","page":886,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਮਨੁ ਜੀਤਤ ਹੈ ਸਭ ਦੇਸ ਵਹੈ ਤੁਮਰੈ ਨ੍ਰਿਪ ਹਾਥਿ ਨ ਆਯੋ।","roman":"Jo manu jeetat hai sabh des vahai tumrai nrip haathi na aayo |","meaning_en":"\"The mind, which conquers all lands, has not come into your hands, O king;","page":886,"meaning_status":"draft"},{"gurmukhi":"ਲਾਜ ਗਈ ਕਛੁ ਕਾਜ ਸਰ੍ਯੋ ਨਹੀ ਲੋਕ ਗਯੋ ਪਰਲੋਕ ਨ ਪਾਯੋ। ੧੫੯।","roman":"Laaj gaee kachhu kaaj saryo nahee lok gayo parlok na paayo | 159 |","meaning_en":"\"your honour is gone, nothing has been accomplished; this world is lost and you have not won the next.\"","page":886,"meaning_status":"draft"}]},{"type":"verse","number":[160],"number_text":"੧੬੦।","page":886,"lines":[{"gurmukhi":"ਭੂਮਿ ਕੋ ਕਉਨ ਗੁਮਾਨ ਹੈ ਭੂਪਤਿ ਸੋ ਨਹੀ ਕਾਹੂੰ ਕੇ ਸੰਗ ਚਲੈ ਹੈ।","roman":"Bhoomi ko kaun gumaan hai bhoopti so nahee kaahoon ke sang chalai hai |","meaning_en":"\"What pride is there in land, O king? It goes along with no one.","page":886,"meaning_status":"draft"},{"gurmukhi":"ਹੈ ਛਲਵੰਤ ਬਡੀ ਬਸੁਧਾ ਯਹਿ ਕਾਹੂੰ ਕੀ ਹੈ ਨਹ ਕਾਹੂੰ ਹੁਐ ਹੈ।","roman":"Hai chhalvant badee basudhaa yahi kaahoon kee hai nah kaahoon huai hai |","meaning_en":"\"This earth is a great deceiver; it belongs to no one, and will belong to no one;","page":886,"meaning_status":"draft"},{"gurmukhi":"ਭਉਨ ਭੰਡਾਰ ਸਬੈ ਬਰ ਨਾਰਿ ਸੁ ਅੰਤਿ ਤੁਝੈ ਕੋਊ ਸਾਥ ਨ ਦੈ ਹੈ।","roman":"Bhaun bhandaar sabai bar naari su anti tujhai ko'oo saath na dai hai |","meaning_en":"\"palaces, treasuries, all the fine women, none of them will go with you at the end.","page":886,"meaning_status":"draft"},{"gurmukhi":"ਆਨ ਕੀ ਬਾਤ ਚਲਾਤ ਹੋ ਕਾਹੇ ਕਉ ਸੰਗਿ ਕੀ ਦੇਹ ਨ ਸੰਗਿ ਸਿਧੈ ਹੈ। ੧੬੦।","roman":"Aan kee baat chalaat ho kaahe kau sangi kee deh na sangi sidhai hai | 160 |","meaning_en":"\"Why speak of other things? Not even your own body, which is with you, will go with you.\"","page":886,"meaning_status":"draft"}]},{"type":"verse","number":[161],"number_text":"੧੬੧।","page":887,"lines":[{"gurmukhi":"ਰਾਜ ਕੇ ਸਾਜ ਕੋ ਕਉਨ ਗੁਮਾਨ ਨਿਦਾਨ ਜੁ ਆਪਨ ਸੰਗ ਨ ਜੈ ਹੈ।","roman":"Raaj ke saaj ko kaun gumaan nidaan ju aapan sang na jai hai |","meaning_en":"\"What pride is there in the trappings of rule, which in the end will not go with you?","page":887,"meaning_status":"draft"},{"gurmukhi":"ਭਉਨ ਭੰਡਾਰ ਭਰੇ ਘਰ ਬਾਰ ਸੁ ਏਕ ਹੀ ਬਾਰ ਬਿਗਾਨ ਕਹੈ ਹੈ।","roman":"Bhaun bhandaar bhare ghar baar su ek hee baar bigaan kahai hai |","meaning_en":"\"Palaces, full treasuries, home and household, all at once will call you a stranger;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਪੁਤ੍ਰ ਕਲਤ੍ਰ ਸੁ ਮਿਤ੍ਰ ਸਖਾ ਕੋਈ ਅੰਤਿ ਸਮੈ ਤੁਹਿ ਸਾਥ ਨ ਦੈ ਹੈ।","roman":"Putr kalatr su mitr sakhaa koee anti samai tuhi saath na dai hai |","meaning_en":"\"son, wife, friend or companion, none will keep you company at the last time.","page":887,"meaning_status":"draft"},{"gurmukhi":"ਚੇਤ ਰੇ ਚੇਤ ਅਚੇਤ ਮਹਾ ਪਸੁ ਸੰਗ ਬੀਯੋ ਸੋ ਭੀ ਸੰਗ ਨ ਜੈ ਹੈ। ੧੬੧।","roman":"Chet re chet achet mahaa pasu sang beeyo so bhee sang na jai hai | 161 |","meaning_en":"\"Awake, awake, you thoughtless great beast; even what you were born with will not go with you.\"","page":887,"meaning_status":"draft","note":"ਸੰਗ ਬੀਯੋ: read as 'what came with you' (the body); uncertain."}]},{"type":"verse","number":[162],"number_text":"੧੬੨।","page":887,"lines":[{"gurmukhi":"ਕਉਨ ਭਰੋਸ ਭਟਾਨ ਕੋ ਭੂਪਤਿ ਭਾਰ ਪਰੇ ਜਿਨਿ ਭਾਰ ਸਹੈਂਗੇ।","roman":"Kaun bharos bhataan ko bhoopti bhaar pare jini bhaar sahainge |","meaning_en":"\"What trust is there in warriors, O king? When the weight falls, they will not bear it;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਭਾਜ ਹੈ ਭੀਰ ਭਯਾਨਕ ਹੁਐ ਕਰ ਭਾਰਥ ਸੋ ਨਹੀ ਭੇਰ ਚਹੈਂਗੇ।","roman":"Bhaaj hai bheer bhayaanak huai kar bhaarath so nahee bher chahainge |","meaning_en":"\"the cowards will flee in fright; they will not want to clash in battle;","page":887,"meaning_status":"draft","note":"ਭਾਰਥ: battle. ਭੇਰ: clash, encounter."},{"gurmukhi":"ਏਕ ਉਪਚਾਰ ਨ ਚਾਲ ਹੈ ਰਾਜਨ ਮਿਤ੍ਰ ਸਬੈ ਮ੍ਰਿਤ ਨੀਰ ਬਹੈਂਗੇ।","roman":"Ek upchaar na chaal hai raajan mitr sabai mrit neer bahainge |","meaning_en":"\"no remedy will work, O king; all your friends will only pour out the water for the dead;","page":887,"meaning_status":"draft","note":"ਮ੍ਰਿਤ ਨੀਰ: the water offered for the dead."},{"gurmukhi":"ਪੁਤ੍ਰ ਕਲਤ੍ਰ ਸਭੈ ਤੁਮਰੇ ਨ੍ਰਿਪ ਛੂਟਤ ਪ੍ਰਾਨ ਮਸਾਨ ਕਹੈਂਗੇ। ੧੬੨।","roman":"Putr kalatr sabhai tumre nrip chhootat praan masaan kahainge | 162 |","meaning_en":"\"your son and wife, all of them, O king, when your life departs, will say 'To the cremation ground!'\"","page":887,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","roman":"Paarasnaath baach machhindr so","meaning_en":"Parasnath said to Machhindra:","page":887,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":887,"meaning_status":"draft"},{"type":"verse","number":[163],"number_text":"੧੬੩।","page":887,"lines":[{"gurmukhi":"ਮੁਨਿ ਕਉਨ ਹੈ ਵਹ ਰਾਉ। ਤਿਹ ਆਜ ਮੋਹਿ ਬਤਾਉ।","roman":"Muni kaun hai vah raau | tih aaj mohi bataau |","meaning_en":"\"O sage, who is that king? Tell me about him today;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਜੀਤ ਹੋ ਜਬ ਜਾਇ। ਤਬ ਭਾਖੀਅਉ ਮੁਹਿ ਰਾਇ। ੧੬੩।","roman":"Tih jeet ho jab jaai | tab bhaakheeau muhi raai | 163 |","meaning_en":"\"when I go and conquer him, then call me king.\"","page":887,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","gurmukhi":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","roman":"Machhindr baach paarasnaath so","meaning_en":"Machhindra said to Parasnath:","page":887,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":887,"meaning_status":"draft"},{"type":"verse","number":[164],"number_text":"੧੬੪।","page":887,"lines":[{"gurmukhi":"ਸੁਨ ਰਾਜ ਰਾਜਨ ਹੰਸ। ਭਵ ਭੂਮਿ ਕੇ ਅਵਤੰਸ।","roman":"Sun raaj raajan hans | bhav bhoomi ke avtans |","meaning_en":"\"Listen, O swan among kings, crown-jewel of the earth;","page":887,"meaning_status":"draft","note":"ਅਵਤੰਸ: crest-ornament."},{"gurmukhi":"ਤੁਹਿ ਜੀਤਏ ਸਬ ਰਾਇ। ਪਰ ਸੋ ਨ ਜੀਤਯੋ ਜਾਇ। ੧੬੪।","roman":"Tuhi jeetae sab raai | par so na jeetyo jaai | 164 |","meaning_en":"\"you have conquered all the kings, but he cannot be conquered.","page":887,"meaning_status":"draft"}]},{"type":"verse","number":[165],"number_text":"੧੬੫।","page":887,"lines":[{"gurmukhi":"ਅਬਿਬੇਕ ਹੈ ਤਿਹ ਨਾਉ। ਤਵ ਹੀਯ ਮੈ ਤਿਹ ਠਾਉ।","roman":"Abibek hai tih naau | tav heey mai tih thaau |","meaning_en":"\"Abibek (Non-discernment) is his name; his place is in your heart;","page":887,"meaning_status":"draft","note":"ਅਬਿਬੇਕ: lack of discernment, ignorance; kept as the king's name Abibek."},{"gurmukhi":"ਤਿਹ ਜੀਤ ਕਹੀ ਨ ਭੂਪ। ਵਹ ਹੈ ਸਰੂਪ ਅਨੂਪ। ੧੬੫।","roman":"Tih jeet kahee na bhoop | vah hai saroop anoop | 165 |","meaning_en":"\"you have not conquered him anywhere, O king; he is of a matchless form.","page":887,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhapai metre.","page":887,"meaning_status":"draft"},{"type":"verse","number":[166],"number_text":"੧੬੬।","page":887,"lines":[{"gurmukhi":"ਬਲਿ ਮਹੀਪ ਜਿਨ ਛਲ੍ਯੋ ਬ੍ਰਹਮ ਬਾਵਨ ਬਸ ਕਿਨੋ।","roman":"Bali maheep jin chhalyo braham baavan bas kino |","meaning_en":"\"He who deceived King Bali, and brought Brahma and Vaman under his sway;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਕਿਸਨ ਬਿਸਨ ਜਿਨ ਹਰੇ ਦੰਡ ਰਘੁਪਤਿ ਤੇ ਲਿਨੋ।","roman":"Kisan bisan jin hare dand raghupti te lino |","meaning_en":"\"he who carried off Krishna and Vishnu, and took tribute from Raghupati (Ram);","page":887,"meaning_status":"draft"},{"gurmukhi":"ਦਸ ਗ੍ਰੀਵਹਿ ਜਿਨਿ ਹਰਾ ਸੁਭਟ ਸੁੰਭਾਸੁਰ ਖੰਡ੍ਯੋ।","roman":"Das greevhi jini haraa subhat sunbhaasur khandyo |","meaning_en":"\"he who defeated Ravan (the ten-necked), and cut down the warrior demon Sumbh;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਮਹਖਾਸੁਰ ਮਰਦੀਆ ਮਾਨ ਮਧੁ ਕੀਟ ਬਿਹੰਡ੍ਯੋ।","roman":"Mahkhaasur mardeeaa maan madhu keet bihandyo |","meaning_en":"\"who crushed the pride of Mahishasur and destroyed Madhu and Kaitabh;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਸੋਊ ਮਦਨ ਰਾਜ ਰਾਜਾ ਨ੍ਰਿਪਤਿ ਨ੍ਰਿਪ ਅਬਿਬੇਕ ਮੰਤ੍ਰੀ ਕੀਯੋ।","roman":"So'oo madan raaj raajaa nripti nrip abibek mantree keeyo |","meaning_en":"\"that Madan (Kama), king of kings, King Abibek has made his minister,","page":887,"meaning_status":"draft","note":"ਮਦਨ: Madan, Kama, the god of desire."},{"gurmukhi":"ਜਿਹ ਦੇਵ ਦਈਤ ਗੰਧ੍ਰਬ ਮੁਨਿ ਜੀਤਿ ਅਡੰਡ ਡੰਡਹਿ ਲੀਯੋ। ੧੬੬।","roman":"Jih dev daeet gandhrab muni jeeti adand dandhi leeyo | 166 |","meaning_en":"\"he who conquered gods, demons, Gandharvas and sages, and took tribute from those who had never paid it.","page":887,"meaning_status":"draft"}]},{"type":"verse","number":[167],"number_text":"੧੬੭।","page":887,"lines":[{"gurmukhi":"ਜਵਨ ਕ੍ਰੁਧ ਜੁਧ ਕਰਣ ਕੈਰਵ ਰਣ ਘਾਏ।","roman":"Javan krudh judh karan kairav ran ghaae |","meaning_en":"\"He whose anger slew Karan and the Kauravs in battle;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਜਾਸੁ ਕੋਪ ਕੇ ਕੀਨ ਸੀਸ ਦਸ ਸੀਸ ਗਵਾਏ।","roman":"Jaasu kop ke keen sees das sees gavaae |","meaning_en":"\"by whose wrath Ravan (the ten-headed) lost his heads;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਜਉਨ ਕ੍ਰੁਧ ਕੇ ਕੀਏ ਦੇਵ ਦਾਨਵ ਰਣਿ ਲੁਝੇ।","roman":"Jaun krudh ke kee'e dev daanav rani lujhe |","meaning_en":"\"by whose anger gods and demons clashed in battle;","page":887,"meaning_status":"draft"},{"gurmukhi":"ਜਾਸੁ ਕ੍ਰੋਧ ਕੇ ਕੀਨ ਖਸਟ ਕੁਲ ਜਾਦਵ ਜੁਝੇ।","roman":"Jaasu krodh ke keen khasat kul jaadav jujhe |","meaning_en":"\"by whose wrath the clans of the Yadavs fought and died;","page":887,"meaning_status":"draft","note":"ਖਸਟ ਕੁਲ: 'six clans'; read as the clans of the Yadavs."},{"gurmukhi":"ਸੋਊ ਤਾ ਸਮਾਨੁ ਸੈਨਾਧਿਪਤਿ ਜਿਦਿਨ ਰੋਸ ਵਹੁ ਆਇ ਹੈ।","roman":"So'oo taa samaanu sainaadhipti jidin ros vahu aai hai |","meaning_en":"\"such is his commander-in-chief; on the day he comes in rage,","page":887,"meaning_status":"draft","note":"Here the general is Anger (Krodh), implied."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਸੁਨਹੋ ਨ੍ਰਿਪਤਿ ਅਵਰ ਸਮੁਹਿ ਕੋ ਜਾਇ ਹੈ। ੧੬੭।","roman":"Binu ik bibek sunho nripti avar samuhi ko jaai hai | 167 |","meaning_en":"\"listen, O king, apart from Bibek (Discernment) alone, who else will go and face him?","page":887,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","gurmukhi":"ਪਾਰਸਨਾਥ ਬਾਚ ਮਛਿੰਦ੍ਰ ਸੋ","roman":"Paarasnaath baach machhindr so","meaning_en":"Parasnath said to Machhindra:","page":888,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhapai metre.","page":888,"meaning_status":"draft"},{"type":"verse","number":[168],"number_text":"੧੬੮।","page":888,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਮਛਿੰਦ੍ਰ ਬੈਨ ਕਹੋ ਤੁਹਿ ਬਾਤ ਬਿਚਛਨ।","roman":"Sunhu machhindr bain kaho tuhi baat bichchhan |","meaning_en":"\"Listen, Machhindra, I speak to you; tell me this matter clearly, O wise one:","page":888,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਬਿਬੇਕ ਅਬਿਬੇਕ ਜਗਤ ਦ੍ਵੈ ਨ੍ਰਿਪਤਿ ਸੁਲਛਨ।","roman":"Ik bibek abibek jagat dvai nripti sulchhan |","meaning_en":"\"Bibek and Abibek, the two, are fine kings in the world;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਬਡ ਜੋਧਾ ਦੁਹੂੰ ਸੰਗ ਬਡੇ ਦੋਊ ਆਪ ਧਨੁਰਧਰ।","roman":"Bad jodhaa duhoon sang bade do'oo aap dhanurdhar |","meaning_en":"\"both have great warriors with them, and both are themselves great archers;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਜਾਤਿ ਇਕ ਪਾਤਿ ਏਕ ਹੀ ਮਾਤ ਜੋਧਾਬਰ।","roman":"Ek jaati ik paati ek hee maat jodhaabar |","meaning_en":"\"of one caste, one lineage, one mother, these best of warriors;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਤਾਤ ਏਕ ਹੀ ਬੰਸ ਪੁਨਿ ਬੈਰ ਭਾਵ ਦੁਹ ਕਿਮ ਗਹੋ।","roman":"Ik taat ek hee bans puni bair bhaav duh kim gaho |","meaning_en":"\"of one father and one family; how then did the two come to hold enmity?","page":888,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਨਾਮ ਠਾਮ ਆਭਰਣ ਰਥ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਸਬ ਮੁਨਿ ਕਹੋ। ੧੬੮।","roman":"Tih naam thaam aabhran rath sasatr asatr sab muni kaho | 168 |","meaning_en":"\"O sage, tell me their names, places, ornaments, chariots and all their weapons.\"","page":888,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","gurmukhi":"ਮਛਿੰਦ੍ਰ ਬਾਚ ਪਾਰਸਨਾਥ ਸੋ","roman":"Machhindr baach paarasnaath so","meaning_en":"Machhindra said to Parasnath:","page":888,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhapai metre.","page":888,"meaning_status":"draft"},{"type":"verse","number":[169],"number_text":"੧੬੯।","page":888,"lines":[{"gurmukhi":"ਅਸਿਤ ਬਰਣ ਅਬਿਬੇਕ ਅਸਿਤ ਬਾਜੀ ਰਥ ਸੋਭਤ।","roman":"Asit baran abibek asit baajee rath sobhat |","meaning_en":"\"Dark of hue is Abibek; dark horses and chariot adorn him;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਤ ਬਸਤ੍ਰ ਤਿਹ ਅੰਗਿ ਨਿਰਖਿ ਨਾਰੀ ਨਰ ਲੋਭਤ।","roman":"Asit basatr tih angi nirkhi naaree nar lobhat |","meaning_en":"\"dark clothes are on his body; seeing them men and women are tempted;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਤ ਸਾਰਥੀ ਅਗ੍ਰ ਅਸਿਤ ਆਭਰਣ ਰਥੋਤਮ।","roman":"Asit saarthee agr asit aabhran rathotam |","meaning_en":"\"a dark charioteer in front, dark ornaments, the finest chariot;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਤ ਧਨੁਖ ਕਰਿ ਅਸਿਤ ਧੁਜਾ ਜਾਨੁਕ ਪੁਰਖੋਤਮ।","roman":"Asit dhanukh kari asit dhujaa jaanuk purkhotam |","meaning_en":"\"a dark bow in his hand, a dark banner, as if he were Purushottam (Vishnu);","page":888,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਛਬਿ ਨਰੇਸ ਅਬਿਬੇਕ ਨ੍ਰਿਪ ਜਗਤ ਜਯੰਕਰ ਮਾਨੀਯੈ।","roman":"Ih chhabi nares abibek nrip jagat jayankar maaneeyai |","meaning_en":"\"such is the beauty of King Abibek, consider him the conqueror of the world;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਅਨਜਿਤ ਜਾਸੁ ਕਹ ਨ ਤਜੋ ਕ੍ਰਿਸਨ ਰੂਪ ਤਿਹ ਜਾਨੀਯੈ। ੧੬੯।","roman":"Anjit jaasu kah na tajo krisan roop tih jaaneeyai | 169 |","meaning_en":"\"he is unconquered, and he has spared no one; know him to be of the form of Krishna.","page":888,"meaning_status":"draft","note":"ਕਹ ਨ ਤਜੋ: read as 'has left no one (unconquered)'; uncertain. Krishna ('the dark one') is a comparison of colour."}]},{"type":"verse","number":[170],"number_text":"੧੭੦।","page":888,"lines":[{"gurmukhi":"ਪੁਹਪ ਧਨੁਖ ਅਲਿ ਪਨਚ ਮਤਸ ਜਿਹ ਧੁਜਾ ਬਿਰਾਜੈ।","roman":"Puhap dhanukh ali panach matas jih dhujaa biraajai |","meaning_en":"\"He whose bow is of flowers, whose bowstring is of bees, on whose banner a fish shines,","page":888,"meaning_status":"draft","note":"This describes Madan (Kama)."},{"gurmukhi":"ਬਾਜਤ ਝਾਝਰ ਤੂਰ ਮਧੁਰ ਬੀਨਾ ਧੁਨਿ ਬਾਜੈ।","roman":"Baajat jhaajhar toor madhur beenaa dhuni baajai |","meaning_en":"\"for whom cymbals and trumpets play and the sweet sound of the vina rings;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਸਬ ਬਜੰਤ੍ਰ ਜਿਹ ਸੰਗ ਬਜਤ ਸੁੰਦਰ ਛਬ ਸੋਹਤ।","roman":"Sab bajantr jih sang bajat sundar chhab sohat |","meaning_en":"\"with whom all the instruments play, and who looks splendid in his beauty;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗ ਸੈਨ ਅਬਲਾ ਸੰਬੂਹ ਸੁਰ ਨਰ ਮੁਨਿ ਮੋਹਤ।","roman":"Sang sain ablaa sanbooh sur nar muni mohat |","meaning_en":"\"with an army of hosts of women with him, he enchants gods, men and sages;","page":888,"meaning_status":"draft","note":"ਅਬਲਾ: women."},{"gurmukhi":"ਅਸ ਮਦਨ ਰਾਜ ਰਾਜਾ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਕ੍ਰੁਧ ਕਰਿ ਧਾਇ ਹੈ।","roman":"As madan raaj raajaa nripti jidin krudh kari dhaai hai |","meaning_en":"\"such is Madan, king of kings; on the day he charges in anger,","page":888,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਤਾ ਕੇ ਸਮੁਹਿ ਅਉਰ ਦੂਸਰ ਕੋ ਜਾਇ ਹੈ। ੧੭੦।","roman":"Binu ik bibek taa ke samuhi aur doosar ko jaai hai | 170 |","meaning_en":"\"apart from Bibek alone, who else will go and face him?","page":888,"meaning_status":"draft"}]},{"type":"verse","number":[171],"number_text":"੧੭੧।","page":888,"lines":[{"gurmukhi":"ਕਰਤ ਨ੍ਰਿਤ ਸੁੰਦਰੀ ਬਜਤ ਬੀਨਾ ਧੁਨਿ ਮੰਗਲ।","roman":"Karat nrit sundree bajat beenaa dhuni mangal |","meaning_en":"\"Beautiful women dance, the vina plays auspicious tunes,","page":888,"meaning_status":"draft"},{"gurmukhi":"ਉਪਜਤ ਰਾਗ ਸੰਬੂਹ ਬਜਤ ਬੈਰਾਰੀ ਬੰਗਲਿ।","roman":"Upjat raag sanbooh bajat bairaaree bangli |","meaning_en":"\"hosts of ragas arise, Bairari and Bangali are played,","page":888,"meaning_status":"draft"},{"gurmukhi":"ਭੈਰਵ ਰਾਗ ਬਸੰਤ ਦੀਪ ਹਿੰਡੋਲ ਮਹਾ ਸੁਰ।","roman":"Bhairav raag basant deep hindol mahaa sur |","meaning_en":"\"Raag Bhairav, Basant, Deepak and Hindol in grand tones;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਉਘਟਤ ਤਾਨ ਤਰੰਗ ਸੁਨਤ ਰੀਝਤ ਧੁਨਿ ਸੁਰ ਨਰ।","roman":"Ughtat taan tarang sunat reejhat dhuni sur nar |","meaning_en":"\"waves of melody burst forth; hearing the sound gods and men are delighted;","page":888,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਭਾਵ ਰਿਤੁ ਰਾਜ ਨ੍ਰਿਪ ਜਿਦਿਨ ਰੋਸ ਕਰਿ ਧਾਇ ਹੈ।","roman":"Ih chhabi prabhaav ritu raaj nrip jidin ros kari dhaai hai |","meaning_en":"\"such is the beauty and power of King Ritu-raj (Spring); on the day he charges in anger,","page":888,"meaning_status":"draft","note":"ਰਿਤੁ ਰਾਜ: 'king of seasons', Spring (Basant), here a son of Madan."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਤਾ ਕੇ ਨ੍ਰਿਪਤਿ ਅਉਰ ਸਮੁਹਿ ਕੋ ਜਾਇ ਹੈ। ੧੭੧।","roman":"Binu ik bibek taa ke nripti aur samuhi ko jaai hai | 171 |","meaning_en":"\"apart from Bibek alone, O king, who else will face him?","page":888,"meaning_status":"draft"}]},{"type":"verse","number":[172],"number_text":"੧੭੨।","page":889,"lines":[{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਸੁਧ ਮਲਾਰ ਬਿਭਾਸ ਸਰਬਿ ਗਨਿ।","roman":"Sorthi saarang sudh malaar bibhaas sarbi gani |","meaning_en":"\"Sorath, Sarang, pure Malar, Bibhas, count them all;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਰਾਮਕਲੀ ਹਿੰਡੋਲ ਗੌਡ ਗੂਜਰੀ ਮਹਾ ਧੁਨਿ।","roman":"Raamaklee hindol gaud goojree mahaa dhuni |","meaning_en":"\"Ramkali, Hindol, Gaund, Gujri, with great sound;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਲਲਤ ਪਰਜ ਗਵਰੀ ਮਲਾਰ ਕਾਨੜਾ ਮਹਾ ਛਬਿ।","roman":"Lalat paraj gavree malaar kaanraa mahaa chhabi |","meaning_en":"\"Lalit, Paraj, Gauri, Malar, Kanara, of great beauty;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਜਾਹਿ ਬਿਲੋਕਤ ਬੀਰ ਸਰਬ ਤੁਮਰੇ ਜੈ ਹੈ ਦਬਿ।","roman":"Jaahi bilokat beer sarab tumre jai hai dabi |","meaning_en":"\"seeing whom all your heroes will be overpowered;","page":889,"meaning_status":"draft","note":"ਦਬਿ: 'pressed down, subdued'."},{"gurmukhi":"ਇਹ ਬਿਧਿ ਨਰੇਸ ਰਿਤੁ ਰਾਜ ਨ੍ਰਿਪ ਮਦਨ ਸੂਅਨ ਜਬ ਗਰਜ ਹੈ।","roman":"Ih bidhi nares ritu raaj nrip madan sooan jab garaj hai |","meaning_en":"\"thus, O king, when King Ritu-raj, son of Madan, roars,","page":889,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਇਕ ਗ੍ਯਾਨ ਸੁਨ ਹੋ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਦੂਸਰ ਕੋ ਬਰਜਿ ਹੈ। ੧੭੨।","roman":"Binu ik gyaan sun ho nripti su aur doosar ko barji hai | 172 |","meaning_en":"\"listen, O king, apart from Knowledge alone, who else will hold him back?","page":889,"meaning_status":"draft"}]},{"type":"verse","number":[173],"number_text":"੧੭੩।","page":889,"lines":[{"gurmukhi":"ਕਊਧਤ ਦਾਮਨਿ ਸਘਨ ਸਘਨ ਘੋਰਤ ਚਹੁਦਿਸ ਘਨ।","roman":"Kaoodhat daamni saghan saghan ghorat chahudis ghan |","meaning_en":"\"The lightning flashes thickly, the clouds thunder thickly in all four directions;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਮੋਹਿਤ ਭਾਮਿਨ ਸਘਨ ਡਰਤ ਬਿਰਹਨਿ ਤ੍ਰਿਯ ਲਖਿ ਮਨਿ।","roman":"Mohit bhaamin saghan darat birahni triy lakhi mani |","meaning_en":"\"women are deeply enchanted; women parted from their lovers are afraid, seeing it in their minds;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਬੋਲਤ ਦਾਦੁਰ ਮੋਰ ਸਘਨ ਝਿਲੀ ਝਿੰਕਾਰਤ।","roman":"Bolat daadur mor saghan jhilee jhinkaarat |","meaning_en":"\"frogs and peacocks call thickly, the crickets chirp;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖਤ ਦ੍ਰਿਗਨ ਪ੍ਰਭਾਵ ਅਮਿਤ ਮੁਨਿ ਮਨ ਬ੍ਰਿਤ ਹਾਰਤ।","roman":"Dekhat drigan prabhaav amit muni man brit haarat |","meaning_en":"\"seeing its boundless power with their eyes, the sages lose their composure of mind;","page":889,"meaning_status":"draft","note":"ਬ੍ਰਿਤ: state of mind, resolve."},{"gurmukhi":"ਇਹ ਬਿਧਿ ਹੁਲਾਸ ਮਦਨਜ ਦੂਸਰ ਜਿਦਿਨ ਚਟਕ ਦੈ ਸਟਕ ਹੈ।","roman":"Ih bidhi hulaas madnaj doosar jidin chatak dai satak hai |","meaning_en":"\"such is Hulas (Delight), Madan's second son; on the day he strikes with a crack,","page":889,"meaning_status":"draft","note":"ਹੁਲਾਸ: delight, exhilaration; kept as a name. ਚਟਕ ਦੈ ਸਟਕ ਹੈ: read as 'strikes swiftly'; uncertain."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਸੁਨਹੋ ਨ੍ਰਿਪਤਿ ਅਉਰ ਦੂਸਰ ਕੋ ਹਟਕ ਹੇ। ੧੭੩।","roman":"Binu ik bibek sunho nripti aur doosar ko hatak he | 173 |","meaning_en":"\"listen, O king, apart from Bibek alone, who else will stop him?","page":889,"meaning_status":"draft"}]},{"type":"verse","number":[174],"number_text":"੧੭੪।","page":889,"lines":[{"gurmukhi":"ਤ੍ਰਿਤੀਆ ਪੁਤ੍ਰ ਅਨੰਦ ਜਿਦਿਨ ਸਸਤ੍ਰਨ ਕਹੁ ਧਰਿ ਹੈ।","roman":"Triteeaa putr anand jidin sastran kahu dhari hai |","meaning_en":"\"On the day the third son, Anand (Pleasure), takes up his weapons,","page":889,"meaning_status":"draft","note":"ਅਨੰਦ: joy, pleasure; kept as a name."},{"gurmukhi":"ਕਰਿ ਹੈ ਚਿਤ੍ਰ ਬਚਿਤ੍ਰ ਸੁ ਰਣ ਸੁਰ ਨਰ ਮੁਨਿ ਡਰਿ ਹੈ।","roman":"Kari hai chitr bachitr su ran sur nar muni dari hai |","meaning_en":"\"he will make a wondrous battle; gods, men and sages will be afraid;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਕੋ ਭਟ ਧਰਿ ਹੈ ਧੀਰ ਜਿਦਿਨ ਸਾਮੁਹਿ ਵਹ ਐ ਹੈ।","roman":"Ko bhat dhari hai dheer jidin saamuhi vah ai hai |","meaning_en":"\"what warrior will keep his nerve on the day he comes face to face?","page":889,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਕੋ ਤੇਜ ਪ੍ਰਤਾਪ ਛਿਨਕ ਭੀਤਰ ਹਰ ਲੈ ਹੈ।","roman":"Sabh ko tej prataap chhinak bheetar har lai hai |","meaning_en":"\"he will take away everyone's radiance and glory in an instant;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਨੰਦ ਦੁਰ ਧਰਖ ਭਟ ਜਿਦਿਨ ਸਸਤ੍ਰ ਗਹ ਮਿਕ ਹੈ।","roman":"Ih bidhi anand dur dharakh bhat jidin sasatr gah mik hai |","meaning_en":"\"such is Anand, the invincible warrior; on the day he takes up weapons and flashes,","page":889,"meaning_status":"draft","note":"ਦੁਰ ਧਰਖ: invincible, hard to withstand. ਮਿਕ ਹੈ: read as 'will flash'; uncertain."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਸੁਨਿ ਰੇ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਨ ਦੂਸਰਿ ਟਿਕ ਹੈ। ੧੭੪।","roman":"Binu ik dheeraj suni re nripti su aur na doosri tik hai | 174 |","meaning_en":"\"listen, O king, apart from Dhiraj (Patience) alone, no other will stand firm.","page":889,"meaning_status":"draft","note":"ਧੀਰਜ: patience, steadiness; kept as a name."}]},{"type":"verse","number":[175],"number_text":"੧੭੫।","page":889,"lines":[{"gurmukhi":"ਰਤਨ ਜਟਤ ਰਥ ਸੁਭਤ ਖਚਿਤ ਬਜ੍ਰਨ ਮੁਕਤਾਫਲ।","roman":"Ratan jatat rath subhat khachit bajran muktaaphal |","meaning_en":"\"His chariot, set with jewels, shines, studded with diamonds and pearls;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਹੀਰ ਚੀਰ ਆਭਰਣ ਧਰੇ ਸਾਰਥੀ ਮਹਾਬਲ।","roman":"Heer cheer aabhran dhare saarthee mahaabal |","meaning_en":"\"his very mighty charioteer wears diamonds, fine clothes and ornaments;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਕਨਕ ਦੇਖ ਕੁਰਰਾਤ ਕਠਨ ਕਾਮਿਨ ਬ੍ਰਿਤ ਹਾਰਤ।","roman":"Kanak dekh kurraat kathan kaamin brit haarat |","meaning_en":"\"seeing the gold, even hard (hearts) cry out, and women lose their resolve;","page":889,"meaning_status":"draft","note":"ਕੁਰਰਾਤ: read as 'cry out (like the kurari bird)'; uncertain."},{"gurmukhi":"ਤਨਿ ਪਟੰਬਰ ਜਰਕਸੀ ਪਰਮ ਭੂਖਨ ਤਨ ਧਾਰਤ।","roman":"Tani patanbar jaraksee param bhookhan tan dhaarat |","meaning_en":"\"on his body he wears silks embroidered with gold thread, and supreme ornaments;","page":889,"meaning_status":"draft","note":"ਜਰਕਸੀ: gold-embroidered (Persian zarkash)."},{"gurmukhi":"ਇਹ ਛਬਿ ਅਨੰਦ ਮਦਨਜ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਗਰਜ ਦਲ ਗਾਹਿ ਹੈ।","roman":"Ih chhabi anand madnaj nripti jidin garaj dal gaahi hai |","meaning_en":"\"such is the beauty of King Anand, son of Madan; on the day he roars and churns the armies,","page":889,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਸੁਨਿ ਰੇ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਸਮੁਹ ਕੋ ਜਾਹਿ ਹੈ। ੧੭੫।","roman":"Binu ik dheeraj suni re nripti su aur samuh ko jaahi hai | 175 |","meaning_en":"\"listen, O king, apart from Dhiraj alone, who else will go and face him?","page":889,"meaning_status":"draft"}]},{"type":"verse","number":[176],"number_text":"੧੭੬।","page":889,"lines":[{"gurmukhi":"ਧੂਮ੍ਰ ਬਰਣ ਸਾਰਥੀ ਧੂਮ੍ਰ ਬਾਜੀਰਥ ਛਾਜਤ।","roman":"Dhoomr baran saarthee dhoomr baajeerath chhaajat |","meaning_en":"\"Smoke-coloured is his charioteer; smoke-coloured horses and chariot look splendid;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਧੂਮ੍ਰ ਬਰਣ ਆਭਰਣ ਨਿਰਖਿ ਸੁਰ ਨਰ ਮੁਨਿ ਲਾਜਤ।","roman":"Dhoomr baran aabhran nirkhi sur nar muni laajat |","meaning_en":"\"his ornaments are smoke-coloured; seeing him, gods, men and sages are ashamed;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਧੂਮ੍ਰ ਨੈਨ ਧੂਮਰੋ ਗਾਤ ਧੂਮਰ ਤਿਹ ਭੂਖਨ।","roman":"Dhoomr nain dhoomro gaat dhoomar tih bhookhan |","meaning_en":"\"smoky eyes, smoky body, smoky are his ornaments;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਧੂਮ੍ਰ ਬਦਨ ਤੇ ਬਮਤ ਸਰਬ ਸਤ੍ਰੂ ਕੁਲ ਦੂਖਨ।","roman":"Dhoomr badan te bamat sarab satroo kul dookhan |","meaning_en":"\"from his smoky mouth he spews (smoke), the bane of all the enemy clans;","page":889,"meaning_status":"draft"},{"gurmukhi":"ਅਸ ਭਰਮ ਮਦਨ ਚਤੁਰਥ ਸੁਵਨ ਜਿਦਿਨ ਰੋਸ ਕਰਿ ਧਾਇ ਹੈ।","roman":"As bharam madan chaturath suvan jidin ros kari dhaai hai |","meaning_en":"\"such is Bharam (Delusion), Madan's fourth son; on the day he charges in anger,","page":889,"meaning_status":"draft","note":"ਭਰਮ: delusion, doubt; kept as a name."},{"gurmukhi":"ਦਲ ਲੂਟ ਕੂਟ ਤੁਮਰੋ ਨ੍ਰਿਪਤਿ ਸੁ ਸਰਬ ਛਿਨਕ ਮਹਿ ਜਾਇ ਹੈ। ੧੭੬।","roman":"Dal loot koot tumro nripti su sarab chhinak mahi jaai hai | 176 |","meaning_en":"\"your army, O king, will be looted and smashed, all of it, in an instant.","page":889,"meaning_status":"draft"}]},{"type":"verse","number":[177],"number_text":"੧੭੭।","page":890,"lines":[{"gurmukhi":"ਅਉਰ ਅਉਰ ਜੇ ਸੁਭਟਿ ਗਨੋ ਤਿਹ ਨਾਮ ਬਿਚਛਨ।","roman":"Aur aur je subhti gano tih naam bichchhan |","meaning_en":"\"Other warriors I count besides, whose names are remarkable,","page":890,"meaning_status":"draft"},{"gurmukhi":"ਬਡ ਜੋਧਾ ਬਡ ਸੂਰ ਬਡੇ ਜਿਤਵਾਰ ਸੁਲੱਛਨ।","roman":"Bad jodhaa bad soor bade jitvaar sulcchhan |","meaning_en":"\"great fighters, great heroes, great conquerors, of fine marks;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਕਲਹਿ ਨਾਮ ਇਕ ਨਾਰਿ ਮਹਾ ਕਲ ਰੂਪ ਕਲਹ ਕਰ।","roman":"Kalhi naam ik naari mahaa kal roop kalah kar |","meaning_en":"\"there is a woman named Kalah (Strife), the very form of discord, who makes quarrels;","page":890,"meaning_status":"draft","note":"ਕਲਹਿ: strife, quarrel; kept as a name."},{"gurmukhi":"ਲੋਗ ਚਤੁਰਦਸ ਮਾਝਿ ਜਾਸੁ ਛੋਰਾ ਨਹੀ ਸੁਰ ਨਰ।","roman":"Log chaturdas maajhi jaasu chhoraa nahee sur nar |","meaning_en":"\"among the fourteen worlds she has spared neither god nor man;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਸਬ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਭੀਤਰ ਨਿਪੁਣ ਅਤਿ ਪ੍ਰਭਾਵ ਤਿਹ ਜਾਨੀਐ।","roman":"Sab sasatr asatr bheetar nipun ati prabhaav tih jaaneeai |","meaning_en":"\"skilled in all weapons, know her power to be very great;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਸਬ ਦੇਸ ਭੇਸ ਅਰੁ ਰਾਜ ਸਬ ਤ੍ਰਾਸ ਜਵਨ ਕੋ ਮਾਨੀਐ। ੧੭੭।","roman":"Sab des bhes aru raaj sab traas javan ko maaneeai | 177 |","meaning_en":"\"all lands, all garbs, all kingdoms stand in dread of her.","page":890,"meaning_status":"draft"}]},{"type":"verse","number":[178],"number_text":"੧੭੮।","page":890,"lines":[{"gurmukhi":"ਬੈਰ ਨਾਮ ਇਕ ਬੀਰ ਮਹਾ ਦੁਰ ਧਰਖ ਅਜੈ ਰਣਿ।","roman":"Bair naam ik beer mahaa dur dharakh ajai rani |","meaning_en":"\"There is a hero named Bair (Enmity), very hard to withstand, unconquerable in battle;","page":890,"meaning_status":"draft","note":"ਬੈਰ: enmity; kept as a name."},{"gurmukhi":"ਕਬਹੁ ਦੀਨ ਨਹੀ ਪੀਠਿ ਅਨਿਕ ਜੀਤੇ ਜਿਹ ਨ੍ਰਿਪ ਗਣ।","roman":"Kabhu deen nahee peethi anik jeete jih nrip gan |","meaning_en":"\"he has never turned his back, and has conquered many hosts of kings;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਲੋਚਨ ਸ੍ਰੌਣਤ ਬਰਣ ਅਰੁਣ ਸਬ ਸਸਤ੍ਰ ਅੰਗਿ ਤਿਹ।","roman":"Lochan sraunat baran arun sab sasatr angi tih |","meaning_en":"\"his eyes are the colour of blood, red; all weapons are on his body;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਰਵਿ ਪ੍ਰਕਾਸ ਸਰ ਧੁਜਾ ਅਰੁਣ ਲਾਜਤ ਲਖਿ ਛਬਿ ਜਿਹ।","roman":"Ravi prakaas sar dhujaa arun laajat lakhi chhabi jih |","meaning_en":"\"(he has) the light of the sun, arrows and a red banner; seeing his splendour (others) are ashamed;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਭਾਤਿ ਬੈਰ ਬੀਰਾ ਬਡੈ ਜਿਦਿਨ ਕ੍ਰੁਧ ਕਰਿ ਗਰਜਿ ਹੈ।","roman":"Ih bhaati bair beeraa badai jidin krudh kari garji hai |","meaning_en":"\"such is the great hero Bair; on the day he roars in anger,","page":890,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸਾਂਤਿ ਸੁਨ ਰੇ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਨ ਦੂਸਰ ਬਰਜਿ ਹੈ। ੧੭੮।","roman":"Binu ek saanti sun re nripti su aur na doosar barji hai | 178 |","meaning_en":"\"listen, O king, apart from Shanti (Peace) alone, no other will hold him back.","page":890,"meaning_status":"draft","note":"ਸਾਂਤਿ: peace, calm; kept as a name."}]},{"type":"verse","number":[179],"number_text":"੧੭੯।","page":890,"lines":[{"gurmukhi":"ਧੂਮ੍ਰ ਧੁਜਾ ਰਥ ਧੂਮ੍ਰ ਧੂਮ੍ਰ ਸਾਰਥੀ ਬਿਰਾਜਤ।","roman":"Dhoomr dhujaa rath dhoomr dhoomr saarthee biraajat |","meaning_en":"\"His banner is smoky, his chariot smoky, his smoky charioteer looks splendid;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਧੂਮ੍ਰ ਬਸਤ੍ਰ ਤਨ ਧਰੋ ਨਿਰਖਿ ਧੂਅਰੋ ਮਨਿ ਲਾਜਤ।","roman":"Dhoomr basatr tan dharo nirkhi dhooaro mani laajat |","meaning_en":"\"he wears smoky clothes on his body; seeing him, even smoke is ashamed at heart;","page":890,"meaning_status":"draft","note":"ਧੂਅਰੋ: read as 'smoke'; uncertain."},{"gurmukhi":"ਧੂਮ੍ਰ ਧਨੁਖ ਕਰ ਛਕ੍ਯੋ ਬਾਨ ਧੂਮਰੇ ਸੁਹਾਏ।","roman":"Dhoomr dhanukh kar chhakyo baan dhoomre suhaae |","meaning_en":"\"a smoky bow in his hand, and fine smoky arrows look splendid;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਸੁਰ ਨਰ ਨਾਗ ਭੁਜੰਗ ਜਛ ਅਰੁ ਅਸੁਰ ਲਜਾਏ।","roman":"Sur nar naag bhujang jachh aru asur lajaae |","meaning_en":"\"gods, men, Nagas, serpents, Yakshas and demons are put to shame;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਭਾਵ ਆਲਸ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਜੁਧ ਕਹ ਜੁਟ ਹੈ।","roman":"Ih chhabi prabhaav aalas nripti jidin judh kah jut hai |","meaning_en":"\"such is the beauty and power of King Alas (Sloth); on the day he joins battle,","page":890,"meaning_status":"draft","note":"ਆਲਸ: sloth, idleness; kept as a name."},{"gurmukhi":"ਉਦਮ ਬਿਹੀਨ ਸੁਨ ਰੇ ਨ੍ਰਿਪਤਿ ਅਉਰ ਸਕਲ ਦਲ ਫੁਟ ਹੈ। ੧੭੯।","roman":"Udam biheen sun re nripti aur sakal dal phut hai | 179 |","meaning_en":"\"apart from Udam (Effort), listen O king, the whole army will scatter.","page":890,"meaning_status":"draft","note":"ਉਦਮ ਬਿਹੀਨ: literally 'without Effort'; read as 'apart from Udam (Effort)'. Uncertain."}]},{"type":"verse","number":[180],"number_text":"੧੮੦।","page":890,"lines":[{"gurmukhi":"ਹਰਿਤ ਧੁਜਾ ਅਰੁ ਧਨੁਖ ਹਰਿਤ ਬਾਜੀ ਰਥ ਸੋਭੰਤ।","roman":"Harit dhujaa aru dhanukh harit baajee rath sobhant |","meaning_en":"\"A green banner and a green bow, green horses and chariot look splendid;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਹਰਤ ਬਸਤ੍ਰ ਤਨ ਧਰੇ ਨਿਰਖਿ ਸੁਰ ਨਰ ਮਨ ਮੋਹੰਤ।","roman":"Harat basatr tan dhare nirkhi sur nar man mohant |","meaning_en":"\"he wears green clothes on his body; seeing him, the minds of gods and men are enchanted;","page":890,"meaning_status":"draft","note":"ਹਰਤ: printed so; read as 'harit', green."},{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਚਲਤ ਭ੍ਰਮਨ ਬਘੂਲਾ ਲਖਿ ਲਜਿਤ।","roman":"Pavan beg rath chalat bhraman baghoolaa lakhi lajit |","meaning_en":"\"his chariot moves at the speed of the wind; seeing it whirl, the whirlwind is ashamed;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਤ ਸ੍ਰਵਨ ਚਕ ਸਬਦ ਮੇਘ ਮਨ ਮਹਿ ਸੁਖੁ ਸਜਿਤ।","roman":"Sunat sravan chak sabad megh man mahi sukhu sajit |","meaning_en":"\"hearing the sound of its wheels with their ears, the clouds feel joy in their minds;","page":890,"meaning_status":"draft","note":"Clouds rejoice, taking the rumble for thunder; uncertain."},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਤਾਪ ਮਦ ਨਾਮ ਨ੍ਰਿਪ ਜਿਦਿਨ ਤੁਰੰਗ ਨਚਾਇ ਹੈ।","roman":"Ih chhabi prataap mad naam nrip jidin turang nachaai hai |","meaning_en":"\"such is the beauty and glory of the king named Mad (Intoxication); on the day he makes his horse dance,","page":890,"meaning_status":"draft","note":"ਮਦ: intoxication, pride; kept as a name."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਬਿਬੇਕ ਸੁਨ ਲੈ ਨ੍ਰਿਪਤਿ ਸਸੁ ਸਮਰਿ ਨ ਦੂਸਰ ਜਾਇ ਹੈ। ੧੮੦।","roman":"Binu ik bibek sun lai nripti sasu samri na doosar jaai hai | 180 |","meaning_en":"\"listen, O king, apart from Bibek alone, no other will go to face him in battle.","page":890,"meaning_status":"draft","note":"ਸਸੁ: unclear; perhaps 'that one'. Uncertain."}]},{"type":"verse","number":[181],"number_text":"੧੮੧।","page":890,"lines":[{"gurmukhi":"ਅਸਿਤ ਧੁਜਾ ਸਾਰਥੀ ਅਸਿਤ ਬਸਤ੍ਰੈ ਅਰੁ ਬਾਜੀ।","roman":"Asit dhujaa saarthee asit bastrai aru baajee |","meaning_en":"\"A dark banner, a dark charioteer, dark clothes and horses;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਤ ਕਵਚ ਤਨ ਕਸੇ ਤਜਤ ਬਾਣਨ ਕੀ ਰਾਜੀ।","roman":"Asit kavach tan kase tajat baanan kee raajee |","meaning_en":"\"dark armour bound on his body, he looses volleys of arrows;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਤ ਸਕਲ ਤਿਹ ਬਰਣ ਅਸਿਤ ਲੋਚਨ ਦੁਖ ਮਰਦਨ।","roman":"Asit sakal tih baran asit lochan dukh mardan |","meaning_en":"\"all of him is dark in colour, dark-eyed, a crusher (of others) with sorrow;","page":890,"meaning_status":"draft","note":"ਦੁਖ ਮਰਦਨ: read as 'who crushes with pain'; it usually means 'destroyer of sorrow'. Uncertain."},{"gurmukhi":"ਅਸਿਤ ਮਣਿਣ ਕੇ ਸਕਲ ਅੰਗਿ ਭੁਖਣ ਰੁਚਿ ਬਰਧਨ।","roman":"Asit manin ke sakal angi bhukhan ruchi bardhan |","meaning_en":"\"ornaments of dark gems on all his limbs heighten his splendour;","page":890,"meaning_status":"draft"},{"gurmukhi":"ਅਸ ਕੁਵ੍ਰਿਤਿ ਬੀਰ ਦੁਰ ਧਰਖ ਅਤਿ ਜਿਦਿਨ ਸਮਰ ਕਹ ਸਜਿ ਹੈ।","roman":"As kuvriti beer dur dharakh ati jidin samar kah saji hai |","meaning_en":"\"such is the hero Kuvritti (Evil Disposition), very hard to withstand; on the day he arrays himself for battle,","page":890,"meaning_status":"draft","note":"ਕੁਵ੍ਰਿਤਿ: evil disposition, bad tendency; kept as a name."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਬੀਰਤ ਤਜਿ ਅਉਰ ਸਕਲ ਦਲ ਭਜਿ ਹੈ। ੧੮੧।","roman":"Binu ik dheeraj beerat taji aur sakal dal bhaji hai | 181 |","meaning_en":"\"apart from Dhiraj (Patience) alone, all the rest of the army will give up its valour and flee.","page":890,"meaning_status":"draft"}]},{"type":"verse","number":[182],"number_text":"੧੮੨।","page":891,"lines":[{"gurmukhi":"ਚਰਮ ਬਰਮ ਕਹ ਧਰੇ ਧਰਮ ਛਤ੍ਰੀ ਕੋ ਧਾਰਤ।","roman":"Charam baram kah dhare dharam chhatree ko dhaarat |","meaning_en":"\"Bearing shield and armour, he keeps the dharma of the Kshatriya;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਅਜੈ ਜਾਨਿ ਆਪਨਹਿ ਸਰਬ ਰਣ ਸੁਭਟ ਪਚਾਰਤ।","roman":"Ajai jaani aapanhi sarab ran subhat pachaarat |","meaning_en":"\"thinking himself unconquerable, he challenges all the warriors in battle;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਧਰਨ ਨ ਆਗੈ ਧੀਰ ਬੀਰ ਜਿਹ ਸਮੁਹ ਧਾਵਤ।","roman":"Dharan na aagai dheer beer jih samuh dhaavat |","meaning_en":"\"no hero can keep his nerve before him, when he charges at him;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਸੁਰ ਅਸੁਰ ਅਰੁ ਨਰ ਨਾਰਿ ਜਛ ਗੰਧ੍ਰਬ ਗੁਨ ਗਾਵਤ।","roman":"Sur asur aru nar naari jachh gandhrab gun gaavat |","meaning_en":"\"gods, demons, men, women, Yakshas and Gandharvas sing his praises;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਗੁਮਾਨ ਜਾ ਦਿਨ ਗਰਜ ਪਰਮ ਕ੍ਰੋਧ ਕਰ ਢੂਕ ਹੈ।","roman":"Ih bidhi gumaan jaa din garaj param krodh kar dhook hai |","meaning_en":"\"such is Guman (Arrogance); on the day he roars and closes in with great anger,","page":891,"meaning_status":"draft","note":"ਗੁਮਾਨ: arrogance, pride; kept as a name."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਸੀਲ ਸੁਨ ਨ੍ਰਿਪਤਿ ਨ੍ਰਿਪਾਣਿ ਸੁ ਅਉਰ ਸਕਲ ਦਲ ਹੂਕ ਹੈ। ੧੮੨।","roman":"Binu ik seel sun nripti nripaani su aur sakal dal hook hai | 182 |","meaning_en":"\"listen, O king of kings, apart from Seel (Gentleness) alone, all the rest of the army will cry out.","page":891,"meaning_status":"draft","note":"ਸੀਲ: good conduct, gentleness; kept as a name. ਨ੍ਰਿਪਾਣਿ: read as 'king of kings'. ਹੂਕ ਹੈ: 'will wail'."}]},{"type":"verse","number":[183],"number_text":"੧੮੩।","page":891,"lines":[{"gurmukhi":"ਕੜਕਿ ਕ੍ਰੋਧ ਕਰਿ ਚੜਗੁ ਭੜਕਿ ਭਾਦਵਿ ਜ੍ਯੋਂ ਗਜਤ।","roman":"Karki krodh kari chargu bharki bhaadvi jyon gajat |","meaning_en":"\"Crackling with anger, he mounts and flares up, and roars like (the clouds of) Bhadon;","page":891,"meaning_status":"draft","note":"ਭਾਦਵਿ: the rainy month Bhadon. Sound-words ਕੜਕਿ, ਭੜਕਿ."},{"gurmukhi":"ਸੜਕ ਤੇਗ ਦਾਮਿਨ ਤੜਕ ਤੜਭੜ ਰਣ ਸਜਤ।","roman":"Sarak teg daamin tarak tarbhar ran sajat |","meaning_en":"\"his sword swishes and flashes like lightning as he arrays the battle with clatter;","page":891,"meaning_status":"draft","note":"ਸੜਕ, ਤੜਕ, ਤੜਭੜ: sound-words."},{"gurmukhi":"ਲੁੜਕ ਲੁਥ ਬਿਥੁਰਗ ਸੇਲ ਸਾਮੁਹਿ ਹ੍ਵੈ ਘਲਤ।","roman":"Lurak luth bithurag sel saamuhi hvai ghalat |","meaning_en":"\"corpses roll and scatter as he hurls lances face to face;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਜਿਦਿਨ ਰੋਸ ਰਾਵਤ ਰਣਹਿ ਦੂਸਰ ਕੋ ਝਲਤ।","roman":"Jidin ros raavat ranhi doosar ko jhalat |","meaning_en":"\"on the day the chief rages in battle, who else will withstand him?","page":891,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਪਮਾਨ ਤਿਹ ਭ੍ਰਾਤ ਭਨ ਜਿਦਿਨ ਰੁਦ੍ਰ ਰਸ ਮਚਿ ਹੈ।","roman":"Ih bidhi apmaan tih bhraat bhan jidin rudr ras machi hai |","meaning_en":"\"such is Apman (Insult), said to be his brother; on the day he stirs up the mood of fury,","page":891,"meaning_status":"draft","note":"ਅਪਮਾਨ: insult, dishonour; kept as a name. ਰੁਦ੍ਰ ਰਸ: the furious mood (raudra rasa)."},{"gurmukhi":"ਬਿਨ ਇਕ ਸੀਲ ਦੁਸੀਲ ਭਟ ਸੁ ਅਉਰ ਕਵਣ ਰਣਿ ਰਚਿ ਹੈ। ੧੮੩।","roman":"Bin ik seel duseel bhat su aur kavan rani rachi hai | 183 |","meaning_en":"\"apart from Seel alone, what other warrior will fight with this ill-natured warrior?","page":891,"meaning_status":"draft","note":"ਦੁਸੀਲ: ill-natured."}]},{"type":"verse","number":[184],"number_text":"੧੮੪।","page":891,"lines":[{"gurmukhi":"ਧਨੁਖ ਮੰਡਲਾਕਾਰ ਲਗਤ ਜਾ ਕੋ ਸਦੀਵ ਰਣ।","roman":"Dhanukh mandlaakaar lagat jaa ko sadeev ran |","meaning_en":"\"His bow is always drawn into a circle in battle;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖਤ ਤੇਜ ਪ੍ਰਭਾਵ ਭਟਕ ਭਾਜਤ ਹੈ ਭਟ ਗਣ।","roman":"Nirkhat tej prabhaav bhatak bhaajat hai bhat gan |","meaning_en":"\"seeing his radiance and power, hosts of warriors run off astray;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਕਉਨ ਬਾਧਿ ਤੇ ਧੀਰ ਬੀਰ ਨਿਰਖਤ ਦੁਤਿ ਲਾਜਤ।","roman":"Kaun baadhi te dheer beer nirkhat duti laajat |","meaning_en":"\"what brave hero can stand firm? Seeing his splendour they are ashamed;","page":891,"meaning_status":"draft","note":"ਕਉਨ ਬਾਧਿ ਤੇ ਧੀਰ: read as 'who keeps his nerve'; uncertain."},{"gurmukhi":"ਨਹਨ ਜੁਧ ਠਹਰਾਤਿ ਤ੍ਰਸਤ ਦਸਹੂੰ ਦਿਸ ਭਾਜਤ।","roman":"Nahan judh thahraati trasat dashoon dis bhaajat |","meaning_en":"\"they do not stand in battle; terrified, they flee in all ten directions;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਅਨਰਥ ਸਮਰਥ ਰਣਿ ਜਿਦਿਨ ਤੁਰੰਗ ਮਟਕ ਹੈ।","roman":"Ih bidhi anrath samrath rani jidin turang matak hai |","meaning_en":"\"such is Anarth (Calamity), mighty in battle; on the day he makes his horse prance,","page":891,"meaning_status":"draft","note":"ਅਨਰਥ: calamity, wrong-doing; kept as a name."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰ ਸੁਨ ਬੀਰ ਬਰੁ ਸੁ ਦੂਸਰ ਕਉਨ ਹਟਕਿ ਹੈ। ੧੮੪।","roman":"Binu ik dheer sun beer baru su doosar kaun hatki hai | 184 |","meaning_en":"\"listen, O best of heroes, apart from Dhir (Steadfastness) alone, who else will hold him back?","page":891,"meaning_status":"draft"}]},{"type":"verse","number":[185],"number_text":"੧੮੫।","page":891,"lines":[{"gurmukhi":"ਪ੍ਰੀਤ ਬਸਤ੍ਰ ਤਨਿ ਧਰੇ ਧੁਜਾ ਪੀਅਰੀ ਰਥ ਧਾਰੇ।","roman":"Preet basatr tani dhare dhujaa peearee rath dhaare |","meaning_en":"\"He wears yellow clothes on his body, and a yellow banner is on his chariot;","page":891,"meaning_status":"draft","note":"ਪ੍ਰੀਤ: printed so; read as 'peet', yellow."},{"gurmukhi":"ਪੀਤ ਮਨੁਖ ਕਰਿ ਸੋਭ ਮਾਨ ਰਤਿ ਪਤਿ ਕੋ ਟਾਰੇ।","roman":"Peet manukh kari sobh maan rati pati ko taare |","meaning_en":"\"a yellow bow in his hand gives him splendour that puts down the husband of Rati (Kama);","page":891,"meaning_status":"draft","note":"ਮਨੁਖ: printed so; read as 'dhanukh', bow. Uncertain."},{"gurmukhi":"ਪੀਤ ਬਰਣ ਸਾਰਥੀ ਪੀਤ ਬਰਣੈ ਰਥ ਬਾਜੀ।","roman":"Peet baran saarthee peet barnai rath baajee |","meaning_en":"\"his charioteer is yellow, his chariot and horses are yellow;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਪੀਤ ਬਰਨ ਕੋ ਬਾਣ ਖੇਤਿ ਚੜਿ ਗਰਜਤ ਗਾਜੀ।","roman":"Peet baran ko baan kheti chari garjat gaajee |","meaning_en":"\"his arrows are yellow; mounted, the champion roars on the field;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਭਾਤਿ ਬੈਰ ਸੂਰਾ ਨ੍ਰਿਪਤਿ ਜਿਦਿਨ ਗਰਜਿ ਦਲ ਗਾਹਿ ਹੈ।","roman":"Ih bhaati bair sooraa nripti jidin garji dal gaahi hai |","meaning_en":"\"such is the hero Bair (Enmity), O king; on the day he roars and churns the army,","page":891,"meaning_status":"draft","note":"ਬੈਰ ਸੂਰਾ: printed so; Bair (Enmity) was described above in red; perhaps a different figure is meant. Uncertain."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਗਿਆਨ ਸਵਧਾਨ ਹ੍ਵੈ ਅਉਰ ਸਮਰ ਕੋ ਚਾਹਿ ਹੈ। ੧੮੫।","roman":"Binu ik giaan savdhaan hvai aur samar ko chaahi hai | 185 |","meaning_en":"\"apart from Gyan (Knowledge), being alert, who else will want to fight?","page":891,"meaning_status":"draft"}]},{"type":"verse","number":[186],"number_text":"੧੮੬।","page":891,"lines":[{"gurmukhi":"ਮਲਿਤ ਬਸਤ੍ਰ ਤਨਿ ਧਰੇ ਮਲਿਤ ਭੂਖਨ ਰਥ ਬਾਧੇ।","roman":"Malit basatr tani dhare malit bhookhan rath baadhe |","meaning_en":"\"He wears dirty clothes on his body, and dirty ornaments are tied on his chariot;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਮਲਿਤ ਮੁਕਟ ਸਿਰ ਧਰੇ ਪਰਮ ਬਾਣਣ ਕਹ ਸਾਧੇ।","roman":"Malit mukat sir dhare param baanan kah saadhe |","meaning_en":"\"he wears a dirty crown on his head and has mastered the finest arrows;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਮਲਿਤ ਬਰਣ ਸਾਰਥੀ ਮਲਿਤ ਤਾਹੂੰ ਆਭੂਖਨ।","roman":"Malit baran saarthee malit taahoon aabhookhan |","meaning_en":"\"his charioteer is dirty in colour, and dirty too are his ornaments;","page":891,"meaning_status":"draft"},{"gurmukhi":"ਮਲਯਾਗਰ ਕੀ ਗੰਧੰ ਸਕਲ ਸਤ੍ਰੂ ਕੁਲ ਦੂਖਨ।","roman":"Malyaagar kee gandhan sakal satroo kul dookhan |","meaning_en":"\"(he has) the scent of sandal, a torment to all enemy clans;","page":891,"meaning_status":"draft","note":"ਮਲਯਾਗਰ: sandalwood of the Malaya hills."},{"gurmukhi":"ਇਹ ਭਾਤਿ ਨਿੰਦ ਅਨਧਰ ਸੁਭਟ ਜਿਦਿਨ ਅਯੋਧਨ ਮਚਿ ਹੈ।","roman":"Ih bhaati nind andhar subhat jidin ayodhan machi hai |","meaning_en":"\"such is the hero Nind (Slander), hard to withstand; on the day the battle rages,","page":891,"meaning_status":"draft","note":"ਨਿੰਦ: slander; may also be 'sleep' (nindra). Kept as a name. ਅਨਧਰ: read as 'not to be withstood'; uncertain."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਧੀਰਜ ਸੁਨ ਬੀਰਬਰ ਸੁ ਆਉਰ ਕਵਣ ਰਣਿ ਰਚਿ ਹੈ। ੧੮੬।","roman":"Binu ik dheeraj sun beerbar su aaur kavan rani rachi hai | 186 |","meaning_en":"\"listen, O best of heroes, apart from Dhiraj alone, who else will fight in the battle?","page":891,"meaning_status":"draft"}]},{"type":"verse","number":[187],"number_text":"੧੮੭।","page":892,"lines":[{"gurmukhi":"ਘੋਰ ਬਸਤ੍ਰ ਤਨਿ ਧਰੇ ਘੋਰ ਪਗੀਆ ਸਿਰ ਬਾਧੇ।","roman":"Ghor basatr tani dhare ghor pageeaa sir baadhe |","meaning_en":"\"He wears dreadful clothes on his body, and a dreadful turban tied on his head;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਘੋਰ ਬਰਣ ਸਿਰਿ ਮੁਕਟ ਘੋਰ ਸਤ੍ਰਨ ਕਹ ਸਾਧੇ।","roman":"Ghor baran siri mukat ghor satran kah saadhe |","meaning_en":"\"a dreadful crown of colour is on his head, and he has mastered dreadful weapons;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਘੋਰ ਮੰਤ੍ਰ ਮੁਖ ਜਪਤ ਪਰਮ ਆਘੋਰ ਰੂਪ ਤਿਹ।","roman":"Ghor mantr mukh japat param aaghor roop tih |","meaning_en":"\"he chants dreadful mantras with his mouth; his form is supremely terrible;","page":892,"meaning_status":"draft","note":"ਆਘੋਰ: fearsome."},{"gurmukhi":"ਲਖਤ ਸ੍ਵਰਗ ਭਹਰਾਤ ਘੋਰ ਆਭਾ ਲਖਿ ਕੇ ਜਿਹ।","roman":"Lakhat svarag bhahraat ghor aabhaa lakhi ke jih |","meaning_en":"\"seeing him, heaven trembles, seeing his dreadful splendour;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਭਾਤਿ ਨਰਕ ਦੁਰ ਧਰਖ ਭਟ ਜਿਦਿਨ ਰੋਸਿ ਰਣਿ ਆਇ ਹੈ।","roman":"Ih bhaati narak dur dharakh bhat jidin rosi rani aai hai |","meaning_en":"\"such is the warrior Narak (Hell), hard to withstand; on the day he comes to battle in anger,","page":892,"meaning_status":"draft","note":"ਨਰਕ: hell; kept as a name."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਹਰਿਨਾਮ ਸੁਨ ਹੋ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਨ ਕੋਇ ਬਚਾਇ ਹੈ। ੧੮੭।","roman":"Binu ik harinaam sun ho nripti su aur na koi bachaai hai | 187 |","meaning_en":"\"listen, O king, apart from the Name of the Lord alone, no one else will save (you).","page":892,"meaning_status":"draft"}]},{"type":"verse","number":[188],"number_text":"੧੮੮।","page":892,"lines":[{"gurmukhi":"ਸਮਟ ਸਾਗ ਸੰਗ੍ਰਹੈ ਸੇਲ ਸਾਮੁਹਿ ਹ੍ਵੈ ਸੁਟੈ।","roman":"Samat saag sangrahai sel saamuhi hvai sutai |","meaning_en":"\"Gathering lances, he hurls spears face to face;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਕਲਿਤ ਕ੍ਰੋਧ ਸੰਜੁਗਤਿ ਗਲਿਤ ਗੈਵਰ ਜਿਯੋਂ ਜੁਟੈ।","roman":"Kalit krodh sanjugti galit gaivar jiyon jutai |","meaning_en":"\"filled with anger, he fights like a rutting elephant;","page":892,"meaning_status":"draft","note":"ਗਲਿਤ ਗੈਵਰ: an elephant in musth."},{"gurmukhi":"ਇਕ ਇਕ ਬਿਨੁ ਕੀਨ ਇਕ ਤੇ ਇਕ ਨ ਚਲੈ।","roman":"Ik ik binu keen ik te ik na chalai |","meaning_en":"\"one by one he has made (them) lifeless; not one gets away from him;","page":892,"meaning_status":"draft","note":"ਇਕ ਇਕ ਬਿਨੁ ਕੀਨ: read as 'made each one lifeless'; uncertain."},{"gurmukhi":"ਇਕ ਇਕ ਸੰਗ ਭਿੜੈ ਸਸਤ੍ਰ ਸਨਮੁਖ ਹ੍ਵੈ ਝਲੈ।","roman":"Ik ik sang bhirai sasatr sanmukh hvai jhalai |","meaning_en":"\"he clashes with each one, and bears their weapons face to face;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਨਸੀਲ ਦੁਸੀਲ ਭਟ ਸਹਤ ਕੁਚੀਲ ਗਰਜਿ ਹੈ।","roman":"Ih bidhi naseel duseel bhat sahat kucheel garji hai |","meaning_en":"\"thus the warriors Naseel (Immodesty) and Duseel (Ill-nature), together with Kucheel (Filth), will roar;","page":892,"meaning_status":"draft","note":"ਨਸੀਲ, ਦੁਸੀਲ, ਕੁਚੀਲ: lack of modesty, bad nature, impurity; kept as names. Uncertain."},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸੁਚਹਿ ਸੁਨਿ ਨ੍ਰਿਪ ਨ੍ਰਿਪਣਿ ਸੁ ਅਉਰ ਨ ਕੋਊ ਬਰਜਿ ਹੈ। ੧੮੮।","roman":"Binu ek suchhi suni nrip nripni su aur na ko'oo barji hai | 188 |","meaning_en":"\"listen, O king of kings, apart from Such (Purity) alone, no one else will hold them back.","page":892,"meaning_status":"draft","note":"ਸੁਚ: purity; kept as a name."}]},{"type":"verse","number":[189],"number_text":"੧੮੯।","page":892,"lines":[{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਦੋਊ ਨਿਪੁਣ ਨਿਪੁਣ ਸਬ ਬੇਦ ਸਾਸਤ੍ਰ ਕਰ।","roman":"Sasatr asatr do'oo nipun nipun sab bed saasatr kar |","meaning_en":"\"Skilled in both kinds of weapons, skilled in all the Vedas and Shastras,","page":892,"meaning_status":"draft"},{"gurmukhi":"ਅਰੁਣ ਨੇਤ੍ਰ ਅਰੁ ਰਕਤ ਬਸਤ੍ਰ ਧ੍ਰਿਤਵਾਨ ਧਨੁਰਧਰ।","roman":"Arun netr aru rakat basatr dhritvaan dhanurdhar |","meaning_en":"\"with red eyes and red clothes, steadfast archers,","page":892,"meaning_status":"draft"},{"gurmukhi":"ਬਿਕਟ ਬਾਕ੍ਯ ਬਡ ਡ੍ਯਾਛ ਬਡੋ ਅਭਿਮਾਨ ਧਰੇ ਮਨ।","roman":"Bikat baaky bad dyaachh bado abhimaan dhare man |","meaning_en":"\"of fierce speech, wide-eyed, holding great pride in their minds,","page":892,"meaning_status":"draft","note":"ਡ੍ਯਾਛ: read as 'large-eyed'; uncertain."},{"gurmukhi":"ਅਮਿਤ ਰੂਪ ਅਮਿਤੋਜ ਅਭੈ ਆਲੋਕ ਅਜੈ ਰਨ।","roman":"Amit roop amitoj abhai aalok ajai ran |","meaning_en":"\"of boundless form and boundless might, fearless, radiant, unconquerable in battle;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਅਸ ਸੁਭਟ ਛੁਧਾ ਤ੍ਰਿਸਨਾ ਸਬਲ ਜਿਦਿਨ ਰੰਗ ਰਣ ਰਚਿ ਹੈ।","roman":"As subhat chhudhaa trisnaa sabal jidin rang ran rachi hai |","meaning_en":"\"such are the mighty warriors Chhudha (Hunger) and Trisna (Thirst); on the day they set up the play of battle,","page":892,"meaning_status":"draft","note":"ਛੁਧਾ, ਤ੍ਰਿਸਨਾ: hunger and craving/thirst; kept as names."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਨ੍ਰਿਪਤਿ ਨਿਗ੍ਰਹ ਬਿਨਾ ਅਉਰ ਜੀਅ ਨ ਲੈ ਬਚਿ ਹੈ। ੧੮੯।","roman":"Binu ik nripti nigrah binaa aur jeea na lai bachi hai | 189 |","meaning_en":"\"apart from King Nigrah (Restraint) alone, no other will escape with his life.","page":892,"meaning_status":"draft","note":"ਨਿਗ੍ਰਹ: restraint, self-control; kept as a name."}]},{"type":"verse","number":[190],"number_text":"੧੯੦।","page":892,"lines":[{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਚਲਤ ਸੁ ਛਬਿ ਸਾਵਜ ਤਾੜਤਾ ਕ੍ਰਿਤ।","roman":"Pavan beg rath chalat su chhabi saavaj taartaa krit |","meaning_en":"\"His chariot moves at the speed of the wind; with fine splendour he strikes the wild beasts;","page":892,"meaning_status":"draft","note":"ਸਾਵਜ ਤਾੜਤਾ: read as 'striking the wild beasts'; uncertain."},{"gurmukhi":"ਗਿਰਤ ਧਰਨ ਸੁੰਦਰੀ ਨੈਕ ਜਿਹ ਦਿਸਿ ਫਿਰਿ ਝਾਕਤ।","roman":"Girat dharan sundree naik jih disi phiri jhaakat |","meaning_en":"\"beautiful women fall to the ground whichever way he turns his glance a little;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਮਦਨ ਮੋਹ ਰਹਤ ਮਨੁਛ ਦੇਖਿ ਛਬਿ ਲਾਜਤ।","roman":"Madan moh rahat manuchh dekhi chhabi laajat |","meaning_en":"\"even Madan is held enchanted; men, seeing his beauty, are ashamed;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਉਪਜਤ ਹੀਯ ਹੁਲਾਸ ਨਿਰਖਿ ਦੁਤਿ ਕਹ ਦੁਖ ਭਾਜਤ।","roman":"Upjat heey hulaas nirkhi duti kah dukh bhaajat |","meaning_en":"\"delight arises in the heart, and seeing his splendour sorrow flees;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਇਮਿ ਕਪਟ ਦੇਵ ਅਨਜੇਵ ਨ੍ਰਿਪੁ ਜਿਦਿਨ ਝਟਕ ਦੈ ਧਾਇ ਹੈ।","roman":"Imi kapat dev anjev nripu jidin jhatak dai dhaai hai |","meaning_en":"\"such is Kapat (Deceit), the unconquerable king; on the day he springs to the charge,","page":892,"meaning_status":"draft","note":"ਕਪਟ: deceit; kept as a name. ਅਨਜੇਵ: read as 'unconquerable'; uncertain."},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸਾਂਤਿ ਸੁਨੇਹੋ ਨ੍ਰਿਪਤਿ ਸੁ ਅਉਰ ਕਵਨ ਸਮੁਹਾਇ ਹੈ। ੧੯੦।","roman":"Binu ek saanti suneho nripti su aur kavan samuhaai hai | 190 |","meaning_en":"\"listen, O king, apart from Shanti alone, who else will face him?","page":892,"meaning_status":"draft"}]},{"type":"verse","number":[191],"number_text":"੧੯੧।","page":892,"lines":[{"gurmukhi":"ਚਖਨ ਚਾਰੁ ਚੰਚਲ ਪ੍ਰਭਾਵ ਖੰਜਨ ਲਖਿ ਲਾਜਤ।","roman":"Chakhan chaaru chanchal prabhaav khanjan lakhi laajat |","meaning_en":"\"His eyes, lovely and restless, put the wagtail to shame;","page":892,"meaning_status":"draft","note":"ਖੰਜਨ: the wagtail, a bird to which restless eyes are compared."},{"gurmukhi":"ਗਾਵਤ ਰਾਗ ਬਸੰਤ ਬੇਣ ਬੀਨਾ ਧੁਨਿ ਬਾਜਤ।","roman":"Gaavat raag basant ben beenaa dhuni baajat |","meaning_en":"\"he sings Raag Basant; flutes and the sound of the vina play;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਧਧਕਤ ਧ੍ਰਿਕਟ ਮ੍ਰਿਦੰਗ ਝਾਂਝ ਝਾਲਰ ਸੁਭ ਸੋਹਤ।","roman":"Dhadhkat dhrikat mridang jhaanjh jhaalar subh sohat |","meaning_en":"\"the mridang throbs, cymbals and bells look fine;","page":892,"meaning_status":"draft","note":"ਧਧਕਤ ਧ੍ਰਿਕਟ: sound-words of the drum."},{"gurmukhi":"ਖਗ ਮ੍ਰਿਗ ਜਛ ਭੁਜੰਗ ਅਸਰ ਸੁਰ ਨਰ ਮਨ ਮੋਹਤ।","roman":"Khag mrig jachh bhujang asar sur nar man mohat |","meaning_en":"\"he enchants the minds of birds, beasts, Yakshas, serpents, demons, gods and men;","page":892,"meaning_status":"draft"},{"gurmukhi":"ਅਸ ਲੋਭ ਨਾਮ ਜੋਧਾ ਬਡੋ ਜਿਦਿਨ ਜੁਧ ਕਹ ਜੁਟਿ ਹੈ।","roman":"As lobh naam jodhaa bado jidin judh kah juti hai |","meaning_en":"\"such is the great warrior named Lobh (Greed); on the day he joins battle,","page":892,"meaning_status":"draft","note":"ਲੋਭ: greed; kept as a name."},{"gurmukhi":"ਜਸ ਪਵਨ ਬੇਗ ਤੇ ਮੇਘ ਗਣ ਸੁ ਅਸ ਤਵ ਸਬ ਦਲ ਫੁਟਿ ਹੈ। ੧੯੧।","roman":"Jas pavan beg te megh gan su as tav sab dal phuti hai | 191 |","meaning_en":"\"as hosts of clouds are scattered by the speed of the wind, so will all your army scatter.","page":892,"meaning_status":"draft"}]},{"type":"verse","number":[192],"number_text":"੧੯੨।","page":893,"lines":[{"gurmukhi":"ਧੁਜ ਪ੍ਰਮਾਣ ਬੀਜੁਰੀ ਭੁਜਾ ਭਾਰੀ ਜਿਹ ਰਾਜਤ।","roman":"Dhuj pramaan beejuree bhujaa bhaaree jih raajat |","meaning_en":"\"His banner is like lightning; his great arms look splendid;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਚੰਚਲ ਰਥ ਚਲਤ ਨਿਰਖ ਸੁਰ ਨਰ ਮੁਨਿ ਭਾਜਤ।","roman":"Ati chanchal rath chalat nirakh sur nar muni bhaajat |","meaning_en":"\"his chariot moves very swiftly; seeing it gods, men and sages flee;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਅਧਿਕ ਰੂਪ ਅਮਿਤੋਜ ਅਮਿਟ ਜੋਧਾ ਰਣ ਦੁਹ ਕਰ।","roman":"Adhik roop amitoj amit jodhaa ran duh kar |","meaning_en":"\"of great beauty and boundless might, an ineffaceable warrior, (a weapon) in both hands in battle;","page":893,"meaning_status":"draft","note":"ਰਣ ਦੁਹ ਕਰ: read as 'fighting with both hands'; uncertain."},{"gurmukhi":"ਅਤਿ ਪ੍ਰਤਾਪ ਬਲਵੰਤ ਲਗਤ ਸਤ੍ਰਨ ਕਹ ਰਿਪੁ ਹਰ।","roman":"Ati prataap balvant lagat satran kah ripu har |","meaning_en":"\"of great glory and strength, he seems to enemies their destroyer;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਅਸ ਮੋਹ ਨਾਮ ਜੋਧਾ ਜਸ ਜਿਦਿਨ ਜੁਧ ਕਹ ਜੁਟਿ ਹੈ।","roman":"As moh naam jodhaa jas jidin judh kah juti hai |","meaning_en":"\"such is the warrior named Moh (Attachment); on the day he joins battle,","page":893,"meaning_status":"draft","note":"ਮੋਹ: attachment, infatuation; kept as a name."},{"gurmukhi":"ਬਿਨ ਇਕ ਬਿਚਾਰ ਅਬਿਚਾਰ ਨ੍ਰਿਪ ਅਉਰ ਸਕਲ ਦਲ ਫੁਟਿ ਹੈ। ੧੯੨।","roman":"Bin ik bichaar abichaar nrip aur sakal dal phuti hai | 192 |","meaning_en":"\"apart from Bichar (Reflection) alone, O king Abichar, all the rest of the army will scatter.","page":893,"meaning_status":"draft","note":"ਬਿਚਾਰ: reflection, right thinking; kept as a name. ਅਬਿਚਾਰ ਨ੍ਰਿਪ: read as 'O thoughtless king' or the name Abichar. Uncertain."}]},{"type":"verse","number":[193],"number_text":"੧੯੩।","page":893,"lines":[{"gurmukhi":"ਪਵਨ ਬੇਗ ਰਥ ਚਲਤ ਗਵਨ ਲਖਿ ਮੋਹਿਤ ਨਾਗਰ।","roman":"Pavan beg rath chalat gavan lakhi mohit naagar |","meaning_en":"\"His chariot moves at the speed of the wind; seeing it go, the townsmen are enchanted;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪ੍ਰਤਾਪ ਅਮਿਤੋਜ ਅਜੈ ਪ੍ਰਤਮਾਨ ਪ੍ਰਭਾਧਰ।","roman":"Ati prataap amitoj ajai pratmaan prabhaadhar |","meaning_en":"\"of great glory, boundless might, unconquerable, an image full of splendour;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਬਲਿਸਟ ਅਧਿਸਟ ਸਕਲ ਸੈਨਾ ਕਹੁ ਜਾਨਹੁ।","roman":"Ati balisat adhisat sakal sainaa kahu jaanhu |","meaning_en":"\"know him to be very strong, the commander of the whole army;","page":893,"meaning_status":"draft","note":"ਅਧਿਸਟ: read as 'chief, commander'."},{"gurmukhi":"ਕ੍ਰੋਧ ਨਾਮ ਬਢਿਯਾਛ ਬਡੋ ਜੋਧਾ ਜੀਅ ਮਾਨਹੁ।","roman":"Krodh naam badhiyaachh bado jodhaa jeea maanhu |","meaning_en":"\"consider in your heart the great wide-eyed warrior named Krodh (Anger);","page":893,"meaning_status":"draft","note":"ਕ੍ਰੋਧ: anger; kept as a name. ਬਢਿਯਾਛ: read as 'large-eyed'; uncertain."},{"gurmukhi":"ਧਰਿ ਅੰਗਿ ਕਵਚ ਧਰ ਪਨਚ ਕਰਿ ਜਿਦਿਨ ਤੁਰੰਗ ਮਟਕ ਹੈ।","roman":"Dhari angi kavach dhar panach kari jidin turang matak hai |","meaning_en":"\"wearing armour on his body and holding the bowstring in his hand, on the day he makes his horse prance,","page":893,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਏਕ ਸਾਂਤਿ ਸੁਨ ਸਤਿ ਨ੍ਰਿਪ ਸੁ ਅਉਰ ਨ ਕੋਊ ਹਟਕਿ ਹੈ। ੧੯੩।","roman":"Binu ek saanti sun sati nrip su aur na ko'oo hatki hai | 193 |","meaning_en":"\"listen, O true king, apart from Shanti alone, no one else will hold him back.","page":893,"meaning_status":"draft"}]},{"type":"verse","number":[194],"number_text":"੧੯੪।","page":893,"lines":[{"gurmukhi":"ਗਲਿਤ ਦੁਰਦ ਮਦਿ ਚੜ੍ਯੋ ਕਢਿ ਕਰਵਾਰ ਭਯੰਕਰ।","roman":"Galit durad madi charyo kadhi karvaar bhayankar |","meaning_en":"\"He mounts a rutting elephant, drawing his terrible sword;","page":893,"meaning_status":"draft","note":"ਦੁਰਦ: elephant."},{"gurmukhi":"ਸ੍ਯਾਮ ਬਰਣ ਆਭਰਣ ਖਚਿਤ ਸਬ ਨੀਲ ਮਣਿਣ ਬਰ।","roman":"Syaam baran aabhran khachit sab neel manin bar |","meaning_en":"\"his ornaments are dark in colour, all set with fine sapphires;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਵਰਨ ਕਿੰਕਣੀ ਜਾਲ ਬਧੇ ਬਾਨੈਤ ਗਜੋਤਮ।","roman":"Svaran kinknee jaal badhe baanait gajotam |","meaning_en":"\"the excellent elephant has nets of gold bells tied on it, and it is fit for archers;","page":893,"meaning_status":"draft","note":"ਬਾਨੈਤ: archer, or well-equipped; uncertain."},{"gurmukhi":"ਅਤਿ ਪ੍ਰਭਾਵ ਜੁਤਿ ਬੀਰ ਸਿਧ ਸਾਵੰਤ ਨਰੋਤਮ।","roman":"Ati prabhaav juti beer sidh saavant narotam |","meaning_en":"\"a hero of great power, a perfect warrior, the best of men;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਛਬਿ ਹੰਕਾਰ ਨਾਮਾ ਸੁਭਟ ਅਤਿ ਬਲਿਸਟ ਤਿਹ ਮਾਨੀਐ।","roman":"Ih chhabi hankaar naamaa subhat ati balisat tih maaneeai |","meaning_en":"\"such is the beauty of the warrior named Hankar (Ego); consider him very strong;","page":893,"meaning_status":"draft","note":"ਹੰਕਾਰ: ego, egotism; kept as a name."},{"gurmukhi":"ਜਿਹ ਜਗਤ ਜੀਵ ਜੀਤੇ ਸਬੈ ਆਪ ਅਜੀਤ ਤਿਹ ਜਾਨੀਐ। ੧੯੪।","roman":"Jih jagat jeev jeete sabai aap ajeet tih jaaneeai | 194 |","meaning_en":"\"he who has conquered all the beings of the world; know him to be himself unconquered.","page":893,"meaning_status":"draft"}]},{"type":"verse","number":[195],"number_text":"੧੯੫।","page":893,"lines":[{"gurmukhi":"ਸੇਤ ਹਸਤ ਆਰੂੜ ਢੁਰਤ ਚਹੂੰ ਓਰਿ ਚਵਰ ਬਰ।","roman":"Set hasat aaroor dhurat chahoon ori chavar bar |","meaning_en":"\"Mounted on a white elephant, with fine whisks waving on all four sides,","page":893,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਵਰਣ ਕਿੰਕਣੀ ਬਧੇ ਨਿਰਖਿ ਮੋਹਤ ਨਾਰੀ ਨਰ।","roman":"Svaran kinknee badhe nirkhi mohat naaree nar |","meaning_en":"\"with gold bells tied on; seeing him, women and men are enchanted;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਸੁਭ੍ਰ ਸੈਹਥੀ ਪਾਣਿ ਪ੍ਰਭਾ ਕਰ ਮੈ ਅਸ ਧਾਵਤ।","roman":"Subhr saihthee paani prabhaa kar mai as dhaavat |","meaning_en":"\"he charges with a bright lance in his hand, giving off such splendour,","page":893,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖਿ ਦਿਪਤਿ ਦਾਮਨੀ ਪ੍ਰਭਾ ਹੀਯਰੇ ਪਛੁਤਾਵਤ।","roman":"Nirkhi dipti daamnee prabhaa heeyre pachhutaavat |","meaning_en":"\"that seeing its brilliance, the lightning repents in its heart (of its own glow);","page":893,"meaning_status":"draft"},{"gurmukhi":"ਅਸ ਦ੍ਰੋਹ ਨਾਮ ਜੋਧਾ ਬਡੋ ਅਤਿ ਪ੍ਰਭਾਵ ਤਿਹ ਜਾਨੀਐ।","roman":"As droh naam jodhaa bado ati prabhaav tih jaaneeai |","meaning_en":"\"such is the great warrior named Droh (Treachery); know his power to be very great;","page":893,"meaning_status":"draft","note":"ਦ੍ਰੋਹ: treachery, malice; kept as a name."},{"gurmukhi":"ਜਲ ਥਲ ਬਿਦੇਸ ਦੇਸਨ ਨ੍ਰਿਪਤਿ ਆਨ ਜਵਨ ਕੀ ਮਾਨੀਐ। ੧੯੫।","roman":"Jal thal bides desan nripti aan javan kee maaneeai | 195 |","meaning_en":"\"in water and on land, in foreign lands and his own, the kings submit to his authority.","page":893,"meaning_status":"draft","note":"ਆਨ: authority, command."}]},{"type":"verse","number":[196],"number_text":"੧੯੬।","page":893,"lines":[{"gurmukhi":"ਤਬਲ ਬਾਜ ਘੁੰਘਰਾਰ ਸੀਸ ਕਲਗੀ ਜਿਹਾ ਸੋਹਤ।","roman":"Tabal baaj ghunghraar sees kalgee jihaa sohat |","meaning_en":"\"His drums play, his horse has curly mane, a plume shines on his head;","page":893,"meaning_status":"draft","note":"ਘੁੰਘਰਾਰ: read as 'curly' or 'with ankle-bells'; uncertain."},{"gurmukhi":"ਦ੍ਵੈ ਕ੍ਰਿਪਾਣ ਗਜਗਾਹ ਨਿਰਖਿ ਨਾਰੀ ਨਰ ਮੋਹਤ।","roman":"Dvai kripaan gajgaah nirkhi naaree nar mohat |","meaning_en":"\"two swords and elephant-trappings; seeing him, women and men are enchanted;","page":893,"flags":[{"code":"0x50","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਗਜਗਾਹ: ornament or trappings; uncertain."},{"gurmukhi":"ਅਮਿਤ ਰੂਪ ਅਮਿਤੋਜ ਬਿਕਟ ਬਾਨੈਤ ਅਮਿਟ ਭਟ।","roman":"Amit roop amitoj bikat baanait amit bhat |","meaning_en":"\"of boundless form and might, a fierce archer, an ineffaceable warrior;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਸੁਬਾਹ ਅਤਿ ਸੂਰ ਅਜੈ ਅਨਭਿਦ ਸੁ ਅਨਕਟ।","roman":"Ati subaah ati soor ajai anbhid su ankat |","meaning_en":"\"very strong-armed, very brave, unconquerable, impenetrable and uncuttable;","page":893,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਭਾਤਿ ਭਰਮ ਅਨਭਿਦ ਭਟ ਜਿਦਿਨ ਕ੍ਰੁਧ ਜੀਯ ਧਾਰ ਹੈ।","roman":"Ih bhaati bharam anbhid bhat jidin krudh jeey dhaar hai |","meaning_en":"\"such is Bharam (Delusion), the impenetrable warrior; on the day he holds anger in his heart,","page":893,"meaning_status":"draft","note":"Bharam (Delusion) was also named earlier as Madan's fourth son."},{"gurmukhi":"ਬਿਨ ਇਕ ਬਿਚਾਰ ਅਬਚਿਾਰ ਨ੍ਰਿਪ ਸਸੁ ਅਉਰ ਨ ਆਨਿ ਉਬਾਰਿ ਹੈ। ੧੯੬।","roman":"Bin ik bichaar abchaar nrip sasu aur na aani ubaari hai | 196 |","meaning_en":"\"apart from Bichar alone, O king Abichar, no other will come and save (you).","page":893,"meaning_status":"draft","note":"ਅਬਚਿਾਰ: printed so; read as 'Abichar'. ਸਸੁ: unclear. Uncertain."}]},{"type":"verse","number":[197],"number_text":"੧੯੭।","page":894,"lines":[{"gurmukhi":"ਲਾਲ ਮਾਲ ਸੁਭ ਬਧੈ ਨਗਨ ਸਰਪੇਚਿ ਖਚਿਤ ਸਿਰ।","roman":"Laal maal subh badhai nagan sarpechi khachit sir |","meaning_en":"\"A fine garland of rubies is tied on him, and his head-ornament is set with gems;","page":894,"meaning_status":"draft","note":"ਸਰਪੇਚਿ: turban ornament (Persian sarpech)."},{"gurmukhi":"ਅਤਿ ਬਲਿਸਟ ਅਨਿਭੇਦ ਅਜੈ ਸਾਵੰਤ ਭਟਾਂਬਰ।","roman":"Ati balisat anibhed ajai saavant bhataanbar |","meaning_en":"\"very strong, impenetrable, unconquerable, the chief of warriors;","page":894,"meaning_status":"draft","note":"ਸਾਵੰਤ ਭਟਾਂਬਰ: read as 'a hero, best of warriors'; uncertain."},{"gurmukhi":"ਕਟਿ ਕ੍ਰਿਪਾਣ ਸੈਹਥੀ ਤਜਤ ਧਾਰਾ ਬਾਣਨ ਕਰ।","roman":"Kati kripaan saihthee tajat dhaaraa baanan kar |","meaning_en":"\"with sword at his waist and lance, he looses streams of arrows from his hand;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖਤ ਹਸਤ ਪ੍ਰਭਾਵ ਲਜਤ ਤੜਿਤਾ ਧਾਰਾਧਰ।","roman":"Dekhat hasat prabhaav lajat taritaa dhaaraadhar |","meaning_en":"\"seeing the power of his hand, the lightning and the clouds are ashamed;","page":894,"meaning_status":"draft","note":"ਧਾਰਾਧਰ: cloud."},{"gurmukhi":"ਅਸ ਬ੍ਰਹਮ ਦੋਖ ਅਨਮੋਖ ਭਟ ਅਕਟ ਅਜੈ ਤਿਹ ਜਾਨੀਐ।","roman":"As braham dokh anmokh bhat akat ajai tih jaaneeai |","meaning_en":"\"such is the warrior Brahm Dokh (Offence against Brahmins), not to be escaped; know him uncuttable and unconquerable;","page":894,"meaning_status":"draft","note":"ਬ੍ਰਹਮ ਦੋਖ: sin against Brahmins (or against God); kept as a name. ਅਨਮੋਖ: 'without release'. Uncertain."},{"gurmukhi":"ਅਰਿ ਦਵਨ ਅਜੈ ਆਨੰਦ ਕਰ ਨ੍ਰਿਪ ਅਬਿਬੇਕ ਕੋ ਮਾਨੀਐ। ੧੯੭।","roman":"Ari davan ajai aanand kar nrip abibek ko maaneeai | 197 |","meaning_en":"\"subduer of enemies, unconquerable, a giver of joy to King Abibek, consider him so.","page":894,"meaning_status":"draft"}]},{"type":"verse","number":[198],"number_text":"੧੯੮।","page":894,"lines":[{"gurmukhi":"ਅਸਿਤ ਬਸਤ੍ਰ ਅਰੁ ਅਸਿਤ ਗਾਤ ਅਮਿਤੋਜ ਰਣਾਚਲ।","roman":"Asit basatr aru asit gaat amitoj ranaachal |","meaning_en":"\"Dark clothes and a dark body, of boundless might, steady as a mountain in battle;","page":894,"meaning_status":"draft","note":"ਰਣਾਚਲ: 'a mountain in battle'."},{"gurmukhi":"ਅਤਿ ਪ੍ਰਚੰਡ ਅਤਿ ਬੀਰ ਬੀਰ ਜੀਤੇ ਜਿਨ ਜਲ ਥਲ।","roman":"Ati prachand ati beer beer jeete jin jal thal |","meaning_en":"\"very fierce, very brave, a hero who has conquered water and land;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਅਕਟ ਅਜੈ ਅਨਭੇਦ ਅਮਿਟ ਅਨਰਥਿ ਨਾਮ ਤਿਹੈ।","roman":"Akat ajai anbhed amit anarthi naam tihai |","meaning_en":"\"uncuttable, unconquerable, impenetrable, ineffaceable, Anarth (Calamity) is his name;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਪ੍ਰਮਾਥ ਅਰਿ ਮਥਨ ਸਤ੍ਰੁ ਸੋਖਨ ਹੈ ਬ੍ਰਿਦ ਜਿਹ।","roman":"Ati pramaath ari mathan satru sokhan hai brid jih |","meaning_en":"\"very crushing, churner of foes, drier-up of enemies, such is his title;","page":894,"meaning_status":"draft","note":"ਬ੍ਰਿਦ: title, epithet (birad)."},{"gurmukhi":"ਦੁਰ ਧਰਖ ਸੂਰ ਅਨਭੇਦ ਭਟ ਅਤਿ ਪ੍ਰਤਾਪ ਤਿਹ ਜਾਨੀਐ।","roman":"Dur dharakh soor anbhed bhat ati prataap tih jaaneeai |","meaning_en":"\"an invincible hero, an impenetrable warrior; know his glory to be very great;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਅਨਜੈ ਅਨੰਦ ਦਾਤਾ ਅਪਨ ਅਤਿ ਸੁਬਾਹ ਤਿਹ ਮਾਨੀਐ। ੧੯੮।","roman":"Anjai anand daataa apan ati subaah tih maaneeai | 198 |","meaning_en":"\"unconquerable, a giver of joy to his own (king), consider him very strong-armed.","page":894,"meaning_status":"draft"}]},{"type":"verse","number":[199],"number_text":"੧੯੯।","page":894,"lines":[{"gurmukhi":"ਮੋਰ ਬਰਣ ਰਥ ਬਾਜ ਮੋਰ ਹੀ ਬਰਣ ਪਰਮ ਜਿਹ।","roman":"Mor baran rath baaj mor hee baran param jih |","meaning_en":"\"His chariot and horses are the colour of the peacock, and he himself is supremely peacock-coloured;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਦੁਰ ਧਰਖ ਸਤ੍ਰੁ ਲਖ ਕਰ ਕੰਪਤ ਤਿਹ।","roman":"Amit tej dur dharakh satru lakh kar kanpat tih |","meaning_en":"\"of boundless radiance, hard to withstand; seeing him, enemies tremble;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਟ ਬੀਰ ਆਜਾਨ ਬਾਹੁ ਅਲੋਕ ਰੂਪ ਗਨ।","roman":"Amit beer aajaan baahu alok roop gan |","meaning_en":"\"an ineffaceable hero, with arms reaching to his knees, reckoned of a radiant form;","page":894,"meaning_status":"draft","note":"ਆਜਾਨ ਬਾਹੁ: arms reaching to the knees, a sign of a great man."},{"gurmukhi":"ਮਤਸ ਕੇਤੁ ਲਖਿ ਜਾਹਿ ਹ੍ਰਿਦੈ ਲਾਜਤ ਹੈ ਦੁਤਿ ਮਨਿ।","roman":"Matas ketu lakhi jaahi hridai laajat hai duti mani |","meaning_en":"\"seeing him, the fish-bannered one (Kama) is ashamed in his heart of his own splendour;","page":894,"meaning_status":"draft","note":"ਮਤਸ ਕੇਤੁ: 'fish-bannered', Kama."},{"gurmukhi":"ਅਸ ਝੂਠ ਰੂਠਿ ਜਿਦਿਨ ਨ੍ਰਿਪਤਿ ਰਣਹਿ ਤੁਰੰਗ ਉਥਕਿ ਹੈ।","roman":"As jhooth roothi jidin nripti ranhi turang uthki hai |","meaning_en":"\"such is Jhooth (Falsehood); on the day, O king, he makes his horse leap in anger in the battle,","page":894,"meaning_status":"draft","note":"ਝੂਠ: falsehood; kept as a name. ਰੂਠਿ: 'angered'."},{"gurmukhi":"ਬਿਨੁ ਇਕ ਸਤਿ ਸੁਣ ਸਤਿ ਨ੍ਰਿਪ ਸੁ ਅਉਰ ਨ ਆਨਿ ਹਟਕਿ ਹੈ। ੧੯੯।","roman":"Binu ik sati sun sati nrip su aur na aani hatki hai | 199 |","meaning_en":"\"listen, O true king, apart from Sat (Truth) alone, no other will come and hold him back.","page":894,"meaning_status":"draft","note":"ਸਤਿ: truth; kept as a name."}]},{"type":"verse","number":[200],"number_text":"੨੦੦।","page":894,"lines":[{"gurmukhi":"ਰਥ ਤੁਰੰਗ ਸਿਤ ਅਸਿਤ ਅਸਿਤ ਸਿਤ ਧੁਜਾ ਬਿਰਾਜਤ।","roman":"Rath turang sit asit asit sit dhujaa biraajat |","meaning_en":"\"His chariot and horses are white and dark; a dark and white banner shines;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਤ ਸੇਤਹਿ ਬਸਤ੍ਰ ਨਿਰਖਿ ਸੁਰ ਨਰ ਮੁਨਿ ਲਾਜਤ।","roman":"Asit sethi basatr nirkhi sur nar muni laajat |","meaning_en":"\"dark and white are his clothes; seeing them, gods, men and sages are ashamed;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਅਸਿਤ ਸੇਤ ਸਾਰਥੀ ਅਸਿਤ ਸੇਤ ਛਕਿਓ ਰਥਾਂਬਰ।","roman":"Asit set saarthee asit set chhakio rathaanbar |","meaning_en":"\"his charioteer is dark and white; dark and white is his splendid chariot-canopy;","page":894,"meaning_status":"draft","note":"ਰਥਾਂਬਰ: read as 'chariot-covering'; uncertain."},{"gurmukhi":"ਸੁਵਰਣ ਕਿੰਕਨੀ ਕੇਸ ਜਨੁਕ ਦੂਸਰੇ ਦੇਵੇਸੁਰ।","roman":"Suvran kinknee kes januk doosre devesur |","meaning_en":"\"with gold bells on the hair, as if he were a second lord of the gods (Indra);","page":894,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਛਬਿ ਪ੍ਰਭਾਵ ਮਿਥਿਆ ਸੁਭਟ ਅਤਿ ਬਲਿਸਟ ਤਿਹ ਕਹ ਕਹ੍ਯੋ।","roman":"Ih chhabi prabhaav mithiaa subhat ati balisat tih kah kahyo |","meaning_en":"\"such is the beauty and power of the warrior Mithya (Untruth); he is said to be very strong;","page":894,"meaning_status":"draft","note":"ਮਿਥਿਆ: untruth, illusion; kept as a name."},{"gurmukhi":"ਜਿਹ ਜਗਤ ਜੀਵ ਜੀਤੇ ਸਬੈ ਨਹਿ ਅਜੀਤ ਨਰ ਕੋ ਰਹ੍ਯੋ। ੨੦੦।","roman":"Jih jagat jeev jeete sabai nahi ajeet nar ko rahyo | 200 |","meaning_en":"\"he has conquered all the beings of the world; no man has remained unconquered by him.","page":894,"meaning_status":"draft"}]},{"type":"verse","number":[201],"number_text":"੨੦੧।","page":894,"lines":[{"gurmukhi":"ਚਕ੍ਰ ਬਕ੍ਰ ਕਰ ਧਰੇ ਚਾਰੁ ਬਾਗਾ ਤਨਿ ਧਾਰੇ।","roman":"Chakr bakr kar dhare chaaru baagaa tani dhaare |","meaning_en":"\"He holds a curved discus in his hand and wears a fine robe on his body;","page":894,"meaning_status":"draft","note":"ਬਾਗਾ: a long robe."},{"gurmukhi":"ਆਨਨ ਖਾਤ ਤੰਬੋਲ ਗੰਧਿ ਉਤਮ ਬਿਸਥਾਰੇ।","roman":"Aanan khaat tanbol gandhi utam bisthaare |","meaning_en":"\"he chews betel in his mouth, and spreads fine perfume;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਚਵਰੁ ਚਾਰੁ ਚਹੂੰ ਓਰਿ ਢੁਰਤ ਸੁੰਦਰ ਛਬਿ ਪਾਵਤ।","roman":"Chavru chaaru chahoon ori dhurat sundar chhabi paavat |","meaning_en":"\"fine whisks wave on all four sides, and he looks beautiful;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖਤ ਨੈਨ ਬਸੰਤ ਪ੍ਰਭਾ ਤਾਕਹ ਸਿਰ ਨ੍ਯਾਵਤ।","roman":"Nirkhat nain basant prabhaa taakah sir nyaavat |","meaning_en":"\"seeing his splendour with their eyes, Spring bows its head to him;","page":894,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਧਿ ਸੁਬਾਹੁ ਚਿੰਤਾ ਸੁਭਟ ਅਤਿ ਦੁਰ ਧਰਖ ਬਖਾਨੀਐ।","roman":"Ih bidhi subaahu chintaa subhat ati dur dharakh bakhaaneeai |","meaning_en":"\"such is the strong-armed warrior Chinta (Anxiety), said to be very hard to withstand;","page":894,"meaning_status":"draft","note":"ਚਿੰਤਾ: worry, anxiety; kept as a name."},{"gurmukhi":"ਅਨਭੰਗ ਗਾਤ ਅਨਭੈ ਸੁਭਟ ਅਤਿ ਪ੍ਰਚੰਡ ਤਿਹ ਮਾਨੀਐ। ੨੦੧।","roman":"Anbhang gaat anbhai subhat ati prachand tih maaneeai | 201 |","meaning_en":"\"a warrior unbroken in body, fearless; consider him very fierce.","page":894,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Rual metre.","page":895,"meaning_status":"draft"},{"type":"verse","number":[202],"number_text":"੨੦੨।","page":895,"lines":[{"gurmukhi":"ਲਾਲ ਹੀਰਨ ਕੇ ਧਰੇ ਜਿਹ ਸੀਸ ਪੈ ਬਹੁ ਹਾਰ।","roman":"Laal heeran ke dhare jih sees pai bahu haar |","meaning_en":"\"He who wears many garlands of rubies and diamonds on his head,","page":895,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਵਰਣੀ ਕਿੰਕਣਿ ਸੌ ਛਕ ਗਜ ਰਾਜ ਪਬਾਕਾਰ।","roman":"Svarnee kinkni sau chhak gaj raaj pabaakaar |","meaning_en":"\"(riding) a great elephant like a mountain, decked with gold bells,","page":895,"meaning_status":"draft","note":"ਪਬਾਕਾਰ: 'mountain-shaped'."},{"gurmukhi":"ਦੁਰਦ ਰੂੜ ਦਰਿਦ੍ਰ ਨਾਮ ਸੁ ਬੀਰ ਹੈ ਸੁਨਿ ਭੂਪ।","roman":"Durad roor daridr naam su beer hai suni bhoop |","meaning_en":"\"mounted on the elephant, that hero is named Daridra (Poverty); listen, O king;","page":895,"meaning_status":"draft","note":"ਦਰਿਦ੍ਰ: poverty, wretchedness; kept as a name."},{"gurmukhi":"ਕਉਨ ਤਾ ਤੇ ਜੀਤ ਹੈ ਰਣ ਆਨਿ ਰਾਜ ਸਰੂਪ। ੨੦੨।","roman":"Kaun taa te jeet hai ran aani raaj saroop | 202 |","meaning_en":"\"who can come and win against him in battle, O you of kingly form?","page":895,"meaning_status":"draft"}]},{"type":"verse","number":[203],"number_text":"੨੦੩।","page":895,"lines":[{"gurmukhi":"ਜਰਕਸੀ ਕੇ ਬਸਤ੍ਰ ਹੈ ਅਰੁ ਪਰਮ ਬਾਜਾਰੂੜ।","roman":"Jaraksee ke basatr hai aru param baajaaroor |","meaning_en":"\"His clothes are embroidered with gold, and he rides a superb horse;","page":895,"meaning_status":"draft"},{"gurmukhi":"ਪਰਮ ਰੂਪ ਪਵਿਤਰ ਗਾਤ ਅਛਿਜ ਰੂਪ ਅਗੂੜ।","roman":"Param roop pavitar gaat achhij roop agoor |","meaning_en":"\"of supreme beauty, pure of body, of indestructible form, not hidden;","page":895,"meaning_status":"draft","note":"ਅਗੂੜ: read as 'manifest, not hidden'; uncertain."},{"gurmukhi":"ਛਤ੍ਰ ਧਰਮ ਧਰੇ ਮਹਾ ਭਟ ਬੰਸ ਕੀ ਜਿਹ ਲਾਜ।","roman":"Chhatr dharam dhare mahaa bhat bans kee jih laaj |","meaning_en":"\"a great warrior who keeps the dharma of the Kshatriya, the honour of his lineage;","page":895,"meaning_status":"draft"},{"gurmukhi":"ਸੰਕ ਨਾਮਾ ਸੂਰ ਸੋ ਸਬ ਸੂਰ ਹੈ ਸਿਰਤਾਜ। ੨੦੩।","roman":"Sank naamaa soor so sab soor hai sirtaaj | 203 |","meaning_en":"\"that hero is named Sank (Doubt), the crown of all heroes.","page":895,"meaning_status":"draft","note":"ਸੰਕ: doubt, fear; kept as a name."}]},{"type":"verse","number":[204],"number_text":"੨੦੪।","page":895,"lines":[{"gurmukhi":"ਪਿੰਗ ਬਾਜ ਨਹੇ ਰਥੈ ਸਹਿ ਅਡਿਗ ਬੀਰ ਅਖੰਡ।","roman":"Ping baaj nahe rathai sahi adig beer akhand |","meaning_en":"\"Tawny horses are yoked to his chariot; with them is the unshakeable, unbroken hero;","page":895,"meaning_status":"draft","note":"ਨਹੇ: yoked."},{"gurmukhi":"ਅੰਤ ਰੂਪ ਧਰੇ ਮਨੋ ਅਛਿਜ ਗਾਤ ਪ੍ਰਚੰਡ।","roman":"Ant roop dhare mano achhij gaat prachand |","meaning_en":"\"as if he had taken the form of Death, fierce, with an indestructible body;","page":895,"meaning_status":"draft","note":"ਅੰਤ: read as 'the end, Death'; uncertain."},{"gurmukhi":"ਨਾਮ ਸੂਰ ਅਸੋਭ ਤਾ ਕਹ ਜਾਨਹੀ ਸਭ ਲੋਕ।","roman":"Naam soor asobh taa kah jaanhee sabh lok |","meaning_en":"\"the hero's name is Asobh (Unseemliness); all the worlds know him;","page":895,"meaning_status":"draft","note":"ਅਸੋਭ: unseemliness, disgrace; kept as a name."},{"gurmukhi":"ਕਉਨ ਰਾਵ ਬਿਬੇਕ ਹੈ ਜੁ ਨ ਮਾਨਿ ਹੈ ਇਹ ਸੋਕ। ੨੦੪।","roman":"Kaun raav bibek hai ju na maani hai ih sok | 204 |","meaning_en":"\"what is King Bibek, that he would not feel this grief?\"","page":895,"meaning_status":"draft","note":"Read as: even Bibek would be grieved before him. Uncertain."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":895,"meaning_status":"draft"},{"type":"verse","number":[205],"number_text":"੨੦੫।","page":895,"lines":[{"gurmukhi":"ਸਜੇ ਸ੍ਯਾਮ ਬਾਜੀ ਰਥੰ ਜਾਸੁ ਜਾਨੋ। ਮਹਾ ਜੰਗ ਜੋਧਾ ਅਜੈ ਤਾਸੁ ਮਾਨੋ।","roman":"Saje syaam baajee rathan jaasu jaano | mahaa jang jodhaa ajai taasu maano |","meaning_en":"\"Know him whose chariot is drawn by dark horses; consider him a great warrior, unconquerable in war;","page":895,"meaning_status":"draft"},{"gurmukhi":"ਅਸੰਤੁਸਟ ਨਾਮ ਮਹਾਬੀਰ ਸੋਹੈ। ਤਿਹੂੰ ਲੋਕ ਜਾ ਕੋ ਬਡੋ ਤ੍ਰਾਸ ਮੋਹੈ। ੨੦੫।","roman":"Asantusat naam mahaabeer sohai | tihoon lok jaa ko bado traas mohai | 205 |","meaning_en":"\"the great hero named Asantusht (Discontent) looks splendid; all three worlds are held in great dread of him.","page":895,"meaning_status":"draft","note":"ਅਸੰਤੁਸਟ: discontent; kept as a name."}]},{"type":"verse","number":[206],"number_text":"੨੦੬।","page":895,"lines":[{"gurmukhi":"ਚੜ੍ਯੋ ਤਤ ਤਾਜੀ ਸਿਰਾਜੀਤ ਸੋਭੈ। ਸਿਰੰ ਜੈਤ ਪਤ੍ਰੰ ਲਖੇ ਚੰਦ੍ਰ ਛੋਭੈ।","roman":"Charyo tat taajee siraajeet sobhai | siran jait patran lakhe chandr chhobhai |","meaning_en":"\"Mounted on a swift Arab horse of Shiraz he looks splendid; seeing the plume of victory on his head, the moon is troubled;","page":895,"meaning_status":"draft","note":"ਤਾਜੀ: Arab horse. ਸਿਰਾਜੀਤ: read as 'of Shiraz'; uncertain."},{"gurmukhi":"ਅਨਾਸ ਊਚ ਨਾਮਾ ਮਹਾ ਸੂਰ ਸੋਹੈ। ਬਡੋ ਛਤ੍ਰਧਾਰੀ ਧਰੈ ਛਤ੍ਰ ਜੋ ਹੈ। ੨੦੬।","roman":"Anaas ooch naamaa mahaa soor sohai | bado chhatradhaaree dharai chhatr jo hai | 206 |","meaning_en":"\"the great hero named Anas Uch (?) looks splendid, a great bearer of the canopy, who holds the royal canopy.","page":895,"meaning_status":"draft","note":"ਅਨਾਸ ਊਚ: unclear; perhaps 'Hopelessness' (anaas) or 'Haughtiness'. Uncertain."}]},{"type":"verse","number":[207],"number_text":"੨੦੭।","page":895,"lines":[{"gurmukhi":"ਰਥੰ ਸੇਤ ਬਾਜੀ ਸਿਰਾਜੀਤ ਸੋਹੈ। ਲਖੇ ਇੰਦ੍ਰ ਬਾਜੀ ਤਰੈ ਦ੍ਰਿਸਟ ਕੋ ਹੈ।","roman":"Rathan set baajee siraajeet sohai | lakhe indr baajee tarai drisat ko hai |","meaning_en":"\"His chariot with white horses of Shiraz looks splendid; seeing it, even Indra's horse falls below in view;","page":895,"meaning_status":"draft","note":"ਲਖੇ ਇੰਦ੍ਰ ਬਾਜੀ ਤਰੈ ਦ੍ਰਿਸਟ ਕੋ ਹੈ: read as 'Indra's horse seems inferior'; uncertain."},{"gurmukhi":"ਹਠੀ ਬਾਬਰੀ ਕੋ ਹਿੰਸਾ ਨਾਮ ਜਾਨੋ। ਮਹਾ ਜੰਗ ਜੋਧਾ ਅਜੈ ਲੋਕ ਮਾਨੋ। ੨੦੭।","roman":"Hathee baabree ko hinsaa naam jaano | mahaa jang jodhaa ajai lok maano | 207 |","meaning_en":"\"know the stubborn one with long hair as named Hinsa (Violence); people consider him a great warrior, unconquerable in war.","page":895,"meaning_status":"draft","note":"ਬਾਬਰੀ: long locks of hair. ਹਿੰਸਾ: violence; kept as a name."}]},{"type":"verse","number":[208],"number_text":"੨੦੮।","page":895,"lines":[{"gurmukhi":"ਸੁਭੰ ਸੰਦਲੀ ਬਾਜ ਰਾਜੀ ਸਿਰਾਜੀ। ਲਖੇ ਰੂਪ ਤਾ ਕੋ ਲਜੈ ਇੰਦ੍ਰ ਬਾਜੀ।","roman":"Subhan sandlee baaj raajee siraajee | lakhe roop taa ko lajai indr baajee |","meaning_en":"\"Fine sandal-coloured horses of Shiraz are lined up; seeing their beauty, Indra's horse is ashamed;","page":895,"meaning_status":"draft","note":"ਸੰਦਲੀ: sandal-coloured."},{"gurmukhi":"ਕੁਮੰਤੰ ਮਹਾ ਜੰਗ ਜੋਧਾ ਜੁਝਾਰੰ। ਜਲੰ ਵਾ ਥਲੰ ਜੇਣ ਜਿਤੇ ਬਰਿਆਰੰ। ੨੦੮।","roman":"Kumantan mahaa jang jodhaa jujhaaran | jalan vaa thalan jen jite bariaaran | 208 |","meaning_en":"\"Kumant (Evil Counsel) is a great warrior in war, a fighter, the mighty one who has conquered water and land.","page":895,"meaning_status":"draft","note":"ਕੁਮੰਤ: evil counsel; kept as a name."}]},{"type":"verse","number":[209],"number_text":"੨੦੯।","page":895,"lines":[{"gurmukhi":"ਚੜ੍ਯੋ ਬਾਜ ਤਾਜੀ ਕੋਪਤੰ ਸਰੂਪੰ। ਧਰੇ ਚਰਮ ਬਰਮੰ ਬਿਸਾਲੰ ਅਨੂਪੰ।","roman":"Charyo baaj taajee koptan saroopan | dhare charam barman bisaalan anoopan |","meaning_en":"\"Mounted on an Arab horse, of angry form, bearing a shield and armour, large and peerless;","page":895,"meaning_status":"draft"},{"gurmukhi":"ਧੁਜਾ ਬਧ ਸਿਧੰ ਅਲਜਾ ਜੁਝਾਰੰ। ਬਡੋ ਜੰਗ ਜੋਧਾ ਸੁ ਕ੍ਰੁਧੀ ਬਰਾਰੰ। ੨੦੯।","roman":"Dhujaa badh sidhan aljaa jujhaaran | bado jang jodhaa su krudhee baraaran | 209 |","meaning_en":"\"his banner tied, accomplished, is Alaja (Shamelessness) the fighter, a great warrior in war, wrathful and strong.","page":895,"meaning_status":"draft","note":"ਅਲਜਾ: shamelessness; kept as a name. ਬਰਾਰੰ: read as 'strong'; uncertain."}]},{"type":"verse","number":[210],"number_text":"੨੧੦।","page":896,"lines":[{"gurmukhi":"ਧਰੇ ਛੀਨ ਬਸਤ੍ਰੰ ਮਲੀਨੰ ਦਰਿਦ੍ਰੀ। ਧੁਜਾ ਫਾਟ ਬਸਤ੍ਰੰ ਸੁ ਧਾਰੇ ਉਪਦ੍ਰੀ।","roman":"Dhare chheen bastran maleenan daridree | dhujaa phaat bastran su dhaare updree |","meaning_en":"\"He wears worn, dirty clothes, wretched; a torn cloth for a banner, he is a troublemaker;","page":896,"meaning_status":"draft","note":"ਉਪਦ੍ਰੀ: one who makes trouble (upadrav)."},{"gurmukhi":"ਮਹਾ ਸੂਰ ਚੋਰੀ ਕਰੋਰੀ ਸਮਾਨੰ। ਲਸੈ ਤੇਜ ਐਸੋ ਲਜੈ ਦੇਖਿ ਸ੍ਵਾਨੰ। ੨੧੦।","roman":"Mahaa soor choree karoree samaanan | lasai tej aiso lajai dekhi svaanan | 210 |","meaning_en":"\"the great hero Chori (Theft), equal to millions; his radiance shines such that a dog, seeing it, is ashamed.","page":896,"meaning_status":"draft","note":"ਚੋਰੀ: theft; kept as a name."}]},{"type":"verse","number":[211],"number_text":"੨੧੧।","page":896,"lines":[{"gurmukhi":"ਫਟੇ ਬਸਤ੍ਰ ਸਰਬੰ ਸਬੈ ਅੰਗ ਧਾਰੇ। ਬਧੇ ਸੀਸ ਜਾਰੀ ਬੁਰੀ ਅਰਧ ਜਾਰੇ।","roman":"Phate basatr sarban sabai ang dhaare | badhe sees jaaree buree aradh jaare |","meaning_en":"\"Torn clothes are worn on all his limbs; on his head is tied an ugly, half-burnt net;","page":896,"meaning_status":"draft","note":"ਜਾਰੀ: read as 'net / mesh cloth'; uncertain."},{"gurmukhi":"ਚੜ੍ਯੋ ਭੀਮ ਭੈਸੰ ਮਹਾ ਭੀਮ ਰੂਪੰ। ਬਿਭੈਚਾਰ ਜੋਧਾ ਕਹੋ ਤਾਸ ਭੂਪੰ। ੨੧੧।","roman":"Charyo bheem bhaisan mahaa bheem roopan | bibhaichaar jodhaa kaho taas bhoopan | 211 |","meaning_en":"\"mounted on a terrible buffalo, of very terrible form, the warrior is called Bibhichar (Debauchery), O king.","page":896,"meaning_status":"draft","note":"ਬਿਭੈਚਾਰ: debauchery, adultery; kept as a name."}]},{"type":"verse","number":[212],"number_text":"੨੧੨।","page":896,"lines":[{"gurmukhi":"ਸਭੈ ਸਿਆਮ ਬਰਣੰ ਸਿਰੰ ਸੇਤ ਏਕੰ। ਨਹੇ ਗਰਧਪੰ ਸ੍ਯੰਦਨੇਕੰ ਅਨੇਕੰ।","roman":"Sabhai siaam barnan siran set ekan | nahe garadhpan syandnekan anekan |","meaning_en":"\"All dark in colour, with one white (spot) on his head, he has many chariots yoked with donkeys;","page":896,"meaning_status":"draft","note":"ਗਰਧਪੰ: donkeys. ਸ੍ਯੰਦਨ: chariot."},{"gurmukhi":"ਧੁਜਾ ਸ੍ਯਾਮ ਬਰਣੰ ਭੁਜੰ ਭੀਮ ਰੂਪੰ। ਸਰੰ ਸ੍ਰੋਣਿਤੰ ਏਕ ਅਛੇਕ ਕੂਪੰ। ੨੧੨।","roman":"Dhujaa syaam barnan bhujan bheem roopan | saran sronitan ek achhek koopan | 212 |","meaning_en":"\"a dark-coloured banner, arms of terrible form, (and) a pool of blood, one unfailing well.","page":896,"meaning_status":"draft","note":"ਸਰੰ ਸ੍ਰੋਣਿਤੰ ਏਕ ਅਛੇਕ ਕੂਪੰ: obscure; read as above. Uncertain."}]},{"type":"verse","number":[213],"number_text":"੨੧੩।","page":896,"lines":[{"gurmukhi":"ਮਹਾ ਜੋਧ ਦਾਰਿਦ੍ਰ ਨਾਮਾ ਜੁਝਾਰੰ। ਧਰੇ ਚਰਮ ਬਰਮੰ ਸੁ ਪਾਣੰ ਕੁਠਾਰੰ।","roman":"Mahaa jodh daaridr naamaa jujhaaran | dhare charam barman su paanan kuthaaran |","meaning_en":"\"The great warrior named Daridra (Poverty), a fighter, bearing shield and armour and an axe in hand;","page":896,"meaning_status":"draft","note":"Daridra appears again here (cf. 27.278.2)."},{"gurmukhi":"ਬਡੋ ਚਿਤ੍ਰ ਜੋਧੀ ਕਰੋਧੀ ਕਰਾਲੰ। ਤਜੈ ਨਾਸਕਾ ਨੈਨ ਧੂਮ੍ਰੰ ਬਰਾਲੰ। ੨੧੩।","roman":"Bado chitr jodhee karodhee karaalan | tajai naaskaa nain dhoomran baraalan | 213 |","meaning_en":"\"a great and wondrous warrior, angry and terrible; from his nostrils and eyes he lets out fierce smoke.","page":896,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਬਰਾਲੰ: read as 'fierce'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Rual metre.","page":896,"meaning_status":"draft"},{"type":"verse","number":[214],"number_text":"੨੧੪।","page":896,"lines":[{"gurmukhi":"ਸ੍ਵਾਮਿਘਾਤ ਕ੍ਰਿਤਘਨਤਾ ਦੋਊ ਬੀਰ ਹੈ ਦੁਰ ਧਰਖ।","roman":"Svaamighaat kritghantaa do'oo beer hai dur dharakh |","meaning_en":"\"Swamighat (Betrayal of one's master) and Kritaghanta (Ingratitude), both heroes are hard to withstand;","page":896,"meaning_status":"draft","note":"ਸ੍ਵਾਮਿਘਾਤ, ਕ੍ਰਿਤਘਨਤਾ: betrayal of the master, ingratitude; kept as names."},{"gurmukhi":"ਸਤ੍ਰੁ ਸੂਰਨ ਕੇ ਸੰਘਾਰਕ ਸੈਨ ਕੇ ਭਰਤਰਖ।","roman":"Satru sooran ke sanghaarak sain ke bharatrakh |","meaning_en":"\"destroyers of enemy heroes, protectors of the army;","page":896,"meaning_status":"draft","note":"ਭਰਤਰਖ: read as 'protectors'; uncertain."},{"gurmukhi":"ਕਉਨ ਦੋ ਥਨ ਸੋ ਜਨਾ ਜੁ ਨ ਮਾਨਿ ਹੈ ਤਿਹੰ ਤ੍ਰਾਸ।","roman":"Kaun do than so janaa ju na maani hai tihan traas |","meaning_en":"\"who is the person in either place who will not stand in fear of them?","page":896,"meaning_status":"draft","note":"ਦੋ ਥਨ: read as 'in the two places (worlds)'; uncertain."},{"gurmukhi":"ਰੂਪ ਅਨੂਪ ਬਿਲੋਕਿ ਕੈ ਭਟ ਭਜੈ ਹੋਇ ਉਦਾਸ। ੨੧੪।","roman":"Roop anoop biloki kai bhat bhajai hoi udaas | 214 |","meaning_en":"\"seeing their peerless form, warriors run away dejected.","page":896,"meaning_status":"draft"}]},{"type":"verse","number":[215],"number_text":"੨੧੫।","page":896,"lines":[{"gurmukhi":"ਮਿਤ੍ਰ ਦੋਖ ਅਰੁ ਰਾਜ ਦੋਖ ਸੁ ਏਕ ਹੀ ਹੈ ਭ੍ਰਾਤ।","roman":"Mitr dokh aru raaj dokh su ek hee hai bhraat |","meaning_en":"\"Mitra Dokh (Wronging a friend) and Raj Dokh (Treason) are brothers;","page":896,"meaning_status":"draft","note":"ਮਿਤ੍ਰ ਦੋਖ, ਰਾਜ ਦੋਖ: offence against a friend and against the king; kept as names."},{"gurmukhi":"ਏਕ ਬੰਸ ਦੁਹੂੰਨ ਕੋ ਅਰ ਏਕ ਹੀ ਤਿਹ ਮਾਤ।","roman":"Ek bans duhoonn ko ar ek hee tih maat |","meaning_en":"\"both are of one family, and theirs is one mother;","page":896,"meaning_status":"draft"},{"gurmukhi":"ਛਤ੍ਰਿ ਧਰਮ ਧਰੇ ਹਠੀ ਰਣ ਧਾਇ ਹੈ ਜਿਹ ਓਰ।","roman":"Chhatri dharam dhare hathee ran dhaai hai jih or |","meaning_en":"\"keeping the dharma of the Kshatriya, the stubborn ones charge in battle whichever way they go;","page":896,"meaning_status":"draft"},{"gurmukhi":"ਕਉਨ ਧੀਰ ਧਰ ਭਟਾਂਬਰ ਲੇਤ ਹੈ ਝਕਝੋਰ। ੨੧੫।","roman":"Kaun dheer dhar bhataanbar let hai jhakjhor | 215 |","meaning_en":"\"what best of warriors will keep his nerve? They shake (everyone) violently.","page":896,"meaning_status":"draft"}]},{"type":"verse","number":[216],"number_text":"੨੧੬।","page":896,"lines":[{"gurmukhi":"ਈਰਖਾ ਅਰੁ ਉਚਾਟ ਏ ਦੋਊ ਜੰਗ ਜੋਧਾ ਸੂਰ।","roman":"Eerkhaa aru uchaat e do'oo jang jodhaa soor |","meaning_en":"\"Irkha (Jealousy) and Uchat (Restless aversion) are both heroes, warriors in war;","page":896,"meaning_status":"draft","note":"ਈਰਖਾ, ਉਚਾਟ: jealousy, and restlessness or aversion; kept as names."},{"gurmukhi":"ਭਾਜਿ ਹੈ ਅਵਿਲੋਕ ਕੈ ਅਰੁ ਰੀਝਿ ਹੈ ਲਖਿ ਹੂਰ।","roman":"Bhaaji hai avilok kai aru reejhi hai lakhi hoor |","meaning_en":"\"(your men) will flee on seeing them, and the houris will be delighted to see them;","page":896,"meaning_status":"draft","note":"ਹੂਰ: houris, heavenly maidens (Arabic/Persian)."},{"gurmukhi":"ਕਉਨ ਧੀਰ ਧਰੈ ਭਟਾਂਬਰ ਜੀਤਿ ਹੈ ਸਬ ਸਤ੍ਰੂ।","roman":"Kaun dheer dharai bhataanbar jeeti hai sab satroo |","meaning_en":"\"what best of warriors will keep his nerve and conquer all the enemies?","page":896,"meaning_status":"draft"},{"gurmukhi":"ਦੰਤ ਲੈ ਤ੍ਰਿਣ ਭਾਜਿ ਹੈ ਭਟ ਕੋ ਨ ਗਹਿ ਹੈ ਅਤ੍ਰ। ੨੧੬।","roman":"Dant lai trin bhaaji hai bhat ko na gahi hai atr | 216 |","meaning_en":"\"warriors will flee with straw between their teeth; none will take up a weapon.","page":896,"meaning_status":"draft","note":"Straw in the teeth: a sign of surrender."}]},{"type":"verse","number":[217],"number_text":"੨੧੭।","page":896,"lines":[{"gurmukhi":"ਘਾਤ ਅਉਰ ਬਸੀਕਰਣ ਬਡ ਬੀਰ ਧੀਰ ਅਪਾਰ।","roman":"Ghaat aur baseekran bad beer dheer apaar |","meaning_en":"\"Ghat (Murder) and Basikaran (Enslaving spells) are great heroes of boundless nerve;","page":896,"meaning_status":"draft","note":"ਘਾਤ: killing; ਬਸੀਕਰਣ: control by spells; kept as names."},{"gurmukhi":"ਕ੍ਰੂਰ ਕਰਮ ਕੁਠਾਰ ਪਾਣਿ ਕਰਾਲ ਦਾੜ ਬਰਿਆਰ।","roman":"Kroor karam kuthaar paani karaal daar bariaar |","meaning_en":"\"of cruel deeds, axe in hand, with terrible tusks, mighty;","page":896,"meaning_status":"draft"},{"gurmukhi":"ਬਿਜ ਤੇਜ ਅਛਿਜ ਗਾਤਿ ਅਭਿਜ ਰੂਪ ਦੁਰੰਤ।","roman":"Bij tej achhij gaati abhij roop durant |","meaning_en":"\"radiant as lightning, indestructible in body, of impenetrable form, invincible;","page":896,"meaning_status":"draft","note":"ਬਿਜ: read as 'lightning' (bijli); uncertain."},{"gurmukhi":"ਕਉਨ ਕਉਨ ਨ ਜੀਤਿਏ ਜਿਨਿ ਜੀਵ ਜੰਤ ਮਹੰਤ। ੨੧੭।","roman":"Kaun kaun na jeetie jini jeev jant mahant | 217 |","meaning_en":"\"whom have they not conquered, of all living beings, creatures and great ones?","page":896,"meaning_status":"draft"}]},{"type":"verse","number":[218],"number_text":"੨੧੮।","page":897,"lines":[{"gurmukhi":"ਆਪਦਾ ਅਰੁ ਝੂਠਤਾ ਅਰੁ ਬੀਰ ਬੰਸ ਕੁਠਾਰ।","roman":"Aapdaa aru jhoothtaa aru beer bans kuthaar |","meaning_en":"\"Apada (Calamity) and Jhoothta (Falseness), the heroes, are axes to lineages;","page":897,"meaning_status":"draft","note":"ਆਪਦਾ, ਝੂਠਤਾ: calamity, falseness; kept as names."},{"gurmukhi":"ਪਰਮ ਰੂਪ ਦੁਰ ਧਰਖ ਗਾਤ ਅਮਰਖ ਤੇਜ ਅਪਾਰ।","roman":"Param roop dur dharakh gaat amrakh tej apaar |","meaning_en":"\"of supreme form, of invincible body, of boundless wrathful radiance;","page":897,"meaning_status":"draft","note":"ਅਮਰਖ: wrath, intolerance."},{"gurmukhi":"ਅੰਗ ਅੰਗਨਿ ਨੰਗ ਬਸਤ੍ਰ ਨ ਅੰਗ ਬਲਕੁਲ ਪਾਤ।","roman":"Ang angni nang basatr na ang balkul paat |","meaning_en":"\"their limbs are naked, with no clothes; not even bark or leaves on their bodies;","page":897,"meaning_status":"draft"},{"gurmukhi":"ਦੁਸਟ ਰੂਪ ਦਰਿਦ੍ਰ ਧਾਮ ਸੁ ਬਾਣ ਸਾਧੇ ਸਾਤ। ੨੧੮।","roman":"Dusat roop daridr dhaam su baan saadhe saat | 218 |","meaning_en":"\"of evil form, abode of wretchedness, they have mastered seven (kinds of) arrows.","page":897,"meaning_status":"draft","note":"ਸਾਤ: 'seven'; the reference is unclear. Uncertain."}]},{"type":"verse","number":[219],"number_text":"੨੧੯।","page":897,"lines":[{"gurmukhi":"ਬਿਯੋਗ ਅਉਰ ਅਪਰਾਧ ਨਾਮ ਸੁ ਧਾਰ ਹੈ ਜਬ ਕੋਪ।","roman":"Biyog aur apraadh naam su dhaar hai jab kop |","meaning_en":"\"When the ones named Biyog (Separation) and Apradh (Offence) take on anger,","page":897,"meaning_status":"draft","note":"ਬਿਯੋਗ, ਅਪਰਾਧ: separation, offence; kept as names."},{"gurmukhi":"ਕਉਨ ਠਾਢ ਸਕੈ ਮਹਾ ਬਲਿ ਭਾਜਿ ਹੈ ਬਿਨੁ ਓਪ।","roman":"Kaun thaadh sakai mahaa bali bhaaji hai binu op |","meaning_en":"\"who can stand? Even the mighty will flee, lustreless;","page":897,"meaning_status":"draft","note":"ਓਪ: lustre, splendour."},{"gurmukhi":"ਸੂਲ ਸੈਥਨ ਪਾਨਿ ਬਾਨ ਸੰਭਾਰਿ ਹੈ ਤਵ ਸੂਰ।","roman":"Sool saithan paani baan sanbhaari hai tav soor |","meaning_en":"\"your heroes will take up tridents, lances and arrows in hand,","page":897,"meaning_status":"draft"},{"gurmukhi":"ਭਾਜਿ ਹੈ ਤਜਿ ਲਾਜ ਕੋ ਬਿਸੰਭਾਰ ਹ੍ਵੈ ਸਬ ਕੂਰ। ੨੧੯।","roman":"Bhaaji hai taji laaj ko bisanbhaar hvai sab koor | 219 |","meaning_en":"\"(but) all those cowards will lose their senses and flee, abandoning shame.","page":897,"meaning_status":"draft"}]},{"type":"verse","number":[220],"number_text":"੨੨੦।","page":897,"lines":[{"gurmukhi":"ਭਾਨੁ ਕੀ ਸਰ ਭੇਦ ਜਾ ਦਿਨ ਤਪਿ ਹੈ ਰਣ ਸੂਰ।","roman":"Bhaanu kee sar bhed jaa din tapi hai ran soor |","meaning_en":"\"On the day the hero Bhed (Division), like the sun, blazes in battle,","page":897,"meaning_status":"draft","note":"ਭਾਨੁ ਕੀ ਸਰ ਭੇਦ: read as 'Bhed, equal of the sun'; the name is uncertain."},{"gurmukhi":"ਕਉਨ ਧੀਰ ਧਰੈ ਮਹਾ ਭਟ ਭਾਜਿ ਹੈ ਸਭ ਕੂਰ।","roman":"Kaun dheer dharai mahaa bhat bhaaji hai sabh koor |","meaning_en":"\"what great warrior will keep his nerve? All the cowards will flee;","page":897,"meaning_status":"draft"},{"gurmukhi":"ਸਸਤ੍ਰ ਅਸਤ੍ਰਨ ਛਾਡਿ ਕੈ ਅਰੁ ਬਾਜ ਰਾਜ ਬਿਸਾਰਿ।","roman":"Sasatr astran chhaadi kai aru baaj raaj bisaari |","meaning_en":"\"leaving their weapons and forgetting their fine horses,","page":897,"meaning_status":"draft"},{"gurmukhi":"ਕਾਟਿ ਕਾਟਿ ਸਨਾਹ ਤਵ ਭਟ ਭਾਜਿ ਹੈ ਬਿਸੰਭਾਰ। ੨੨੦।","roman":"Kaati kaati sanaah tav bhat bhaaji hai bisanbhaar | 220 |","meaning_en":"\"cutting off their armour, your warriors will flee, senseless.","page":897,"meaning_status":"draft"}]},{"type":"verse","number":[221],"number_text":"੨੨੧।","page":897,"lines":[{"gurmukhi":"ਧੂਮ੍ਰ ਬਰਣ ਅਉ ਧੂਮ੍ਰ ਨੈਨ ਸੁ ਸਾਤ ਧੂਮ੍ਰ ਜੁਆਲ।","roman":"Dhoomr baran au dhoomr nain su saat dhoomr juaal |","meaning_en":"\"Smoke-coloured, with smoky eyes, and seven smoky flames;","page":897,"meaning_status":"draft","note":"ਸਾਤ: 'seven'; unclear. Uncertain."},{"gurmukhi":"ਛੀਨ ਬਸਤ੍ਰ ਧਰੇ ਸਬੈ ਤਨ ਕ੍ਰੂਰ ਬਰਣ ਕਰਾਲ।","roman":"Chheen basatr dhare sabai tan kroor baran karaal |","meaning_en":"\"all of them wear worn clothes on their bodies, cruel of colour and terrible;","page":897,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਆਲਸ ਤਵਨ ਕੋ ਸੁਨਿ ਰਾਜ ਰਾਜ ਵਤਾਰ।","roman":"Naam aalas tavan ko suni raaj raaj vataar |","meaning_en":"\"his name is Alas (Sloth); listen, O incarnation of the king of kings;","page":897,"meaning_status":"draft","note":"Alas also appears at 27.254.4."},{"gurmukhi":"ਕਉਨ ਸੂਰ ਸੰਘਾਰਿ ਹੈ ਤਿਹ ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਪ੍ਰਹਾਰ। ੨੨੧।","roman":"Kaun soor sanghaari hai tih sasatr asatr prahaar | 221 |","meaning_en":"\"what hero will destroy him by striking him with weapons?","page":897,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"Totak metre.","page":897,"meaning_status":"draft"},{"type":"verse","number":[222],"number_text":"੨੨੨।","page":897,"lines":[{"gurmukhi":"ਚੜਿ ਹੈ ਗਹਿ ਕੋਪ ਕ੍ਰਿਪਾਣ ਰਣੰ। ਘਮਕੰਤ ਕਿ ਘੁੰਘਰ ਘੋਰ ਘਣੰ।","roman":"Chari hai gahi kop kripaan ranan | ghamkant ki ghunghar ghor ghanan |","meaning_en":"\"He will mount (his horse), seizing his sword in anger in battle, like dense clouds thundering, with jangling bells;","page":897,"meaning_status":"draft","note":"ਘਮਕੰਤ, ਘੁੰਘਰ: the jingle of bells and the rumble of clouds."},{"gurmukhi":"ਤਿਹ ਨਾਮ ਸੁ ਖੇਦ ਅਭੇਦ ਭਟੰ। ਤਿਹ ਬੀਰ ਸੁਧੀਰ ਲਖੋ ਨਿਪਟੰ। ੨੨੨।","roman":"Tih naam su khed abhed bhatan | tih beer sudheer lakho niptan | 222 |","meaning_en":"\"his name is Khed (Grief), the impenetrable warrior; consider him a hero of utter steadiness.","page":897,"meaning_status":"draft","note":"ਖੇਦ: grief, weariness; kept as a name."}]},{"type":"verse","number":[223],"number_text":"੨੨੩।","page":897,"lines":[{"gurmukhi":"ਕਲ ਰੂਪ ਕਰਾਲ ਜ੍ਵਾਲ ਜਲੰ। ਅਸਿ ਉਜਲ ਪਾਨਿ ਪ੍ਰਭਾ ਨਿਮ੍ਰਲੰ।","roman":"Kal roop karaal jvaal jalan | asi ujal paani prabhaa nimralan |","meaning_en":"\"Of the form of Death, terrible, burning with flames, a bright sword in hand, of pure brilliance;","page":897,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਉਜਲ ਦੰਦ ਅਨੰਦ ਮਨੰ। ਕੁਕ੍ਰਿਆ ਤਿਹ ਨਾਮ ਸੁ ਜੋਧ ਗਨੰ। ੨੨੩।","roman":"Ati ujal dand anand manan | kukriaa tih naam su jodh ganan | 223 |","meaning_en":"\"very bright teeth, joyful in mind, Kukria (Evil Deed) is the name of that warrior, count him among them.","page":897,"meaning_status":"draft","note":"ਕੁਕ੍ਰਿਆ: wicked deed; kept as a name."}]},{"type":"verse","number":[224],"number_text":"੨੨੪।","page":897,"lines":[{"gurmukhi":"ਅਤਿ ਸਿਆਮ ਸਰੂਪ ਕਰੂਪ ਤਨੰ। ਉਪਜੰ ਅਗ੍ਯਾਨ ਬਿਲੋਕਿ ਮਨੰ।","roman":"Ati siaam saroop karoop tanan | upjan agyaan biloki manan |","meaning_en":"\"Very dark of form and ugly of body, ignorance arises in the mind on seeing him;","page":897,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਨਾਮ ਗਿਲਾਨਿ ਪ੍ਰਧਾਨ ਭਟੰ। ਰਣ ਮੋ ਨ ਮਹਾ ਹਠਿ ਹਾਰਿ ਹਟੰ। ੨੨੪।","roman":"Tih naam gilaani pradhaan bhatan | ran mo na mahaa hathi haari hatan | 224 |","meaning_en":"\"his name is Gilani (Remorse), a chief warrior; very stubborn, he never turns back defeated in battle.","page":897,"meaning_status":"draft","note":"ਗਿਲਾਨਿ: remorse, self-loathing; kept as a name."}]},{"type":"verse","number":[225],"number_text":"੨੨੫।","page":897,"lines":[{"gurmukhi":"ਅਤਿ ਅੰਗ ਸੁਰੰਗ ਸਨਾਹ ਸੁਭੰ। ਬਹੁ ਕਸਟ ਸਰੂਪ ਸੁ ਕਸਟ ਛੁਭੰ।","roman":"Ati ang surang sanaah subhan | bahu kasat saroop su kasat chhubhan |","meaning_en":"\"Fine of limb, with handsome armour, of the form of great hardship, he afflicts with hardship;","page":897,"meaning_status":"draft","note":"ਕਸਟ: hardship. Read as the warrior Kasht (Hardship); uncertain."},{"gurmukhi":"ਅਤਿ ਬੀਰ ਅਧੀਰ ਨ ਭਯੋ ਕਬ ਹੀ। ਦਿਵ ਦੇਵ ਪਛਾਨਤ ਹੈ ਸਬ ਹੀ। ੨੨੫।","roman":"Ati beer adheer na bhayo kab hee | div dev pachhaanat hai sab hee | 225 |","meaning_en":"\"a great hero, never once faint-hearted; the gods of heaven all recognise him.","page":897,"meaning_status":"draft"}]},{"type":"verse","number":[226],"number_text":"੨੨੬।","page":898,"lines":[{"gurmukhi":"ਭਟ ਕਰਮ ਬਿਕਰਮ ਜਬੈ ਧਰਿ ਹੈ। ਰਣ ਰੰਗ ਤੁਰੰਗਹਿ ਬਿਚਰਿ ਹੈ।","roman":"Bhat karam bikram jabai dhari hai | ran rang turanghi bichri hai |","meaning_en":"\"When the warrior Karam (Ritual Action) takes up his prowess, and moves his horse about in the fray of battle,","page":898,"meaning_status":"draft","note":"ਕਰਮ ਬਿਕਰਮ: read as 'the warrior Karam, (with) prowess'; the name is uncertain."},{"gurmukhi":"ਤਬ ਬੀਰ ਸੁ ਧੀਰਹਿੰ ਕੋ ਧਰਿ ਹੈ। ਬਲ ਬਿਕ੍ਰਮ ਤੇਜ ਤਬੈ ਹਰਿ ਹੈ। ੨੨੬।","roman":"Tab beer su dheerhin ko dhari hai | bal bikram tej tabai hari hai | 226 |","meaning_en":"\"then he will capture even heroes of firm nerve, and take away their strength, prowess and radiance.\"","page":898,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":898,"meaning_status":"draft"},{"type":"verse","number":[227],"number_text":"੨੨੭।","page":898,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਤਨ ਸੂਰਾ ਸੁ ਧਰਿ ਧੈ ਹੈ ਨ੍ਰਿਪ ਅਬਿਬੇਕ।","roman":"Ih bidhi tan sooraa su dhari dhai hai nrip abibek |","meaning_en":"\"In this way King Abibek will come charging with such heroes in his body (army);","page":898,"meaning_status":"draft","note":"ਤਨ: read as 'in (his) body / ranks'; uncertain."},{"gurmukhi":"ਨ੍ਰਿਪ ਬਿਬੇਕ ਕੀ ਦਿਸਿ ਸੁਭਟ ਠਾਢ ਨ ਰਹਿ ਹੈ ਏਕ। ੨੨੭।","roman":"Nrip bibek kee disi subhat thaadh na rahi hai ek | 227 |","meaning_en":"\"on King Bibek's side, not one warrior will remain standing.\"","page":898,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ ਨਾਟਕ ਗ੍ਰੰਥੇ ਪਾਰਸ ਮਛਿੰਦ੍ਰ ਸੰਬਾਦੇ ਨ੍ਰਿਪ ਅਬਿਬੇਕ ਆਗਮਨ ਨਾਮ","roman":"Iti sree bachit naatak granthe paaras machhindr sanbaade nrip abibek aagman naam","meaning_en":"Here ends, in the sacred Bachittar Natak granth, in the dialogue of Paras and Machhindra, the chapter named \"The Coming of King Abibek\"","page":898,"meaning_status":"draft"},{"gurmukhi":"ਸੁਭਟ ਬਰਨਨੰ ਨਾਮ ਧਿਆਇ ਸਮਾਪਤਮ ਸਤ ਸੁਭਮ ਸਤ।","roman":"Subhat barannan naam dhiaai samaaptam sat subham sat |","meaning_en":"and the Description of His Warriors. All is well, all is auspicious.","page":898,"meaning_status":"draft","note":"ਸਤ ਸੁਭਮ ਸਤ: 'true, auspicious, true', the customary closing words."}],"page":898}});
